insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'MAT', $b$Y-Mathiơ$b$, $b$["Nau Mhe Mhan Ueh Tĭng Nâm", "Y-MATHIƠ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MAT',1,1,null,$b$Amoh phung chô yau Yêsu Krist, kon sau Y-Đavit, kon sau Y-Abraham.$b$,true),
('bunong-vn','MAT',1,2,null,$b$Y-Abraham jêng mbơ̆ ma Y-Isăk; Y-Isăk jêng mbơ̆ Y-Yakôp; Y-Yakôp jêng mbơ̆ Y-Yuđa jêh ri ma phung oh nâu păng;$b$,true),
('bunong-vn','MAT',1,3,null,$b$Y-Yuđa đah ur păng H'Tamar geh kon bu klâu Y-Parês jêh ri Y-Sara; Y-Parês jêng mbơ̆ Y-Êsrôm; Y-Êsrôm jêng mbơ̆ Y-Aram;$b$,false),
('bunong-vn','MAT',1,4,null,$b$Y-Aram jêng mbơ̆ Y-Aminadap; Y-Aminadap jêng mbơ̆ Y-Nahsôn; Y-Nahsôn jêng mbơ̆ Y-Salmôn;$b$,false),
('bunong-vn','MAT',1,5,null,$b$Y-Salmôn đah ur păng H'Rahap, geh kon bu klâu Y-Bôas; Y-Bôas đah ur păng, H'Rut, geh kon bu klâu Y-Ôbet; Y-Ôbet jêng mbơ̆ Y-Yêsê.$b$,false),
('bunong-vn','MAT',1,6,null,$b$Y-Yêsê jêng mbơ̆ hađăch Y-Đavit, Hađăch Đavit jêng mbơ̆ Y-Salômôn, păng geh kon nây đah ur Y-Uri;$b$,false),
('bunong-vn','MAT',1,7,null,$b$Y-Salômôn jêng mbơ̆ Y-Rôbôam. Y-Rôbôam jêng mbơ̆ Y-Abia; Y-Abia jêng mbơ̆ Y-Asa;$b$,false),
('bunong-vn','MAT',1,8,null,$b$Y-Asa jêng mbơ̆ Y-Yôsaphat; Y-Yôsaphat jêng mbơ̆ Y-Yôram; Y-Yôram jêng mbơ̆ Y-Ôsia;$b$,false),
('bunong-vn','MAT',1,9,null,$b$Y-Ôsia jêng mbơ̆ Y-Yôtham. Y-Yôtham jêng mbơ̆ Y-Akas; Y-Akas jêng mbơ̆ Y-Êsêkia;$b$,false),
('bunong-vn','MAT',1,10,null,$b$Y-Êsêkia jêng mbơ̆ Y-Manasê. Y-Manasê jêng mbơ̆ Y-Amôn; Y-Amôn jêng mbơ̆ Y-Yôsia;$b$,false),
('bunong-vn','MAT',1,11,null,$b$Y-Yôsia jêng mbơ̆ Y-Yêkônia jêh ri ma phung oh nâu păng; dôl bu nhŭp phung Israel jêng dĭk tâm bri Babilôn.$b$,false),
('bunong-vn','MAT',1,12,null,$b$Jêh khân păng gŭ tâm bri Babilôn, Y-Yêkônia geh kon Y-Salathiel. Y-Salathiel jêng mbơ̆ Y-Sôrôƀaƀel;$b$,true),
('bunong-vn','MAT',1,13,null,$b$Y-Sôrôƀaƀel jêng mbơ̆ Y-Abiut; Y-Abiut jêng mbơ̆ Y-Êliakim. Y-Êliakim jêng mbơ̆ Y-Asôr.$b$,false),
('bunong-vn','MAT',1,14,null,$b$Y-Asôr jêng mbơ̆ Y-Sadôk; Y-Sadôk jêng mbơ̆ Y-Akim. Y-Akim jêng mbơ̆ Y-Êliut;$b$,false),
('bunong-vn','MAT',1,15,null,$b$Y-Êliut jêng mbơ̆ Y-Êlêasar. Y-Êlêasar jêng mbơ̆ Y-Mathan; Y-Mathan jêng mbơ̆ Y-Yakôp;$b$,false),
('bunong-vn','MAT',1,16,null,$b$Y-Yakôp jêng mbơ̆ Y-Yôsep; sai H'Mari; bu ur nây deh ma Brah Yêsu, tâm amoh Brah Krist.$b$,false),
('bunong-vn','MAT',1,17,null,$b$Pô ri ntơm bơh Y-Abraham tât ta Y-Đavit geh lĕ rngôch jât ma puăn rô̆ ; ntơm bơh Y-Đavit tât ma rnôk bu nhŭp leo phung Israel jêng dĭk tâm bri Babilôn geh jât ma puăn rô̆ ; jêh ri ntơm bơh rnôk bu nhŭp leo phung Israel jêng dĭk tâm bri Babilôn tât ma Brah Krist geh jât ma puăn rô̆ đŏng.$b$,true),
('bunong-vn','MAT',1,18,null,$b$Aơ jêng nau nkoch bri nau bu deh ma Yêsu Krist. Mê̆ păng H'Mari, hŏ ƀư ndrôi jêh đah Y-Yôsep, jêh ri păng ntreo ma Brah Huêng Ueh, ê lor khân păng gŭ ndrel.$b$,true),
('bunong-vn','MAT',1,19,null,$b$Y-Yôsep, sai păng, jêng du huê bunuyh sŏng srăng; păng mâu ŭch ăn ndrôi păng geh nau bêk prêng ôh, yor ri păng ŭch lơi ndrôi păng ma nau ndâp.$b$,false),
('bunong-vn','MAT',1,20,null,$b$Dôl păng gŭ mĭn nau nây, geh du huê brah ntuh bâr Kôranh Brah mpơl ma păng tâm nau mbơi, păng lah pô aơ: “Hơi Y-Yôsep, kon sau Y-Đavit, lơi may klach ôh sŏk H'Mari jêng ur may, yor lah kon nây Brah Huêng Ueh yơh ăn păng ntreo.$b$,false),
('bunong-vn','MAT',1,21,null,$b$Păng mra deh du huê kon bu klâu, may mra tâm amoh Păng Yêsu, jêng Nơm tâm rklaih yor lah Păng yơh mra tâm rklaih phung ƀon lan Păng bơh nau tih.”$b$,false),
('bunong-vn','MAT',1,22,null,$b$Lĕ nau nây tât jêng di ngăn tâm ban ma nau nơm djôt nau Kôranh Brah hŏ mbơh jêh pô aơ:$b$,false),
('bunong-vn','MAT',1,23,null,$b$“Du huê bu ur druh mra ntreo, jêh ri deh du huê kon bu klâu, jêh ri bu mra tâm Amoh păng Êmanuel,” (nâm bu ntĭt Brah Ndu gŭ ndrel he).$b$,false),
('bunong-vn','MAT',1,24,null,$b$Y-Yôsep kah rngăl bêch păng ƀư tĭng nâm nau brah ntuh bâr Kôranh Brah ntăm. Păng sŏk H'Mari jêng ur păng.$b$,true),
('bunong-vn','MAT',1,25,null,$b$Ƀiă lah khân păng ê tâm mâp bu ur bu klâu ôh, tât ur păng deh du huê kon bu klâu. Jêh ri păng tâm amoh kon se nây jêng Yêsu.$b$,false),
('bunong-vn','MAT',2,1,null,$b$Rnôk bu deh ma Brah Yêsu tâm ƀon Ƀêtlêhem tâm n'gor Yuđa rnôk hađăch Hêrôt, geh phung njêh bơh luh nar tât ta ƀon Yêrusalem, jêh ri ôp:$b$,true),
('bunong-vn','MAT',2,2,null,$b$“Ta ntŭk hađăch Yuđa mhe deh? Yor lah hên saơ jêh mbing păng tă bơh lơ jêh ri hên văch mbah ma Păng.”$b$,false),
('bunong-vn','MAT',2,3,null,$b$Tơ lah hađăch Hêrôt tăng lư nau nây, păng jêh ri lĕ rngôch ƀon Yêrusalem geh nau rŭng răng da dê.$b$,false),
('bunong-vn','MAT',2,4,null,$b$Păng rgum lĕ rngôch phung n'gâng kan kôranh ƀư brah, nđâp ma phung kôranh nchih sămƀŭt, jêh ri ôp ma khân păng ta ntŭk bu deh ma Brah Krist.$b$,false),
('bunong-vn','MAT',2,5,null,$b$Khân păng plơ̆ lah: “Ta ƀon Ƀêtlêhem tâm n'gor Yuđa; yor lah kôranh nơm mbơh lor nchih jêh pô aơ:$b$,false),
('bunong-vn','MAT',2,6,null,$b$‘Jêh ri may, hơi ƀon Ƀêtlêhem, tâm n'gor Yuđa. Nanê̆ may mâu jêng ƀon jê̆ lơn ôh đah lĕ ƀon toyh tâm n'gor Yuđa. Yor lah tă bơh may yơh mra luh du huê kôranh toyh. Păng mra jêng rmăk biăp phung Israel, mpôl băl gâp.’ ”$b$,false),
('bunong-vn','MAT',2,7,null,$b$Pô ri Hêrôt kuăl phung njêh ma nau ndâp. Păng ôp n'hêl nanê̆ ndah jŏ mbing hŏ mpơl jêh.$b$,false),
('bunong-vn','MAT',2,8,null,$b$Hađăch đă khân păng hăn ta ƀon Ƀêtlêhem, jêh ri păng ntăm ma khân păng: “Hăn hom jêh ri ôp joi nanê̆ kon se jê̆ nây, jêh ri tơ lah khân may saơ Păng, mbơh an ma gâp gĭt. Gâp mra hăn mbah ma păng tâm ban lĕ.”$b$,false),
('bunong-vn','MAT',2,9,null,$b$Jêh khân păng tăng nau hađăch Hêrôt lah, khân păng hăn ro; aơ, mbing khân păng saơ tă bơh luh nar hăn pa năp khân păng, tât jêh ri gŭ tham klơ ntŭk kon se jê̆ nây.$b$,false),
('bunong-vn','MAT',2,10,null,$b$Tơ lah khân păng saơ mbing nây khân păng răm maak ngăn.$b$,false),
('bunong-vn','MAT',2,11,null,$b$Jêh ri khân păng lăp tâm ngih, khân păng saơ kon se jê̆ ndrel mê̆ Păng, H'Mari. Khân păng chon mon mbah ta năp kon se jê̆ nây jêh ri pơk hip. Khân păng nhhơr ma kon se jê̆ nây ma mah, dak si ƀâu kah, jêh ri dak si tăng.$b$,true),
('bunong-vn','MAT',2,12,null,$b$Jêh ri Brah Ndu mbơh ma khân păng tâm nau mbơi mâu ăn khân păng sĭt ma hađăch Hêrôt ôh. Pô ri khân păng plơ̆ sĭt ma n'gor khân păng nơm trong êng.$b$,false),
('bunong-vn','MAT',2,13,null,$b$Jêh phung njêh sĭt, geh du huê Tông mpăr Kôranh Brah mpơl tâm nau mbơi ma Y-Yôsep jêh ri lah ma păng: “Dâk hom may djôt kon se jê̆ jêh ri mê̆ Păng, hăn du ta n'gor Êjipt, jêh ri may mra gŭ ta nây tât gâp mra ngơi ma may; yor lah hađăch Hêrôt mra joi kon se jê̆ ŭch nkhĭt lơi Păng.”$b$,true),
('bunong-vn','MAT',2,14,null,$b$Pô ri Y-Yôsep dâk dôl măng, sŏk kon se jê̆ jêh ri mê̆ Păng. Khân păng du ta n'gor Êjipt.$b$,false),
('bunong-vn','MAT',2,15,null,$b$Khân păng gŭ ta nây tât hađăch Hêrôt khĭt. Pô ri nanê̆ jêh nau Kôranh Brah lah đah bâr mbung kôranh nơm mbơh lor pô aơ: “Gâp kuăl jêh Kon gâp ngluh tă bơh n'gor Êjipt.”$b$,true),
('bunong-vn','MAT',2,16,null,$b$Tơ lah hađăch Hêrôt gĭt ma phung njêh mưch ma păng, păng ji nuih hâu ngăn, jêh ri păng đă bu nkhĭt lơi lĕ rngôch phung kon se jê̆ bu klâu tâm ƀon Ƀêtlêhem jêh ri lam n'gor nây, ntơm bơh jê̆ tât bar năm. Păng kơp năm ntơm bơh nar phung njêh mbơh ma Păng.$b$,false),
('bunong-vn','MAT',2,17,null,$b$Pô ri nanê̆ jêh nau kôranh nơm mbơh lor Y-Yêrêmi pô aơ:$b$,false),
('bunong-vn','MAT',2,18,null,$b$“Bu tăng bâr nter tâm ƀon Rama. Geh nau nhhiăng nhĭm jêh ri nau vơh vơl. H'Rachel nhhiăng nhĭm ma phung kon păng. Jêh ri păng mâu blau bah ôh nau klâng, yor khân ô băl hŏ khĭt jêh.”$b$,false),
('bunong-vn','MAT',2,19,null,$b$Ƀiă lah jêh hađăch Hêrôt khĭt geh du huê Tông mpăr ueh Kôranh Brah mpơl tâm nau mbơi ma Y-Yôsep ta n'gor Êjipt jêh ri lah ma păng:$b$,false),
('bunong-vn','MAT',2,20,null,$b$“Dâk hom may djôt kon se jê̆ jêh ri mê̆ Păng plơ̆ sĭt hom ma bri Israel, yor lah phung ŭch nkhĭt kon se jê̆ nây hŏ khĭt jêh.”$b$,false),
('bunong-vn','MAT',2,21,null,$b$Y-Yôsep dâk, sŏk kon se jê̆ jêh ri mê̆ Păng, Păng plơ̆ ta bri Israel.$b$,false),
('bunong-vn','MAT',2,22,null,$b$Ƀiă lah tơ lah păng gĭt ma Y-Arkêlôs jêng hađăch chiă uănh n'gor Yuđa ntrok hađăch Hêrôt, mbơ̆ păng, Y-Yôsep klach sĭt ta bri nây, yor lah Brah Ndu mbơh ma păng tâm nau mbơi, păng hăn gŭ tâm n'gor Galilê.$b$,true),
('bunong-vn','MAT',2,23,null,$b$Jêh tât ta nây păng gŭ tâm ƀon, amoh ƀon nây Nasaret. Pô ri n'hêl nanê̆ ngăn nau kôranh nơm mbơh lor lah jêh pô aơ: “Bu tâm amoh Păng bunuyh ƀon Nasaret.”$b$,true),
('bunong-vn','MAT',3,1,null,$b$Tâm rnôk nây geh Y-Yôhan, nơm ƀư ƀaptem, nti lah tâm bri rdah n'gor Yuđa. Pô aơ păng lah:$b$,true),
('bunong-vn','MAT',3,2,null,$b$“Rmal hom nau tih khân ay may, yor lah ƀon bri hađăch Brah Ndu dăch tât jêh.”$b$,false),
('bunong-vn','MAT',3,3,null,$b$Ma păng yơh kôranh nơm mbơh lor Y-Êsai hŏ mbơh jêh pô aơ: “Geh bâr nter tâm bri rdah: ‘Nkra hom trong Kôranh Brah, ƀư lâng hom trong Păng.’ ”$b$,false),
('bunong-vn','MAT',3,4,null,$b$Y-Yôhan nsoh ao ƀư ma rsau seh samô, jêh ri păng vân rse bŭt ntâu. Păng sa krah jêh ri dak sŭt bri.$b$,false),
('bunong-vn','MAT',3,5,null,$b$Rnôk nây lĕ rngôch bunuyh ƀon Yêrusalem, lam n'gor Yuđa, jêh ri lĕ n'gor êp dak krong Yurdan hăn ma păng da dê.$b$,false),
('bunong-vn','MAT',3,6,null,$b$Jêh mbơh nau tih, khân păng dơn Y-Yôhan ƀư ƀaptem ma khân păng tâm dak krong Yurdan.$b$,false),
('bunong-vn','MAT',3,7,null,$b$Yor păng saơ âk phung Pharisi jêh ri phung Sađusê văch dơn nau ƀaptem păng, păng lah pô aơ: “Hơi phung mpôl bêh rmâng, mbu nti khân may dơi du bơh nau Brah Ndu ji nuih mra tât?$b$,true),
('bunong-vn','MAT',3,8,null,$b$Ăn khân may geh play di tâm nau rmal nau tih.$b$,false),
('bunong-vn','MAT',3,9,null,$b$Jêh ri lơi lah ôh tâm nuih n'hâm khân ay may: ‘Hên geh jêh Y-Abraham jêng mbơ̆ hên’ yor lah gâp mbơh ma khân ay may, tă bơh phung lŭ aơ Brah Ndu dơi ăn deh kon ma Y-Braham đŏng.$b$,false),
('bunong-vn','MAT',3,10,null,$b$Aƀaơ sung bu hŏ dơm jêh ta reh si; lĕ rngôch si mâu geh play ueh bu mra kăl jêh ri mƀăr lơi tâm ŭnh.$b$,false),
('bunong-vn','MAT',3,11,null,$b$Gâp ƀư ƀaptem ma khân ay may ma dak ma nau khân ay may rmal nau tih, ƀiă lah nơm văch pa kơi gâp, Păng brah lơn ma gâp, jêh ri gâp mâu khư ôh djôt ntâu jot Păng. Păng yơh mra ƀư ƀaptem ma khân ay may ma Brah Huêng Ueh jêh ri ma ŭnh.$b$,true),
('bunong-vn','MAT',3,12,null,$b$Păng djôt dông tâm ti, jêh ri mra ƀư kloh ntŭk plên ba Păng. Păng mra bun ba tâm ngih prăp ba Păng, ƀiă lah Păng su lơi rhe tâm ŭnh mâu blau nhhât.”$b$,true),
('bunong-vn','MAT',3,13,null,$b$Rnôk nây Brah Yêsu luh bơh n'gor Galilê hăn ta Y-Yôhan ta dak krong Yurdan, gay ma Y-Yôhan ƀư ƀaptem ma Păng.$b$,true),
('bunong-vn','MAT',3,14,null,$b$Ƀiă lah Y-Yôhan dun jêh ri lah: “Gâp yơh ŭch ăn may ƀư ƀaptem ma gâp. Mâm ƀư may văch ma gâp?” Brah Yêsu plơ̆ lah ma păng:$b$,false),
('bunong-vn','MAT',3,15,null,$b$“Ƀư hom aƀaơ ro; yor lah di jêh ma he ƀư nanê̆ lĕ rngôch nau sŏng pô ri.” Jêh ri Y-Yôhan tông nau păng lah.$b$,false),
('bunong-vn','MAT',3,16,null,$b$Jêh Brah Yêsu dơn nau ƀaptem, dôl Păng mhe luh tă bơh dak, ri trôk pơk mpơl, jêh ri Y-Yôhan saơ Brah Huêng Ueh Brah Ndu trŭnh ta Brah Yêsu nâm bu du mlâm plŭk.$b$,false),
('bunong-vn','MAT',3,17,null,$b$Jêh ri geh bâr ngơi tă bơh trôk lah: “Păng aơ jêng kon gâp rŏng ngăn ngên, tâm Păng gâp geh nau maak ngăn.”$b$,false),
('bunong-vn','MAT',4,1,null,$b$Jêh ta nây Brah Huêng Ueh njŭn leo Brah Yêsu tâm bri rdah, ăn brah mhĭk ndơm Păng.$b$,true),
('bunong-vn','MAT',4,2,null,$b$Păng ât sông sa puăn jât nar jêh ri puăn jât măng, jêh ri Păng ji ngot.$b$,false),
('bunong-vn','MAT',4,3,null,$b$Brah mhĭk ndơm hăn êp păng jêh ri lah ma păng: “Tơ lah may jêng Kon Brah Ndu, dŏng phung lŭ aơ rlơ̆ jêng kapŭng;”$b$,true),
('bunong-vn','MAT',4,4,null,$b$ƀiă lah Brah Yêsu plơ̆ lah: “Bu nchih jêh pô aơ, ‘bunuyh gŭ rêh mâu di ôh knŏng sa kapŭng, ƀiă lah yor lĕ nau ngơi luh bơh bâr mbung Brah Ndu.’ ”$b$,false),
('bunong-vn','MAT',4,5,null,$b$Jêh nây brah mhĭk chông njŭn păng tâm ƀon kloh ueh, n'gân păng ta klơ chor ngih brah Yuđa,$b$,false),
('bunong-vn','MAT',4,6,null,$b$jêh ri lah ma Păng: “Tơ lah may jêng Kon Brah Ndu, ntŭp hom may nơm ta neh yor lah bu nchih jêh pô aơ: ‘Păng mra đă phung Tông mpăr Păng chiă uănh may, jêh ri khân păng mra kâp chông may tâm ti khân păng, klach lah jâng may tŭp nchinh đah lŭ.’ ”$b$,false),
('bunong-vn','MAT',4,7,null,$b$Brah Yêsu lah ma păng: “Bu nchih jêh pô aơ: ‘Lơi may rlong uănh ôh Kôranh Brah Ndu may.’ ”$b$,false),
('bunong-vn','MAT',4,8,null,$b$Brah mhĭk njŭn Păng ta klơ yôk prêh ngăn, nchŏng ma Păng lĕ rngôch ƀon bri hađăch neh ntu jêh ri nau chrêk rmah khân păng.$b$,true),
('bunong-vn','MAT',4,9,null,$b$Jêh ri păng lah: “Gâp mra ăn ma may lĕ rngôch ndơ aơ tơ lah may chon mon ta năp gâp jêh ri yơk mbah ma gâp.”$b$,false),
('bunong-vn','MAT',4,10,null,$b$Brah Yêsu lah ma păng: “Du hom Satan! Yor lah bu nchih jêh pô aơ: ‘May mra yơk mbah ma Kôranh Brah Ndu may, jêh ri may mra pah kan knŏng du huê Păng yơh.’ ”$b$,true),
('bunong-vn','MAT',4,11,null,$b$Pô ri brah mhĭk du tă bơh Păng, jêh ri geh phung Tông mpăr ueh Brah Ndu hăn êp Păng jêh ri kơl kan Păng.$b$,false),
('bunong-vn','MAT',4,12,null,$b$Tơ lah Brah Yêsu gĭt bu krŭng jêh Y-Yôhan, Păng hăn tâm n'gor Galilê.$b$,true),
('bunong-vn','MAT',4,13,null,$b$Păng lơi ƀon Nasaret jêh ri Păng hăn gŭ ta ƀon Kapernum êp dak mƀŭt, ta n'har n'gor Sabulôn jêh ri n'gor Naptali.$b$,false),
('bunong-vn','MAT',4,14,null,$b$Pô ri n'hêl nanê̆ jêh lĕ nau kôranh nơm mbơh lor, Y-Êsai, lah:$b$,false),
('bunong-vn','MAT',4,15,null,$b$“Bri Sabulôn jêh ri n'gor Naptali mpeh dak mƀŭt. N'gor kăl tê̆ dak krong Yurdan. Bri Galilê phung pa dih.$b$,false),
('bunong-vn','MAT',4,16,null,$b$Phung bunuyh ƀon lan nây gŭ krâm tâm ntŭk ngo. Khân păng saơ jêh nau ang toyh. Jêh ri ma phung bunuyh gŭ krâm tâm ntŭk. Jêh ri tâm dâng n'hâm nau khĭt nau ang hŏ lah jêh ma khân păng.”$b$,false),
('bunong-vn','MAT',4,17,null,$b$Ntơm bơh nar nây Brah Yêsu ntơm nti. Păng lah: “Rmal hom nau tih khân ay may, yor lah ƀon bri hađăch Brah Ndu dăch tât jêh.”$b$,false),
('bunong-vn','MAT',4,18,null,$b$Dôl Brah Yêsu hăn rŏ kơh dak mƀŭt Galilê, Păng saơ bar hê oh nâu, Y-Simôn tâm amoh Y-Pêtrôs, jêh ri Y-Andrê, oh păng. Khân păng ntơm seng ka tâm dak mƀŭt yor lah khân păng jêng bunuyh vay seng jal.$b$,true),
('bunong-vn','MAT',4,19,null,$b$Brah Yêsu kuăl khân păng: “Tĭng hom gâp, jêh ri gâp mra njêng khân may jêng bunuyh seng bunuyh.”$b$,true),
('bunong-vn','MAT',4,20,null,$b$Ƀât lât ta nây khân păng mƀăr lơi jal jêh ri tĭng Kôranh Brah Yêsu.$b$,false),
('bunong-vn','MAT',4,21,null,$b$Ngai djê̆ ta nây Păng saơ bar hê oh nâu êng, Y-Yakơ, kon Y-Sêƀêđê, jêh ri Y-Yôhan, oh păng. Khân păng gŭ jĭm jal tâm plŭng ndrel ma Y-Sêƀêđê, mbơ̆ khân păng, jêh ri Brah Yêsu kuăl khân păng.$b$,false),
('bunong-vn','MAT',4,22,null,$b$Ƀât lât ta nây khân păng mƀăr lơi plŭng, nđâp ma mbơ̆ khân păng jêh ri tĭng Brah Yêsu.$b$,false),
('bunong-vn','MAT',4,23,null,$b$Brah Yêsu hăn lam n'gor Galilê, nti tâm ngih tâm rƀŭn Yuđa. Păng nti nau mhe mhan ueh ma ƀon bri hađăch Brah Ndu, jêh ri Păng ƀư bah ăp ntil nau ji kuet ma phung ƀon lan.$b$,true),
('bunong-vn','MAT',4,24,null,$b$Pô ri bu tăng lư n'găr ma Păng lam n'gor Siri bu njŭn leo ma Păng lĕ phung bunuyh ji kuet, geh nau ji kuet êng êng, ƀa ƀă brah mhĭk lơh phung brŭt rluk, phung rvĕn; Păng ƀư bah lĕ rngôch.$b$,false),
('bunong-vn','MAT',4,25,null,$b$Jêh ri geh âk bunuyh tĭng ndô̆ Păng tă bơh n'gor Galilê, tă bơh ƀon Đêkapôlis, bơh ƀon Yêrusalem, bơh n'gor Yuđa kŏ tât ta bri kăl tê̆ dak krong Yurdan.$b$,false),
('bunong-vn','MAT',5,1,null,$b$Brah Yêsu saơ bunuyh âk. Păng hao yôk jêh ri tơ lah Păng gŭ, phung oh mon Păng văch êp Păng.$b$,true),
('bunong-vn','MAT',5,2,null,$b$Jêh ri Brah Yêsu pơk nau ngơi jêh ri nti lah pô aơ:$b$,false),
('bunong-vn','MAT',5,3,null,$b$“Ueh maak ngăn ma phung o ach tâm huêng nuih n'hâm yor lah ƀon bri hađăch Brah Ndu prăp ăn jêh ma khân păng.$b$,false),
('bunong-vn','MAT',5,4,null,$b$“Ueh maak ngăn ma phung geh nau nhĭm rngot, yor lah Brah Ndu mra bonh khân păng.$b$,true),
('bunong-vn','MAT',5,5,null,$b$“Ueh maak ngăn ma phung geh nau dêh rhêt, yor lah khân păng mra sŏk dơn neh.$b$,true),
('bunong-vn','MAT',5,6,null,$b$“Ueh maak ngăn ma phung ji ngot, nđơr ƀư tĭng nâm nau Brah Ndu đă, yor lah Brah Ndu mra n'hơm khân păng.$b$,true),
('bunong-vn','MAT',5,7,null,$b$“Ueh maak ngăn ma phung gĭt nau yô̆, yor lah Brah Ndu mra yô̆ an đŏng ma khân păng.$b$,true),
('bunong-vn','MAT',5,8,null,$b$“Ueh maak ngăn ma phung geh nuih n'hâm kloh ueh, yor lah khân păng mra saơ Brah Ndu.$b$,true),
('bunong-vn','MAT',5,9,null,$b$“Ueh maak ngăn ma phung gĭt tâm kơl nau đăp mpăn ndrăng nơm, yor lah bu mra kuăl khân păng jêng kon Brah Ndu.$b$,true),
('bunong-vn','MAT',5,10,null,$b$“Ueh maak ngăn ma phung bu ƀư mhĭk yor păng tĭng nau Brah Ndu đă, yor lah Brah Ndu mra chiă uănh khân păng tâm bri hađăch Păng.$b$,true),
('bunong-vn','MAT',5,11,null,$b$“Ueh maak ngăn ma khân may tơ lah bu rak suai, ƀư mhĭk mâu lah ngơi nchơt âk ntil nau mhĭk ma khân may, yor khân may tĭng gâp.$b$,true),
('bunong-vn','MAT',5,12,null,$b$Răm hom, maak răm hom ma lĕ nuih n'hâm, yor lah tâm trôk bu hŏ prăp jêh nau nkhôm toyh ma khân may. Phung djôt nau Brah Ndu kăl e, bu hŏ ƀư mhĭk tâm ban pô ri lĕ.”$b$,false),
('bunong-vn','MAT',5,13,null,$b$“Khân ay may jêng boh ma neh ntu; ƀiă lah tơ lah boh mâu hôm kah ôh, mâm bu mra ƀư kah păng? Păng mâu hôm khlay ôh, knŏng nkhŭt lơi pa dih jêh ri bu mra jot păng ma jâng.$b$,true),
('bunong-vn','MAT',5,14,null,$b$Khân ay may jêng nau ang ma neh ntu. Du ƀon toyh gŭ ta klơ yôk prêh mâu dơi ndâp ôh.$b$,false),
('bunong-vn','MAT',5,15,null,$b$Jêh ri bu mâu mpoh ôh ŭnh kđen jêh ri rdêl lơi tâm dâng trôm yăng, ƀiă lah bu kât yông ta n'gâng păng ăn nchrat ang ma lĕ rngôch bunuyh tâm ngih.$b$,false),
('bunong-vn','MAT',5,16,null,$b$Ăn nau ang khân ay may chrat ta năp bunuyh tâm ban lĕ, pô ri mơ khân păng saơ kan ueh khân ay may jêh ri khân păng mât ton ma mbơ̆ khân ay may tâm trôk.$b$,false),
('bunong-vn','MAT',5,17,null,$b$“Lơi mĭn ôh gâp văch ngroh lơi nau vay mâu lah nau phung kôranh nơm mbơh lor hŏ mbơh jêh. Gâp văch mâu di ŭch ngroh lơi ôh ƀiă lah ŭch ƀư n'hêl nanê̆.$b$,true),
('bunong-vn','MAT',5,18,null,$b$Yor lah gâp lah nanê̆ ma khân ay may, dôl trôk jêh ri neh ntu ê hŏ rlau, mâu mra roh du ntil mâu lah du rplay sămƀŭt tâm nau vay ôh. Lĕ rngôch nau nây mra tât ngăn.$b$,false),
('bunong-vn','MAT',5,19,null,$b$Mbu nơm mra rlau du ntil jê̆ jê̆ tâm phung nau vay aơ, jêh ri nti ma bu ƀư pô ri, bu mra kuăl păng jê̆ lơn tâm ƀon bri hađăch Brah Ndu; ƀiă lah mbu nơm tông ma nau vay aơ jêh ri nti ma bu, bu mra kuăl păng toyh lơn tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','MAT',5,20,null,$b$Yor lah gâp lah ma khân ay may, tơ lah nau sŏng srăng khân ay may mâu rlau nau sŏng srăng phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nanê̆ khân ay may mâu mra lăp ôh tâm ƀon bri hađăch Brah Ndu.$b$,true),
('bunong-vn','MAT',5,21,null,$b$“Khân may tăng jêh bu lah ma phung ơm, lơi nkhĭt bunuyh. Jêh ri mbu nơm nkhĭt bunuyh mra dơn nau bu phat dôih.$b$,true),
('bunong-vn','MAT',5,22,null,$b$Ƀiă lah gâp lah ma khân ay may, mbu nơm biănh ma oh nâu păng, mra dơn nau bu phat dôih; mbu nơm ngơi ma oh nâu păng ‘raka’ sôt nuih mra dơn nau bu phat dôih ktang, jêh ri mbu nơm mra lah ma bu, ‘brŭt ndrăng’ mra dơn nau tâm rmal tâm n'gar ŭnh.$b$,true),
('bunong-vn','MAT',5,23,null,$b$Pô ri yơh, tơ lah may djôt leo ndơ nhhơr ma Brah Ndu ta nơng ƀư brah, jêh ri ta nây may kah gĭt ma oh nâu may geh nau mhĭk đah may.$b$,false),
('bunong-vn','MAT',5,24,null,$b$Ăn ndơ may nhhơr pa năp nơng ƀư brah jêh ri hăn nkra ăn soih ndrăng oh nâu may lor, lôch nau nây may dơi plơ̆ văch nhhơr ndơ may.$b$,false),
('bunong-vn','MAT',5,25,null,$b$Gơnh ƀư soih hom đah bunuyh geh nau đah may, dôl may hăn ndrel ma păng, klach lah păng njŭn leo may ma kôranh ndrung, jêh ri bu mra krŭng may.$b$,false),
('bunong-vn','MAT',5,26,null,$b$Nanê̆ gâp lah ma may, may mâu dơi luh ôh tă bơh ndrung kŏ tât may ăn nau tâm chuai rĭng, mâu roh du rêl.$b$,false),
('bunong-vn','MAT',5,27,null,$b$“Khân may tăng jêh nau bu lah: ‘Ver lơi ta văng tĭr.’$b$,true),
('bunong-vn','MAT',5,28,null,$b$Ƀiă lah gâp lah ma khân may, mbu nơm uănh ma bu ur ma nau kơnh, păng văng tĭr jêh đah bu ur nây tâm nuih n'hâm păng.$b$,false),
('bunong-vn','MAT',5,29,null,$b$Pô ri yơh, tơ lah măt pa ma may ƀư tŭp may tâm nau tih, rvek lơi păng jêh ri mƀăr lơi păng ngai tă bơh may; yor lah ueh lơn may roh du kô̆ tâm săk jăn, ma may geh du mlâm săk jăn mƀăr tâm n'gar ŭnh.$b$,false),
('bunong-vn','MAT',5,30,null,$b$Tơ lah ti ma may ƀư tŭp may tâm nau tih, sreh mƀăr lơi păng ngai tă bơh may, yor lah ueh lơn may roh du kô̆ tâm săk jăn, ma may geh du mlâm săk jăn mƀăr tâm n'gar ŭnh.$b$,false),
('bunong-vn','MAT',5,31,null,$b$“Bu lah jêh pô aơ: ‘Tơ lah du huê cha lơi ur păng, ăn păng nchih ma ô băl du pŏk sămƀŭt nau lơi.’$b$,true),
('bunong-vn','MAT',5,32,null,$b$Ƀiă lah gâp lah ma khân may: Mbu nơm cha lơi ur păng mâu di yor ur păng jêng văng tĭr, nơm nây ƀư ma ur păng jêng bu ur văng tĭr jêh; jêh ri mbu nơm gŭ bu ur bu hŏ cha lơi jêh jêng bunuyh văng tĭr tâm ban lĕ.$b$,false),
('bunong-vn','MAT',5,33,null,$b$“Nau nti di nau ton ma nglay săk: ‘Khân may hŏ tăng jêh bu lah ma phung ơm, lơi rlăm ôh nau may ton, ƀiă lah ăn may ƀư n'hêl nanê̆ ta năp Kôranh Brah lĕ rngôch nau may hŏ ton jêh.’$b$,true),
('bunong-vn','MAT',5,34,null,$b$Ƀiă lah gâp lah ma khân may: Lơi ta ton ôh. Lơi ton đah trôk, yor lah trôk jêng sưng hađăch Brah Ndu.$b$,false),
('bunong-vn','MAT',5,35,null,$b$Mâu lĕ ton đah neh, yor lah jêng rnơl Brah Ndu chrong jâng. Mâu đŏng ton đah ƀon Yêrusalem, yor lah ƀon nây jêng ƀon ma Hađăch toyh.$b$,true),
('bunong-vn','MAT',5,36,null,$b$Mâu lĕ ton đah bôk may nơm, yor lah may mâu dơi ôh njêng nglang mâu lah krăk tâm du mbrai sŏk.$b$,false),
('bunong-vn','MAT',5,37,null,$b$Ƀiă lah ăn may ngơi ‘di’ lah ‘di’, ‘mâu’ lah ‘mâu’; jêh ri nau bu ntop ma nau nây luh tă brah mhĭk.$b$,true),
('bunong-vn','MAT',5,38,null,$b$“Khân may tăng jêh nau bu lah: ‘Măt ntrok ma măt, sêk ntrok ma sêk.’$b$,true),
('bunong-vn','MAT',5,39,null,$b$Ƀiă lah gâp lah ma khân may: Lơi khân may tâm rdâng ôh đah bunuyh mhĭk. Ƀiă lah tơ lah bu tap may ta pa ma, ăn pa chiau ma păng tap tâm ban lĕ.$b$,false),
('bunong-vn','MAT',5,40,null,$b$Tơ lah bu phong may ŭch sŏk ao gleh may, ăn păng sŏk nđâp ma ao jong đŏng.$b$,false),
('bunong-vn','MAT',5,41,null,$b$Jêh ri tơ lah bu ŭch nchâp may hăn du vang, ăn may hăn đah păng bar vang.$b$,false),
('bunong-vn','MAT',5,42,null,$b$Ăn hom ma mbu nơm dăn ma may, jêh ri lơi ndôn kơi ma mbu nơm ŭch manh ndơ may.$b$,false),
('bunong-vn','MAT',5,43,null,$b$“Khân may tăng jêh bu lah pô aơ: ‘Ăn may rŏng ma bunuyh chiau meng may, tâm rmot bunuyh rlăng đah may.’$b$,true),
('bunong-vn','MAT',5,44,null,$b$Ƀiă lah gâp lah ma khân may, Ăn may rŏng ma bunuyh rlăng đah may, jêh ri mbơh sơm hom ma phung ƀư mhĭk ma khân may,$b$,false),
('bunong-vn','MAT',5,45,null,$b$gay ma khân may jêng phung kon ma Mbơ̆ khân may gŭ tâm trôk; yor lah Păng ăn nar luh ma phung tih nđâp ma phung ueh, jêh ri păng ăn trôk mih ma phung sŏng nđâp ma phung kue.$b$,false),
('bunong-vn','MAT',5,46,null,$b$Tơ lah khân may rŏng knŏng bunuyh rŏng ma khân may, moh nau nkhôm khân may geh? Mâu di hĕ phung riu pi ƀư nau nâm bu pô nây?$b$,false),
('bunong-vn','MAT',5,47,null,$b$Jêh ri tơ lah khân may knŏng rom oh nâu khân may, moh nau khân may ƀư rlau lơn ma phung êng? Mâu di hĕ phung pa dih ƀư nâm bu pô nây?$b$,false),
('bunong-vn','MAT',5,48,null,$b$Pô ri yơh, ăn khân may jêng bunuyh ueh n'hêl nanê̆ nâm bu Mbơ̆ khân may tâm trôk jêng ueh nanê̆ ngăn.”$b$,false),
('bunong-vn','MAT',6,1,null,$b$“Njrăng hom, lơi ntưih ôh nau sŏng khân may ta năp bunuyh, gay ma khân păng saơ khân may, tơ lah khân may ƀư pô ri khân may mâu geh ôh nau nkhôm tă bơh Mbơ̆ khân may klơ trôk.$b$,true),
('bunong-vn','MAT',6,2,null,$b$“Tơ lah may ăn yô̆ ma bu, lơi uh nŭng ta năp may ôh nâm bu phung bunuyh geh nuih n'hâm ndâp mpôn, ƀư tâm ngih rƀŭn Yuđa jêh ri rŏ trong sâng, gay ma bunuyh yơk. Nanê̆ gâp lah ma khân may, phung nây geh jêh nau nkhôm ma khân păng.$b$,true),
('bunong-vn','MAT',6,3,null,$b$Ƀiă lah tơ lah may ăn yô̆, lơi ăn ôh ti chiau may gĭt mâm nau ti ma may ƀư,$b$,false),
('bunong-vn','MAT',6,4,null,$b$pô ri yơh nau may ăn yô̆ jêng ndâp; jêh ri Mbơ̆ may saơ tâm nau ndâp; păng mra ăn nau nkhôm ma may.”$b$,false),
('bunong-vn','MAT',6,5,null,$b$“Tơ lah khân may mbơh sơm, lơi jêng ôh nâm bu phung bunuyh geh nau mĭn ndâp mpôn; yor lah khân păng ŭch dâk mbơh sơm tâm ngih rƀŭn Yuđa jêh ri ta meng trong, gay ma bu saơ khân păng. Nanê̆ gâp lah ma khân may, khân păng geh jêh nau nkhôm ma khân păng.$b$,true),
('bunong-vn','MAT',6,6,null,$b$Ƀiă lah tơ lah may mbơh sơm, lăp tâm jrô may, nchăng hom mpông, mbơh sơm ma Mbơ̆ may, nơm gŭ tâm ntŭk ndâp; jêh ri Mbơ̆ may, Nơm saơ tâm ntŭk ndâp mra ăn nau nkhôm ma may.$b$,false),
('bunong-vn','MAT',6,7,null,$b$“Tơ lah khân may mbơh sơm, lơi răk rlŏk ƀa ƀơ ôh du ntil nau nây, nâm bu phung pa dih; yor lah khân păng mĭn tơ lah ngơi âk ri mơ Brah Ndu mra dơn.$b$,true),
('bunong-vn','MAT',6,8,null,$b$Pô ri lơi khân may jêng ôh nâm bu khân păng, yor lah Mbơ̆ khân may gĭt jêh moh nau khân may ŭch ê lor ma khân may dăn ndơ nây ma Păng.$b$,false),
('bunong-vn','MAT',6,9,null,$b$Pô ri yơh ăn khân may mbơh sơm pô aơ: ‘Ơ Mbơ̆ hên gŭ tâm trôk ơi, ăn amoh may bu yơk ăn ueh.$b$,false),
('bunong-vn','MAT',6,10,null,$b$Ăn bri hađăch may gơnh tât, ăn nau may ŭch mra jêng ta neh ntu tâm ban ma ta klơ trôk.$b$,true),
('bunong-vn','MAT',6,11,null,$b$Ăn ma hên mpa sông sa nar aơ ăn tŏng,$b$,true),
('bunong-vn','MAT',6,12,null,$b$Yô̆ an ma nau tih hên, tâm ban ma hên yô̆ an jêh ma bunuyh ƀư tih đah hên.$b$,false),
('bunong-vn','MAT',6,13,null,$b$Lơi ta njŭn leo hên tâm nau ndơm ôh, ƀiă lah ăn may rklaih hên bơh nơm tih mhĭk. ‘May yơh jêng hađăch hên bêng ma nau brah jêh ri nau chrêk rmah ƀa ƀơ n'ho ro. Amen!’$b$,true),
('bunong-vn','MAT',6,14,null,$b$“Pô ri, tơ lah khân may yô̆ an ma bunuyh ƀư tih đah khân may, mbơ̆ khân may tâm trôk mra yô̆ an khân may tâm ban đŏng.$b$,false),
('bunong-vn','MAT',6,15,null,$b$Ƀiă lah tơ lah khân may mâu yô̆ an ma bu, Mbơ̆ khân may mâu mra yô̆ an đŏng nau tih khân may.”$b$,false),
('bunong-vn','MAT',6,16,null,$b$“Tơ lah khân may ât sông sa, lơi khân may ƀư ôh muh măt rngot nâm bu phung bunuyh geh nuih n'hâm ndâp mpôn, yor lah khân păng ƀư muh măt rngot, ŭch ăn bunuyh gĭt ma khân păng ât sông sa. Nanê̆ gâp lah ma khân may, khân păng geh jêh nau nkhôm ma khân păng.$b$,true),
('bunong-vn','MAT',6,17,null,$b$Ƀiă lah tơ lah may ât sông sa; mhĭng dak kôlônh ta klơ bôk may, jêh ri rpuh muh măt may,$b$,false),
('bunong-vn','MAT',6,18,null,$b$gay ma bunuyh mâu saơ ôh may ntơm ât sông sa; ƀiă lah knŏng Mbơ̆ may gŭ tâm ntŭk ndâp saơ, jêh ri Mbơ̆ may, nơm saơ tâm ntŭk ndâp mra ăn nau nkhôm ma may.”$b$,false),
('bunong-vn','MAT',6,19,null,$b$“Lơi khân may bun prăp drăp ndơ khlay ta neh ntu aơ, ntŭk geh ndrŭng jêh ri geh ek găm ƀư rai, jêh ri geh phung bunuyh ntŭng lôk mpir, lăp ntŭng.$b$,true),
('bunong-vn','MAT',6,20,null,$b$Ƀiă lah ăn bun prăp drăp ndơ khlay ta klơ trôk, ta nây mâu geh ôh ndrŭng mâu lah ek găm ƀư rai, mâu lĕ geh phung ntŭng dơi lôk mpir jêh ri lăp ntŭng.$b$,false),
('bunong-vn','MAT',6,21,null,$b$Yor lah ta ntŭk drăp ndơ khlay khân may, ta nây đŏng nuih n'hâm khân may mra gŭ.$b$,false),
('bunong-vn','MAT',6,22,null,$b$“Măt jêng ŭnh kđen ma săk jăn. Tơ lah măt may ueh, lĕ săk jăn may mra bêng nau ang;$b$,true),
('bunong-vn','MAT',6,23,null,$b$ƀiă lah tơ lah măt may chieh, lĕ săk jăn may mra ngo. Tơ lah nau ang tâm may jêng ngo, pô ri nau ngo nây toyh ngăn yơh.”$b$,false),
('bunong-vn','MAT',6,24,null,$b$“Mâu dơi ôh du huê pah kan, ma bar hê kôranh yor lah păng mra tâm rmot ma du huê aơ, jêh ri rŏng ma du huê êng. Mâu lah păng mra yơk ma du huê aơ jêh ri mưch ma du huê êng. Khân may mâu dơi ôh pah kan nđâp ma Brah Ndu, jêh ri nđâp ma nau ŭch jêng ndrŏng.”$b$,true),
('bunong-vn','MAT',6,25,null,$b$“Yor nây, Gâp lah ma khân may, lơi yor ma nau rêh khân may rvê ir moh ndơ mra sông sa mâu lah nhêt; lơi yor ma săk jăn khân may rvê ir moh ndơ khân may mra nsoh n'gut. Di lĕ nau rêh khlay lơn ma ndơ sông sa jêh ri săk jăn khlay lơn ma bok ao?$b$,true),
('bunong-vn','MAT',6,26,null,$b$Uănh hom ma phung sĭm tâm trôk khân păng mâu mâp tăm, mâu lĕ khân păng mâp rek, mâu lĕ khân păng bun prăp tâm jay, ƀiă lah mbơ̆ khân may tâm trôk siăm khân păng. Di lĕ khân may khlay lơn ma phung sĭm?$b$,false),
('bunong-vn','MAT',6,27,null,$b$Jêh ri mbu nơm tâm phung khân may ma nau păng rvê ir dơi ƀư njong nau rêh păng du hăt đŏng?$b$,false),
('bunong-vn','MAT',6,28,null,$b$Jêh ri mâm ƀư khân may rvê ir ma bok ao? Uănh hom ma kao si tâm mir mâm khân păng văch ma toyh; khân păng mâu rgănh pah kan, mâu lĕ khân păng mâp tanh;$b$,false),
('bunong-vn','MAT',6,29,null,$b$Ƀiă lah gâp lah ma khân may, hađăch Salamôn tâm lĕ nau chrêk rmah păng mâu dơi geh ôh ao ueh nâm bu du ntil tâm phung kao si nây.$b$,false),
('bunong-vn','MAT',6,30,null,$b$Tơ lah Brah Ndu nsoh ăn nâm bu pô nây ma gơ̆ tâm mir, jêng ndơ nar aơ mâu lah ôi taơ bu mra mƀăr păng tâm ŭnh, pô ri nanê̆ păng mra nsoh ăn khân may âk lơn, hơi phung bunuyh geh nau chroh djê̆.$b$,true),
('bunong-vn','MAT',6,31,null,$b$Pô ri lơi khân may rvê ir ôh jêh ri lah: ‘Moh ndơ hên mra sông sa?’ ‘Moh ndơ hên mra nhêt?’ ‘Moh ndơ hên mra nsoh?’$b$,false),
('bunong-vn','MAT',6,32,null,$b$Yor lah lĕ rngôch ndơ nây phung pa dih joi đŏng? Ƀiă lah Mbơ̆ khân may tâm trôk gĭt jêh moh ndơ khân may ŭch.$b$,false),
('bunong-vn','MAT',6,33,null,$b$Ƀiă lah ăn khân may joi lor lơn ƀon bri hađăch Păng jêh ri nau sŏng Păng, jêh ri lĕ rngôch ndơ nây Păng mra ntop ăn ma khân may.$b$,false),
('bunong-vn','MAT',6,34,null,$b$Lơi khân may rngot rvê ôh ma nar ôi taơ, yor lah nar ôi taơ mra mĭn ma kan tâm nar ôi taơ. Ăp nar mra geh nau jêr tâm ăp nar.”$b$,false),
('bunong-vn','MAT',7,1,null,$b$“Lơi ta khân may phat ôh dôih bu, gay bu mâu phat dôih khân may.$b$,true),
('bunong-vn','MAT',7,2,null,$b$Yor lah tĭng nâm khân may phat dôih bu, bu mra phat dôih khân may tâm ban lĕ, jêh ri ndah rnoh khân may veh ma bu, bu mra veh ma khân may dŭm rnoh nây lĕ.$b$,false),
('bunong-vn','MAT',7,3,null,$b$Mâm ƀư may saơ ndruyh tâm măt oh nâu may, ƀiă lah may mâu saơ ôh rda tơm si tâm măt may nơm?$b$,false),
('bunong-vn','MAT',7,4,null,$b$Mâu lah mâm ƀư may janh lah ma oh nâu may pô aơ: ‘Ăn gâp sŏk lơi ndruyh tă bơh măt may;’ ƀiă lah may nơm ăt geh rda tơm si tâm măt may?$b$,false),
('bunong-vn','MAT',7,5,null,$b$Hơi bunuyh geh nuih n'hâm ndâp, sŏk hom rda tơm si tă bơh măt may lor, ri mơ may mra dơi saơ ang sŏk ndruyh bơh măt oh nâu may.$b$,false),
('bunong-vn','MAT',7,6,null,$b$“Lơi ăn ndơ kloh, ma phung so ôh; mâu lĕ mƀăr nhong khlay khân may pa năp phung sŭr, klach lah păng plơ̆ kăp khân may.”$b$,true),
('bunong-vn','MAT',7,7,null,$b$“Dăn hom dĭng geh; joi hom dĭng saơ; goh hom mpông dĭng bu ma pơk an.$b$,true),
('bunong-vn','MAT',7,8,null,$b$Yor lah mbu nơm dăn mra geh; mbu nơm joi mra saơ, jêh ri mbu nơm goh mpông bu mra pơk ăn ma khân may.$b$,false),
('bunong-vn','MAT',7,9,null,$b$Mbu tâm khân may lah kon dăn kapŭng, păng ăn nkhơng lŭ đŏng?$b$,false),
('bunong-vn','MAT',7,10,null,$b$Mâu lah kon dăn ka păng ăn bêh lĕ?$b$,false),
('bunong-vn','MAT',7,11,null,$b$Nđâp tơ lah khân may jêng bunuyh mhĭk, ăt khân may gĭt lĕ ăn ndơ ueh ma oh kon khân may, lơ hâu ma nĕ đŏng Mbơ̆ khân may klơ trôk mra ăn ndơ ueh ma mbu nơm dăn ma Păng.$b$,false),
('bunong-vn','MAT',7,12,null,$b$“Pô ri yơh, moh nau khân may ŭch ăn bu ƀư ma khân may, ăn khân may ƀư nau nây tâm ban lĕ ma khân păng; nau nây di tĭng nâm nau vay jêh ri nau phung kôranh nơm mbơh lor hŏ nchih jêh.”$b$,true),
('bunong-vn','MAT',7,13,null,$b$“Lăp hom khân may ta mpông pêr huêt, yor lah mpông pêr huy jêh ri trong toyh njŭn leo ma nau rai yot, jêh ri geh âk bunuyh lăp ta trong nây.$b$,true),
('bunong-vn','MAT',7,14,null,$b$Ƀiă lah mpông pêr huêt jêh ri trong jê̆ njŭn leo ma nau rêh, jêh ri djê̆ bunuyh saơ ntŭk nây.”$b$,false),
('bunong-vn','MAT',7,15,null,$b$“Njrăng hom ma khân may ma phung kôranh nơm mbơh lor tih, khân păng mra văch ma khân may njêng nâm bu biăp, ƀiă lah tâm trôm khân păng jêng so bri hay sa.$b$,true),
('bunong-vn','MAT',7,16,null,$b$Khân may mra gĭt năl khân păng ta play khân păng. Mâp geh lĕ bunuyh pĕ play kriăk ƀâu ta tơm lok, mâu lah play rvi ta rtau lok?$b$,false),
('bunong-vn','MAT',7,17,null,$b$Pô ri, ăp tơm si ueh geh play ueh, tơm si mhĭk geh play mhĭk.$b$,false),
('bunong-vn','MAT',7,18,null,$b$Du mlâm tơm si ueh mâu dơi play mhĭk ôh; du mlâm tơm si mhĭk mâu dơi lĕ luh play ueh.$b$,false),
('bunong-vn','MAT',7,19,null,$b$Ăp tơm si mâu geh play ueh bu mra kăl lơi jêh ri mƀăr lơi păng tâm ŭnh.$b$,false),
('bunong-vn','MAT',7,20,null,$b$Pô ri ta play khân păng yơh khân may mra gĭt năl khân păng.”$b$,false),
('bunong-vn','MAT',7,21,null,$b$“Mâu di ôh mbu nơm lah ma gâp: ‘Ơ Kôranh Brah, ơ Kôranh Brah,’ mra lăp tâm ƀon bri hađăch Brah Ndu, ƀiă lah knŏng mbu nơm ƀư tĭng nâm nau Mbơ̆ gâp tâm trôk ŭch.$b$,true),
('bunong-vn','MAT',7,22,null,$b$Âk bunuyh mra lah ma gâp tâm nar nây: ‘Ơ Kôranh Brah, ơ Kôranh Brah, di đŏng hên mâp nti jêh tâm amoh may, hên mâp mprơh jêh brah mhĭk tâm amoh may, jêh ri hên mâp ƀư âk nau khlay tâm amoh may?’$b$,false),
('bunong-vn','MAT',7,23,null,$b$Mông nây gâp mra lah ma khân păng: ‘Hơi phung tih mhĭk, gâp mâu mâp gĭt năl khân may ôh; du hom khân may tă bơh gâp.’ ”$b$,false),
('bunong-vn','MAT',7,24,null,$b$“Pô ri yơh, mbu nơm tăng nau gâp ngơi jêh ri tông mra jêng nâm bu du huê bunuyh blau mĭn ƀư ngih păng ta klơ lŭ.$b$,true),
('bunong-vn','MAT',7,25,null,$b$Geh trôk mih, dak lêng, jêh ri sial ktang ƀư ma ngih nây ƀiă lah ngih mâu rlâm ôh, yor lah bu ƀư păng ta klơ lŭ klêr.$b$,false),
('bunong-vn','MAT',7,26,null,$b$Ƀiă lah mbu nơm tăng nau gâp ngơi jêh ri mâu tông ôh, păng jêng nâm bu du huê bunuyh rluk mâl ƀư ngih păng ta klơ neh choih.$b$,false),
('bunong-vn','MAT',7,27,null,$b$Geh mih, dak lêng jêh ri phŭt sial ktang ƀư ma ngih nây. Păng rlâm jêh ri rai.”$b$,false),
('bunong-vn','MAT',7,28,null,$b$Tơ lah jêh Brah Yêsu ngơi nau nây, phung âk gŭ iăt hih rhâl ngăn,$b$,true),
('bunong-vn','MAT',7,29,null,$b$yor lah păng nti ma khân păng ma nau dơi toyh, mâu di nâm bu phung kôranh nchih sămƀŭt khân păng ôh.$b$,false),
('bunong-vn','MAT',8,1,null,$b$Tơ lah Brah Yêsu trŭnh tă bơh yôk, geh âk bunuyh tĭng Păng.$b$,true),
('bunong-vn','MAT',8,2,null,$b$Aơ, geh du huê bunuyh phŭng sa văch êp, păng chon mon mbah ta năp Brah Yêsu jêh ri lah: “Ơ Kôranh Brah tơ lah may ŭch, dăn may dơi ƀư kloh gâp.”$b$,false),
('bunong-vn','MAT',8,3,null,$b$Brah Yêsu yơr ti, bi păng jêh ri lah: “Gâp ŭch, jêng kloh hom may.” Jêh ri ƀât lât ta nây, phŭng păng bah ro.$b$,false),
('bunong-vn','MAT',8,4,null,$b$Jêh ri Brah Yêsu lah ma păng: “Njrăng hom may, lơi nkoch bri nau aơ ma bu ôh; ƀiă lah hăn hom, mpơl may nơm ma kôranh ƀư brah, jêh ri nhhơr ndơ ƀư brah tĭng nâm nau vay Y-Môis ntăm, gay mbơh nau nây ma khân păng.”$b$,false),
('bunong-vn','MAT',8,5,null,$b$Lah Brah Yêsu lăp ta ƀon Kapernum, geh du huê kôranh ta han văch ta Păng jêh ri lah ma păng pô aơ:$b$,true),
('bunong-vn','MAT',8,6,null,$b$“Ơ Kôranh Brah, oh mon gâp ji gŭ bêch tâm ngih. Păng rvĕn, ji hâu ngăn.”$b$,false),
('bunong-vn','MAT',8,7,null,$b$Brah Yêsu lah ma păng: “Gâp mra hăn ƀư bah păng.”$b$,false),
('bunong-vn','MAT',8,8,null,$b$Kôranh ta han plơ̆ lah: “Ơ Kôranh Brah, gâp mâu khư ôh rom may lăp tâm ngih gâp, ƀiă lah ăn may ngơi knŏng du tong, dơi ƀư bah oh mon gâp ro.$b$,false),
('bunong-vn','MAT',8,9,null,$b$Yor lah gâp nơm jêng tâm dâng bu, jêh ri geh phung ta han tâm dâng gâp. Tơ lah gâp lah ma du huê aơ: Hăn hom! Păng hăn ro, mâu lah ma du huê êng, văch hom! Păng văch ro, jêh ri ma oh mon gâp, ƀư pô aơ păng ƀư ro.”$b$,false),
('bunong-vn','MAT',8,10,null,$b$Tơ lah Brah Yêsu tăng nau kôranh ta han nây ngơi, păng hih rhâl jêh ri lah ma phung tĭng păng pô aơ: “Nanê̆ gâp lah ma khân may, gâp ê hŏ mâp saơ ôh du huê bunuyh tâm bri Israel, geh nau chroh ktang nâm bu pô nây.$b$,false),
('bunong-vn','MAT',8,11,null,$b$Jêh ri gâp lah ma khân may, mra geh âk bunuyh văch tă bơh lơ, tă bơh dâng jêh ri mra gŭ sông sa tâm ƀon bri hađăch Brah Ndu ndrel ma Y-Abraham, Y-Isăk, jêh ri Y-Yakôp,$b$,true),
('bunong-vn','MAT',8,12,null,$b$ƀiă lah phung kon, ƀon nơm bu mra mƀăr khân păng tâm nau ngo pa dih ta nây mra geh nau nhĭm nhhiăng jêh ri nau rket sêk.”$b$,false),
('bunong-vn','MAT',8,13,null,$b$Jêh ri Brah Yêsu lah ma kôranh ta han: “Hăn hom may, mra geh tĭng nâm nau chroh.” Jêh ri ta mông nây ro oh mon păng bah.$b$,false),
('bunong-vn','MAT',8,14,null,$b$Jêh Brah Yêsu lăp tâm ngih Y-Pêtrôs, Păng saơ po bu ur Pêtrôs gŭ bêch ji.$b$,true),
('bunong-vn','MAT',8,15,null,$b$Păng pah ti Păng, jêh ri nau ji păng bah ro. Păng dâk jêh ri kơl kan khân păng.$b$,false),
('bunong-vn','MAT',8,16,null,$b$Tơ lah măng jêh bu njŭn leo ma Brah Yêsu âk bunuyh brah mhĭk lơh, jêh ri Păng nsot brah mhĭk ma nau Păng ngơi. Păng ƀư bah đŏng lĕ rngôch phung ji kuet.$b$,true),
('bunong-vn','MAT',8,17,null,$b$Pô ri yơh n'hêl nanê̆ ngăn nau kôranh nơm mbơh lor, Y-Êsai, hŏ mbơh jêh: “Păng sŏk lơi lĕ nau ji tă bơh he, tuy nau ji kuet he.”$b$,false),
('bunong-vn','MAT',8,18,null,$b$Tơ lah Brah Yêsu saơ âk bunuyh jŭm Păng, Păng dâk rgăn kơh kăl tê̆.$b$,false),
('bunong-vn','MAT',8,19,null,$b$Dôl nây geh du huê kôranh nchih sămƀŭt hăn êp Păng jêh ri lah ma Păng: “Hơi Kôranh nơm nti ơi, gâp mra tĭng may ta ntŭk may hăn.”$b$,false),
('bunong-vn','MAT',8,20,null,$b$Brah Yêsu lah ma păng: “Phung mpik geh trôm, jêh ri phung sĭm tâm trôk geh rsuăn, ƀiă lah kon bunuyh mâu geh ntŭk dâm bôk ôh.”$b$,true),
('bunong-vn','MAT',8,21,null,$b$Geh du huê tâm phung oh mon Păng lah ma Păng: “Ơ Kôranh Brah. Ăn gâp hăn tâp lơi mbơ̆ gâp lor.”$b$,false),
('bunong-vn','MAT',8,22,null,$b$Ƀiă lah Brah Yêsu lah ma păng: “Tĭng hom gâp, jêh ri ăn phung khĭt tâp êng bunuyh khĭt khân păng nơm.”$b$,false),
('bunong-vn','MAT',8,23,null,$b$Jêh ta nây Păng ncho plŭng, jêh ri phung oh mon Păng tĭng Păng.$b$,true),
('bunong-vn','MAT',8,24,null,$b$Aơ, geh sial vănh blông ktang ngăn ta dak mƀŭt, jêh ri geh dak n'gŏch gay ƀư nkrâm lơi plŭng khân păng, ƀiă lah Brah Yêsu gŭ bêch.$b$,false),
('bunong-vn','MAT',8,25,null,$b$Phung oh mon hăn dăch Păng rlay Păng, jêh ri lah: “Ơ Kôranh Brah ơi tâm rklaih hên, he mra khĭt yơh!”$b$,false),
('bunong-vn','MAT',8,26,null,$b$Brah Yêsu lah ma khân păng: “Hơi phung geh djê̆ lê̆ nau chroh, mâm ƀư khân may klach?” Brah Yêsu dâk, buay sial jêh ri dak mƀŭt, jêh ri geh nau rngân yơh.$b$,false),
('bunong-vn','MAT',8,27,null,$b$Phung nây bêng ma nau hih rhâl, khân păng lah: “Mbu moh bunuyh aơ, sial nđâp ma dak mƀŭt tông nau păng da dê?”$b$,false),
('bunong-vn','MAT',8,28,null,$b$Tơ lah Păng tât jêh, ta kơh kăl tê̆, tâm n'gor phung Gađara, Păng mâp bar hê bunuyh brah mhĭk lơh. Khân păng luh văch tă bơh môch, uănh janh ngăn tât mâu geh bunuyh janh prot găn ta trong nây ôh.$b$,true),
('bunong-vn','MAT',8,29,null,$b$Khân Păng lŭng nter pô aơ: “Moh nau hên geh đah may, ơ Kon Brah Ndu? Di lĕ may tât ta aơ ŭch tâm rmal hên, ê lor tât nar phat dôih?”$b$,true),
('bunong-vn','MAT',8,30,null,$b$Dôl nây geh phung sŭr gŭ sa mpa ngai djê̆ đah nĕ.$b$,false),
('bunong-vn','MAT',8,31,null,$b$Jêh ri phung brah mhĭk dăn ma Brah Yêsu pô aơ: “Tơ lah may mprơh nsot hên, ăn hên lăp tâm phung sŭr ta ri.”$b$,false),
('bunong-vn','MAT',8,32,null,$b$Brah Yêsu lah ma khân păng: “Du hom!” Pô ri phung brah mhĭk luh du jêh ri khân păng hăn lăp tâm phung sŭr ro? Ƀât lât ta nây lĕ rngôch sŭr, du tă bơh yôk leo ta kơh sop, nklăch săk tâm dak mƀŭt dak bŭk khĭt lĕ rngôch.$b$,false),
('bunong-vn','MAT',8,33,null,$b$Pô ri phung mât sŭr nây du jêh, jêh ri khân păng hăn ta ƀon mbơh lĕ, moh nau tât ma sŭr, jêh ri mâm nau tât ma phung bar hê brah mhĭk lơh.$b$,false),
('bunong-vn','MAT',8,34,null,$b$Ƀât lât ta nây, lĕ rngôch bunuyh ƀon lan nây hăn tâm mâp ma Brah Yêsu, tơ lah saơ jêh Brah Yêsu, khân păng dăn ma Păng ăn du hom tă bơh ƀon khân păng.$b$,false),
('bunong-vn','MAT',9,1,null,$b$Brah Yêsu ncho plŭng, rgăn dak mƀŭt, jêh ri plơ̆ ta ƀon Păng nơm.$b$,true),
('bunong-vn','MAT',9,2,null,$b$Jêh ri aơ, bu tung njŭn ma Păng du huê bunuyh rvĕn gŭ bêch ta sưng. Brah Yêsu saơ nau rnơm phung nây. Păng lah ma bunuyh rvĕn: “Hơi kon gâp ơi, maak hom may yor lah nau tih may yô̆ an jêh.”$b$,false),
('bunong-vn','MAT',9,3,null,$b$Dôl nây geh phung kôranh nchih sămƀŭt, mĭn tâm nuih n'hâm khân păng: “Bunuyh aơ ngơi sưr.”$b$,false),
('bunong-vn','MAT',9,4,null,$b$Ƀiă lah Brah Yêsu hŏ gĭt jêh nau mĭn khân păng lah pô aơ: “Mâm ƀư khân may geh nau mĭn mhĭk pô ri tâm nuih n'hâm khân may?$b$,false),
('bunong-vn','MAT',9,5,null,$b$Moh nau ngơi di lơn: ‘Nau tih may yô̆ an jêh!’ Mâu lah. ‘Dâk hom may jêh ri hăn.’$b$,false),
('bunong-vn','MAT',9,6,null,$b$Ƀiă lah ŭch ăn khân may gĭt ma Kon Bunuyh ta neh ntu aơ dơi yô̆ an nau tih” Brah Yêsu lah tay ma bunuyh rvĕn “Dâk hom may, sŏk sưng may, jêh ri sĭt ta ngih may.”$b$,false),
('bunong-vn','MAT',9,7,null,$b$Pô ri păng dâk ro, jêh ri sĭt ma ngih.$b$,false),
('bunong-vn','MAT',9,8,null,$b$Saơ nau khlay nây, phung bunuyh âk klach ngăn jêh ri khân păng mât ton ma Brah Ndu, yor lah Păng ăn nau dơi nâm bu pô nây ma bunuyh.$b$,false),
('bunong-vn','MAT',9,9,null,$b$Brah Yêsu du tă bơh nây. Păng saơ du huê bunuyh amoh păng Y-Mathiơ, gŭ ta sưng riu pi, Brah Yêsu lah ma păng: “Tĭng gâp!” Păng dâk jêh ri tĭng Brah Yêsu ro.$b$,true),
('bunong-vn','MAT',9,10,null,$b$Dôl Brah Yêsu gŭ sông sa ta ngih Y-Mathiơ, geh âk phung riu pi jêh ri phung tih hăn gŭ sông sa ndrel ma Brah Yêsu, jêh ri phung oh mon Păng ta nây.$b$,true),
('bunong-vn','MAT',9,11,null,$b$Phung Pharisi saơ pô nây, khân păng lah ma phung oh mon Brah Yêsu: “Mâm ƀư kôranh nơm nti khân may, sông sa ndrel ma phung riu pi, jêh ri đah phung tih?”$b$,false),
('bunong-vn','MAT',9,12,null,$b$Brah Yêsu tăng nau nây jêh ri lah ma khân păng: “Mâu di phung ngăch săk jăn ôh ŭch ma nai dak si, ƀiă lah phung ji kuet.$b$,false),
('bunong-vn','MAT',9,13,null,$b$Hăn hom jêh ri nti ăn gĭt nâm bu ntĭt nau ngơi aơ: Gâp ŭch nau yô̆ an, mâu di ndơ ƀư brah ôh. Yor lah gâp văch mâu di ŭch kuăl phung sŏng ôh, ƀiă lah phung tih.”$b$,false),
('bunong-vn','MAT',9,14,null,$b$Dôl nây phung oh mon Y-Yôhan hăn ta Brah Yêsu jêh ri lah: “Mâm ƀư hên jêh ri phung Pharisi ât sông sa, ƀiă lah phung oh mon may mâu ât sông sa ôh?”$b$,false),
('bunong-vn','MAT',9,15,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Phung mĭt jiăng bu klâu ntơm gŭ ur, dơi lĕ ât sông sa dôl bu klâu nây gŭ ndrel đah khân păng? Ƀiă lah tât ta nar bu kuăl bu klâu nây du tă bơh khân păng, khân păng mra ât sông sa.$b$,false),
('bunong-vn','MAT',9,16,null,$b$Mâu mâp ôh geh bunuyh koh du blah bok mhe ŭch jĭm ndop ta du blah bok ơm, yor lah bok mhe mra ƀư sat bok ơm jêh ri trôm sat mra khêk huy lơn.$b$,true),
('bunong-vn','MAT',9,17,null,$b$Mâu lĕ bu troch dak play kriăk ƀâu mhe tâm dŭng ntâu ơm tơ lah troch pô nây dŭng mra rai, ƀiă lah bu troch dak play kriăk ƀâu mhe tâm dŭng mhe, jêh ri bu dơi prăp lĕ bar ăn ueh.”$b$,false),
('bunong-vn','MAT',9,18,null,$b$Dôl păng gŭ ngơi nau nây, geh du huê kôranh ngih brah, văch chon mon mbah ta năp Păng jêh ri lah pô aơ: “Kon bu ur gâp khĭt jêh mhe aơ pơ, văch hom, pah ti may ta păng jêh ri păng mra rêh tay.”$b$,true),
('bunong-vn','MAT',9,19,null,$b$Brah Yêsu dâk tĭng kôranh ngih brah nây ndrel ma phung oh mon păng.$b$,false),
('bunong-vn','MAT',9,20,null,$b$Jêh ri aơ, geh du huê bu ur ji rih geh jât ma bar năm jêh, hăn êp pa kơi Păng jêh ri pah ta n'gar ao Brah Yêsu.$b$,true),
('bunong-vn','MAT',9,21,null,$b$Yor lah păng mĭn tâm nuih n'hâm păng: “Tơ lah gâp pah ta ao Păng, gâp mra bah ro.”$b$,false),
('bunong-vn','MAT',9,22,null,$b$Brah Yêsu n'gĭl uănh ma păng jêh ri lah: “Maak hom ay, hơi kon bu ur gâp, nau chroh ay yơh ƀư bah ay jêh.” Jêh ri mông nây ro bu ur bah nau ji păng.$b$,false),
('bunong-vn','MAT',9,23,null,$b$Tơ lah Brah Yêsu tât ta ngih kôranh ngih brah, Păng saơ phung uh nŭng, uh mbuăt jêh ri bunuyh âk ƀư nhau nhau,$b$,true),
('bunong-vn','MAT',9,24,null,$b$Păng lah ma phung nây: “Luh hom khân ay may, bu ur jê̆ aơ mâu khĭt ôh, păng bêch.” Pô ri lĕ rngôch bunuyh mưch ma Păng.$b$,false),
('bunong-vn','MAT',9,25,null,$b$Jêh phung âk luh pa dih Brah Yêsu lăp, kuăn ti bu ur jê̆ nây jêh ri păng dâk ro.$b$,false),
('bunong-vn','MAT',9,26,null,$b$Jêh ri nau mhe mhan ueh aơ lư lam n'gor nây.$b$,false),
('bunong-vn','MAT',9,27,null,$b$Dôl Brah Yêsu du tă bơh ntŭk nây, geh bar hê bunuyh chieh măt groi pa kơi Păng ma nau nter lah: “Hơi kon Đavit, yô̆ an ma hên ƀă.”$b$,true),
('bunong-vn','MAT',9,28,null,$b$Jêh Păng lăp tâm ngih, phung bunuyh chieh măt nây văch, jêh ri Brah Yêsu lah ma khân păng: “Khân may rnơm lĕ gâp dơi ƀư nau khân may ŭch?” Khân păng lah: “Hơi Kôranh, hên rnơm ngăn.”$b$,false),
('bunong-vn','MAT',9,29,null,$b$Brah Yêsu bi măt khân păng jêh ri lah: “Ăn nau aơ tât ngăn, tĭng nâm nau khân may chroh.”$b$,true),
('bunong-vn','MAT',9,30,null,$b$Jêh pah, măt khân păng lin ro. Brah Yêsu lah ma: “Khân păng ma nau săr lah, njrăng hom, lơi ăn bunuyh êng gĭt ôh nau aơ.”$b$,false),
('bunong-vn','MAT',9,31,null,$b$Ƀiă lah jêh khân păng luh pa dih, khân păng mbơh nau lư n'găr Brah Yêsu lam bri nây.$b$,false),
('bunong-vn','MAT',9,32,null,$b$Dôl khân păng luh, bu njŭn ma Brah Yêsu du huê bunuyh mlo brah mhĭk lơh.$b$,true),
('bunong-vn','MAT',9,33,null,$b$Tơ lah brah djơh luh jêh, bunuyh mlo nây blau ngơi. Phung âk gŭ ta nây hih rhâl, jêh ri lah: “Mâu, mâu mâp saơ ôh nau aơ tâm bri Israel.”$b$,true),
('bunong-vn','MAT',9,34,null,$b$Ƀiă lah phung Pharisi lah: “Păng mprơh brah mhĭk tâm amoh kon hađăch brah mhĭk.”$b$,false),
('bunong-vn','MAT',9,35,null,$b$Brah Yêsu hăn tâm ăp ƀon toyh ƀon jê̆, nti tâm ngih rƀŭn Yuđa nau mhe mhan ueh ƀon bri hađăch Brah Ndu, jêh ri ƀư bah ăp ntil nau ji.$b$,true),
('bunong-vn','MAT',9,36,null,$b$Tơ lah saơ phung âk Brah Yêsu geh nau yô̆ ma khân păng, yor lah khân păng jêng rêh ni jêh ri nhhơt nkhah du êng êng nâm bu phung biăp mâu geh rmăk.$b$,false),
('bunong-vn','MAT',9,37,null,$b$Jêh nây Brah Yêsu lah ma phung oh mon Păng: “Geh âk ba ŭch rek, ƀiă lah geh djê̆ bunuyh rek.$b$,false),
('bunong-vn','MAT',9,38,null,$b$Pô ri yơh, dăn hom ma kôranh mir ăn păng njuăl hom bunuyh hăn rek.”$b$,false),
('bunong-vn','MAT',10,1,null,$b$Brah Yêsu kuăl phung jât ma bar oh mon Păng, jêh ri Păng ăn ma khân păng nau brah dơi nsot brah mhĭk, jêh ri dơi ƀư bah nau ji ăp ntil.$b$,true),
('bunong-vn','MAT',10,2,null,$b$Amoh săk phung tĭng ma bar oh mon nâm bu pô aơ. Lor lơn Y-Simôn, tâm amoh Y-Pêtrôs, jêh ri Y-Andrê, oh păng; Y-Yakơ, kon Y-Sêƀêđê, jêh ri Y-Yôhan, oh păng;$b$,false),
('bunong-vn','MAT',10,3,null,$b$Y-Philip jêh ri Y-Ƀartêlômi. Y-Thômas jêh ri Y-Mathiơ, nơm riu pi; Y-Yakơ, kon Y-Alphê, jêh ri Y-Thadê.$b$,false),
('bunong-vn','MAT',10,4,null,$b$Y-Simôn, bunuyh n'gor Kanaan jêh ri Y-Yuđas Iskariôt, nơm ƀư rlăng ma Brah Yêsu.$b$,false),
('bunong-vn','MAT',10,5,null,$b$Dŭm rĭ yơh phung jât ma bar oh mon Brah Yêsu njuăl hăn, jêh ri Păng ntăm ma khân păng pô aơ: “Lơi hăn ôh mpeh phung n'gor bu năch, jêh ri lơi lăp tâm ƀon phung Samari.$b$,true),
('bunong-vn','MAT',10,6,null,$b$Ƀiă lah ueh lơn hăn ta phung biăp roh tâm ngih phung Israel.$b$,false),
('bunong-vn','MAT',10,7,null,$b$Jêh ri rŏ trong ăn khân may nti lah: ‘Ƀon bri hađăch Brah Ndu dăch tât jêh!’$b$,false),
('bunong-vn','MAT',10,8,null,$b$Ăn khân may ƀư bah phung bunuyh ji kuet ji rôi, ăn dâk rêh phung bunuyh khĭt, ƀư bah phung bunuyh geh phŭng jêh ri nsot phung brah mhĭk. Khân may hŏ sŏk dơn jêh dơm dam, ăn hom ma bu dơm dam tâm ban lĕ.$b$,false),
('bunong-vn','MAT',10,9,null,$b$Lơi khân may djôt ndrel khân may, mah, prăk, mâu lah luy tâm dŭng khân may ôh.$b$,false),
('bunong-vn','MAT',10,10,null,$b$Lơi khân may djôt ndrel khân may dŭng, bar blah ao, ntâu jot jêh ri mâng jra ôh; yor lah tơ lah bunuyh pah kan păng khư geh ndơ sông sa.$b$,false),
('bunong-vn','MAT',10,11,null,$b$Tâm ƀon toyh mâu lah ƀon jê̆ khân may lăp, ôp hom mbu nơm khư rom khân may, jêh ri ăn khân may gŭ tâm ngih păng tât nar khân may luh du.$b$,false),
('bunong-vn','MAT',10,12,null,$b$Tơ lah mbu moh ngih khân may lăp, ăn khân may mât ton ma ngih nây.$b$,false),
('bunong-vn','MAT',10,13,null,$b$Tơ lah ngih nây dơi khư, ăn nau đăp mpăn khân may trŭnh ta ngih nây; ƀiă lah tơ lah ngih nây mâu dơi khư ôh, ăn nau đăp mpăn khân may mplơ̆ ma khân may nơm.$b$,false),
('bunong-vn','MAT',10,14,null,$b$Tơ lah bu mâu rom khân may, mâu lah mâu bu iăt nau khân may ngơi, tơ lah luh tă bơh ngih nây mâu lah ƀon nây, rtuh lơi hom ndruyh jâng khân may.$b$,false),
('bunong-vn','MAT',10,15,null,$b$Nanê̆ gâp lah ma khân may, ta nar phat dôih pa kơi ƀon Sôdôm jêh ri ƀon Gômôrơ mra geh nau tâm rmal n'gơch lơn ma ƀon nây.”$b$,false),
('bunong-vn','MAT',10,16,null,$b$“Aơ, gâp njuăl khân may nâm bu biăp lăp ta nklang phung so bri; ăn khân may blau njrăng nâm bu bêh, jêh ri kloh nâm bu plŭk.$b$,true),
('bunong-vn','MAT',10,17,null,$b$Ƀiă lah njrăng hom khân may ma phung bunuyh; yor lah khân păng mra nhŭp njŭn khân may ta ngih phat dôih, jêh ri mra lơh khân may ktang tâm ngih rƀŭn Yuđa.$b$,false),
('bunong-vn','MAT',10,18,null,$b$Bu mra njŭn khân may ta năp phung kôranh n'gor, jêh ri ta năp phung hađăch yor gâp, gay mbơh ta năp khân păng jêh ri ta năp âk ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','MAT',10,19,null,$b$Ƀiă lah tơ lah bu nhŭp khân may, lơi khân may rvê ôh moh ntil nau khân may mra ngơi mâu lah moh nau khân may mra lah; yor lah mâm nau khân may mra ngơi, mra mpơl ma khân may mông nây ro.$b$,true),
('bunong-vn','MAT',10,20,null,$b$Yor lah mâu di khân may ôh ngơi, ƀiă lah Brah Huêng Ueh Mbơ̆ khân may ngơi tâm khân may.$b$,false),
('bunong-vn','MAT',10,21,null,$b$Nâu mra jao oh păng nơm ma bu ƀư nkhĭt, jêh ri Mbơ̆ mra jao Kon Păng nơm. Phung kon mra rlơ̆ ƀư rlăng đah mê̆ mbơ̆ khân păng, jêh ri ăn bu nkhĭt lơi khân păng.$b$,false),
('bunong-vn','MAT',10,22,null,$b$Lĕ rngôch bunuyh mra tâm rmot ma khân may yor amoh gâp; ƀiă lah mbu nơm srôih tât ta nar lôch mra klaih.$b$,false),
('bunong-vn','MAT',10,23,null,$b$Tơ lah khân păng ƀư mhĭk ma khân may tâm du ƀon, ăn khân may der du ta ƀon êng; yor lah gâp lah nanê̆ ma khân may, ê hŏ lam ôh khân may hăn tâm ƀon Israel, tât Kon Bunuyh mra plơ̆ .”$b$,false),
('bunong-vn','MAT',10,24,null,$b$“Oh mon mâu toyh lơn ma kôranh nơm nti păng ôh. Oh mon mâu lĕ toyh lơn ma kôranh păng;$b$,true),
('bunong-vn','MAT',10,25,null,$b$tơ lah oh mon jêng nâm bu kôranh nơm nti păng, jêh ri tơ lah oh mon jêng nâm bu kôranh păng kđôi lĕ. Tơ lah bu tâm amoh Bêlsêbul ma kôranh ngih, nanê̆ bu mra tâm amoh phung tâm ngih nây tâm ban lĕ.$b$,false),
('bunong-vn','MAT',10,26,null,$b$Pô ri lơi klach ôh; yor lah mâu geh ôh ndơ ndâp mâu mra mpơl, jêh ri mâu geh ôh nau ndâp mâu mra gĭt.$b$,false),
('bunong-vn','MAT',10,27,null,$b$Pô ri moh nau Gâp lah ma khân may tâm ntŭk ngo, mbơh hom tâm ntŭk ang; jêh ri moh nau khân may tăng jêh tâm tôr khân may, mbơh hom ta klơ chor ngih.$b$,true),
('bunong-vn','MAT',10,28,null,$b$Lơi klach ôh ma nơm dơi nkhĭt săk jăn, ƀiă lah mâu dơi nkhĭt huêng; ƀiă lah ăn khân may klach ma nơm dơi nkhĭt huêng jêh ri săk jăn tâm ndrung ŭnh.$b$,false),
('bunong-vn','MAT',10,29,null,$b$Bu mâu tăch ôh bar mlâm sĭm jê̆ du luy? Jêh ri mâu mâp geh ôh du mlâm sĭm tŭp ta neh, tơ lah mâu tĭng nau Mbơ̆ may ŭch.$b$,false),
('bunong-vn','MAT',10,30,null,$b$Sŏk ta klơ bôk khân may bu hŏ kơp jêh.$b$,false),
('bunong-vn','MAT',10,31,null,$b$Pô ri lơi klach ôh; khân may khlay lơn ma âk phung sĭm jê̆.$b$,false),
('bunong-vn','MAT',10,32,null,$b$Yor nây mbu nơm mbơh amoh gâp ta năp bunuyh, gâp mra mbơh lĕ nơm nây ta năp Mbơ̆ gâp tâm trôk.$b$,false),
('bunong-vn','MAT',10,33,null,$b$Ƀiă lah mbu nơm mra dun gâp ta năp bunuyh, gâp mra dun nơm nây tâm ban lĕ ta năp Mbơ̆ gâp tâm trôk.$b$,false),
('bunong-vn','MAT',10,34,null,$b$“Lơi mĭn ôh gâp văch djôt nau đăp mpăn ta neh ntu; gâp văch djôt mâu di nau đăp mpăn ƀiă lah tak đao.$b$,true),
('bunong-vn','MAT',10,35,null,$b$Gâp văch djôt nau tâm nkhah kon bu klâu đah mbơ̆ păng, jêh ri kon bu ur đah mê̆ păng, jêh ri ƀăn păng đah po bu ur păng;$b$,false),
('bunong-vn','MAT',10,36,null,$b$jêh ri bu mra geh nơm rlăng tâm ngih păng nơm.$b$,false),
('bunong-vn','MAT',10,37,null,$b$Mbu nơm rŏng ma mê̆ mbơ̆ păng âk lơn ma gâp, nơm nây mâu khư ma gâp ôh; mbu nơm rŏng kon bu klâu kon bu ur păng âk lơn ma gâp, păng nây mâu khư ma gâp ôh.$b$,false),
('bunong-vn','MAT',10,38,null,$b$Jêh ri mbu nơm mâu tuy si tâm rkăng păng tĭng gâp, păng nây mâu khư ma gâp ôh.$b$,true),
('bunong-vn','MAT',10,39,null,$b$Mbu nơm prăp kuan nau rêh păng nơm, nau rêh păng roh, ƀiă lah mbu nơm ƀư roh lơi nau rêh păng nơm, yor ma gâp, mra saơ đŏng.$b$,false),
('bunong-vn','MAT',10,40,null,$b$“Mbu nơm rom khân may nâm bu păng rom gâp, jêh ri mbu nơm rom gâp nâm bu păng rom nơm njuăl gâp văch.$b$,true),
('bunong-vn','MAT',10,41,null,$b$Mbu nơm rom du huê kôranh mbơh lor, yor lah păng jêng kôranh nơm mbơh lor, păng mra sŏk dơn nau nkhôm nâm bu kôranh nơm mbơh lor, jêh ri mbu nơm rom du huê bunuyh sŏng, yor lah păng jêng bunuyh sŏng, mra sŏk dơn nau nkhôm nâm bu du huê bunuyh sŏng lĕ.$b$,false),
('bunong-vn','MAT',10,42,null,$b$Mbu nơm ăn ma du huê tâm phung jê̆ aơ nhêt du kchok dak me, yor lah nơm jê nây jêng oh mon gâp, nanê̆ gâp lah ma khân may, nơm ăn nây mâu roh nau nkhôm ma păng ôh.”$b$,false),
('bunong-vn','MAT',11,1,null,$b$Jêh Brah Yêsu nti nau nây ma phung jât ma bar oh mon, păng hăn tă bơh nây gay ma nti tâm âk ƀon êng.$b$,true),
('bunong-vn','MAT',11,2,null,$b$Dôl Y-Yôhan gŭ tâm ndrung bu nă, păng lư bu nkoch bri kan Brah Yêsu Krist. Păng prơh njuăl phung oh mon Păng.$b$,true),
('bunong-vn','MAT',11,3,null,$b$Ôp ma Brah Yêsu pô aơ: “Di lĕ may jêng nơm mra văch, mâu lah hên ăt kâp gân nơm êng?”$b$,false),
('bunong-vn','MAT',11,4,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Hăn mbơh ma Y-Yôhan mâm nau khân may tăng, jêh ri saơ.$b$,true),
('bunong-vn','MAT',11,5,null,$b$Phung chieh măt dơi saơ ang, phung kuet jâng dơi blau hăn, phung geh phŭng dơi bah, phung tê̆ k dơi tăng, phung khĭt dơi dâk rêh, jêh ri nau mhe mhan ueh mbơh jêh ma phung o ach.$b$,false),
('bunong-vn','MAT',11,6,null,$b$Ueh maak yơh ma mbu nơm mâu vĭ ôh yor ma gâp.”$b$,false),
('bunong-vn','MAT',11,7,null,$b$Dôl khân păng sĭt, Brah Yêsu ntơm ngơi đah phung âk ma nau Y-Yôhan: “Moh ndơ khân may hŏ hăn uănh tâm bri rdah? Du mlâm tơm treng geh sial khôm rgu lĕ?$b$,true),
('bunong-vn','MAT',11,8,null,$b$Ƀiă lah moh ndơ khân may hăn uănh? Di lĕ uănh du huê bunuyh nsoh ao dŭt ueh? Đơ phung nsoh ao dŭt ueh gŭ tâm ngih hađăch.$b$,false),
('bunong-vn','MAT',11,9,null,$b$Moh ndơ khân may hăn uănh? Ŭch uănh du huê kôranh nơm mbơh lor ƀơh? Ơ, gâp lah ma khân may, Nơm toyh lơn ma du huê kôranh nơm mbơh lor.$b$,true),
('bunong-vn','MAT',11,10,null,$b$Ma Nơm nây bu nchih lor jêh: ‘Aơ, gâp njuăl bunuyh hăn mbơh gâp pa năp may, Nơm nkra trong lor ma may.’$b$,false),
('bunong-vn','MAT',11,11,null,$b$Nanê̆ gâp lah ma khân may, đơ phung deh tă bơh bu ur, mâu geh nơm toyh lơn ma Y-Yôhan nơm ƀư ƀaptem ôh. Ƀiă lah nơm jê̆ lơn tâm ƀon bri hađăch Brah Ndu jêng toyh lơn ma păng.$b$,false),
('bunong-vn','MAT',11,12,null,$b$Ƀiă lah ntơm bơh nar Y-Yôhan ƀư ƀaptem tât aƀaơ, ƀon bri hađăch Brah Ndu jêng rhăt, jêh ri phung ktang pit lăp tâm ntŭk nây.$b$,false),
('bunong-vn','MAT',11,13,null,$b$Yor lah lĕ rngôch phung kôranh mbơh lor, jêh ri nau vay mbơh jêh ê lor tât ta rnôk Y-Yôhan.$b$,false),
('bunong-vn','MAT',11,14,null,$b$Jêh ri tơ lah khân may mra dơn nau aơ, păng yơh Y-Êli, nơm mra văch.$b$,true),
('bunong-vn','MAT',11,15,null,$b$Mbu nơm geh tôr iăt hom:$b$,false),
('bunong-vn','MAT',11,16,null,$b$“Mbu đah gâp mra tâm rđĭl phung bunuyh rnôk aơ? Khân păng nâm bu phung kon se gŭ ta nklang ngih tăch drăp, nter ma mpôl băl păng pô aơ,$b$,false),
('bunong-vn','MAT',11,17,null,$b$‘hên uh jêh mbuăt, ƀiă lah khân may mâu ntlơ̆ ntlơn ôh; hên mprơ rngot ƀiă lah khân may mâu nhhiăng nhĭm ôh.’$b$,false),
('bunong-vn','MAT',11,18,null,$b$Yor lah Y-Yôhan văch jêh mâu sông sa mâu lĕ nhêt, pô ri bu lah: ‘Păng geh brah mhĭk ƀư ma Păng.’$b$,false),
('bunong-vn','MAT',11,19,null,$b$Kon Bunuyh văch jêh sông sa nhêt pô ri bu lah: ‘Uănh hom, du huê bunuyh nhêt sông âk, jêng mĭt jiăng đah phung riu pi jêh ri phung tih!’ Ƀiă lah bu kơp sŏng nau blau mĭn ta kan păng pah.”$b$,false),
('bunong-vn','MAT',11,20,null,$b$Yor lah tâm phung ƀon Brah Yêsu hŏ ƀư jêh âk nau khlay, jêh ri khân păng mâu rmal ôh nau tih khân păng, pô ri Brah Yêsu ntơm nduyh ma khân păng pô aơ:$b$,true),
('bunong-vn','MAT',11,21,null,$b$“Rêh ni yơh ma may, hơi ƀon Kôrasin! Rêh ni yơh ma may, hơi ƀon Ƀêtsaiđa! Yor lah nau mbên khlay bu ƀư jêh ta nklang khân may, tơ lah bu ƀư nâm bu ta ƀon Tyr jêh ri ƀon Sidôn, nanê̆ jŏ jêh khân păng rmal nau tih khân păng, ma nau nsoh ao dŭr sui ŭnh buh.$b$,false),
('bunong-vn','MAT',11,22,null,$b$Pô ri gâp mbơh ma khân may, ƀon Tyr jêh ri ƀon Sidôn mra geh nau tâm rmal n'gơch lơn ma khân may tâm nar phat dôih pa kơi.$b$,false),
('bunong-vn','MAT',11,23,null,$b$Bi may, hơi ƀon Kapernum, bu n'hao jêh may tât ta klơ trôk? May mra ntrŭnh tât ta ƀon phung khĭt: Yor lah nau mbên khlay bu ƀư jêh ta nklang may, tơ lah bu ƀư nâm bu ta ƀon Sôdôm nanê̆ păng ăt hôm tât ta nar aơ.$b$,false),
('bunong-vn','MAT',11,24,null,$b$Pô ri gâp mbơh ma khân may, ƀon Sôdôm mra geh nau tâm rmal n'gơch lơn tâm nar phat dôih pa kơi.”$b$,false),
('bunong-vn','MAT',11,25,null,$b$Dôl nây Brah Yêsu ngơi pô aơ: “Gâp tâm rnê ma may, ơ Mbơ̆ gâp, Kôranh trôk jêh ri neh ntu, yor lah may pôn jêh nau aơ ma bunuyh gĭt rbăng, ƀiă lah may mpơl ma phung kon se jê̆.$b$,true),
('bunong-vn','MAT',11,26,null,$b$Nanê̆, ơ Mbơ̆ ơi, yor lah may saơ nau nây ueh.$b$,false),
('bunong-vn','MAT',11,27,null,$b$Lĕ rngôch ndơ Mbơ̆ gâp jao jêh ma gâp; mâu geh nơm gĭt năl Kon ôh, knŏng du huê Mbơ̆ yơh, jêh ri mâu geh nơm gĭt năl Mbơ̆ ôh, knŏng du huê Kon, jêh ri mbu nơm Kon ŭch tâm mpơl yơh.$b$,false),
('bunong-vn','MAT',11,28,null,$b$“Văch ta gâp, hơi lĕ rngôch bunuyh rgănh jêh ri anh jâk, jêh ri gâp mra ăn khân may rlu.$b$,true),
('bunong-vn','MAT',11,29,null,$b$Gâp geh nuih n'hâm rdơ̆ rbăn jêh ri blau dêh rhêt, pô ri ăn khân may anh ndơ mbăk gâp jêh ri nti tă bơh gâp; huêng khân may mra rlu.$b$,false),
('bunong-vn','MAT',11,30,null,$b$Yor lah ndơ mbăk gâp, n'gơch jêh ri ndơ gâp ăn mbăk mâu geh jâk ôh”$b$,false),
('bunong-vn','MAT',12,1,null,$b$Rnôk nây dôl Brah Yêsu rgăn ta mir bu tâm nar Saƀat, phung oh mon păng ji ngot. Khân păng roih sa ba tâm mir bu.$b$,true),
('bunong-vn','MAT',12,2,null,$b$Phung Pharisi saơ, pô ri khân păng lah ma Brah Yêsu: “Uănh hom phung oh mon may, ƀư nau bu mâu vay ƀư tâm nar Saƀat.”$b$,false),
('bunong-vn','MAT',12,3,null,$b$Brah Yêsu lah ma khân păng: “Khân may mâu mâp uănh hĕ tâm ndrom sămƀŭt nau bu nkoch bri ma Y-Đavit ƀư, tơ lah păng jêh ri phung hăn ndrel păng ji ngot.$b$,false),
('bunong-vn','MAT',12,4,null,$b$Mâm păng lăp tâm ngih Brah Ndu jêh ri sa kapŭng nhhơr ma Brah Ndu, kapŭng nây păng, mâu lah phung hăn ndrel păng mâu vay sa ôh, ƀiă lah knŏng phung kôranh ƀư brah sa?$b$,false),
('bunong-vn','MAT',12,5,null,$b$Mâu lah khân may mâu mâp uănh tâm ndrom sămƀŭt nau vay, bu nkoch bri ma phung kôranh ƀư brah tâm ngih brah Yuđa, khân păng rlau nar Saƀat ƀiă lah mâu ƀư tih ôh?$b$,false),
('bunong-vn','MAT',12,6,null,$b$Pô ri gâp lah ma khân may, geh ta aơ du huê bu yơk lơn ma ngih brah Yuđa.$b$,false),
('bunong-vn','MAT',12,7,null,$b$Tơ lah khân may gĭt rbăng mâm nau ngơi aơ: ‘Gâp ŭch nau blau yô̆, mâu di ndơ ƀư brah ôh,’ khân may mâu nduyh ôh phung mâu mâp ƀư tih.$b$,false),
('bunong-vn','MAT',12,8,null,$b$Yor lah Kon Bunuyh jêng kôranh ma nar Saƀat.”$b$,false),
('bunong-vn','MAT',12,9,null,$b$Du tă bơh nây, Păng lăp tâm ngih rƀŭn Yuđa.$b$,true),
('bunong-vn','MAT',12,10,null,$b$Păng saơ ta nây du huê bunuyh siăr du đah ti. Geh bunuyh ôp ma Brah Yêsu: “Vay lĕ ƀư bah tâm nar Saƀat?” Khân păng lah pô nây ŭch joi nau phong Brah Yêsu.$b$,false),
('bunong-vn','MAT',12,11,null,$b$Brah Yêsu lah ma khân păng: “Mbu nơm tâm phung khân may, tơ lah geh du mlâm biăp tŭp tâm brŏng nar Saƀat păng mâu đŏt ôh ô băl klơ kơh?$b$,true),
('bunong-vn','MAT',12,12,null,$b$Ƀiă lah du huê bunuyh khlay lơn ma du mlâm biăp! Pô ri vay lĕ ƀư nau ueh tâm nar Saƀat.”$b$,false),
('bunong-vn','MAT',12,13,null,$b$Jêh nây Păng lah ma bunuyh siăr ti, “Yơr hom ti may.” Nơm nây yơr ro, jêh ri ti păng dơi bah nâm bu ti đah ri.$b$,false),
('bunong-vn','MAT',12,14,null,$b$Ƀiă lah phung Pharisi luh jêh ri tâm nchră joi nau dơi nkhĭt Brah Yêsu.$b$,false),
('bunong-vn','MAT',12,15,null,$b$Jêh ri Brah Yêsu gĭt, pô ri Păng du tă bơh nây. Geh âk bunuyh tĭng ndô̆ Păng jêh ri Păng ƀư bah lĕ rngôch khân păng,$b$,true),
('bunong-vn','MAT',12,16,null,$b$jêh ri păng buay khân păng mâu ăn mbơh nau nây ma bu gĭt ôh.$b$,false),
('bunong-vn','MAT',12,17,null,$b$Pô ri ƀư nanê̆ jêh nau kôranh nơm mbơh lor, Y-Êsai, mbơh jêh pô aơ: p$b$,false),
('bunong-vn','MAT',12,18,null,$b$“Aơ, oh mon gâp săch jêh jêng nơm gâp rŏng ngăn ngên, tâm Păng gâp geh nau maak ngăn. Gâp mra ăn Brah Huêng Ueh gâp trŭnh ta Păng, jêh ri păng mra mbơh nau sŏng srăng ma phung ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','MAT',12,19,null,$b$Păng mâu tâm rlăch mâu lah nter ôh, mâu lĕ bu mra tăng bâr Păng rŏ trong.$b$,true),
('bunong-vn','MAT',12,20,null,$b$Păng mâu rtăch lơi ôh tơm treng hŏ deh jêh, jêh ri Păng mâu khôm lơi ôh ŭnh jrêng bơi nhhât, kŏ tât Păng ăn nau sŏng srăng dơi.$b$,true),
('bunong-vn','MAT',12,21,null,$b$Jêh ri phung pa dih mra kâp gân tâm amoh Păng.”$b$,true),
('bunong-vn','MAT',12,22,null,$b$Dôl nây bu njŭn leo ma Brah Yêsu, du huê bunuyh brah mhĭk lơh, chieh măt jêh ri mlo. Păng ƀư bah khân ô băl jêh ri bunuyh mlo blau ngơi, bunuyh chieh dơi saơ ang.$b$,true),
('bunong-vn','MAT',12,23,null,$b$Phung âk hih rhâl ngăn, lah pô aơ: “Di lĕ bunuyh aơ jêng kon Y-Đavit.”$b$,true),
('bunong-vn','MAT',12,24,null,$b$Ƀiă lah jêh phung Pharisi tăng pô ri khân păng lah: “Bunuyh nây nsot brah mhĭk tâm amoh Bêlsêbul, du huê kon hađăch, phung brah mhĭk.”$b$,false),
('bunong-vn','MAT',12,25,null,$b$Brah Yêsu gĭt nau mĭn khân păng jêh ri lah: “Tơ lah du ƀon hađăch tâm nkhah tâm pă păng nơm, păng mra rai yot, jêh ri ăp ƀon mâu lah ăp ngih tâm nkhah tâm pă păng nơm, mâu dơi gŭ ƀa ƀơ ôh,$b$,true),
('bunong-vn','MAT',12,26,null,$b$tơ lah Satan nsot Satan nơm păng tâm nkhah ndrăng păng nơm; mâm ƀon bri hađăch păng dơi gŭ nâp?$b$,false),
('bunong-vn','MAT',12,27,null,$b$Jêh ri tơ lah gâp nsot brah mhĭk tâm amoh Bêlsêbul, bi phung kon khân may, mbu amoh khân păng nsot? Yor nây khân păng nơm yơh mra phat dôih khân may.$b$,false),
('bunong-vn','MAT',12,28,null,$b$Ƀiă lah tơ lah gâp nsot phung brah mhĭk tâm amoh Brah Huêng Ueh Brah Ndu, pô ri ƀon bri hađăch Brah Ndu tât jêh ma khân may.$b$,false),
('bunong-vn','MAT',12,29,null,$b$Mâu lah mâm ƀư bu dơi lăp tâm ngih du huê bunuyh ktang jêh ri pit ndô ndơ păng, tơ lah bu mâu chăp lơi bunuyh ktang nây lor? Păng chăp lơi nơm nây lor mơ, păng dơi pit ndơ tâm ngih păng.$b$,false),
('bunong-vn','MAT',12,30,null,$b$Mbu nơm mâu gŭ ndrel ma gâp, nơm nây jêng rlăng đah gâp, jêh ri mbu nơm mâu tâm gop đah gâp, păng mra nkhah êng êng.$b$,false),
('bunong-vn','MAT',12,31,null,$b$Pô ri gâp lah ma khân may, lĕ rngôch nau tih, lĕ rngôch nau ngơi sưr bu mra yô̆ ma phung bunuyh, ƀiă lah nau ngơi sưr đah Brah Huêng Ueh bu mâu dơi yô̆ ôh.$b$,false),
('bunong-vn','MAT',12,32,null,$b$Jêh ri tơ lah mbu nơm ngơi mhĭk ma Kon Bunuyh nau tih păng bu mra yô̆ an; ƀiă lah tơ lah mbu nơm ngơi mhĭk ma Brah Huêng Ueh, nau tih păng bu mâu dơi yô̆ ôh, tâm rnôk aơ mâu lah tâm rnôk pa kơi taơ tâm ban lĕ.”$b$,false),
('bunong-vn','MAT',12,33,null,$b$“Mâu lah tơm si ueh play păng ueh tâm ban lĕ; mâu lah tơm si mhĭk, play păng mhĭk lĕ; yor lah bu dơi gĭt năl tơm si ta play păng.$b$,true),
('bunong-vn','MAT',12,34,null,$b$Hơi phung kon bêh rmâng! Khân may phung djơh mhĭk, mâm dơi ngơi nau ueh? Yor lah mbung bâr ngơi hŏ bêng ler jêh tâm nuih n'hâm.$b$,false),
('bunong-vn','MAT',12,35,null,$b$Bunuyh ueh mpơl ndơ ueh tă bơh ntŭk prăp nau ueh păng, ƀiă lah bunuyh mhĭk mpơl ndơ mhĭk tă bơh ntŭk prăp nau mhĭk păng.$b$,false),
('bunong-vn','MAT',12,36,null,$b$Gâp mbơh ma khân may, tâm nar phat dôih bu mra mbơh lĕ rngôch nau păng ngơi mâu khlay;$b$,false),
('bunong-vn','MAT',12,37,null,$b$yor lah bu mra kơp khân may sŏng yor nau khân may ngơi, jêh ri tâm rmal khân may yor nau khân may ngơi đŏng.”$b$,false),
('bunong-vn','MAT',12,38,null,$b$Jêh nây, geh ƀa ƀă phung kôranh nchih sămƀŭt jêh ri phung Pharisi lah ma Păng: “Hơi Kôranh nơm nti ơi, hên ŭch uănh may ƀư nau mbên khlay.”$b$,true),
('bunong-vn','MAT',12,39,null,$b$Păng plơ̆ lah ma phung nây: “Phung ndŭl mpôl ƀai jêh ri văng tĭr aơ, dăn du ntil nau mbên khlay; ƀiă lah mâu geh nau mbên khlay êng ma khân may ôh, knŏng nau mbên khlay ma kôranh nơm mbơh lor Y-Yônas.$b$,false),
('bunong-vn','MAT',12,40,null,$b$Yor lah nâm bu Y-Yônas gŭ tâm trôm ndŭl ka toyh pe nar pe măng, pô ri lĕ Kon Bunuyh mra gŭ tâm trôm neh ntu pe nar pe măng.$b$,false),
('bunong-vn','MAT',12,41,null,$b$Tât ta nar phat dôih phung bunuyh ƀon lan Ninivơ mra dâk ndrel ma phung ndŭl mpôl aơ; jêh ri phung khân păng mra tâm rmal phung ndŭl mpôl aơ; yor lah phung bunuyh ƀon lan Ninivơ mƀăr lơi nau tih, tơ lah Y-Yônas mbơh lor, jêh ri aơ geh du huê toyh lơn ma Y-Yônas.$b$,false),
('bunong-vn','MAT',12,42,null,$b$Tât ta nar phat dôih hađăch bu ur tă pa dâng mra dâk ndrel ma phung ndŭl mpôl aơ, jêh ri bu ur nây mra tâm rmal khân păng; yor lah păng văch tă bơh n'gar neh ntu ŭch iăt nau gĭt mĭn hađăch Salômôn, jêh ri aơ geh du huê toyh lơn ma hađăch Salômôn.”$b$,false),
('bunong-vn','MAT',12,43,null,$b$“Tơ lah brah mhĭk luh du tă bơh du huê bunuyh, păng hăn tâm ntŭk sơh joi ntŭk rlu, ƀiă lah păng mâu saơ ôh.$b$,true),
('bunong-vn','MAT',12,44,null,$b$Pô ri păng lah: Gâp mra plơ̆ gŭ tâm ngih gâp mhe luh dơh, jêh ri tơ lah păng plơ̆ ta ngih nây, păng saơ ngih hŏng, pih kloh jêh, jêh ri rep jêh ăn ueh.$b$,false),
('bunong-vn','MAT',12,45,null,$b$Păng hăn jêh ri sŏk tay ndrel păng pơh brah mhĭk janh lơn ma păng; khân păng lăp gŭ ta nây. Pô ri bunuyh nây jêng mhĭk glăm lơn ma sa ơm. Pô ri phung ndŭl mpôl ƀai aơ mra jêng tâm ban lĕ.”$b$,false),
('bunong-vn','MAT',12,46,null,$b$Dôl Brah Yêsu ăt gŭ ngơi ma phung âk nây, mê̆ Păng jêh ri phung oh Păng gŭ pa dih ŭch ngơi đah Păng.$b$,true),
('bunong-vn','MAT',12,47,null,$b$Geh du huê lah ma Păng: “Aơ, mê̆ may phung oh may gŭ pa dih. Khân păng ŭch ngơi đah may.”$b$,false),
('bunong-vn','MAT',12,48,null,$b$Păng lah pô aơ: “Mbu nơm mê̆ gâp? Jêh ri mbu nơm phung oh gâp?”$b$,true),
('bunong-vn','MAT',12,49,null,$b$Jêh ri Păng yơr ti Păng nchŏng ma phung oh mon Păng jêh ri lah: “Aơ, phung mê̆ gâp jêh ri phung oh gâp!$b$,false),
('bunong-vn','MAT',12,50,null,$b$Yor lah mbu nơm ƀư tĭng nâm nau Mbơ̆ gâp tâm trôk ŭch, păng nây yơh jêng oh, yuh, mâu lah mê̆ gâp.”$b$,false),
('bunong-vn','MAT',13,1,null,$b$Nar nây lĕ Brah Yêsu luh tă bơh ngih jêh ri păng gŭ ta kơh dak mƀŭt.$b$,true),
('bunong-vn','MAT',13,2,null,$b$Jêh ri geh âk bunuyh rƀŭn jŭm Păng, tât Păng ncho tâm plŭng jêh ri gŭ; bi phung âk gŭ dâk ta kơh.$b$,true),
('bunong-vn','MAT',13,3,null,$b$Jêh ri Păng nti lah âk ma khân păng ma nau hôr, pô aơ Păng lah: “Geh du huê bunuyh srih grăp hăn srih.$b$,false),
('bunong-vn','MAT',13,4,null,$b$Dôl păng srih du rnglay grăp tŭp rŏ trong, jêh ri geh sĭm văch chôk sa.$b$,false),
('bunong-vn','MAT',13,5,null,$b$Du rnglay êng tŭp ta neh lŭ, geh neh n'gơ jêh ri găr hon ro, yor lah reh păng mâu lăp jru ôh,$b$,false),
('bunong-vn','MAT',13,6,null,$b$jêh ri tơ lah geh nar luh, nchrat păng, yor lah mâu geh reh jru, păng kro ro.$b$,false),
('bunong-vn','MAT',13,7,null,$b$Du găr êng tŭp tâm ntŭk lok. Lok hon âk jêh ri in nu păng.$b$,false),
('bunong-vn','MAT',13,8,null,$b$Du găr êng tŭp tâm ntŭk neh ueh jêh ri play, geh tơ̆ du găr jêng du rhiăng, geh tơ̆ du găr jêng prao jât, geh tơ̆ du găr geh pe jât.$b$,false),
('bunong-vn','MAT',13,9,null,$b$Pô ri, mbu nơm geh tôr rkêng iăt hom.”$b$,false),
('bunong-vn','MAT',13,10,null,$b$Jêh ri phung oh mon hăn dăch ôp Păng: “Mâm ƀư may ngơi ma khân păng ma nau hôr pô nây?”$b$,true),
('bunong-vn','MAT',13,11,null,$b$Brah Yêsu lah: “Yor lah bu ăn jêh ma khân may gĭt rbăng, nau ndâp ƀon hađăch Brah Ndu, ƀiă lah ma khân păng bu mâu ăn nâm bu pô nây.$b$,false),
('bunong-vn','MAT',13,12,null,$b$Yor lah bu mra ntop ăn ma mbu nơm hŏ geh jêh, jêh ri păng mra geh âk lơn; ƀiă lah ma mbu nơm mâu geh bu mra sŏk pit lơi moh ndơ păng hŏ geh jêh.$b$,false),
('bunong-vn','MAT',13,13,null,$b$Yor nây gâp ngơi ma khân păng ma nau hôr, yor lah khân păng uănh jêh ri mâu saơ ôh, khân păng nkêng tôr mâu tăng ôh, mâu lĕ khân păng gĭt rbăng.$b$,false),
('bunong-vn','MAT',13,14,null,$b$Pô ri n'hêl nanê̆ jêh ma khân păng nau Y-Êsai mbơh jêh tă bơh lor pô aơ: ‘Khân may mra tăng ƀiă lah mâu gĭt rbăng, khân may mra uănh ƀiă lah mâu saơ.$b$,false),
('bunong-vn','MAT',13,15,null,$b$Yor lah nuih n'hâm phung aơ jêng brơl, tôr jêng rngêl, măt lĕ nhêp, Lah mâu, măt khân păng lĕ saơ, tôr khân păng lĕ tăng, nuih n'hâm khân păng lĕ gĭt rbăng, klăp lah khân păng plơ̆ tay, gay ma Gâp mra ƀư bah an.’ q$b$,true),
('bunong-vn','MAT',13,16,null,$b$Ƀiă lah ueh maak yơh ma măt khân may yor lah dơi saơ, jêh ri ueh maak yơh tôr khân may, dơi tăng.$b$,false),
('bunong-vn','MAT',13,17,null,$b$Nanê̆ gâp mbơh ma khân may, âk phung kôranh nơm mbơh lor jêh ri phung sŏng, ŭch uănh mâm nau khân may saơ aƀaơ, ƀiă lah khân păng mâu saơ ôh, jêh ri ŭch iăt, moh nau khân may tăng, ƀiă lah khân păng mâu dơi tăng ôh.$b$,false),
('bunong-vn','MAT',13,18,null,$b$“Pô ri ăn khân may iăt hom nâm bu ntĭt nau hôr ma bunuyh srih grăp aơ.$b$,true),
('bunong-vn','MAT',13,19,null,$b$Tơ lah du huê bunuyh tăng nau ngơi ma ƀon hađăch Brah Ndu, jêh ri mâu gĭt rbăng ôh, brah mhĭk văch sŏk lơi, moh nau bu srih jêh tâm nuih n'hâm păng, nây jêng nâm bu grăp srih rŏ trong.$b$,false),
('bunong-vn','MAT',13,20,null,$b$Bunuyh tăng nau ngơi jêh ri sŏk dơn ro ma nau răm, bunuyh nây jêng nâm bu grăp bu srih ta ntŭk geh lŭ.$b$,false),
('bunong-vn','MAT',13,21,null,$b$Ƀiă lah tâm nuih n'hâm păng mâu geh reh ôh. Pô ri păng gŭ rêh ƀât lât, tơ lah geh nau rêh ni, mâu lah nau bu ƀư mhĭk tât yor nau ngơi; păng cha lơi ro.$b$,true),
('bunong-vn','MAT',13,22,null,$b$Bunuyh dơn grăp srih ta ntŭk lok jêng nơm tăng nau ngơi, ƀiă lah nau rvê ma neh ntu, nau kơnh ma nau ndrŏng, tŭn jot lơi nau ngơi, jêh ri păng mâu dơi geh play ôh.$b$,false),
('bunong-vn','MAT',13,23,null,$b$Ƀiă lah bunuyh dơn grăp ta neh ueh, jêng nơm iăt nau ngơi jêh ri gĭt rbăng. Nanê̆ păng play du găr jêng tât du rhiăng, ƀa ƀă prao jât, ƀa ƀă pe jât.”$b$,false),
('bunong-vn','MAT',13,24,null,$b$Brah Yêsu nti ma khân păng nau hôr êng pô aơ: “Ƀon bri hađăch Brah Ndu, jêng nâm bu du huê bunuyh srih grăp ueh tâm mir lŏ păng.$b$,true),
('bunong-vn','MAT',13,25,null,$b$Ƀiă lah dôl bu bêch, bunuyh rlăng păng văch srih gơ̆ mhĭk tâm ba jêh ri păng du.$b$,false),
('bunong-vn','MAT',13,26,null,$b$Tơ lah ba văch ma prêh jêh ri play, gơ̆ mhĭk nây ăt mpơl đŏng.$b$,false),
('bunong-vn','MAT',13,27,null,$b$Jêh ri phung oh mon nơm mir lŏ nây văch lah ma păng: ‘Hơi Kôranh, may mâu srih hĕ găr ueh tâm mir lŏ may? Mbah tă luh gơ̆ mhĭk aơ mih?’$b$,false),
('bunong-vn','MAT',13,28,null,$b$Păng lah ma khân păng: ‘Du huê nơm rlăng yơh ƀư nau nây.’ Phung oh mon plơ̆ lah ma păng: ‘May ŭch lĕ hên rôk lơi păng?’$b$,false),
('bunong-vn','MAT',13,29,null,$b$Kôranh lah: ‘Mâu, lơi ƀư pô ri ôh, klach lah dôl khân may rôk gơ̆ mhĭk nây, klach khân may rôk nđâp ma ba.$b$,false),
('bunong-vn','MAT',13,30,null,$b$Lơi lĕ bar ntil nây văch ma prêh kŏ tât yan rek; jêh ri ta yan rek gâp mra ntăm ma phung rek, rôk jêh ri tâm rƀŭn gơ̆ mhĭk lor, jêh ri su lơi păng, ƀiă lah tâm rƀŭn ba prăp tâm ngih ba gâp.’ ”$b$,false),
('bunong-vn','MAT',13,31,null,$b$Brah Yêsu ntĭt du nau hôr êng: “Ƀon bri hađăch Brah Ndu nâm bu du găr trau, du huê bunuyh sŏk jêh ri srih tâm mir lŏ păng,$b$,true),
('bunong-vn','MAT',13,32,null,$b$păng jêng găr jê̆ lơn ma lĕ rngôch găr êng, ƀiă lah tơ lah păng hon jêh păng jêng toyh lơn ma lĕ rngôch tơm trau. Păng jêng du mlâm tơm si, tât phung sĭm tâm trôk văch ƀư rsuăn ta n'gĭng păng.”$b$,false),
('bunong-vn','MAT',13,33,null,$b$Păng lah ma khân păng ma nau ngơi hôr êng: “Ƀon bri hađăch Brah Ndu jêng nâm bu ndrui, du huê bu ur sŏk, tâm pot ma pe rbâng rnih tât rnih nây dang lĕ rngôch.”$b$,true),
('bunong-vn','MAT',13,34,null,$b$Brah Yêsu ngơi lĕ rngôch nau nây ma nau hôr phung âk. Păng mâu ngơi nau êng ôh tơ lah păng mâu ngơi đah nau hôr ma khân păng.$b$,true),
('bunong-vn','MAT',13,35,null,$b$Pô ri n'hêl nanê̆ jêh nau kôranh nơm mbơh lor hŏ mbơh jêh pô aơ: “Gâp mra hă ngơi ŭch nti ma nau hôr, gâp mra mbơh nau ndâp ntơm bơh kăl e.”$b$,false),
('bunong-vn','MAT',13,36,null,$b$Dôl nây Păng mplơ̆ sĭt phung âk jêh ri Păng lăp tâm ngih. Phung oh mon hăn dăch Păng jêh ri lah: “Rblang ma hên nau hôr ma gơ̆ mhĭk tâm mir lŏ.”$b$,false),
('bunong-vn','MAT',13,37,null,$b$Păng plơ̆ lah: “Nơm srih grăp ueh nâm bu ntĭt Kon Bunuyh.$b$,false),
('bunong-vn','MAT',13,38,null,$b$Mir lŏ, nâm bu ntĭt neh ntu, găr ueh, nâm bu ntĭt phung kon ƀon bri hađăch Brah Ndu; phung gơ̆ mhĭk, nâm bu phung kon brah mhĭk.$b$,false),
('bunong-vn','MAT',13,39,null,$b$Nơm rlăng srih găr gơ̆ mhĭk, nâm bu ntĭt brah mhĭk. Yan rek, nâm bu ntĭt nau kêng lôch ma neh ntu; phung rek, nâm bu ntĭt phung Tông mpăr Brah Ndu.$b$,false),
('bunong-vn','MAT',13,40,null,$b$Tâm ban ma bu rôk gơ̆ mhĭk nây, su tâm ŭnh, bu mra ƀư tâm ban pô nây lĕ ta nar kêng lôch neh ntu.$b$,false),
('bunong-vn','MAT',13,41,null,$b$Kon Bunuyh mra njuăl phung Tông mpăr Păng, ăn nhŭp tă bơh ƀon bri hađăch Păng, lĕ rngôch phung ƀư tŭp bu jêh ri phung mhĭk,$b$,false),
('bunong-vn','MAT',13,42,null,$b$jêh ri mra mƀăr khân păng tâm ŭnh toyh duh hâu ngăn; ta ntŭk nây mra geh nau nhĭm nhhiăng jêh ri nau rket sêk.$b$,false),
('bunong-vn','MAT',13,43,null,$b$Nar nây phung sŏng mra geh nchrat ang, nâm bu măt nar tâm ƀon bri hađăch Mbơ̆ khân păng, mbu nơm geh tôr rkêng iăt hom.$b$,false),
('bunong-vn','MAT',13,44,null,$b$“Ƀon bri hađăch Brah Ndu, nâm bu drăp ndơ khlay bu tâp ndâp lơi tâm du lôk mir lŏ. Du huê bunuyh saơ, jêh ri păng pôn ro, yor lah păng răm maak. Păng sĭt tăch lĕ rngôch ndơ păng geh, jêh ri păng rvăt mir lŏ nây.$b$,true),
('bunong-vn','MAT',13,45,null,$b$“Ƀon bri hađăch Brah Ndu, jêng nâm bu du huê bunuyh tăch drăp joi nhong khlay ngăn,$b$,true),
('bunong-vn','MAT',13,46,null,$b$Tơ lah păng saơ jêh du găr nhong khlay ngăn, păng hăn, tăch lĕ rngôch ndơ păng geh, jêh ri păng rvăt nhong nây.$b$,false),
('bunong-vn','MAT',13,47,null,$b$“Ƀon bri hađăch Brah Ndu, tâm ntĭt đah jal bu seng tâm dak mƀŭt, geh nhŭp ăp ntil ka;$b$,true),
('bunong-vn','MAT',13,48,null,$b$tơ lah jal bêng jêh phung bunuyh seng đŏt ta kơh. Khân păng gŭ săch, ăn phung ka ueh tâm ra-i, jêh ri khân păng mƀăr lơi phung ka mhĭk.$b$,false),
('bunong-vn','MAT',13,49,null,$b$Nâm bu pô nây lĕ ta nar lôch neh ntu. Phung Tông mpăr Brah Ndu mra văch jêh ri khân păng mra tâm pă phung mhĭk đah phung sŏng.$b$,false),
('bunong-vn','MAT',13,50,null,$b$Jêh ri khân păng mra mƀăr lơi phung mhĭk tâm ŭnh toyh duh hâu ngăn. Ta ntŭk nây mra geh nau nhĭm nhhiăng jêh ri rket sêk.$b$,false),
('bunong-vn','MAT',13,51,null,$b$“Khân may gĭt rbăng lĕ nau aơ?” Khân păng lah: “Ơ.”$b$,true),
('bunong-vn','MAT',13,52,null,$b$Jêh ri Păng lah: “Pô ri ăp nơm kôranh nchih sămƀŭt nti ăn gĭt lĕ nau ƀon bri hađăch Brah Ndu, păng jêng nâm bu du huê nơm ngih, mpơl tă bơh drăp ndơ păng nđâp ma ndơ khlay mhe nđâp ma ndơ khlay ơm.”$b$,false),
('bunong-vn','MAT',13,53,null,$b$Tơ lah jêh Brah Yêsu nti nau hôr nây, Păng hăn tă bơh ntŭk nây.$b$,true),
('bunong-vn','MAT',13,54,null,$b$Păng sĭt ta n'gor Păng nơm. Păng nti lah tâm ngih tâm rƀŭn Yuđa, tât lĕ rngôch bunuyh iăt hih rhâl ngăn jêh ri lah: “Mbah tă luh nau Păng blau âk nây, jêh ri nau mbên khlay nây?$b$,false),
('bunong-vn','MAT',13,55,null,$b$Di lĕ Păng jêng kon du huê trah meh? Di lĕ amoh mê̆ păng H'Mari? Jêh ri phung oh Păng Y-Yakơ, Y-Yôsep, Y-Simôn, Y-Yut?$b$,true),
('bunong-vn','MAT',13,56,null,$b$Di lĕ phung oh bu ur Păng gŭ ndrel ma he ta aơ? Pô ri mbah tă luh bunuyh aơ geh lĕ rngôch nau nây.”$b$,false),
('bunong-vn','MAT',13,57,null,$b$Jêh ri khân păng vĭ yor Brah Yêsu. Ƀiă lah Brah Yêsu lah ma khân păng pô aơ: “Du huê kôranh nơm mbơh lor bu mưch ma păng knŏng tâm ƀon păng nơm jêh ri tâm ngih păng nơm.”$b$,false),
('bunong-vn','MAT',13,58,null,$b$Jêh ri păng mâu ƀư âk ôh nau mbên khlay ta nây, yor lah khân păng mâu chroh ôh.$b$,false),
('bunong-vn','MAT',14,1,null,$b$Rnôk nây hađăch Hêrôt lư bu nkoch bri ma Brah Yêsu.$b$,true),
('bunong-vn','MAT',14,2,null,$b$Păng lah ma phung oh mon păng pô aơ: “Păng nây yơh jêng Y-Yôhan nơm ƀư ƀaptem. Păng dâk rêh jêh tă bơh phung khĭt. Yor nây păng dơi ƀư âk ntil nau mbên khlay pô nây.”$b$,false),
('bunong-vn','MAT',14,3,null,$b$Yor lah hađăch Hêrôt ăn bu nhŭp chăp jêh Y-Yôhan jêh ri krŭng jêh ô băl tâm ndrung yor H'Hêrôdias, ur oh păng, Y-Philip ŭch pô ri,$b$,false),
('bunong-vn','MAT',14,4,null,$b$Yor lah Y-Yôhan buay păng pô aơ: “Mâu dơi vay ôh may sŏk bu ur nây jêng ur may.”$b$,false),
('bunong-vn','MAT',14,5,null,$b$Pô ri hađăch Hêrôt ŭch nkhĭt Y-Yôhan ƀiă lah păng klach ma phung âk, yor lah bu uănh ma Y-Yôhan jêng hađăch kôranh nơm mbơh lor.$b$,false),
('bunong-vn','MAT',14,6,null,$b$Tơ lah nar bu nhêt sa kah gĭt nau deh Hêrôt, kon bu ur păng H'Hêrôdias ntlơ̆ ntlơn pa năp phung tâm rƀŭn ta nây, jêh ri păng ƀư maak ma hađăch Hêrôt,$b$,true),
('bunong-vn','MAT',14,7,null,$b$Tât hađăch Hêrôt ton săk ma păng ŭch ăn moh ndơ păng mra dăn.$b$,false),
('bunong-vn','MAT',14,8,null,$b$Pô ri bu ur nây dơn nau mê̆ păng nchâp, dăn ma hađăch pô aơ: “Ăn ma gâp aƀaơ ro bôk Y-Yôhan nơm ƀư ƀaptem n'gân ta ngan grưng.”$b$,false),
('bunong-vn','MAT',14,9,null,$b$Hađăch rngot ngăn; ƀiă lah yor păng ton săk jêh ta năp phung âk gŭ rƀŭn ta nây, pô ri păng đă bu ăn ma bu ur nây tĭng nâm nau păng hŏ dăn jêh.$b$,false),
('bunong-vn','MAT',14,10,null,$b$Păng njuăl bunuyh hăn koh trô ko Y-Yôhan tâm ndrung,$b$,false),
('bunong-vn','MAT',14,11,null,$b$jêh ri bu n'gân bôk ô băl tâm ngan grưng, djôt ăn ma bu ur nây, jêh ri phung oh mon Y-Yôhan văch.$b$,false),
('bunong-vn','MAT',14,12,null,$b$Khân păng djôt săk ô băl jêh ri tâp, jêh ri khân păng sĭt hăn mbơh nau nây ma Brah Yêsu.$b$,true),
('bunong-vn','MAT',14,13,null,$b$Jêh Brah Yêsu tăng nau nây, Păng hăn ncho plŭng, êng du huê Păng hăn ta ntŭk bri rdah, tơ lah phung âk gĭt, khân păng hăn jâng ntơm bơh ƀon toyh tĭng Brah Yêsu.$b$,true),
('bunong-vn','MAT',14,14,null,$b$Tơ lah Brah Yêsu luh tă bơh plŭng, Păng saơ bunuyh âk ngăn; Păng bêng ma nau yô̆, jêh ri Păng ƀư bah nau ji kuet.$b$,true),
('bunong-vn','MAT',14,15,null,$b$Tât măng phung oh mon hăn dăch Păng jêh ri lah: “Ntŭk aơ bri rdah, jêh ri trôk măng jêh; ăn phung âk aơ hăn tâm ƀon bu rvăt ndơ ‘sông sa’ ”$b$,true),
('bunong-vn','MAT',14,16,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Mâu khlay ôh khân păng hăn. Ăn khân may nơm siăm khân păng.”$b$,false),
('bunong-vn','MAT',14,17,null,$b$Phung oh mon plơ̆ lah ma Păng: “Hên geh jêh ta aơ knŏng prăm mlâm kapŭng jêh ri bar mlâm ka.”$b$,true),
('bunong-vn','MAT',14,18,null,$b$Păng lah ma phung nây: “Njŭn kapŭng, ka nây ma gâp.”$b$,false),
('bunong-vn','MAT',14,19,null,$b$Jêh ri Păng ăn phung âk nây gŭ ta ndrêch. Păng sŏk prăm mlâm kapŭng jêh ri bar mlâm ka nây, n'gơr măt klơ trôk, lah ueh ma Brah Ndu, jêh ri Păng nkêch kapŭng; Păng ăn ma phung oh mon Păng, jêh ri phung oh mon Păng tâm pă ăn ma phung âk nây.$b$,false),
('bunong-vn','MAT',14,20,null,$b$Lĕ rngôch sa hơm da dê jêh ri kapŭng hôm rmeh bu dônh sĭt bêng jât ma bar bĭ.$b$,true),
('bunong-vn','MAT',14,21,null,$b$Phung bunuyh sa kapŭng nây geh klăp lah prăm rbăn bunuyh bu klâu, mâu geh kơp bu ur jêh ri kon se ôh.$b$,true),
('bunong-vn','MAT',14,22,null,$b$Ƀât lât ta nây Brah Yêsu ntrôl phung oh mon Păng ncho plŭng jêh ri rgăn dak mƀŭt, hăn tât ta kơh kăl tê̆, dôl Păng ăn phung âk nây sĭt.$b$,true),
('bunong-vn','MAT',14,23,null,$b$Jêh phung âk nây sĭt, Păng hao yôk êng du huê Păng gay mbơh sơm, tât măng ngo Păng gŭ êng du huê Păng ta nây.$b$,false),
('bunong-vn','MAT',14,24,null,$b$Dôl nây plŭng lĕ lăn hăn tât n'gul dak mƀŭt jêh, geh dak rbuh yor phŭt sial ktang rpuh plŭng khân păng.$b$,true),
('bunong-vn','MAT',14,25,null,$b$Ƀiă lah dăch ôi Brah Yêsu hăn ta klơ mpiăt dak tĭng khân păng.$b$,false),
('bunong-vn','MAT',14,26,null,$b$Tơ lah saơ Păng hăn ta klơ dak, phung oh mon Păng klach hâu ngăn jêh ri lah: “Ri chiak nhhu!” Jêh ri, khân păng klach nter hâu ngăn.$b$,false),
('bunong-vn','MAT',14,27,null,$b$Ƀiă lah Brah Yêsu ngơi ro ma khân păng pô aơ: “Gŭ đăp mpăn hom! Gâp yơh aơ! Lơi klach ôh.”$b$,false),
('bunong-vn','MAT',14,28,null,$b$Jêh ri Y-Pêtrôs lah ma Păng: “Ơ Kôranh Brah, tơ lah di may, ăn gâp chuat klơ mpiăt dak hăn ta may.”$b$,false),
('bunong-vn','MAT',14,29,null,$b$Brah Yêsu lah ma păng: “Văch hom!” Y-Pêtrôs trŭnh tă bơh plŭng ro jêh ri hăn ta klơ mpiăt dak leo ta Brah Yêsu.$b$,false),
('bunong-vn','MAT',14,30,null,$b$Ƀiă lah tơ lah păng saơ phŭt ktang ngăn păng klach ngâm tâm dak, pô ri păng nter: “Ơ Kôranh Brah, tâm rklaih gâp ƀă.”$b$,true),
('bunong-vn','MAT',14,31,null,$b$Ƀât lât Brah Yêsu yơr ti, đŏt păng jêh ri Brah Yêsu lah ma păng: “Hơi bunuyh geh nau chroh djê̆, mâm ƀư may đing?”$b$,false),
('bunong-vn','MAT',14,32,null,$b$Jêh ri tơ lah khân păng hao jêh ta plŭng, mâu hôm geh phŭt sial ôh.$b$,false),
('bunong-vn','MAT',14,33,null,$b$Jêh ri phung gŭ tâm plŭng chon mon mbah ta năp Păng jêh ri lah: “May jêng Kon Brah Ndu nanê̆ ngăn.”$b$,false),
('bunong-vn','MAT',14,34,null,$b$Tơ lah rgăn dak mƀŭt jêh, khân păng tât ta n'gor Gênêsaret.$b$,true),
('bunong-vn','MAT',14,35,null,$b$Tơ lah bunuyh tâm n'gor nây gĭt năl Păng khân păng njuăl bunuyh hăn mbơh tâm lĕ rngôch ƀon êp dăch ta nây, jêh ri bu njŭn leo ma păng lĕ rngôch phung ji kuet.$b$,false),
('bunong-vn','MAT',14,36,null,$b$Khân păng dăn ma Brah Yêsu ăn phung ji kuet knŏng pah ta n'gar ao păng; jêh ri lĕ rngôch phung pah bah da dê.$b$,false),
('bunong-vn','MAT',15,1,null,$b$Rnôk nây geh phung Pharisi nđâp ma phung kôranh nchih sămƀŭt văch tă bơh ƀon Yêrusalem, tât dăch Brah Yêsu jêh ri lah ma păng pô aơ:$b$,true),
('bunong-vn','MAT',15,2,null,$b$“Mâm ƀư phung oh mon may gao nau vay phung bu bŭnh bu ranh? Yor lah khân păng mâu rao ôh ti khân păng ê lor khân păng sa?”$b$,false),
('bunong-vn','MAT',15,3,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Bi khân may, mâm ƀư khân may rlau nau vay Brah Ndu, yor nau nkoch bri ơm khân may nơm?$b$,false),
('bunong-vn','MAT',15,4,null,$b$Yor lah Brah Ndu ăn jêh nau vay aơ: ‘Yơk hom ma mê̆ mbơ̆ may,’ jêh ri: ‘Mbu nơm rak suai mê̆ mbơ̆ păng mra khĭt.’$b$,false),
('bunong-vn','MAT',15,5,null,$b$Ƀiă lah khân may lah, ‘mbu nơm lah ma mê̆ mbơ̆ păng pô aơ: Moh ndơ gâp dơi kơl khân may gâp nhhơr jêh ma Brah Ndu, bunuyh nây mâu yơk ma mê̆ mbơ̆ păng ôh.’$b$,false),
('bunong-vn','MAT',15,6,null,$b$Pô ri khân may cha lơi nau Brah Ndu ngơi, yor nau vay khân may nơm.$b$,false),
('bunong-vn','MAT',15,7,null,$b$Hơi phung bunuyh geh nuih n'hâm ndâp! Di jêh nau Y-Êsai mbơh lor jêh ma khân may, tơ lah păng lah pô aơ:$b$,false),
('bunong-vn','MAT',15,8,null,$b$‘Phung aơ yơk ma gâp knŏng ma mbung bâr khân păng, ƀiă lah nuih n'hâm khân păng ngai đah gâp.$b$,false),
('bunong-vn','MAT',15,9,null,$b$Mâu khlay ôh nau khân păng yơk ma gâp pô ri, yor lah khân păng nti knŏng nau vay luh tă bơh bunuyh.’ ”$b$,true),
('bunong-vn','MAT',15,10,null,$b$Jêh ri păng kuăl phung âk nây jêh ri lah pô aơ: “Gŭ iăt hom, jêh ri ăn khân may gĭt rbăng.$b$,true),
('bunong-vn','MAT',15,11,null,$b$Mâu di ndơ lăp tâm trôm mbung ôh, ƀư ƀơ̆ bunuyh, ƀiă lah ndơ luh tă bơh mbung, ndơ nây yơh ƀư ƀơ̆ bunuyh.”$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MAT',15,12,null,$b$Jêh ri phung oh mon Păng hăn dăch jêh ri lah ma Păng: “May gĭt lĕ phung Pharisi bêk jêh ri nuih, yor lah nau may ngơi pô nây?”$b$,false),
('bunong-vn','MAT',15,13,null,$b$Păng plơ̆ lah ma khân păng: “Lĕ rngôch tơm si Mbơ̆ gâp tâm trôk mâu mâp tăm, bu mra rôk lơi.$b$,true),
('bunong-vn','MAT',15,14,null,$b$Lơi, klăp lah khân păng jêng phung chieh măt njŭn phung chieh măt. Tơ lah du huê chieh măt njŭn du huê chieh măt, lĕ bar hê khân păng mra tŭp tâm brŏng.”$b$,false),
('bunong-vn','MAT',15,15,null,$b$Jêh ri Y-Pêtrôs lah ma Păng: “Rblang ma hên nau ngơi hôr nây.”$b$,false),
('bunong-vn','MAT',15,16,null,$b$Jêh ri Brah Yêsu lah: “Khân may tâm ban lĕ, khân may ê hŏ gĭt rbăng.$b$,false),
('bunong-vn','MAT',15,17,null,$b$Khân may mâu gĭt rbăng, moh ndơ lăp tâm trôm mbung, hăn lăp trôm ndŭl, jêh ri mra luh pa dih?$b$,false),
('bunong-vn','MAT',15,18,null,$b$Ƀiă lah moh ndơ luh tă bơh trôm mbung păng văch tă bơh nuih n'hâm ndơ nây yơh ƀư ƀơ̆ bunuyh.$b$,false),
('bunong-vn','MAT',15,19,null,$b$Yor lah tă bơh nuih n'hâm yơh luh văch nau mĭn mhĭk, nau mhĭk bunuyh, nau văng tĭr, nau ka n'hong, nau ntŭng, nau ngơi mƀruh, nau nchơt.$b$,false),
('bunong-vn','MAT',15,20,null,$b$Ndơ nây yơh ƀư ƀơ̆ bunuyh; ƀiă lah tơ lah sa mâu geh rao ti mâu geh ƀư ƀơ̆ bunuyh ôh.”$b$,false),
('bunong-vn','MAT',15,21,null,$b$Brah Yêsu du tă bơh nây, hăn tâm n'gor Tir jêh ri Sidôn.$b$,true),
('bunong-vn','MAT',15,22,null,$b$Jêh ri geh du huê bu ur bri Kanaan văch, nter lah: “Ơ Kôranh Brah, kon bu klâu Y-Đavit. Yô̆ an ma gâp ƀă; kon bu ur gâp, brah mhĭk ƀư nđêh nji ngăn.”$b$,false),
('bunong-vn','MAT',15,23,null,$b$Ƀiă lah Brah Yêsu mâu ngơi đah păng ôh, jêh ri phung oh mon Păng văch êp jêh ri vơh vơl ma Păng: “Mprơh lơi hom bu ur nây, yor lah păng tĭng lŭng nter pa kơi he.”$b$,true),
('bunong-vn','MAT',15,24,null,$b$Păng plơ̆ lah: “Bu njuăl gâp văch knŏng ma phung biăp nkhah du ngih Israel.”$b$,true),
('bunong-vn','MAT',15,25,null,$b$Ƀiă lah păng văch êp, jêh ri chon mon mbah ta năp Păng, jêh ri lah: “Ơ Kôranh Brah, kơl gâp ƀă.”$b$,false),
('bunong-vn','MAT',15,26,null,$b$Păng plơ̆ lah: “Mâu ueh ôh sŏk kapŭng kon dôl sa, mƀăr ma phung kon so sa.”$b$,false),
('bunong-vn','MAT',15,27,null,$b$Ƀiă lah Păng plơ̆ lah: “N'hêl nanê̆, ơ Kôranh Brah ƀiă lah phung kon so sa djah tŭp tă bơh sưng kôranh khân păng nơm.”$b$,false),
('bunong-vn','MAT',15,28,null,$b$Jêh ri Brah Yêsu lah ma păng: “Hơi bu ur, nau chroh ay toyh ngăn! Ăn nau nây tât tĭng nâm nau ay ŭch.” Jêh ri mông nây ro kon bu ur păng bah.$b$,true),
('bunong-vn','MAT',15,29,null,$b$Brah Yêsu du tă bơh ntŭk nây, hăn dăch dak mƀŭt Galilê. Păng hao yôk jêh ri gŭ ta nây.$b$,true),
('bunong-vn','MAT',15,30,null,$b$Dôl nây geh âk bunuyh hăn êp Păng, njŭn leo ma Păng phung ji jâng, phung chieh măt, phung mlo, phung rvĕn, jêh ri âk phung ji kuet êng êng, mbu n'gân ta jâng Brah Yêsu jêh ri păng ƀư bah khân păng.$b$,false),
('bunong-vn','MAT',15,31,null,$b$Pô ri phung âk ta nây hih rhâl ngăn saơ phung mlo ngơi, phung rvĕn bah phung ji jâng blau hăn, phung chieh măt dơi saơ, jêh ri khân păng mât ton tâm rnê ma Brah Ndu phung Israel.$b$,false),
('bunong-vn','MAT',15,32,null,$b$Brah Yêsu kuăl phung oh mon Păng jêh ri lah ma khân păng: “Gâp geh nau yô̆ ma phung âk aơ, yor lah geh jêh pe nar khân păng gŭ ndrel ma gâp, jêh ri mâu geh ndơ sông sa ôh; gâp mâu ŭch ăn khân păng sĭt ndŭl ji ngot ôh, klach khân păng huăr rŏ trong.”$b$,true),
('bunong-vn','MAT',15,33,null,$b$Phung oh mon lah ma Păng: “Mâm he dơi geh tŏng kapŭng tâm bri rdah aơ lĕ, siăm phung bunuyh âk râk aơ?”$b$,false),
('bunong-vn','MAT',15,34,null,$b$Brah Yêsu ôp ma khân păng: “Ndah âk kapŭng khân may geh?” Khân păng plơ̆ lah: “Pơh mlâm jêh ri ka djê̆ lê̆.”$b$,false),
('bunong-vn','MAT',15,35,null,$b$Pô ri păng ăn phung âk nây gŭ ta neh.$b$,false),
('bunong-vn','MAT',15,36,null,$b$Jêh ri Păng sŏk pơh mlâm kapŭng jêh ri ka, Păng lah ueh ma Brah Ndu, nkêch kapŭng, ka jêh ri ăn phung oh mon Păng tâm pă ăn ma phung âk nây.$b$,false),
('bunong-vn','MAT',15,37,null,$b$Lĕ rngôch sa hơm da dê, jêh ri bu dônh ndơ rmeh bêng pơh bĭ.$b$,false),
('bunong-vn','MAT',15,38,null,$b$Phung bunuyh sa kapŭng nây geh puăn rbăn bu klâu, mâu kơp ôh bu ur jêh ri kon se.$b$,true),
('bunong-vn','MAT',15,39,null,$b$Jêh păng ăn phung âk sĭt, păng ncho du mlâm plŭng jêh ri hăn ta n'gor Magadan.$b$,false),
('bunong-vn','MAT',16,1,null,$b$Phung Pharisi jêh ri phung Sađusê văch ŭch rlong uănh Brah Yêsu. Khân păng dăn ma Brah Yêsu ăn khân păng uănh du ntil nau mbên khlay tă bơh trôk.$b$,true),
('bunong-vn','MAT',16,2,null,$b$Ƀiă lah Brah Yêsu plơ̆ lah ma khân păng: “Lah trôk măng jêh khân may lah: ‘Nar ôi taơ mra prăng; yor lah trôk chăng.’$b$,true),
('bunong-vn','MAT',16,3,null,$b$Jêh ri ôi, khân may lah: ‘Nar aơ mra geh mih sial, yor lah trôk geh n'hâm tŭk jêh ri chăng.’ Khân may gĭt năl moh trôk jêng, ƀiă lah khân may mâu dơi ôh uănh nau mbên năm khay.$b$,false),
('bunong-vn','MAT',16,4,null,$b$Rnôk phung mhĭk ƀai jêh ri văng tĭr aơ, dăn ŭch uănh nau mbên khlay, ƀiă lah mâu geh nau mbên khlay êng mpơl ma khân păng ôh, geh knŏng nau mbên khlay Y-Yônas.” Jêh ri lơi phung nây, păng lŏ hăn.$b$,false),
('bunong-vn','MAT',16,5,null,$b$Tơ lah phung oh mon hăn rgăn kơh kăl tê̆, khân păng chuêl djôt kapŭng.$b$,true),
('bunong-vn','MAT',16,6,null,$b$Brah Yêsu lah ma khân păng: “Njrăng hom khân may ma ndrui phung Pharisi jêh ri phung Sađusê.”$b$,false),
('bunong-vn','MAT',16,7,null,$b$Khân păng mĭn, jêh ri lah ndrăng khân păng: “Yor lah he mâu djôt kapŭng yơh.”$b$,false),
('bunong-vn','MAT',16,8,null,$b$Brah Yêsu gĭt nau nây lah ma khân păng: “Hơi phung geh nau chroh djê̆, mâm ƀư khân may mĭn, yor lah khân may mâu geh kapŭng hĕ?$b$,false),
('bunong-vn','MAT',16,9,null,$b$Khân may ê hŏ gĭt rbăng hĕ? Khân may mâu kah gĭt ma prăm mlâm kapŭng dơi siăm prăm rbăn bunuyh jêh ri ndah âk bĭ khân may djôt sĭt ndơ rmeh?$b$,false),
('bunong-vn','MAT',16,10,null,$b$Mâu lah pơh mlâm kapŭng dơi siăm puăn rbăn bunuyh jêh ri ndah bĭ khân may djôt sĭt ndơ rmeh?$b$,true),
('bunong-vn','MAT',16,11,null,$b$Mâm ƀư khân may mâu gĭt rbăng, mâu di gâp ngơi ma khân may ma kapŭng ôh? Ƀiă lah njrăng hom khân may ma ndrui phung Pharisi jêh ri phung Sađusê.”$b$,false),
('bunong-vn','MAT',16,12,null,$b$Pô ri khân păng gĭt rbăng ma nau Brah Yêsu lah ma khân păng, ăn njrăng mâu di ndrui ƀư đah kapŭng. Ƀiă lah ma nau phung Pharisi jêh ri phung Sađusê nti.$b$,false),
('bunong-vn','MAT',16,13,null,$b$Tơ lah tât ta n'gor Sêsarê Philip, Brah Yêsu ôp ma phung oh mon Păng pô aơ: “Tĭng nâm nau bu lah, mbu amoh Kon Bunuyh jêng?”$b$,true),
('bunong-vn','MAT',16,14,null,$b$Jêh ri khân păng: “Ƀa ƀă lah Y-Yôhan nơm ƀư ƀaptem, ƀa ƀă lah Y-Êli, ƀa ƀă nơm êng lah Y-Yêrêmi mâu lah du huê tâm phung kôranh nơm mbơh lor.”$b$,false),
('bunong-vn','MAT',16,15,null,$b$Păng lah ma khân păng: “Mbu Gâp jêng khân may lah?”$b$,false),
('bunong-vn','MAT',16,16,null,$b$Y-Simôn Pêtrôs plơ̆ lah: “May jêng Brah Krist Kon Brah Ndu rêh n'ho ro.”$b$,false),
('bunong-vn','MAT',16,17,null,$b$Jêh ri Brah Yêsu lah ma păng: “May geh nau ueh maak yơh, hơi Y-Simôn kon Y-Yônas! Yor ri mâu di nglay săk jêh ri mham mpơl ma may ôh, ƀiă lah Mbơ̆ gâp tâm trôk yơh.$b$,false),
('bunong-vn','MAT',16,18,null,$b$Jêh ri gâp mbơh ma may, may jêng Y-Pêtrôs, jêh ri ta klơ lŭ aơ gâp mra rdâk phung ngih Brah Ndu gâp, jêh ri mpông pêr ƀon phung khĭt mâu dơi đah păng ôh.$b$,false),
('bunong-vn','MAT',16,19,null,$b$Gâp mra ăn ma may khŏa ƀon bri hađăch Brah Ndu, jêh ri moh nau may mra kât ta neh ntu, bu mra kât tâm trôk, jêh ri moh nau may mra pơk ta neh ntu, bu ma pơk tâm trôk.”$b$,false),
('bunong-vn','MAT',16,20,null,$b$Jêh ri Păng buay phung oh mon Păng, lơi nkoch bri ma bu nau Păng jêng Brah Krist ôh.$b$,false),
('bunong-vn','MAT',16,21,null,$b$Ntơm bơh nar nây, Brah Yêsu ntơm mbơh ma phung oh mon Păng, Păng mra hăn tâm ƀon Yêrusalem, jêh ri ta nây, păng mra dơn âk nau rêh ni, jêh ri tă bơh phung kôranh bu ranh, phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt. Phung nây mra nkhĭt Păng, ƀiă lah tăch pe nar Păng dâk rêh tay.$b$,true),
('bunong-vn','MAT',16,22,null,$b$Jêh ri Y-Pêtrôs jă Păng, hăn êng gay nkhăng lơi Păng jêh ri lah: “Ơ Kôranh Brah, ăn Brah Ndu buay lơi nau nây! Nau nây mâu mra tât ma may ôh.”$b$,false),
('bunong-vn','MAT',16,23,null,$b$Ƀiă lah Brah Yêsu n'gĭl uănh ta Y-Pêtrôs jêh ri lah: “Plơ̆ rŭch hom pa kơi gâp, hơi Satan! May ŭch ƀư tŭp gâp, yor lah nau mĭn may mâu luh tă bơh Brah Ndu ôh, ƀiă lah may mĭn ma kan bunuyh.”$b$,true),
('bunong-vn','MAT',16,24,null,$b$Jêh ri Brah Yêsu lah ma phung oh mon Păng: “Mbu nơm ŭch tĭng ndô̆ gâp, ăn păng dun hom nau păng nơm ŭch, tuy si tâm rkăng păng nơm, jêh ri ăn păng tĭng gâp,$b$,true),
('bunong-vn','MAT',16,25,null,$b$Yor lah mbu nơm ŭch tâm rklaih nau rêh păng, păng mra roh nau rêh păng nơm, ƀiă lah mbu nơm ngroh lơi nau rêh păng, yor ma gâp, mra geh đŏng nau rêh păng.$b$,false),
('bunong-vn','MAT',16,26,null,$b$Moh ntil khlay tơ lah du huê bunuyh geh ăp ntil ndơ ta neh ntu, ƀiă lah huêng păng roh, mâu lah moh ndơ păng mhe ăn gay tâm rgâl đah huêng păng?$b$,true),
('bunong-vn','MAT',16,27,null,$b$Yor lah Kon Bunuyh mra văch tâm nau chrêk rmah Mbơ̆ Păng, ndrel ma phung Tông mpăr ueh Păng, jêh ri Păng mra ăn ma ăp nơm tĭng nâm nau kan păng hŏ pah jêh.$b$,false),
('bunong-vn','MAT',16,28,null,$b$Nanê̆ gâp mbơh ma khân may, geh ƀa ƀă tâm phung khân may ta aơ mâu khĭt ôh, tât khân păng mra saơ Kon Bunuyh văch tâm ƀon bri hađăch păng.”$b$,false),
('bunong-vn','MAT',17,1,null,$b$Prao nar pa kơi, Brah Yêsu jă ndrel ma Păng Y-Pêtrôs, Y-Yakơ, jêh ri Y-Yôhan, oh Păng hăn ta klơ yôk, êng khân păng.$b$,true),
('bunong-vn','MAT',17,2,null,$b$Brah Yêsu rgâl săk jăn ta năp khân păng. Muh măt Păng jêng nchrat ngăn, nâm bu ang nar jêh ri ao Păng jêng nglang ngăn.$b$,false),
('bunong-vn','MAT',17,3,null,$b$Jêh ri aơ Y-Môis, Y-Êli văch mpơl ma khân păng, ngơi đah Brah Yêsu.$b$,true),
('bunong-vn','MAT',17,4,null,$b$Jêh ri Y-Pêtrôs lah ma Brah Yêsu: “Ơ Kôranh Brah ơi, ueh ngăn he gŭ ta aơ, tơ lah may ŭch gâp mra ƀư pe mlâm ngih bok nguay ma may, nguay ma Y-Môis, jêh ri nguay ma Y-Êli.”$b$,false),
('bunong-vn','MAT',17,5,null,$b$Dôl păng ngơi, geh tŭk nchrat ang nkŭm khân păng, jêh ri geh bâr ngơi luh tă bơh tŭk lah: “Păng aơ jêng Kon gâp rŏng ngăn ngên, tâm Păng gâp geh nau maak; ăn khân may iăt nau Păng.”$b$,false),
('bunong-vn','MAT',17,6,null,$b$Tơ lah phung oh mon tăng bâr ngơi aơ, khân păng cha lôt ro, măt khân păng kŭp ta neh, jêh ri klach hâu ngăn.$b$,false),
('bunong-vn','MAT',17,7,null,$b$Ƀiă lah Brah Yêsu hăn êp pah khân păng jêh ri lah: “Dâk hom, lơi klach ôh.”$b$,false),
('bunong-vn','MAT',17,8,null,$b$Jêh ri khân păng n'gơr uănh saơ knŏng du huê Brah Yêsu.$b$,true),
('bunong-vn','MAT',17,9,null,$b$Dôl khân păng trŭnh tă bơh yôk, Brah Yêsu buay khân păng pô aơ: “Lơi nkoch bri ma bu ôh nau khân may saơ tât Kon Bunuyh dâk rêh tay.”$b$,true),
('bunong-vn','MAT',17,10,null,$b$Phung oh mon Păng ôp Păng pô aơ: “Mâm ƀư phung kôranh nchih sămƀŭt lah Y-Êli mra văch lor?”$b$,false),
('bunong-vn','MAT',17,11,null,$b$Păng plơ̆ lah ma khân păng: “Nanê̆, nanê̆ Y-Êli mra văch nkra lĕ rngôch ndơ;$b$,true),
('bunong-vn','MAT',17,12,null,$b$Ƀiă lah gâp lah ma khân may Y-Êli văch jêh, jêh ri bu mâu gĭt năl păng ôh, ƀiă lah bu ƀư ma păng tĭng nâm bu ŭch. Kon Bunuyh mra dơn nau rêh ni bơh ti khân păng.”$b$,false),
('bunong-vn','MAT',17,13,null,$b$Pô ri phung oh mon gĭt rbăng ma Păng ngơi ma Y-Yôhan nơm ƀư ƀaptem yơh.$b$,false),
('bunong-vn','MAT',17,14,null,$b$Tơ lah khân păng plơ̆ ta phung âk, geh du huê bunuyh hăn dăch chon kômâk ta năp Păng jêh ri lah:$b$,true),
('bunong-vn','MAT',17,15,null,$b$“Ơ Kôranh Brah ơi, yô̆ an ma kon gâp ƀă, yor lah păng brŭt ndrăng, rêh ni ngăn, păng vay prah tâm ŭnh, jêh ri tâm dak.$b$,false),
('bunong-vn','MAT',17,16,null,$b$Gâp njŭn păng jêh ma phung oh mon may, ƀiă lah khân păng mâu dơi ƀư bah păng ôh.”$b$,false),
('bunong-vn','MAT',17,17,null,$b$Brah Yêsu plơ̆ lah: “Hơi ndŭl mpôl mâu chroh jêh ri tih mhĭk, ndah jŏ gâp mra gŭ ndrel đah khân may? Ndah jŏ gâp mra nsrôih đah khân may? Njŭn leo păng ma gâp.”$b$,false),
('bunong-vn','MAT',17,18,null,$b$Jêh ri Brah Yêsu ngơi ktang ngăn ma brah mhĭk. Păng luh ro bơh kon se nây. Tâm mông nây ro kon se nây bah.$b$,false),
('bunong-vn','MAT',17,19,null,$b$Jêh nây phung oh mon hăn dăch Brah Yêsu jêh ri ôp êng Păng: “Mâm ƀư hên mâu dơi nsot brah mhĭk?”$b$,true),
('bunong-vn','MAT',17,20,null,$b$Păng plơ̆ lah ma khân păng: “Yor lah nau chroh khân may jê̆, gâp lah nanê̆ ma khân may, tơ lah khân may geh nau chroh nâm bu du găr trau, khân may dơi lah ma yôk aơ: Du hom may ntŭk êng, jêh ri păng du ro, jêh ri mâu geh ôh nau khân may mâu dơi ƀư.$b$,false),
('bunong-vn','MAT',17,21,null,$b$Ƀiă lah ntil brah mhĭk aơ dơi luh du knŏng ma nau mbơh sơm jêh ri ma nau ât sông sa.”$b$,false),
('bunong-vn','MAT',17,22,null,$b$Dôl khân păng hăn lam n'gor Galilê, Brah Yêsu lah ma khân păng: “Bu mra jao Kon Bunuyh tâm ti bunuyh.$b$,true),
('bunong-vn','MAT',17,23,null,$b$Phung nây mra nkhĭt Păng, ƀiă lah tăch pe nar păng mra dâk rêh đŏng.” Jêh ri phung oh mon Păng rngot ngăn.$b$,false),
('bunong-vn','MAT',17,24,null,$b$Tơ lah khân păng tât ta ƀon Kapernum, đơ phung riu pi hăn dăch Y-Pêtrôs jêh ri lah ma păng, “Kôranh nơm nti may, păng rvăt sămƀŭt pi lĕ?”$b$,true),
('bunong-vn','MAT',17,25,null,$b$Y-Pêtrôs plơ̆ lah, “Păng rvăt lĕ.” Tơ lah Y-Pêtrôs lăp jêh tâm ngih, Brah Yêsu ôp lor ma păng, lah, “Mâm may mĭn, hơi Y-Simôn? Mbah tă luh phung hađăch neh ntu riu pi? Tă bơh phung kon khân păng, mâu lah tă phung bu năch?”$b$,false),
('bunong-vn','MAT',17,26,null,$b$Y-Pêtrôs plơ̆ lah: “Tă bơh phung bu năch.” Brah Yêsu lah: “Bi phung kon, mâu lĕ chê̆ pi.$b$,true),
('bunong-vn','MAT',17,27,null,$b$Ƀiă lah gay ma he mâu ƀư tŭp khân păng, hăn hom may ta dak mƀŭt, chê̆ ndar ka, jêh ri sŏk ka geh ndar lor lơn, may pơk mbung păng, may mra saơ du rnglay prăk dăng, sŏk prăk nây, chê̆ pi ma gâp nđâp ma may.”$b$,false),
('bunong-vn','MAT',18,1,null,$b$Dôl nây phung oh mon hăn dăch Brah Yêsu jêh ri lah: “Mbu nơm jêng toyh lơn tâm ƀon bri hađăch Brah Ndu?”$b$,true),
('bunong-vn','MAT',18,2,null,$b$Brah Yêsu kuăl du huê kon se jê̆, n'gân ta nklang khân păng jêh ri lah:$b$,false),
('bunong-vn','MAT',18,3,null,$b$“Nanê̆ gâp lah ma khân may, tơ lah khân may mâu rgâl jêng nâm bu kon se jê̆, khân may mâu dơi lăp tâm ƀon bri hađăch Brah Ndu ôh.$b$,false),
('bunong-vn','MAT',18,4,null,$b$Pô ri mbu nơm geh nau dêh rhêt nâm bu kon se jê̆ aơ, nơm nây yơh toyh lơn tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','MAT',18,5,null,$b$Mbu nơm rom kon se jê̆ aơ tâm amoh gâp, păng jêng nâm bu rom gâp lĕ.$b$,false),
('bunong-vn','MAT',18,6,null,$b$Ƀiă lah tơ lah du huê bunuyh ƀư tŭp du huê tâm phung kon se jê̆ aơ, hŏ chroh jêh ma gâp, ueh lơn kât du mlâm mpăl lŭ ta trô ko păng jêh ri klŭp păng tâm dak mƀŭt.$b$,false),
('bunong-vn','MAT',18,7,null,$b$“Rêh ni yơh ta neh ntu yor ƀư nau tŭp! Yor lah nau ƀư tŭp mra geh, ƀiă lah rêh ni yơh ma mbu nơm ăn nau tŭp tât!$b$,true),
('bunong-vn','MAT',18,8,null,$b$Tơ lah ti may mâu lah jâng may ƀư tŭp may tâm nau tih, sreh lơi păng jêh ri mƀăr lơi păng ngai tă bơh may, yor lah ueh lơn ma may lăp tâm nau rêh đah ti lŭt mâu lah jâng lŭt, ma may geh rĭng jâng ti jêh ri bu mƀăr may tâm ŭnh mâu blau khĭt.$b$,false),
('bunong-vn','MAT',18,9,null,$b$Tơ lah măt may ƀư tŭp may tâm nau tih, rvek lơi păng jêh ri mƀăr păng ngai tă bơh may. Yor lah ueh lơn ma may lăp tâm nau rêh geh knŏng du đah măt, ma may geh rĭng măt jêh ri bu mƀăr may tâm ntŭk ndrung ŭnh.”$b$,false),
('bunong-vn','MAT',18,10,null,$b$“Njrăng hom khân may lơi tâm rmot ma du huê tâm phung kon se jê̆ aơ; yor lah gâp lah ma khân may, tâm trôk phung Tông mpăr ueh khân păng uănh ƀa ƀơ ma muh măt Mbơ̆ gâp, Nơm gŭ tâm trôk.$b$,true),
('bunong-vn','MAT',18,11,null,$b$Yor lah Kon Bunuyh ŭch tâm rklaih mbu nơm roh jêh.$b$,false),
('bunong-vn','MAT',18,12,null,$b$Mâm khân may mĭn? Tơ lah du huê bunuyh geh du rhiăng mlâm biăp, ƀiă lah du mlâm roh tâm bri, di đŏng păng lơi phung sĭn jât ma sĭn mlâm tâm yôk, ŭch hăn joi du mlâm roh tâm bri?$b$,false),
('bunong-vn','MAT',18,13,null,$b$Nanê̆ gâp lah ma khân may, tơ lah păng saơ jêh biăp roh, păng geh nau răm maak ngăn ma biăp nây, âk lơn ma phung sĭn jât sĭn mlâm mâu geh roh.$b$,false),
('bunong-vn','MAT',18,14,null,$b$Nâm bu pô nây lĕ Mbơ̆ khân may tâm trôk mâu ŭch ôh du huê tâm phung jê̆ aơ roh rai.”$b$,false),
('bunong-vn','MAT',18,15,null,$b$“Tơ lah oh nâu may tih đah may, hăn ngơi êng ndrăng khân may nơm. Tơ lah păng dơn nau may, may dơi geh oh nâu may.$b$,true),
('bunong-vn','MAT',18,16,null,$b$Tơ lah păng mâu dơn, jă bar pe nuyh ndrel may, pô ri tĭng nâm nau bar pe nuyh mbơh, lĕ rngôch nau mra jêng ngăn.$b$,false),
('bunong-vn','MAT',18,17,null,$b$Tơ lah păng dun, mâu ŭch dơn nau khân păng, mbơh nau nây ma phung ngih Brah Ndu; jêh ri tơ lah păng dun mâu ŭch dơn, nau phung ngih Brah Ndu, may mra kơp păng nâm bu bunuyh pa dih mâu lah nơm riu pi.$b$,true),
('bunong-vn','MAT',18,18,null,$b$Nanê̆ gâp mbơh ma khân may, lĕ rngôch ndơ khân may kât ta neh ntu mra kât tâm trôk, jêh ri lĕ rngôch ndơ khân may pơk ta neh ntu mra pơk tâm trôk.$b$,false),
('bunong-vn','MAT',18,19,null,$b$Gâp lah đŏng ma khân may, tơ lah bar hê tâm phung khân may ta neh ntu du ai mbơh sơm, dăn du ntil nau Mbơ̆ gâp tâm ƀon ueh klơ, mra ăn nau nây ma khân may.$b$,false),
('bunong-vn','MAT',18,20,null,$b$Yor lah ta ntŭk geh bar pe nuyh khân may tâm rƀŭn, ma amoh săk gâp, ta nây gâp gŭ ndrel.”$b$,true),
('bunong-vn','MAT',18,21,null,$b$Y-Pêtrôs hăn dăch Brah Yêsu jêh ri lah ma păng: “Ơ Kôranh Brah ơi, ndah tơ̆ gâp mra yô̆ an ma oh nâu gâp, tơ lah păng tih đah gâp? Di lĕ pơh tơ̆ ?”$b$,true),
('bunong-vn','MAT',18,22,null,$b$Brah Yêsu plơ̆ lah ma păng: “Gâp mâu lah ma may pơh tơ̆ ôh, ƀiă lah pơh jât tơ̆ pơh.”$b$,false),
('bunong-vn','MAT',18,23,null,$b$“Pô ri ƀon bri hađăch Brah Ndu, jêng nâm bu du huê hađăch ŭch tĭng rnon phung oh mon păng, khan rnon đah păng.$b$,true),
('bunong-vn','MAT',18,24,null,$b$Tơ lah păng ntơm kơp bu nhŭp njŭn ma păng du huê khan rnon jât rbăn prăk;$b$,false),
('bunong-vn','MAT',18,25,null,$b$ƀiă lah oh mon nây mâu geh prăk trok rnon ôh, pô ri kôranh păng đă bu tăch păng, nđâp ma ur kon păng, jêh ri lĕ rngôch ndơ păng geh, gay trok rnon.$b$,false),
('bunong-vn','MAT',18,26,null,$b$Oh mon nây kuăn ta jâng păng, chon mon mbah ta năp păng jêh ri lah: ‘Nsrôih kâp gâp ƀă, gâp mra trok lĕ rngôch.’$b$,false),
('bunong-vn','MAT',18,27,null,$b$Pô ri kôranh păng yô̆ an ma păng, ăn păng sĭt jêh ri mƀơk lơi păng jêng kon me.$b$,false),
('bunong-vn','MAT',18,28,null,$b$Ƀiă lah dôl păng luh tă bơh kôranh păng, păng mâp đah du huê tâm phung băl păng pah kan ndrel păng, ô băl khan rnon păng jât rêl; pô ri păng djôt kuăn rdâng ô băl, pet trô ko jêh ri lah, trok hom rnon gâp.$b$,false),
('bunong-vn','MAT',18,29,null,$b$Băl păng kuăn ta jâng păng jêh ri vơh vơl ma păng, srôih kâp gâp ƀă, gâp mra trok rnon may rĭng lĕ rngôch.$b$,false),
('bunong-vn','MAT',18,30,null,$b$Ƀiă lah păng mâu iăt ôh. Păng nhŭp krŭng ô băl tâm ndrung, tât ô băl tâm lôch rnon.$b$,false),
('bunong-vn','MAT',18,31,null,$b$Phung băl păng saơ pô nây, khân păng rngot ngăn hăn mbơh ma kôranh khân păng, lĕ nau hŏ tât jêh.$b$,true),
('bunong-vn','MAT',18,32,null,$b$Pô ri kôranh păng kuăl păng jêh ri lah, hơi oh mon ƀai mhĭk gâp, gâp mƀơk jêh rnon đah may, yor lah may vơh vơl ma gâp;$b$,false),
('bunong-vn','MAT',18,33,null,$b$Mâm ƀư may mâu yô̆ an ma băl may, pah kan ndrel may, nâm bu gâp hŏ yô̆ jêh ma may?$b$,false),
('bunong-vn','MAT',18,34,null,$b$Pô ri kôranh păng ji nuih ngăn, jao păng ma nơm chiă ndrung, krŭng păng kŏ tât păng chê̆ lôch rnon.$b$,false),
('bunong-vn','MAT',18,35,null,$b$Tơ lah ăp nơm tâm phung khân may mâu yô̆ an ma oh nâu păng, ma lĕ nuih n'hâm, Mbơ̆ gâp tâm trôk mra ƀư ma khân may tâm ban lĕ.”$b$,false),
('bunong-vn','MAT',19,1,null,$b$Tơ lah jêh Brah Yêsu ngơi nau nây, Păng du tă bơh n'gor Galilê, hăn ta n'gor Yuđa ta kăl tê̆ kơh dak krong Yurdan.$b$,true),
('bunong-vn','MAT',19,2,null,$b$Geh âk bunuyh tĭng Păng, jêh ri Păng ƀư bah phung ji kuet ta nây.$b$,true),
('bunong-vn','MAT',19,3,null,$b$Phung Pharisi hăn êp Păng gay rlong uănh Păng jêh ri lah: “Vay lĕ ăn bu cha lơi ur.”$b$,true),
('bunong-vn','MAT',19,4,null,$b$Brah Yêsu plơ̆ lah: “Khân may mâu mâp uănh hĕ nau nchih aơ: Kăl e ri nơm rhăk njêng du huê bu klâu jêh ri du huê bu ur,$b$,false),
('bunong-vn','MAT',19,5,null,$b$jêh ri lah: ‘Yor nây bu klâu mra cha lơi mê̆ mbơ̆ păng jêh ri gŭ ndrel đah ur păng, jêh ri bar hê khân păng mra jêng du nglay săk?’$b$,false),
('bunong-vn','MAT',19,6,null,$b$Pô ri khân păng mâu hôm jêng bar ôh ƀiă lah knŏng du nglay săk. Pô ri bunuyh mâu dơi tâm nkhah nkhat ôh đơ bunuyh Brah Ndu hŏ tâm nđăp jêh.”$b$,false),
('bunong-vn','MAT',19,7,null,$b$Phung Pharisi lah ma Păng: “Mâm ƀư Y-Môis ntăm ăn ƀư sămƀŭt tâm cha lơi ma bu ur, bu ŭch cha lơi?”$b$,true),
('bunong-vn','MAT',19,8,null,$b$Păng plơ̆ lah: “Yor lah nuih n'hâm khân may dăng, pô ri Y-Môis ntăm ăn cha lơi ur khân may, ƀiă lah kăl e mâu di pô ri ôh.$b$,false),
('bunong-vn','MAT',19,9,null,$b$Jêh ri gâp mbơh ma khân may. Mbu nơm cha lơi ur păng, tơ lah păng mâu jêng văng tĭr, jêh ri gŭ tay ur êng, păng jêng bunuyh văng tĭr, jêh ri mbu nơm gŭ bu ur, hŏ bu cha lơi jêh, păng tâm ban lĕ jêng bunuyh văng tĭr.”$b$,false),
('bunong-vn','MAT',19,10,null,$b$Phung oh mon lah ma Păng: “Tơ lah bu klâu gŭ đah ur păng pô ri. Ueh lơn păng mâu gŭ ur ôh.”$b$,false),
('bunong-vn','MAT',19,11,null,$b$Păng plơ̆ lah ma khân păng: “Mâu di lĕ rngôch dơi dơn nau nây, ƀiă lah knŏng phung geh nau gĭt rbăng.$b$,false),
('bunong-vn','MAT',19,12,null,$b$Yor lah geh phung bu klâu janh jêh tă bơh ndŭl mê̆ păng, geh ƀa ƀă phung bunuyh hŏ char, jêh ri geh phung char lơi, yor lah ŭch prăp khân păng nơm ma ƀon bri hađăch Brah Ndu. Pô ri mbu nơm dơi dơn nau ngơi aơ, ăn păng sŏk dơn hom.”$b$,false),
('bunong-vn','MAT',19,13,null,$b$Dôl nây bu njŭn leo phung kon se jê̆ ma Păng, gay ăn Păng pah ti mbơh sơm ăn ma khân păng. Jêh ri phung oh mon Păng buay.$b$,true),
('bunong-vn','MAT',19,14,null,$b$Ƀiă lah Brah Yêsu lah: “Mƀơk phung kon se jê̆ văch ta gâp, lơi buay khân păng ôh; yor lah ƀon bri hađăch Brah Ndu prăp ma phung jêng nâm bu khân păng.”$b$,false),
('bunong-vn','MAT',19,15,null,$b$Jêh păng pah ti ta khân ô băl, păng du tă bơh ntŭk nây.$b$,true),
('bunong-vn','MAT',19,16,null,$b$Aơ geh du huê hăn êp Păng lah: “Hơi kôranh nơm nti, mâm nau ueh gâp mra ƀư gay ma geh nau rêh n'ho ro?”$b$,true),
('bunong-vn','MAT',19,17,null,$b$Brah Yêsu lah ma păng: “Mâm ƀư may ôp gâp ma nau ueh? Knŏng du huê jêng ueh. Tơ lah may ŭch lăp tâm nau rêh, ăn may tông nau vay.”$b$,false),
('bunong-vn','MAT',19,18,null,$b$Păng lah: “Moh nau vay nây.” Brah Yêsu plơ̆ lah ma păng: “Ver lơi ta nkhĭt bu, ver lơi may ntŭng ndô ndơ bu, ver lơi may mƀruh.$b$,false),
('bunong-vn','MAT',19,19,null,$b$Yơk ma mê̆ mbơ̆ may, jêh ri may mra rŏng ma băl may nâm bu may nơm.”$b$,false),
('bunong-vn','MAT',19,20,null,$b$Bu klâu ndăm nây lah ma păng: “Gâp tông jêh lĕ rngôch nau vay nây. Moh nau ê hŏ rĭng?”$b$,false),
('bunong-vn','MAT',19,21,null,$b$Brah Yêsu lah ma păng: “Tơ lah may ŭch jêng sŏng nanê̆, hăn hom, tăch lĕ rngôch ndơ may geh jêh ri tâm pă ma phung rêh ni, jêh ri may mra geh âk drăp ndơ khlay tâm trôk, jêh ri văch hom tĭng ndô̆ gâp.”$b$,false),
('bunong-vn','MAT',19,22,null,$b$Ƀiă lah tơ lah bu klâu ndăm tăng nau ngơi nây, păng du sĭt bêng ma nau rngot. Yor lah păng ndrŏng ngăn.$b$,false),
('bunong-vn','MAT',19,23,null,$b$Brah Yêsu lah ma phung oh mon păng: “Nanê̆ gâp mbơh ma khân may, du huê ndrŏng lăp tâm ƀon bri hađăch Brah Ndu jêr ngăn.$b$,true),
('bunong-vn','MAT',19,24,null,$b$Gâp lah tay ma khân may. Dơh lơn ma du mlâm seh samô lăp tâm trôm nglai, ma du huê ndrŏng lăp tâm ƀon hađăch Brah Ndu.”$b$,false),
('bunong-vn','MAT',19,25,null,$b$Tăng nau ngơi nây, phung oh mon păng gŭ hih rhâl jêh ri lah: “Pô ri mbu nơm dơi klaih?”$b$,false),
('bunong-vn','MAT',19,26,null,$b$Brah Yêsu uănh ta khân păng jêh ri lah: “Nau nây bunuyh mâu dơi ƀư ôh, ƀiă lah Brah Ndu dơi ƀư da dê lĕ rngôch ndơ.”$b$,false),
('bunong-vn','MAT',19,27,null,$b$Y-Pêtrôs lah ma Păng: “Aơ, hên lơi lĕ rngôch ndơ jêh ri tĭng ndô̆ may. Moh ndơ hên mra geh?”$b$,true),
('bunong-vn','MAT',19,28,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Nanê̆ gâp mbơh ma khân may, ta nar lĕ rngôch ndơ mra tâm rgâl mhe, tơ lah Kon Bunuyh mra gŭ ta sưng hađăch nau chrêk rmah Păng, khân may phung tĭng ndô̆ gâp mra gŭ ta jât ma bar sưng hađăch tâm ban lĕ. Phat dôih jât ma bar ndŭl mpôl phung Israel.$b$,false),
('bunong-vn','MAT',19,29,null,$b$Jêh ri mbu nơm cha lơi ruh oh, mê̆ mbơ̆ , kon sau mâu lah mir lŏ ƀa ƀă păng, yor amoh gâp, mra geh du rhiăng tơ̆ âk lơn nđâp ma nau rêh n'ho ro.$b$,false),
('bunong-vn','MAT',19,30,null,$b$Ƀiă lah âk phung lor mra jêng nglĕ dŭt, jêh ri âk phung nglĕ dŭt mra jêng lor.”$b$,false),
('bunong-vn','MAT',20,1,null,$b$“Ƀon bri hađăch Brah Ndu, jêng nâm bu du huê kôranh ngih, ơm ôi păng hăn gay dŏng phung pah kan tâm mir play kriăk ƀâu păng.$b$,true),
('bunong-vn','MAT',20,2,null,$b$Tơ lah tâm nkol jêh đah phung pah kan ma du rêl du nar, păng njuăl khân păng hăn ta mir play kriăk ƀâu păng.$b$,false),
('bunong-vn','MAT',20,3,null,$b$Klăp lah tâm sĭn mông păng plơ̆ tay jêh ri saơ phung bunuyh gŭ dơm ta ngih tăch drăp.$b$,false),
('bunong-vn','MAT',20,4,null,$b$Păng lah ma phung nây: ‘Ăn khân may hăn pah kan tâm mir play kriăk ƀâu gâp, jêh ri gâp mra nkhôm khân may.’ Phung nây hăn ro.$b$,false),
('bunong-vn','MAT',20,5,null,$b$Ta nar nklang bôk jêng ta pe mông păng plơ̆ tay jêh ri ƀư tâm ban đŏng.$b$,false),
('bunong-vn','MAT',20,6,null,$b$Ta prăm mông măng păng luh tay, saơ phung êng gŭ dơm; jêh ri păng lah ma khân păng: ‘Mâm ƀư khân may gŭ dơm dam lôch du nar ta aơ?’$b$,false),
('bunong-vn','MAT',20,7,null,$b$Phung nây plơ̆ lah ma păng: ‘Yor lah mâu geh bunuyh ŭch dŏng hên.’ Păng lah ma phung nây: ‘Hăn hom khân may tâm ban đŏng tâm mir play kriăk ƀâu gâp.’$b$,false),
('bunong-vn','MAT',20,8,null,$b$“Tơ lah ngo jêh, kôranh mir lah ma nơm mât kan păng: ‘Kuăl hom phung pah kan jêh ri ƀơk khân păng, may ƀơk ntơm bơh nglĕ dŭt tât ta phung lor.’$b$,false),
('bunong-vn','MAT',20,9,null,$b$Phung văch ta prăm mông măng geh nau nkhôm ma khân păng du huê du rêl.$b$,false),
('bunong-vn','MAT',20,10,null,$b$Phung văch bơh lor tât đŏng, khân păng mĭn mra geh âk lơn; ƀiă lah khân păng geh nau nkhôm ăp nơm khân păng du rêl tâm ban lĕ.$b$,false),
('bunong-vn','MAT',20,11,null,$b$Jêh khân păng sŏk prăk nây khân păng ngơi kek ma kôranh ngih,$b$,false),
('bunong-vn','MAT',20,12,null,$b$lah: ‘Phung văch pa kơi pah kan knŏng du mông jêh ri may kơp khân păng tâm ban hên, phung pah kan rgănh jêh ri gŭ tâm duh nar ktang lĕ du nar.’$b$,false),
('bunong-vn','MAT',20,13,null,$b$Ƀiă lah păng plơ̆ lah ma du huê tâm phung khân păng: ‘Hơi jiăng, gâp mâu tih đah may ôh; di lĕ may tâm nkol jêh đah gâp ma may mra sa du rêl tâm du nar?$b$,false),
('bunong-vn','MAT',20,14,null,$b$Sŏk hom prăk may jêh ri du; gâp ŭch ăn ma nơm văch pa kơi aơ tâm ban rnoh đah may.$b$,true),
('bunong-vn','MAT',20,15,null,$b$Gâp mâu vay dŏng hĕ prăk gâp tĭng nâm gâp ŭch? Mâu lah, yor lah may saơ gâp gŭ ueh, may uănh gâp đah măt mhĭk?’$b$,false),
('bunong-vn','MAT',20,16,null,$b$Pô ri phung nglĕ dŭt mra jêng lor jêh ri phung lor mra jêng nglĕ dŭt.”$b$,false),
('bunong-vn','MAT',20,17,null,$b$Dôl Brah Yêsu hăn ta ƀon Yêrusalem, Păng leo êng phung jât ma bar oh mon ndrel ma Păng, rŏ trong Păng lah ma khân păng pô aơ:$b$,true),
('bunong-vn','MAT',20,18,null,$b$“Aơ, he hăn ta ƀon Yêrusalem; Bu mra nhŭp Kon Bunuyh, jao ma phung n'gâng kôranh ƀư brah jêh ri ma phung kôranh nchih sămƀŭt, jêh ri phung khân păng mra nkhĭt lơi Păng,$b$,false),
('bunong-vn','MAT',20,19,null,$b$khân păng mra ăn Păng ma phung pa dih, gay ma bu mưch ma Păng, dong Păng ma mâng, jêh ri pâng Păng ta si tâm rkăng, jêh ri tăch pe nar Păng mra dâk rêh đŏng.”$b$,false),
('bunong-vn','MAT',20,20,null,$b$Dôl nây, mê̆ phung kon Y-Sêƀêđê, nđâp ma phung kon păng hăn êp Brah Yêsu. Bu ur nây kŭnh mbah ma Păng ŭch dăn du ntil nau.$b$,true),
('bunong-vn','MAT',20,21,null,$b$Brah Yêsu lah: “Moh nau ay ŭch?” Bu ur nây lah: “Phung bar hê kon gâp, gŭ du huê pa ma, du huê pa chiau may, tâm ƀon bri hađăch may.”$b$,false),
('bunong-vn','MAT',20,22,null,$b$Brah Yêsu plơ̆ lah: “Khân ay mâu gĭt rbăng ôh, moh nau khân ay dăn. Khân ay dơi lĕ nhêt kchok gâp nhêt?” Khân păng lah: “Dơi đŏng.”$b$,false),
('bunong-vn','MAT',20,23,null,$b$Păng lah: “Ngăn khân may mra nhêt kchok rsang gâp nhêt, ƀiă lah nau dơi gŭ pa ma mâu lah pa chiau gâp, mâu di gâp ôh nơm ăn nau nây, ƀiă lah mbu nơm Mbơ̆ gâp nkra an jêh.”$b$,false),
('bunong-vn','MAT',20,24,null,$b$Tơ lah phung jât nuyh êng tăng nau dăn nây, khân păng nuih ma phung bar hê oh nâu nây.$b$,true),
('bunong-vn','MAT',20,25,null,$b$Ƀiă lah Brah Yêsu kuăl khân păng jêh ri lah: “Khân may gĭt, phung hađăch bri êng, tŭn jot phung ƀon lan, jêh ri phung kôranh toyh, chiă uănh phung ƀon lan ma nau nchâp.$b$,false),
('bunong-vn','MAT',20,26,null,$b$Tâm phung khân may mâu di pô ri ôh; ƀiă lah mbu nơm ŭch jêng toyh tâm phung khân may, ăn păng jêng oh mon khân may,$b$,false),
('bunong-vn','MAT',20,27,null,$b$jêh ri mbu nơm ŭch jêng kôranh, ăn păng jêng dĭk khân may;$b$,false),
('bunong-vn','MAT',20,28,null,$b$Pô ri yơh mâu di Kon Bunuyh văch ăn bu pah kan ma Păng ôh, ƀiă lah Păng văch pah kan ma bu, jêh ri ăn nau rêh Păng nơm jêng nau tâm chuai ma âk bunuyh.”$b$,false),
('bunong-vn','MAT',20,29,null,$b$Dôl khân păng luh tă bơh ƀon Yêrikô, geh âk bunuyh tĭng Brah Yêsu.$b$,true),
('bunong-vn','MAT',20,30,null,$b$Aơ, geh bar hê chieh măt gŭ ta meng trong, tơ lah khân păng tăng ma Brah Yêsu rgăn ta nây, khân păng nter ro: “Ơ Kôranh Brah, kon Y-Đavit ơi, yô̆ an ma hên ƀă!”$b$,false),
('bunong-vn','MAT',20,31,null,$b$Phung âk buay ăn khân păng gŭ rklăk, ƀiă lah khân păng nter lơ hâu lơn: “Ơ Kôranh Brah, kon Y-Đavit ơi, yô̆ an ma hên ƀă!”$b$,false),
('bunong-vn','MAT',20,32,null,$b$Brah Yêsu gŭ râng kuăl khân păng jêh ri lah: “Moh khân may ŭch gâp ƀư ma khân may?”$b$,false),
('bunong-vn','MAT',20,33,null,$b$Khân păng lah ma Brah Yêsu: “Ơ Kôranh Brah ơi, ăn măt hên saơ ang.”$b$,true),
('bunong-vn','MAT',20,34,null,$b$Pô ri Brah Yêsu geh nau yô̆, pah măt khân păng, jêh ri ƀât lât ta nây măt khân păng saơ ang ro, jêh ri khân păng tĭng ndô̆ Brah Yêsu.$b$,false),
('bunong-vn','MAT',21,1,null,$b$Tơ lah khân păng dăch tât ta ƀon Yêrusalem, tât jêh ta Bêtphajê, êp yôk Ôlivơ, Brah Yêsu njuăl bar hê oh mon,$b$,true),
('bunong-vn','MAT',21,2,null,$b$lah ma khân păng pô aơ: “Hăn hom ma ƀon ta năp khân may. Ta nây khân may mra saơ ro du mlâm seh bri me bu kât, jêh ri kon păng têk ndrel; doh hom seh bri nây têk njŭn ma gâp,$b$,false),
('bunong-vn','MAT',21,3,null,$b$Tơ lah bu ôp khân may, ăn khân may lah ma khân păng pô aơ: ‘Kôranh Brah ŭch ma bar mlâm seh bri aơ,’ pô ri bu mra ăn khân may têk ro.”$b$,false),
('bunong-vn','MAT',21,4,null,$b$Lĕ rngôch nau nây tât, yor lah gay ƀư nanê̆ nau kôranh nơm mbơh lor ngơi jêh pô aơ:$b$,false),
('bunong-vn','MAT',21,5,null,$b$“Lah hom ma kon bu ur ƀon Siôn. Aơ, hađăch văch ma may, ma nau rdơ̆ rbăn, ncho seh bri, kon seh bri, kon me.”$b$,false),
('bunong-vn','MAT',21,6,null,$b$Phung oh mon luh hăn ro jêh ri ƀư tĭng nâm nau Brah Yêsu ntăm jêh.$b$,false),
('bunong-vn','MAT',21,7,null,$b$Khân păng têk njŭn seh bri me jêh ri kon păng, ntă ao khân păng ta klơ kŭr kuyh seh bri nây, jêh ri ăn Brah Yêsu ncho.$b$,false),
('bunong-vn','MAT',21,8,null,$b$Jêh ri phung bunuyh ƀon lan âk râk ngăn, lăk ao khân păng rŏ trong, ƀa ƀă sreh n'gĭng si jêh ri pla bêng trong.$b$,false),
('bunong-vn','MAT',21,9,null,$b$Phung âk hăn pa năp pa kơi Păng troh huy ktang: “Hôsana ma kon Y-Đavit! Ueh maak yơh ma nơm văch tâm amoh Kôranh Brah! Hôsana ta ntŭk klơ trôk prêh lơn!”$b$,false),
('bunong-vn','MAT',21,10,null,$b$Tơ lah Păng lăp jêh tâm ƀon Yêrusalem, lĕ rngôch bunuyh tâm ƀon hih rhâl jêh ri lah: “Mbu nơm aơ?”$b$,true),
('bunong-vn','MAT',21,11,null,$b$Jêh ri phung âk lah: “Păng aơ Brah Yêsu, kôranh nơm mbơh lor tă bơh ƀon Nasaret, n'gor Galilê.”$b$,false),
('bunong-vn','MAT',21,12,null,$b$Brah Yêsu lăp tâm ngih brah Yuđa. Păng nsot lĕ rngôch bunuyh gŭ tăch drăp tâm ngih nây. Păng nklơ̆ sưng phung rgâl prăk, ntŭk phung tăch plŭk.$b$,true),
('bunong-vn','MAT',21,13,null,$b$Păng lah ma phung nây: “Geh nchih jêh pô aơ: ‘Ngih gâp jêng ngih kuăl mbơh sơm’, ƀiă lah khân may njêng păng ntŭk phung ntŭng.”$b$,false),
('bunong-vn','MAT',21,14,null,$b$Dôl nây phung chieh măt, phung ji jâng văch ta Păng tâm ngih brah Yuđa, jêh ri Păng ƀư bah lĕ rngôch khân păng.$b$,false),
('bunong-vn','MAT',21,15,null,$b$Ƀiă lah phung n'gâng kôranh ƀư brah, jêh ri phung kôranh nchih sămƀŭt saơ nau mbên khlay Păng ƀư, jêh ri tăng phung kon se nter ktang tâm ngih brah Yuđa: “Hôsana ma kon Y-Đavit!” Khân păng ji nuih ngăn.$b$,false),
('bunong-vn','MAT',21,16,null,$b$Khân păng lah ma Brah Yêsu: “May tăng lĕ nau phung kon se aơ lah?” Brah Yêsu plơ̆ lah ma khân păng: “Ơ, khân may mâu mâp uănh hĕ nau nchih jêh pô aơ: May geh jêh nau tâm rnê tă bơh bâr mbung phung kon se, jêh ri phung kon bê jê̆ hôm pu?”$b$,true),
('bunong-vn','MAT',21,17,null,$b$Jêh ri păng cha lơi phung nây, luh du hăn ta ƀon Ƀêtthani rlu ta nây.$b$,false),
('bunong-vn','MAT',21,18,null,$b$Ơm ôi taơ, dôl Păng plơ̆ ta ƀon toyh, Păng ji ngot.$b$,true),
('bunong-vn','MAT',21,19,null,$b$Saơ du tơm rvi ta trong, Păng hăn dăch tơm nây, ƀiă lah saơ knŏng n'ha. Pô ri Păng lah ma tơm play nây: “Ntơm bơh aƀaơ mâu mra play đŏng ôh!” Ƀât lât tơm rvi kro ro.$b$,false),
('bunong-vn','MAT',21,20,null,$b$Phung oh mon saơ, pô ri hih rhâl jêh ri lah: “Mâm ƀư tơm rvi aơ kro mih?”$b$,false),
('bunong-vn','MAT',21,21,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Nanê̆ gâp mbơh ma khân may, tơ lah khân may geh nau rnơm, jêh ri mâu đing ôh, mâu di knŏng ma tơm rvi ôh khân may dơi ƀư, ƀiă lah nđâp ma yôk aơ khân may dơi lah: ‘Du hom jêh ri nklăch hom ta dak mƀŭt,’ nau nây mra tât ro.$b$,false),
('bunong-vn','MAT',21,22,null,$b$Jêh ri lĕ rngôch nau khân may dăn ma nau rnơm dôl mbơh sơm, khân may mra sŏk dơn jêh.”$b$,false),
('bunong-vn','MAT',21,23,null,$b$Tơ lah Brah Yêsu lăp tâm ngih brah Yuđa, phung n'gâng kan kôranh ƀư brah jêh ri phung kôranh bu bŭnh bu ranh hăn êp Păng dôl Păng dâk nti, ôp Păng: “Mâm ƀư may dơi ƀư pô nây? Mbu nơm ăn ma may nau dơi nây?”$b$,true),
('bunong-vn','MAT',21,24,null,$b$Brah Yêsu plơ̆ lah: “Gâp ŭch ôp ma khân may tâm ban lĕ; tơ lah khân may dơi plơ̆ lah ma gâp, gâp mra lah mâm ƀư gâp dơi ƀư nau nây.$b$,false),
('bunong-vn','MAT',21,25,null,$b$Mbah tă luh nau ƀaptem Y-Yôhan, tă bơh trôk mâu lah tă bơh bunuyh?” Pô ri khân păng tâm nchră ndrăng khân păng pô aơ: ‘Lah he plơ̆ lah,’ tă bơh trôk păng mra lah he: ‘Mâm ƀư khân may mâu chroh ma nau Păng ngơi?’$b$,false),
('bunong-vn','MAT',21,26,null,$b$Tơ lah he plơ̆ lah, ‘tă bơh bunuyh,’ he klach ma phung ƀon lan; yor lah lĕ rngôch bunuyh uănh ma Y-Yôhan jêng kôranh nơm mbơh lor.”$b$,false),
('bunong-vn','MAT',21,27,null,$b$Pô ri khân păng plơ̆ lah pô aơ ma Brah Yêsu: “Hên mâu gĭt ôh.” Brah Yêsu lah ma khân păng: “Tâm ban lĕ gâp mâu lah ôh mâm ƀư gâp dơi ƀư pô ri.”$b$,false),
('bunong-vn','MAT',21,28,null,$b$“Mâm khân may mĭn? Du huê bunuyh geh bar huê kon bu klâu; păng lah ma du huê kon bôk rah pô aơ: ‘Hơi nâu, nar aơ may hăn pah kan tâm mir play kriăk ƀâu.’$b$,true),
('bunong-vn','MAT',21,29,null,$b$Păng plơ̆ lah: ‘Mâu, gâp mâu ŭch hăn ôh.’ Ƀiă lah jŏ djê̆ ta nây păng rmal nau tih păng, jêh ri păng hăn.$b$,false),
('bunong-vn','MAT',21,30,null,$b$Jêh ri mbơ̆ hăn lah tâm ban lĕ ma du huê kon êng; nơm aơ plơ̆ lah: ‘Ơ, gâp hăn.’ Ƀiă lah păng mâu hăn ôh.$b$,false),
('bunong-vn','MAT',21,31,null,$b$Mbu nơm tâm phung bar hê aơ ƀư tĭng nâm nau mbơ̆ păng ŭch?” Khân păng lah: “Nơm lor lơn.” Brah Yêsu lah ma khân păng: “Nanê̆ gâp lah ma khân may, phung riu pi jêh ri phung bu ur ka n'hong lăp tâm ƀon bri hađăch Brah Ndu lor lơn ma khân may.$b$,false),
('bunong-vn','MAT',21,32,null,$b$Yor lah Y-Yôhan văch jêh ma khân may tâm trong nau sŏng, ƀiă lah khân may mâu chroh ma păng ôh, Ƀiă lah phung riu pi, bu ur ka n'hong lah ma Brah Yêsu lah khân may saơ khân may mâu rmal ma nau tih khân may jêh ri chroh ma Păng ôh.”$b$,false),
('bunong-vn','MAT',21,33,null,$b$“Iăt hom nau hôr êng, geh du huê kôranh ngih tăm du lôk mir play kriăk ƀâu. Păng ƀư mpêr jŭm mir. Tâm nklang păng kuyh du ntu prăp ndjăt dak play kriăk ƀâu, jêh ri păng ƀư du mlâm ngih prêh, păng nkhôm bu mât jêh ri păng hăn du bri ngai.$b$,true),
('bunong-vn','MAT',21,34,null,$b$Tât yan pĕ play, păng mprơh njuăl phung oh mon nkhôm pĕ play kriăk ƀâu păng.$b$,true),
('bunong-vn','MAT',21,35,null,$b$Phung mât mir nhŭp lơi ô băl, lơh du huê, nkhĭt lơi du huê êng, jêh ri klŭp lŭ ma du huê êng.$b$,true),
('bunong-vn','MAT',21,36,null,$b$Păng prơh njuăl tay phung oh mon êng, âk lơn ma phung lor; jêh ri phung nây ƀư tâm ban lĕ ma khân păng.$b$,false),
('bunong-vn','MAT',21,37,null,$b$Nglĕ dŭt păng mprơh njuăl kon păng nơm ma phung nây jêh ri lah: ‘Khân păng mra yơk ma kon gâp.’$b$,false),
('bunong-vn','MAT',21,38,null,$b$Ƀiă lah tơ lah phung mât mir saơ kon păng, phung nây lah ndrăng khân păng: ‘Păng nây jêng nơm dơn drăp, kay he, nkhĭt lơi păng jêh ri he sŏk drăp păng.’$b$,false),
('bunong-vn','MAT',21,39,null,$b$Pô ri nhŭp ô băl, klŭp lơi pa dih, jêh ri nkhĭt lơi ô băl.$b$,false),
('bunong-vn','MAT',21,40,null,$b$Tơ lah kôranh nơm mir tât, mâm păng mra ƀư ma phung chiă mir nây?”$b$,false),
('bunong-vn','MAT',21,41,null,$b$Khân păng plơ̆ lah ma Brah Yêsu: “Păng mra ƀư rai phung ƀai nây ma nau rêh ni ji klâng, jêh ri păng mra nkhôm phung êng, chiă uănh mir play kriăk ƀâu păng, phung mra ăn play âk ta yan pĕ.”$b$,false),
('bunong-vn','MAT',21,42,null,$b$Brah Yêsu lah ma khân păng: “Khân may mâu mâp uănh hĕ tâm nau nchih pô aơ: ‘Lŭ phung ƀư ngih mƀăr lơi jêh, mra jêng lŭ njônh; kan nây Kôranh Brah ƀư, jêh ri jêng nau khlay ta năp măt he’?$b$,true),
('bunong-vn','MAT',21,43,null,$b$Yor nây gâp lah ma khân may, ƀon bri hađăch Brah Ndu mra pit lơi tă bơh khân may, jêh ri mra ăn ma ndŭl mpôl êng mra play.$b$,true),
('bunong-vn','MAT',21,44,null,$b$Mbu nơm mra tŭp ta klơ lŭ nây, mra nchah rai, mbu nơm lŭ nây tŭp klơ păng, păng mra lêk.”$b$,false),
('bunong-vn','MAT',21,45,null,$b$Tơ lah phung n'gâng kan kôranh ƀư brah jêh ri phung Pharisi tăng nau hôr nây, khân păng gĭt rbăng. Brah Yêsu ngơi di ma khân păng.$b$,true),
('bunong-vn','MAT',21,46,null,$b$Khân păng joi nau ŭch nhŭp Brah Yêsu, ƀiă lah khân păng klach ma phung âk, yor lah bu uănh ma Brah Yêsu jêng du huê kôranh nơm mbơh lor.$b$,false),
('bunong-vn','MAT',22,1,null,$b$Brah Yêsu ntĭt nau ngơi hôr pô aơ:$b$,true),
('bunong-vn','MAT',22,2,null,$b$“Ƀon bri hađăch Brah Ndu nâm bu du huê hađăch nkra nau nhêt sông toyh tâm nkol ur sai ma kon păng,$b$,false),
('bunong-vn','MAT',22,3,null,$b$jêh ri păng prơh njuăl phung oh mon ueh păng kuăl phung păng jă jêh; ƀiă lah phung nây mâu ŭch văch ôh.$b$,false),
('bunong-vn','MAT',22,4,null,$b$Păng prơh njuăl phung oh mon êng jêh ri ntăm ma khân păng pô aơ: ‘Lah ma phung gâp jă jêh pô aơ: Gâp nkra jêh ndơ sông sa toyh, gŭch jêh ndrôk jêh ri biăp lay, lĕ rngôch ndơ nkra jêh da dê; văch hom nhêt sông.’$b$,false),
('bunong-vn','MAT',22,5,null,$b$Ƀiă lah khân păng mâu chrê ôh. Ƀa ƀă luh hăn tâm mir lŏ, ƀa ƀă hăn tăch drăp,$b$,false),
('bunong-vn','MAT',22,6,null,$b$ƀa ƀă nhŭp phung oh mon, suai rak rtăp jêh ri nkhĭt lơi khân ô băl.$b$,false),
('bunong-vn','MAT',22,7,null,$b$Pô ri hađăch nuih, jêh ri păng njuăl phung ta han hăn, ƀư rai phung nkhĭt bunuyh nây, jêh ri su ƀon lan khân păng.$b$,false),
('bunong-vn','MAT',22,8,null,$b$Jêh ri păng lah ma phung oh mon păng: ‘Ndơ sông sa toyh hŏ nkra jêh, ƀiă lah phung gâp jă mâu khư ôh văch nhêt sa.$b$,false),
('bunong-vn','MAT',22,9,null,$b$Pô ri hăn hom tâm lĕ rngôch ntŭk trong tâm chruh, jă leo lĕ rngôch bunuyh khân may saơ, ăn khân păng văch nhêt sông.’$b$,false),
('bunong-vn','MAT',22,10,null,$b$Phung oh mon nây hăn lam trong sâng, jă leo lĕ rngôch bunuyh khân păng saơ, nđâp bunuyh mhĭk nđâp bunuyh ueh; tât jrô nhêt sa bêng bunuyh.$b$,false),
('bunong-vn','MAT',22,11,null,$b$“Tơ lah hađăch lăp ŭch uănh phung gŭ sông sa, păng saơ du huê bunuyh mâu nsoh ao prăp ma nau tâm nkol ur sai.$b$,true),
('bunong-vn','MAT',22,12,null,$b$Păng lah ma nơm nây: ‘Hơi jiăng, mâm ƀư may lăp mâu nsoh ao prăp nau tâm nkol ur sai?’ Bunuyh nây gŭ rklăk.$b$,false),
('bunong-vn','MAT',22,13,null,$b$Jêh ri hađăch lah ma phung oh mon păng: ‘Chăp jâng ti păng, jêh ri klŭp păng tâm ntŭk ngo pa dih; ta nây yơh mra geh nau nhĭm nhhiăng jêh ri nau rket sêk.’$b$,false),
('bunong-vn','MAT',22,14,null,$b$Yor lah geh âk bunuyh bu kuăl, ƀiă lah djê̆ bunuyh bu săch.”$b$,false),
('bunong-vn','MAT',22,15,null,$b$Dôl nây phung Pharisi hăn tâm chră ndrăng khân păng, ŭch joi nau nơih phong Brah Yêsu tâm nau păng ngơi.$b$,true),
('bunong-vn','MAT',22,16,null,$b$Khân păng njuăl phung oh mon khân păng ndrel ma phung băl hađăch Hêrôt lah ma păng pô aơ: “Hơi kôranh nơm nti, hên gĭt may jêng ngăn, jêh ri may nti trong Brah Ndu ma nau nanê̆; may mâu chrê ma bu ôh; yor lah may mâu uănh ma bunuyh pa dih ôh.$b$,false),
('bunong-vn','MAT',22,17,null,$b$Lah ma hên moh may mĭn. Dơi lĕ chê̆ pi ma Sêsar mâu lah mâu?”$b$,true),
('bunong-vn','MAT',22,18,null,$b$Brah Yêsu gĭt nau mĭn mhĭk khân păng, plơ̆ lah: “Mâm ƀư khân may ndơm gâp, hơi phung nuih n'hâm ndâp?$b$,false),
('bunong-vn','MAT',22,19,null,$b$Ăn gâp uănh prăk chê̆ pi nây.” Khân păng ăn ma Brah Yêsu du rêl prăk.$b$,false),
('bunong-vn','MAT',22,20,null,$b$Păng lah ma khân păng: “Mbu nơm rup jêh ri sămƀŭt nchih aơ?”$b$,false),
('bunong-vn','MAT',22,21,null,$b$Khân păng lah: “Sêsar.” Brah Yêsu lah ma khân păng: “Pô ri plơ̆ hom ma Sêsar ndơ Sêsar, jêh ri plơ̆ hom ma Brah Ndu ndơ Brah Ndu.”$b$,false),
('bunong-vn','MAT',22,22,null,$b$Tăng nau Brah Yêsu ngơi pô ri khân păng hih rhâl; jêh ri du, cha lơi Brah Yêsu gŭ êng.$b$,true),
('bunong-vn','MAT',22,23,null,$b$Nar nây lĕ geh phung Sađusê, phung lah mâu geh nau dâk rêh; khân păng hăn êp Brah Yêsu jêh ri ôp:$b$,true),
('bunong-vn','MAT',22,24,null,$b$“Hơi Kôranh nơm nti, Y-Môis lah: w‘Tơ lah du huê bunuyh ur khĭt mâu geh kon, oh păng mra ntrok noi ur nâu păng, jêh ri ăn geh ntrok mpôl nâu păng.’$b$,false),
('bunong-vn','MAT',22,25,null,$b$Pô ri phung hên geh pơh nuyh oh nâu; nâu bôk rah gŭ ur jêh ri păng khĭt, păng mâu geh kon ôh, jêh ri păng cha lơi ma oh păng ntrok gŭ ur păng.$b$,false),
('bunong-vn','MAT',22,26,null,$b$Tâm ban lĕ oh năp păng, jêh ri oh tal n'gul tât ta oh mpŭt.$b$,false),
('bunong-vn','MAT',22,27,null,$b$Kêng nglĕ dŭt ur păng khĭt đŏng.$b$,false),
('bunong-vn','MAT',22,28,null,$b$Pô ri ta nar dâk rêh, ma mbu păng mra jêng ur tâm phung pơh oh nâu nây? Yor lah lĕ rngôch khân păng gŭ jêh bu ur nây.”$b$,true),
('bunong-vn','MAT',22,29,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Khân may vĭ jêh, yor lah khân may mâu gĭt rbăng ôh nau nchih mâu lah nau brah Brah Ndu.$b$,true),
('bunong-vn','MAT',22,30,null,$b$Yor lah ta nar dâk rêh, bu klâu mâu hôm gŭ ur ôh, bu ur mâu hôm gŭ sai lĕ, ƀiă lah khân păng mra jêng nâm bu Tông mpăr ueh Brah Ndu tâm trôk.$b$,true),
('bunong-vn','MAT',22,31,null,$b$Khân may mâu mâp uănh hĕ tâm Nau Brah Ndu Ngơi, lah ma nau dâk rêh phung khĭt jêh pô aơ:$b$,false),
('bunong-vn','MAT',22,32,null,$b$Gâp jêng Brah Ndu Y-Abraham, Brah Ndu Y-Isăk, jêh ri Brah Ndu Y-Yakôp? Păng mâu jêng Brah Ndu phung khĭt ôh, ƀiă lah Brah Ndu phung rêh.”$b$,false),
('bunong-vn','MAT',22,33,null,$b$Phung nây tăng nau ngơi nây, khân păng hih rhâl ngăn.$b$,false),
('bunong-vn','MAT',22,34,null,$b$Phung Pharisi gĭt Brah Yêsu dơi jêh đah phung Sađusê, khân păng rgum ndrăng khân păng.$b$,true),
('bunong-vn','MAT',22,35,null,$b$Jêh ri du huê kôranh nchih sămƀŭt tâm phung khân păng ôp pô aơ, ŭch rlong uănh Brah Yêsu:$b$,false),
('bunong-vn','MAT',22,36,null,$b$“Hơi Kôranh nơm nti, tâm nau vay moh ntil toyh lơn?”$b$,false),
('bunong-vn','MAT',22,37,null,$b$Brah Yêsu lah ma păng: “ ‘May mra rŏng ma Kôranh Brah Ndu may ma lĕ nuih n'hâm, ma lĕ huêng, jêh ri ma lĕ nau mĭn may.’$b$,true),
('bunong-vn','MAT',22,38,null,$b$Nau vay nây toyh lơn, jêh ri lor lơn,$b$,false),
('bunong-vn','MAT',22,39,null,$b$jêh ri nau vay tal bar tâm ban lĕ: ‘May mra rŏng ma phung chiau meng may tâm ban may nơm lĕ.’$b$,false),
('bunong-vn','MAT',22,40,null,$b$Lĕ rngôch nau vay jêh ri nau mbơh lor luh tă bơh bar ntil nau vay nây.”$b$,false),
('bunong-vn','MAT',22,41,null,$b$Dôl phung Pharisi tâm rƀŭn ta nây, Brah Yêsu ôp ma khân păng pô aơ:$b$,true),
('bunong-vn','MAT',22,42,null,$b$“Mâm khân may mĭn ma Brah Krist? Mbu moh kon păng jêng.” Phung Pharisi plơ̆ lah ma păng: “Kon Y-Đavit.”$b$,false),
('bunong-vn','MAT',22,43,null,$b$Brah Yêsu lah ma khân păng: “Pô ri, mâm ƀư Y-Đavit ngơi ma Brah Huêng Ueh, kuăl păng Kôranh Brah, jêh ri lah:$b$,false),
('bunong-vn','MAT',22,44,null,$b$‘Kôranh Brah lah ma Kôranh Brah gâp, gŭ hom may mpeh pa ma gâp, tât gâp mra dơm phung rlăng đah may gŭ tâm dâng jâng may’?$b$,false),
('bunong-vn','MAT',22,45,null,$b$Tơ lah Y-Đavit kuăl Kôranh Brah ma Păng, mâm Păng dơi jêng kon Y-Đavit?”$b$,false),
('bunong-vn','MAT',22,46,null,$b$Mâu geh nơm dơi sĭt lah ma Păng ôh, jêh ri ntơm bơh nar nây mâu hôm geh nơm janh ôp Păng ôh.$b$,false),
('bunong-vn','MAT',23,1,null,$b$Rnôk nây Brah Yêsu ngơi ma phung âk, jêh ri ma phung oh mon păng pô aơ:$b$,true),
('bunong-vn','MAT',23,2,null,$b$“Phung kôranh nchih sămƀŭt jêh ri phung Pharisi gŭ tâm ntŭk Y-Môis.$b$,false),
('bunong-vn','MAT',23,3,null,$b$Ăn khân may ƀư jêh ri tông nau khân păng lah, ƀiă lah lơi tĭng khân păng ôh; yor lah khân păng knŏng lah, mâu ƀư ôh.$b$,false),
('bunong-vn','MAT',23,4,null,$b$Khân păng chăp ndơ jâk ngăn jêh ri dơm ta nglik bu; ƀiă lah khân păng mâu ŭch pah ma du nglau ti khân păng ôh.$b$,false),
('bunong-vn','MAT',23,5,null,$b$Lĕ kan khân păng ƀư, ŭch ma bunuyh saơ; khân păng nđar dŭng, prăp nau vay khân păng djôt, jêh ri ntrŭnh ao jâr khân păng.$b$,false),
('bunong-vn','MAT',23,6,null,$b$Khân păng rŏng geh ntŭk lor lơn tâm nau sông sa toyh, jêh ri ntŭk ta năp bu tâm ngih rƀŭn Yuđa,$b$,true),
('bunong-vn','MAT',23,7,null,$b$gay ma bu mbah ma khân păng tâm ngih tăch drăp, jêh ri gay ma bu kuăl Rabi ma khân păng.$b$,false),
('bunong-vn','MAT',23,8,null,$b$Ƀiă lah lơi ăn bu kuăl Rabi ma khân may ôh, yor lah geh knŏng du huê Kôranh nơm nti, jêh ri khân may lĕ rngôch jêng oh nâu.$b$,false),
('bunong-vn','MAT',23,9,null,$b$Lơi kuăl mbơ̆ du huê bunuyh ta neh ntu aơ ôh, yor lah khân may geh knŏng du huê Mbơ̆ nơm gŭ tâm trôk.$b$,false),
('bunong-vn','MAT',23,10,null,$b$Jêh ri lơi khân may kuăl kôranh ma du huê tâm phung khân may, yor lah khân may geh knŏng du huê Kôranh, Brah Krist.$b$,false),
('bunong-vn','MAT',23,11,null,$b$Ƀiă lah nơm toyh lơn tâm phung khân may mra jêng oh mon khân may.$b$,false),
('bunong-vn','MAT',23,12,null,$b$Mbu nơm yơk păng bu mra jot păng, jêh ri mbu nơm ntrŭnh păng nơm, bu mra yơk ma păng.$b$,false),
('bunong-vn','MAT',23,13,null,$b$“Rêh ni yơh ma khân may, hơi phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nuih n'hâm ndâp mpôn! Yor lah khân may ntĭl ƀon bri hađăch Brah Ndu ma bunuyh; khân may mâu lăp tâm ƀon nây ôh, jêh ri mbu nơm ŭch lăp khân may buay.$b$,true),
('bunong-vn','MAT',23,14,null,$b$Rêh ni yơh ma khân may, hơi phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nuih n'hâm ndâp! Yor lah khân may sa lĕ rngôch ngih phung bu ur khĭt sai, dôl khân may nklă mbơh sơm jŏ ngăn. Yor nây bu mra tâm rmal khân may ktang lơn.$b$,false),
('bunong-vn','MAT',23,15,null,$b$“Rêh ni yơh ma khân may, hơi phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nuih n'hâm ndâp mpôn! Yor lah khân may mblêng hăn lam dak mƀŭt jêh ri neh ntu ŭch ăn du huê êng lăp phung khân may, jêh ri tơ lah khân may geh jêh păng, khân may njêng ô băl du huê kon ndrung ŭnh bar tơ̆ rmeh lơn ma khân may.$b$,true),
('bunong-vn','MAT',23,16,null,$b$“Rêh ni yơh ma khân may, phung chieh măt leo trong. Khân may lah: ‘Tơ lah du huê sân săk đah ngih brah Yuđa mâu geh nau ôh; ƀiă lah tơ lah păng sân săk đah mah tâm ngih brah Yuđa nau sân săk nây jêng dơn.’$b$,true),
('bunong-vn','MAT',23,17,null,$b$Hơi phung rluk jêh ri chieh măt! Moh toyh lơn, mah, mâu lah ngih brah, mâu geh nau ôh; ƀiă lah tơ lah păng sân săk đah ndơ ƀư brah ta sưng nây,$b$,false),
('bunong-vn','MAT',23,18,null,$b$Jêh ri khân may lah: ‘Tơ lah du huê sân săk ma nơng ƀư brah mâu geh nau, ƀiă lah tơ lah păng sân săk ma ndơ ƀư brah ta klơ nơng nây, ăn păng ƀư ngăn nau nây.’$b$,false),
('bunong-vn','MAT',23,19,null,$b$Hơi phung chieh măt! Ndơ ƀư brah mâu lah nơng gay ƀư ma ndơ ƀư brah jêng kloh, moh ndơ khlay lơn?$b$,false),
('bunong-vn','MAT',23,20,null,$b$Pô ri, mbu nơm sân săk đah nơng ƀư brah, nâm bu păng sân săk đah nơng nđâp ma ndơ ƀư brah;$b$,false),
('bunong-vn','MAT',23,21,null,$b$jêh ri mbu nơm sân săk đah ngih brah Yuđa, nâm bu păng sân săk đah ngih brah Yuđa nđâp ma Nơm gŭ tâm ngih nây.$b$,false),
('bunong-vn','MAT',23,22,null,$b$Jêh ri mbu nơm sân săk đah trôk, nâm bu păng sân săk đah sưng hađăch Brah Ndu nđâp ma Nơm gŭ ta klơ sưng nây.$b$,false),
('bunong-vn','MAT',23,23,null,$b$“Rêh ni yơh ma khân may, hơi phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nuih n'hâm ndâp mpôn! Yor lah khân may ăn du kô̆ tâm jât rnoh klôih, cha, trau, jêh ri khân may mâu chrê ôh mâm nau khlay lơn tâm nau vay, nau sŏng, nau yô̆ jêh ri nau răp jăp; lĕ nau nây ăn khân may tông jêh ri lơi cha lơi ôh nau êng nây.$b$,true),
('bunong-vn','MAT',23,24,null,$b$Hơi phung chieh măt leo trong, dôl khân may nkhĕ sŏk rmôi lăp măt, ƀiă lah khân may rvăn seh samô.$b$,false),
('bunong-vn','MAT',23,25,null,$b$“Rêh ni yơh ma khân may, hơi phung kôranh nchih sămƀŭt jêh ri phung Pharisi, nuih n'hâm ndâp! Yor lah khân may tho thaih ngan pa dih, ƀiă lah tâm trôm, bêng ma nau ntŭng jêh ri nau hay.$b$,true),
('bunong-vn','MAT',23,26,null,$b$Hơi phung Pharisi chieh măt! Tho rao hom lor tâm trôm jêh ri ngan thau nây, pô ri mơ nđâp pa dih jêng kloh lĕ.$b$,false),
('bunong-vn','MAT',23,27,null,$b$“Rêh ni yơh ma khân may, hơi phung Pharisi jêh ri phung kôranh nchih sămƀŭt, nuih n'hâm ndâp mpôn! Yor lah khân may jêng nâm bu môch mhĭng klo nglang, pa dih uănh ueh ngăn ƀiă lah tâm trôm bêng ma nting bunuyh khĭt jêh ri đah ăp ntil ndơ ƀơ̆ .$b$,true),
('bunong-vn','MAT',23,28,null,$b$Khân may tâm ban lĕ, pa dih ƀư sŏng ta năp bunuyh, ƀiă lah tâm trôm khân may bêng ma nuih n'hâm ndâp jêh ri tih mhĭk.$b$,false),
('bunong-vn','MAT',23,29,null,$b$“Rêh ni yơh ma khân may, hơi phung Pharisi jêh ri phung kôranh nchih sămƀŭt, nuih n'hâm ndâp mpôn! Yor lah khân may nkra môch phung kôranh nơm mbơh lor, jêh ri khân may prăp môch phung sŏng.$b$,true),
('bunong-vn','MAT',23,30,null,$b$Jêh ri khân may lah: ‘Tơ lah hên gŭ rêh tâm rnôk mbơ̆ hên, hên mâu tĭng ndrel ma khân păng ŭch nkhŭt mham phung kôranh nơm mbơh lor ôh.’$b$,true),
('bunong-vn','MAT',23,31,null,$b$Pô ri, khân may mbơh ma khân may nơm, jêng kon phung nkhĭt phung kôranh nơm mbơh lor nanê̆ ngăn.$b$,false),
('bunong-vn','MAT',23,32,null,$b$Ăn khân may mbêng rnâng phung mbơ̆ khân may lĕ.$b$,true),
('bunong-vn','MAT',23,33,null,$b$Hơi phung bêh, ndŭl mpôl bêh ŭnh, mâm ƀư khân may dơi du tă bơh nau tâm rmal tâm ndrung ŭnh?$b$,false),
('bunong-vn','MAT',23,34,null,$b$“Yor nây aơ, gâp njuăl phung kôranh nơm mbơh lor, phung blau âk, jêh ri phung kôranh nchih sămƀŭt ma khân may. Tâm phung nây, ƀa ƀă khân may mra nkhĭt jêh ri pâng ta si tâm rkăng, ƀa ƀă khân may dong ma mâng tâm ngih rƀŭn Yuđa, jêh ri khân may mra tĭng ƀư mhĭk, ma phung khân păng ntơm bơh ƀon aơ tât ta ƀon êng.$b$,true),
('bunong-vn','MAT',23,35,null,$b$Pô ri yơh, lĕ rngôch mham mâu mâp tih, nkhŭt jêh ta neh ntu mra tŭp ta khân may, ntơm bơh mham Y-Abel, nơm sŏng, tât ta mham Y-Sakari, jêh ri Y-Baraki, nơm khân may nkhĭt tâm vah vang ntŭk kloh jêh ri nơng ƀư brah.$b$,true),
('bunong-vn','MAT',23,36,null,$b$Nanê̆, gâp lah ma khân may, lĕ rngôch nau nây mra tât ma phung ndŭl mpôl aơ.$b$,false),
('bunong-vn','MAT',23,37,null,$b$“Hơi Yêrusalem, Yêrusalem, may nkhĭt phung kôranh nơm mbơh lor, jêh ri klŭp lŭ ta phung prơh njuăl ma may! Âk tơ̆ jêh gâp ŭch tâm rgum phung kon may, nâm bu du mlâm iăr me tâm rgum phung kon păng, tâm dâng nar păng, ƀiă lah khân may mâu ŭch ôh!$b$,true),
('bunong-vn','MAT',23,38,null,$b$Aơ, ngih khân may mra cha lơi hŏng.$b$,false),
('bunong-vn','MAT',23,39,null,$b$Gâp mbơh ma khân may, khân may mâu hôm saơ gâp ôh, tât khân may mra lah, ‘mât ton ma Nơm văch tâm amoh Kôranh Brah.’ ”$b$,false),
('bunong-vn','MAT',24,1,null,$b$Tơ lah Brah Yêsu luh tă bơh ngih brah Yuđa, dôl hăn oh mon Păng hăn êp ŭch ăn Păng uănh ma ngih brah Yuđa.$b$,true),
('bunong-vn','MAT',24,2,null,$b$Ƀiă lah Păng lah ma khân păng: “Khân may saơ lĕ rngôch ndơ nây? Nanê̆ gâp lah ma khân may, mâu geh ôh du mlâm lŭ ta klơ lŭ êng mâu mra tŭp.”$b$,false),
('bunong-vn','MAT',24,3,null,$b$Dôl Păng gŭ ta klơ Ôlivơ, phung oh mon văch ôp Păng pô aơ: “Lah ma hên, ndah jŏ nau nây mra tât? Jêh ri moh ndơ mra mbên ma nar may mra plơ̆ văch, jêh ri ma nar nglĕ dŭt rnôk?”$b$,true),
('bunong-vn','MAT',24,4,null,$b$Brah Yêsu plơ̆ lah: “Njrăng hom klach lah bu ndơm khân may.$b$,false),
('bunong-vn','MAT',24,5,null,$b$Yor lah âk bunuyh mra văch nchơt nklă tâm amoh gâp jêh ri lah: ‘Gâp jêng Brah Krist.’ Jêh ri khân păng mra ndơm âk bunuyh.$b$,false),
('bunong-vn','MAT',24,6,null,$b$Khân may mra tăng nau nkoch bri ma nau tâm lơh jêh ri lư nau tâm lơh; njrăng hom, lơi ta rŭng nuih n'hâm khân may ôh, yor lah lĕ nau nây mra tât, ƀiă lah ê tât nglĕ dŭt ôh.$b$,false),
('bunong-vn','MAT',24,7,null,$b$Yor lah du phung ndŭl mpôl, mra tâm lơh đah du phung ndŭl mpôl êng, jêh ri du ƀon hađăch, mra tâm lơh đah du ƀon hađăch êng, jêh ri mra geh nau sa sât ji ngot, jêh ri nau n'găr neh ntu tâm ăp ntŭk.$b$,false),
('bunong-vn','MAT',24,8,null,$b$Ƀiă lah lĕ rngôch nau nây mra jêng nau ntơm nau rêh ni.$b$,false),
('bunong-vn','MAT',24,9,null,$b$Rnôk nây bu mra jao khân may ma nau rêh ni, jêh ri nkhĭt lơi; jêh ri lĕ rngôch ndŭl mpôl, mra tâm rmot ma khân may yor amoh gâp.$b$,false),
('bunong-vn','MAT',24,10,null,$b$Rnôk nây lĕ, âk bunuyh mra tŭp; khân păng mra rlăng ndrăng nơm, jêh ri tâm djrel ndrăng nơm,$b$,false),
('bunong-vn','MAT',24,11,null,$b$mra geh âk kôranh nơm mbơh lor tih, văch ndơm âk bunuyh.$b$,false),
('bunong-vn','MAT',24,12,null,$b$Jêh ri yor lah nau tih mra hao âk lơn, nau rŏng tâm âk bunuyh mra nđik.$b$,false),
('bunong-vn','MAT',24,13,null,$b$Ƀiă lah mbu nơm srôih ƀa ƀơ tât lôch mra klaih.$b$,false),
('bunong-vn','MAT',24,14,null,$b$Jêh ri nau mhe mhan ueh aơ ma ƀon bri hađăch Brah Ndu bu mra nti lam neh ntu, gay mbơh ma lĕ rngôch ndŭl mpôl bunuyh; rnôk nây yơh nar nglĕ dŭt tât.$b$,false),
('bunong-vn','MAT',24,15,null,$b$“Tơ lah khân may saơ nau bu tâm rmot ngăn ƀư nau mhĭk, nau ƀư rai tâm ntŭk kloh, nau Y-Đaniel hŏ mbơh jêh. Ăn mbu nơm uănh sămƀŭt aơ mĭn ăn gĭt.$b$,true),
('bunong-vn','MAT',24,16,null,$b$Rnôk nây ăn phung gŭ tâm n'gor Yuđa du mpeh ta yôk;$b$,false),
('bunong-vn','MAT',24,17,null,$b$ăn nơm gŭ ta klơ chor ngih, lơi trŭnh sŏk ndơ tâm ngih păng ôh;$b$,false),
('bunong-vn','MAT',24,18,null,$b$jêh ri ăn nơm gŭ tâm mir, lơi sĭt sŏk ao mbâl păng ôh.$b$,false),
('bunong-vn','MAT',24,19,null,$b$Rnôk nây mra geh nau rêh ni yơh ma phung bu ur ntreo jêh ri ma phung ăn kon pu!$b$,false),
('bunong-vn','MAT',24,20,null,$b$Mbơh sơm hom gay ma nar khân may du mâu tât ôh tâm yan sial puh, mâu lah nar Saƀat.$b$,false),
('bunong-vn','MAT',24,21,null,$b$Yor lah rnôk nây mra geh nau rêh ni ji klâng toyh ngăn, ntơm bơh nar geh neh ntu, tât ta nar aơ ê mâp geh ôh pô ri, jêh ri ntơm bơh aơ let pa năp mâu mra geh lĕ.$b$,false),
('bunong-vn','MAT',24,22,null,$b$Jêh ri tơ lah Brah Ndu mâu n'hŭch nar mhĭk nây, mâu geh du huê mra klaih ôh; ƀiă lah Brah Ndu mra n'hŭch lơi nar nây yor phung chroh.$b$,false),
('bunong-vn','MAT',24,23,null,$b$“Rnôk nây tơ lah geh du huê lah ma khân may: ‘Ta aơ Brah Krist!’ Mâu lah: ‘Ta ri Păng!’ Lơi ta chroh ôh.$b$,true),
('bunong-vn','MAT',24,24,null,$b$Yor lah mra geh phung Krist jêh ri phung kôranh nơm mbơh lor tih, jêh ri khân păng mra ndơm nđâp ma phung chroh tơ lah dơi.$b$,false),
('bunong-vn','MAT',24,25,null,$b$Pô ri gâp mbơh lor ma khân may,$b$,false),
('bunong-vn','MAT',24,26,null,$b$pô ri, tơ lah bu lah ma khân may: ‘Ri, Păng gŭ tâm bri rdah,’ Lơi hăn ôh. Tơ lah khân păng lah: ‘Aơ, Păng gŭ tâm ngih.’ Lơi chroh ôh.$b$,false),
('bunong-vn','MAT',24,27,null,$b$Yor lah nâm bu lơp nglaih luh tă bơh lơ tât pa dâng, nâm bu pô ri lĕ, nau Kon Bunuyh mra văch.$b$,false),
('bunong-vn','MAT',24,28,null,$b$“Ta ntŭk geh nglay săk khĭt, phung klang grât mra tâm rgum ta nây.$b$,true),
('bunong-vn','MAT',24,29,null,$b$“Ƀât lât jêh lôch nau rêh ni tâm nar nây, nar mra jêng ngo, khay mâu hôm nchrat ang ôh, phung mănh mra tŭp tă bơh trôk jêh ri nau brah tâm trôk mra mpât n'gơ.$b$,true),
('bunong-vn','MAT',24,30,null,$b$Rnôk nây tâm trôk mra tâm mpơl nau mbên ma Kon Bunuyh, lĕ rngôch phung ndŭl mpôl tâm neh ntu mra nter nhĭm nhhiăng, jêh ri khân păng mra saơ kon bunuyh văch tâm ndâr tŭk ta klơ trôk ma nau brah toyh ngăn jêh ri âk nau chrêk rmah.$b$,true),
('bunong-vn','MAT',24,31,null,$b$Păng mra njuăl văch phung Tông mpăr ueh Păng uh nŭng nteh ktang tâm rgum phung Păng hŏ săch jêh tâm lam ntŭk tă bơh puăn njônh bri neh ntu, ntơm bơh n'gar trôk aơ tât ta n'gar trôk ri.”$b$,false),
('bunong-vn','MAT',24,32,null,$b$“Nti hom nau hôr ma tơm play rvi. Tơ lah n'gĭng păng nse ntơm luh nkŭr, khân may gĭt yan vai êp jêh.$b$,true),
('bunong-vn','MAT',24,33,null,$b$Tâm ban pô nây lĕ, tơ lah khân may mra saơ lĕ nau nây, ăn khân may gĭt ma Kon Bunuyh dăch tât. Păng ntơm gŭ dâk ta năp mpông bloh.$b$,false),
('bunong-vn','MAT',24,34,null,$b$Nanê̆ gâp lah ma khân may, phung rnôk aơ mâu mra rlau lôch ôh, lor ma lĕ nau nây tât.$b$,true),
('bunong-vn','MAT',24,35,null,$b$Trôk jêh ri neh ntu mra rlau lôch, ƀiă lah nau gâp ngơi mâu dơi rlau lôch ôh.$b$,false),
('bunong-vn','MAT',24,36,null,$b$“Ma nar, jêh ri mông nây, mâu geh du huê bunuyh gĭt ôh. Tông mpăr ueh tâm trôk, mâu lah Kon mâu dơi gĭt lĕ, ƀiă lah knŏng êng du huê Mbơ̆ gâp.$b$,true),
('bunong-vn','MAT',24,37,null,$b$Moh nau tât jêh tâm rnôk Y-Nôê mra tât tâm ban lĕ tâm nar Kon Bunuyh mra văch.$b$,false),
('bunong-vn','MAT',24,38,null,$b$Tâm nar, ê lor dak lêng bu nhêt sa, tâm gŭ ur sai, jêh ri ăn phung kon khân păng gŭ ur sai, tât ta nar Y-Nôê lăp tâm kŭmpăn.$b$,false),
('bunong-vn','MAT',24,39,null,$b$Jêh ri khân păng mâu gĭt ôh tât nar dak lêng, tât đô̆ rdu khân păng lĕ rngôch, tâm ban pô nây lĕ, nar Kon Bunuyh văch.$b$,false),
('bunong-vn','MAT',24,40,null,$b$Dôl nây geh bar hê bunuyh gŭ tâm du lôk mir, du huê bu sŏk, du huê bu lơi.$b$,false),
('bunong-vn','MAT',24,41,null,$b$Geh bar hê bu ur gŭ peh ndrel; du huê bu sŏk, du huê bu lơi.$b$,false),
('bunong-vn','MAT',24,42,null,$b$Pô ri njrăng hom, yor lah khân may mâu gĭt ôh moh mông Kôranh Brah khân may mra văch.$b$,false),
('bunong-vn','MAT',24,43,null,$b$“Ăn khân may gĭt nanê̆, tơ lah du huê kôranh ngih gĭt moh mông bunuyh ntŭng mra văch, păng mra njrăng, mâu ăn bunuyh ntŭng lôk mpir lăp tâm ngih păng ôh.$b$,true),
('bunong-vn','MAT',24,44,null,$b$Ăn khân may gŭ njrăng tâm ban lĕ. Yor lah Kon Bunuyh mra văch dôl mông khân may rngơt rngơi$b$,false),
('bunong-vn','MAT',24,45,null,$b$Mbu nơm oh mon sŏng jêh ri blau mĭn, tơ lah kôranh păng jao ăn chiă uănh lĕ rngôch phung oh mon păng, gay păng ăn ndơ sông sa ma khân păng di mông?$b$,false),
('bunong-vn','MAT',24,46,null,$b$Ueh maak yơh ma oh mon nây, tơ lah Kôranh păng tât jêh ri saơ păng ƀư jêh pô ri.$b$,false),
('bunong-vn','MAT',24,47,null,$b$Nanê̆ gâp lah ma khân may, păng mra ăn oh mon nây, chiă uănh lĕ rngôch ndơ păng geh.$b$,false),
('bunong-vn','MAT',24,48,null,$b$Ƀiă lah tơ lah oh mon nây mhĭk mĭn tâm nuih n'hâm păng pô aơ: ‘Kôranh gâp jŏ văch,’$b$,false),
('bunong-vn','MAT',24,49,null,$b$jêh ri păng dong phung băl pah kan ndrel păng, jêh ri păng nhêt sa ndrel đah phung nhŭl ndrănh.$b$,false),
('bunong-vn','MAT',24,50,null,$b$Kôranh oh mon nây mra tât tâm nar păng mâu mĭn, jêh ri dôl mông păng mâu gĭt.$b$,true),
('bunong-vn','MAT',24,51,null,$b$Jêh ri kôranh păng mra dong păng tât rai jêh ri mra kơp păng ndrel ma phung nuih n'hâm ndâp. Ta nây mra geh nau nhĭm nhhiăng jêh ri nau rket sêk.”$b$,true),
('bunong-vn','MAT',25,1,null,$b$“Rnôk nây ƀon bri hađăch Brah Ndu mra jêng nâm bu jât nuyh bu ur druh, djôt ŭnh kđen hăn tâm mâp đah du huê gŭ ur.$b$,true),
('bunong-vn','MAT',25,2,null,$b$Prăm nuyh tâm phung khân păng jêng rluk, jêh ri prăm nuyh blau mĭn.$b$,false),
('bunong-vn','MAT',25,3,null,$b$Phung rluk sŏk ŭnh kđen khân păng, ƀiă lah mâu djôt dak ŭnh ôh$b$,true),
('bunong-vn','MAT',25,4,null,$b$ƀiă lah phung blau mĭn djôt ŭnh kđen geh dak ŭnh tâm rachŏk.$b$,false),
('bunong-vn','MAT',25,5,null,$b$Yor lah nơm gŭ ur văch jŏ ngăn, lĕ rngôch khân păng lâng săk jêh ri bêch hêng.$b$,false),
('bunong-vn','MAT',25,6,null,$b$Tâm n'gul măng geh bâr nter lah: ‘Aơ, nơm gŭ ur văch! Luh hăn ran chuă păng!’$b$,false),
('bunong-vn','MAT',25,7,null,$b$Pô ri lĕ rngôch phung bu ur druh dâk bêch jêh ri nkra ŭnh kđen khân păng.$b$,false),
('bunong-vn','MAT',25,8,null,$b$Phung rluk lah ma phung blau mĭn, tâm pă ma hên ƀă dak ŭnh, yor lah ŭnh kđen hên dăch nhhât jêh?$b$,true),
('bunong-vn','MAT',25,9,null,$b$Ƀiă lah phung blau mĭn lah: ‘Mâu, klach lah mâu tŏng ôh ma hên nơm, nđâp ma khân ay. Ueh lơn hăn hom ta phung tăch dak ŭnh, jêh ri rvăt ma khân ay nơm.’$b$,false),
('bunong-vn','MAT',25,10,null,$b$Ƀiă lah dôl khân păng hăn rvăt dak ŭnh, nơm gŭ ur tât. Phung bu ur gŭ njrăng lăp tâm ngih sông sa tâm nkol; jêh ri bu nchăng lơi mpông.$b$,false),
('bunong-vn','MAT',25,11,null,$b$Jŏ djê̆ ta nây phung bu ur rluk tât đŏng jêh ri lah: ‘Hơi kôranh! Kôranh ơi, pơk an mpông ma hên ƀă.’$b$,false),
('bunong-vn','MAT',25,12,null,$b$Ƀiă lah kôranh plơ̆ lah: ‘Nanê̆ gâp lah ma khân ay, gâp mâu gĭt năl khân ay ôh.’$b$,false),
('bunong-vn','MAT',25,13,null,$b$Pô ri njrăng hom. Yor khân ay mâu gĭt nar, mâu lĕ gĭt mông.”$b$,false),
('bunong-vn','MAT',25,14,null,$b$“Ƀon bri hađăch Brah Ndu mra jêng du huê bunuyh hăn nsong bri bu. Păng kuăl phung oh mon jêh ri jao drăp ma khân păng.$b$,true),
('bunong-vn','MAT',25,15,null,$b$Kôranh ăn ma du huê prăm rnglay prăk, ma nơm êng bar, jêh ri ma nơm pa kơi lơn du rnglay prăk. Păng ăn ma khân păng tĭng nâm ăp nơm blau dŏng prăk, jêh ri păng hăn.$b$,false),
('bunong-vn','MAT',25,16,null,$b$Gơnh ro, nơm sŏk dơn jêh prăm rnglay prăk, hăn rgâl drăp gay hao. Jêh ri păng geh n'hao prăm rnglay prăk êng.$b$,false),
('bunong-vn','MAT',25,17,null,$b$Tâm ban lĕ nơm sŏk dơn jêh bar rnglay prăk geh n'hao bar.$b$,true),
('bunong-vn','MAT',25,18,null,$b$Ƀiă lah nơm sŏk dơn jêh du rnglay prăk, hăn kuyh ntu tâp lơi prăk kôranh păng.$b$,false),
('bunong-vn','MAT',25,19,null,$b$“Jŏ nar ta nây kôranh phung oh mon nây plơ̆ tay, jêh ri păng ăn khân păng tĭng rnoh.$b$,true),
('bunong-vn','MAT',25,20,null,$b$Nơm sŏk dơn prăm rnglay prăk, văch djôt prăm rnglay prăk êng, jêh ri păng lah: ‘Hơi kôranh, may jao jêh ma gâp prăm rnglay prăk. Aơ, prăm rnglay prăk gâp geh n'hao prăm rnglay prăk êng.’$b$,false),
('bunong-vn','MAT',25,21,null,$b$Kôranh lah ma păng: ‘Ueh ngăn, hơi oh mon ueh jêh ri răp jăp; may jêng răp jăp tâm kan jê̆, gâp mra ăn may chiă uănh âk; văch hom dơn nau răm maak kôranh may.’$b$,false),
('bunong-vn','MAT',25,22,null,$b$Nơm sŏk dơn bar rnglay prăk văch, jêh ri lah tâm ban: ‘Hơi kôranh, may jao jêh ma gâp bar rnglay prăk: Aơ, bar rnglay prăk gâp geh n'hao bar rnglay prăk êng.’$b$,false),
('bunong-vn','MAT',25,23,null,$b$Kôranh păng lah ma păng: ‘Ueh ngăn, hơi oh mon ueh jêh ri răp jăp; may jêng răp jăp tâm kan jê̆, gâp mra ăn may chiă uănh âk; văch hom dơn nau răm maak kôranh may.’$b$,false),
('bunong-vn','MAT',25,24,null,$b$Nơm sŏk dơn du rnglay prăk văch đŏng jêh ri lah: ‘Hơi kôranh, gâp gĭt ma may jêng du huê bunuyh dăng. May rek tâm ntŭk may mâu mâp srih,$b$,false),
('bunong-vn','MAT',25,25,null,$b$pô ri gâp klach, jêh ri gâp hăn pôn lơi prăk may tâm neh. Aơ, sŏk hom prăk may nơm.’$b$,false),
('bunong-vn','MAT',25,26,null,$b$Ƀiă lah kôranh plơ̆ lah ma păng: ‘Hơi oh mon ƀai jêh ri ƀlao! May gĭt jêh gâp rek tâm ntŭk gâp mâu mâp tăm jêh ri gâp dônh tâm ntŭk gâp mâu mâp srih.$b$,false),
('bunong-vn','MAT',25,27,null,$b$Pô ri ueh lơn may jao prăk gâp ma bunuyh tăch rgâl prăk, jêh ri ta nar gâp sĭt gâp mra sŏk đŏng prăk gâp nđâp ma kao păng.$b$,false),
('bunong-vn','MAT',25,28,null,$b$Pô ri khân may sŏk hom prăk păng, jêh ri ăn ma nơm geh jêh jât rnglay prăk.$b$,false),
('bunong-vn','MAT',25,29,null,$b$Yor lah bu mra ntop ăn ma mbu nơm geh jêh, jêh ri păng mra geh âk rmeh; ƀiă lah ma nơm mâu geh, bu mra sŏk lơi nđâp ndơ păng hŏ geh jêh.$b$,true),
('bunong-vn','MAT',25,30,null,$b$Bi ma oh mon mâu khlay nây, klŭp lơi păng tâm ntŭk ngo pa dih, ta nây geh nau nhĭm nhhiăng jêh ri nau rket sêk’ ”$b$,false),
('bunong-vn','MAT',25,31,null,$b$“Tơ lah Kon Bunuyh mra văch tâm nau chrêk rmah Păng, ndrel ma lĕ rngôch phung Tông mpăr ueh Păng, rnôk nây Păng mra gŭ ta klơ sưng hađăch chrêk rmah Păng.$b$,true),
('bunong-vn','MAT',25,32,null,$b$Lĕ rngôch mpôl băl bunuyh mra tâm rƀŭn ta năp Păng, jêh ri Păng mra tâm nkhah jêng bar mpôl, nâm bu rmăk biăp tâm nkhah phung biăp đah phung be.$b$,false),
('bunong-vn','MAT',25,33,null,$b$Jêh ri păng mra dơm phung biăp mpeh pa ma păng, jêh ri phung be mpeh pa chiau păng.$b$,false),
('bunong-vn','MAT',25,34,null,$b$Rnôk nây hađăch mra lah ma phung mpeh pa ma păng: ‘Văch hom, phung Mbơ̆ gâp rŏng, ăn khân may sŏk dơn ƀon bri hađăch nkra ăn jêh ma khân may ntơm bơh geh neh ntu.$b$,false),
('bunong-vn','MAT',25,35,null,$b$Yor lah dôl gâp ji ngot khân may ăn jêh ndơ sông sa ma gâp. Gâp ji hir, khân may ăn gâp nhêt dak; gâp jêng bunuyh bu năch, khân may rom gâp.$b$,false),
('bunong-vn','MAT',25,36,null,$b$Gâp săk lưn, khân may ăn ma gâp bok ao. Gâp ji, khân may hăn chop gâp; bu krŭng gâp, khân may văch jô̆ khâl gâp.’$b$,false),
('bunong-vn','MAT',25,37,null,$b$Dôl nây phung sŏng mra plơ̆ lah ma păng: ‘Ơ Kôranh Brah ơi, ndah jŏ hên mâp saơ may ji ngot, jêh ri ăn may sông sa, mâu lah may ji hir, ăn may nhêt dak?$b$,false),
('bunong-vn','MAT',25,38,null,$b$Jêh ri ndah jŏ hên mâp saơ may jêng bu năch, rom may, mâu lah may săk lưn, hên ăn bok ao ma may?$b$,true),
('bunong-vn','MAT',25,39,null,$b$Mâu lah ndah jŏ hên mâp saơ may ji, mâu lah bu krŭng hăn jô̆ khâl may?’$b$,false),
('bunong-vn','MAT',25,40,null,$b$Jêh ri hađăch mra plơ̆ lah ma khân păng: ‘Nanê̆, gâp lah ma khân may, ăp tơ̆ khân may ƀư jêh nau aơ, ma du huê tâm phung oh nâu jê̆ jê̆ aơ, jêng nâm bu khân may ƀư ma gâp tâm ban lĕ.’$b$,false),
('bunong-vn','MAT',25,41,null,$b$“Dôl nây păng mra lah mpeh pa chiau păng: ‘Hơi phung bu rak rtăp jêh, du hom tă bơh gâp, hăn tâm ŭnh hâng ƀa ƀơ n'ho ro, nkra jêh ma brah mhĭk jêh ri ma phung oh mon păng:$b$,false),
('bunong-vn','MAT',25,42,null,$b$Yor lah gâp ji ngot khân may mâu mâp ăn gâp sông sa ôh. Gâp ji hir khân may mâu mâp ăn ma gâp dak nhêt.$b$,false),
('bunong-vn','MAT',25,43,null,$b$Gâp jêng bu năch khân may mâu mâp rom gâp; gâp săk lưn khân may mâu mâp ăn ma gâp bok ao. Gâp ji jêh ri bu krŭng, khân may mâu mâp hăn chop khâl gâp.’$b$,true),
('bunong-vn','MAT',25,44,null,$b$Jêh ri phung aơ plơ̆ lah ma păng: ‘Ơ Kôranh Brah, ndah jŏ hên mâp saơ may ji ngot, ji hir, jêng bu năch, săk lưn, ji, mâu lah bu krŭng jêh ri hên mâu kơl may?’$b$,false),
('bunong-vn','MAT',25,45,null,$b$Păng plơ̆ lah ma phung nây: ‘Nanê̆ gâp lah ma khân may, ăp tơ̆ khân may mâu mâp ƀư nau aơ ma du huê tâm phung jê̆ jê̆ aơ, jêng nâm bu khân may mâu mâp ƀư ma gâp tâm ban lĕ?’$b$,false),
('bunong-vn','MAT',25,46,null,$b$Jêh ri phung aơ mra hăn tâm nau tâm rmal n'ho ro, ƀiă lah phung sŏng mra hăn tâm nau rêh n'ho ro tâm ban lĕ.”$b$,false),
('bunong-vn','MAT',26,1,null,$b$Jêh Brah Yêsu ngơi nau nây, Păng lah ma phung oh mon Păng:$b$,true),
('bunong-vn','MAT',26,2,null,$b$“Khân may gĭt hôm bar nar mra tât Nau Găn, jêh ri bu mra jao Kon Bunuyh ăn bu pâng Păng ta si tâm rkăng.”$b$,false),
('bunong-vn','MAT',26,3,null,$b$Rnôk nây, phung n'gâng kôranh ƀư brah jêh ri phung kôranh bu bŭnh bu ranh tâm rƀŭn tâm nkual ngih kôranh ƀư brah toyh, Y-Kaip,$b$,true),
('bunong-vn','MAT',26,4,null,$b$jêh ri khân păng tâm chră joi nau nhŭp Brah Yêsu ma nau ndơm jêh ri nkhĭt lơi ô băl.$b$,false),
('bunong-vn','MAT',26,5,null,$b$Ƀiă lah khân păng lah: “Mâu ueh ƀư nau nây dôl nau nhêt sa, klach lah ƀư rŭng ƀon lan.”$b$,false),
('bunong-vn','MAT',26,6,null,$b$Dôl Brah Yêsu gŭ ta ƀon Bêthani tâm ngih Y-Simôn, nơm geh phŭng.$b$,true),
('bunong-vn','MAT',26,7,null,$b$Dôl Păng sông sa geh du huê bu ur djôt du rchŏk dak ƀâu kah khlay ngăn hăn dăch jêh ri tŏ ta klơ bôk Păng.$b$,false),
('bunong-vn','MAT',26,8,null,$b$Tơ lah phung oh mon saơ pô ri: “Mâm ƀư roh dơm dam pô nây?$b$,false),
('bunong-vn','MAT',26,9,null,$b$Dak ƀâu kah aơ dơi tăch khlay ngăn jêh ri tâm pă prăk aơ ma phung o ach.”$b$,false),
('bunong-vn','MAT',26,10,null,$b$Ƀiă lah Brah Yêsu gĭt nau nây lah ma khân păng: “Mâm ƀư khân may ƀư rngot bu ur aơ? Păng ƀư nau ueh ma gâp jêh.$b$,false),
('bunong-vn','MAT',26,11,null,$b$Yor lah khân may geh, phung rêh ni ndrel khân may ƀa ƀơ, ƀiă lah gâp mâu gŭ ƀa ƀơ ndrel khân may ôh.$b$,false),
('bunong-vn','MAT',26,12,null,$b$Nau păng tŏ dak ƀâu kah aơ, ta săk jăn gâp, nâm bu păng nkra nau tâp gâp!$b$,false),
('bunong-vn','MAT',26,13,null,$b$N'hêl nanê̆ gâp lah ma khân may, lam neh ntu ta ntŭk bu mra nti nau mhe mhan ueh aơ, bu mra nkoch bri kah gĭt đŏng ma nau bu ur aơ hŏ ƀư jêh.”$b$,true),
('bunong-vn','MAT',26,14,null,$b$Rnôk nây du huê tâm phung jât ma bar nuyh, amoh păng Y-Yuđas Iskariôt, hăn ta phung n'gâng kôranh ƀư brah jêh ri lah pô aơ:$b$,true),
('bunong-vn','MAT',26,15,null,$b$“Moh ndơ khân may ŭch ăn ma gâp, gay gâp jao păng ma khân may?” Phung nây ăn ma păng pe jât rêl prăk.$b$,false),
('bunong-vn','MAT',26,16,null,$b$Ntơm bơh mông nây păng joi nau nơih ŭch jao Brah Yêsu ma khân păng.$b$,false),
('bunong-vn','MAT',26,17,null,$b$Nar nguay tâm nau sa kapŭng mâu geh ndrui, phung oh mon hăn êp Brah Yêsu jêh ri lah: “Mbah ntŭk may ŭch hên nkra sa Nau Găn?”$b$,true),
('bunong-vn','MAT',26,18,null,$b$Păng lah: “Kôranh nơm nti lah, mông gâp dăch tât jêh, tâm ngih may yơh gâp mra sa Nau Găn ndrel ma phung oh mon gâp.”$b$,false),
('bunong-vn','MAT',26,19,null,$b$Phung oh mon ƀư tĭng nâm nau Brah Yêsu ntăm ma khân păng, jêh ri khân păng nkra Nau Găn.$b$,false),
('bunong-vn','MAT',26,20,null,$b$Tât kêng măng păng sông sa ndrel ma phung jât ma bar oh mon.$b$,true),
('bunong-vn','MAT',26,21,null,$b$Dôl gŭ sông sa păng ngơi pô aơ: “Nanê̆ gâp lah ma khân may, du huê tâm phung khân may mra rlăng ma gâp.”$b$,false),
('bunong-vn','MAT',26,22,null,$b$Khân păng rngot ngăn jêh ri ăp nơm khân păng ôp Brah Yêsu: “Di gâp lĕ, kôranh?”$b$,false),
('bunong-vn','MAT',26,23,null,$b$Brah Yêsu plơ̆ lah: “Mbu nơm dơm jêh ti tâm ngan grưng ndrel ma gâp, păng nây yơh mra rlăng ma gâp.$b$,false),
('bunong-vn','MAT',26,24,null,$b$Kon Bunuyh mra hăn tĭng nâm nau bu nchih jêh ma păng, ƀiă lah rêh ni yơh ma nơm rlăng ma Kon Bunuyh! Ueh lơn ma păng nây bu mâu deh ôh.”$b$,false),
('bunong-vn','MAT',26,25,null,$b$Y-Yuđas, nơm rlăng ma Păng, lah: “Di lĕ gâp, Kôranh Brah?” Brah Yêsu plơ̆ lah: “May hŏ lah jêh.”$b$,false),
('bunong-vn','MAT',26,26,null,$b$Dôl sông sa, Brah Yêsu sŏk kapŭng, jêh Păng lah ueh, Păng nkêch kapŭng nây, tâm pă ma phung oh mon Păng, jêh ri lah: “Sŏk sa hom; aơ jêng nglay săk gâp.”$b$,true),
('bunong-vn','MAT',26,27,null,$b$Păng sŏk đŏng kchok, jêh lah ueh, Păng ăn kchok ma khân păng jêh ri lah: “Nhêt hom lĕ rngôch.$b$,false),
('bunong-vn','MAT',26,28,null,$b$Yor lah aơ jêng mham gâp, mham nau tâm rnglăp, nkhŭt ăn ma âk bunuyh ŭch yô̆ an nau tih khân păng.$b$,true),
('bunong-vn','MAT',26,29,null,$b$Gâp lah ma khân may, ntơm aơ leo pa năp, gâp mâu mra hôm nhêt ôh dak play kriăk ƀâu aơ, tât nar gâp mra nhêt ndrel khân may tâm bri hađăch Mbơ̆ gâp.”$b$,false),
('bunong-vn','MAT',26,30,null,$b$Jêh mprơ nau mprơ ơm, khân păng luh hăn ta yôk Ôlivơ.$b$,true),
('bunong-vn','MAT',26,31,null,$b$Jêh ri Brah Yêsu lah ma khân păng: “Măng ta oi lĕ rngôch khân may mra tih yor gâp, yor lah geh nau nchih jêh pô aơ: ‘Gâp mra dong rmăk biăp jêh ri phung biăp mra nkhah du chah rai êng êng.’$b$,false),
('bunong-vn','MAT',26,32,null,$b$Ƀiă lah jêh gâp dâk rêh tay, gâp mra hăn lor ma khân may tâm n'gor Galilê.”$b$,false),
('bunong-vn','MAT',26,33,null,$b$Y-Pêtrôs ngơi pô aơ: “Tơ lah lĕ rngôch mra tih yor may gâp mâu mra tih ôh.”$b$,true),
('bunong-vn','MAT',26,34,null,$b$Brah Yêsu plơ̆ lah ma păng: “Nanê̆ gâp mbơh ma may, măng ta oi, ê lor ta iăr ndrau, may mra dun gâp pe tơ̆ .”$b$,true),
('bunong-vn','MAT',26,35,null,$b$Y-Pêtrôs lah: “Tât gâp mra khĭt ndrel ma may kđôi, gâp mâu dun may ôh.” Jêh ri lĕ rngôch oh mon Păng lah tâm ban.$b$,false),
('bunong-vn','MAT',26,36,null,$b$Brah Yêsu hăn ndrel ma phung oh mon tâm du ntŭk rnha Gêtsêmanê. Păng lah ma khân păng: “Gŭ hom khân may ta aơ dôl gâp hăn mbơh sơm ta ri.”$b$,true),
('bunong-vn','MAT',26,37,null,$b$Păng jă ndrel ma Păng, Y-Pêtrôs jêh ri bar hê kon bu klâu Y-Sêƀêđê, jêh ri păng geh nuih n'hâm bêng ma nau rngot jêh ri nau rŭng răng,$b$,false),
('bunong-vn','MAT',26,38,null,$b$Păng lah ma khân păng: “Huêng gâp rngot ngăn tât ŭch khĭt; gŭ ta aơ jêh ri njrăng ndrel ma gâp.”$b$,false),
('bunong-vn','MAT',26,39,null,$b$Brah Yêsu hăn ngai đê̆, Păng chon mon kŭnh bôk ta neh, mbơh sơm pô aơ: “Ơ Mbơ̆ ơi, tơ lah dơi ăn kchok aơ du ngai tă bơh gâp, ƀiă lah mâu di tĭng nâm gâp ŭch, ƀiă lah tĭng nâm may ŭch.”$b$,false),
('bunong-vn','MAT',26,40,null,$b$Jêh ri Păng plơ̆ tay ma phung oh mon, jêh ri saơ khân păng gŭ bêch jêh; jêh ri păng lah ma Y-Pêtrôs: “Khân may mâu dơi hĕ gŭ njrăng ndrel ma gâp du mông?$b$,false),
('bunong-vn','MAT',26,41,null,$b$Njrăng hom jêh ri mbơh sơm, klach lah khân may tŭp tâm nau ndơm, huêng ŭch ngăn, ƀiă lah nglay săk rdja.”$b$,false),
('bunong-vn','MAT',26,42,null,$b$Păng hăn tay tal bar jêh ri Păng mbơh sơm pô aơ: “Ơ Mbơ̆ ơi, tơ lah kchok aơ mâu dơi ôh du ngai tă bơh gâp tât gâp nhêt păng, ăn tât tĭng nâm may ŭch.”$b$,false),
('bunong-vn','MAT',26,43,null,$b$Păng plơ̆ tay jêh ri saơ khân păng ŭch bêch, yor lah măt khân păng jâk ngăn.$b$,false),
('bunong-vn','MAT',26,44,null,$b$Păng du tă bơh phung oh mon jêh ri hăn mbơh sơm tal pe nâm bu lor lĕ.$b$,true),
('bunong-vn','MAT',26,45,null,$b$Dôl nây Păng plơ̆ tay ma phung oh mon jêh ri lah ma khân păng: “Mâm ƀư khân may bêch jêh ri rlu nkhơng? Tê̆, mông tât jêh, bu mra jao Kon Bunuyh tâm ti phung tih.$b$,false),
('bunong-vn','MAT',26,46,null,$b$Dâk hom khân may, hăn hom he; aơ nơm rlăng ma gâp tât jêh.”$b$,false),
('bunong-vn','MAT',26,47,null,$b$Dôl Păng ngơi, Y-Yuđas Iskariôt, du huê tâm phung jât ma bar oh mon, văch ndrel ma phung âk, djôt đao, tak jêh ri mâng. Phung n'gâng kôranh ƀư brah, jêh ri phung bu bŭnh bu ranh njuăl tât phung aơ.$b$,true),
('bunong-vn','MAT',26,48,null,$b$Nơm rlăng ma Păng ăn nau mbên ma phung nây pô aơ: “Mbu nơm gâp mra chŭm, Păng yơh nây, ăn khân may nhŭp ro.”$b$,false),
('bunong-vn','MAT',26,49,null,$b$Ƀât lât păng hăn êp Brah Yêsu jêh ri lah: “Mbah Kôranh!” Jêh ri păng chŭm ô băl.$b$,false),
('bunong-vn','MAT',26,50,null,$b$Ƀiă lah Brah Yêsu lah ma păng: “Hơi jiăng, moh nau may ŭch văch ta aơ?” Pô ri khân păng hăn êp, nhŭp Brah Yêsu ro.$b$,false),
('bunong-vn','MAT',26,51,null,$b$Jêh ri du huê tâm phung gŭ ndrel ma Brah Yêsu tăk đao păng sreh du huê oh mon kôranh ƀư brah toyh, geh ta tôr, tăch ro.$b$,false),
('bunong-vn','MAT',26,52,null,$b$Brah Yêsu lah ma păng: “Ntrŭp hom đao may tâm ndrop păng, yor lah mbu nơm dŏng đao, tak, đao tak lĕ mra nkhĭt păng.$b$,false),
('bunong-vn','MAT',26,53,null,$b$May mĭn gâp mâu dơi hĕ dăn ma Mbơ̆ gâp, jêh ri Păng mra ăn ma gâp aƀaơ ro, rmeh jât ma bar phung Tông mpăr ueh?$b$,false),
('bunong-vn','MAT',26,54,null,$b$Tơ lah mâu di pô ri, mâm ƀư, gay ƀư nanê̆ nau nchih lor jêh nau aơ mra tât?”$b$,true),
('bunong-vn','MAT',26,55,null,$b$Rnôk nây Brah Yêsu lah ma phung âk nây: “Khân may văch ma đao, tak jêh ri ma mâng ŭch nhŭp gâp nâm bu gâp jêng bunuyh ntŭng? Ăp nar gâp gŭ ndrel ma khân may jêh, tâm ngih brah Yuđa jêh ri gâp nti lah ta nây. Ƀiă lah khân may mâu nhŭp gâp ôh?$b$,true),
('bunong-vn','MAT',26,56,null,$b$Ƀiă lah lĕ rngôch nau aơ tât jêh gay ƀư nanê̆ nau nchih jêh, tă bơh phung kôranh nơm mbơh lor.” Dôl nây lĕ rngôch phung oh mon cha lơi păng jêh ri du.$b$,false),
('bunong-vn','MAT',26,57,null,$b$Phung aơ njŭn leo Brah Yêsu ta ngih kôranh ƀư brah toyh, Y-Kaip. Ta nây phung kôranh nchih sămƀŭt jêh ri phung bu bŭnh bu ranh tâm rƀŭn jêh.$b$,true),
('bunong-vn','MAT',26,58,null,$b$Y-Pêtrôs tĭng groi Brah Yêsu ngai, tât ta ntŭk nkual ngih kôranh ƀư brah toyh. Păng lăp. Gŭ ndrel ma phung ta han chiă ŭch uănh moh nau mra tât.$b$,false),
('bunong-vn','MAT',26,59,null,$b$Rnôk nây phung n'gâng kôranh ƀư brah, jêh ri phung kôranh phat dôih, lĕ rngôch joi nau phong nchơt ma Brah Yêsu ŭch nkhĭt lơi ô băl.$b$,true),
('bunong-vn','MAT',26,60,null,$b$Geh âk nơm phong nchơt hăn mbơh ta nây, ƀiă lah khân păng mâu saơ nau tih ôh. Jêh ri geh bar hê văch ngơi pô aơ:$b$,false),
('bunong-vn','MAT',26,61,null,$b$Bunuyh aơ lah jêh: “Gâp dơi ƀư rai ngih brah Yuđa, jêh ri ƀư tay păng tâm pe nar.”$b$,false),
('bunong-vn','MAT',26,62,null,$b$Pô ri kôranh ƀư brah toyh, dâk jêh ri lah ma Brah Yêsu: “May mâu geh nau plơ̆ lah hĕ ma phung nây phong may?”$b$,false),
('bunong-vn','MAT',26,63,null,$b$Ƀiă lah Brah Yêsu ăt gŭ rklăk. Kôranh ƀư brah toyh lah ma păng: “Gâp đă may tâm amoh Brah Ndu rêh, tơ lah may jêng Brah Krist, Kon Brah Ndu, ăn may lah ma hên?”$b$,true),
('bunong-vn','MAT',26,64,null,$b$Brah Yêsu plơ̆ lah ma păng: “May lah jêh, jêh ri gâp lah ma may, khân may mra saơ Kon Bunuyh gŭ mpeh pa ma nau brah, Brah Ndu, jêh ri plơ̆ văch tâm ndâr tŭk tâm trôk.”$b$,true),
('bunong-vn','MAT',26,65,null,$b$Jêh ri kôranh ƀư brah toyh nkhêk ao păng jêh ri lah: “Păng ngơi sưr jêh. Moh he ŭch ma nơm phong? Khân may mhe tăng jêh nau păng ngơi sưr nây.$b$,false),
('bunong-vn','MAT',26,66,null,$b$Mâm khân may mĭn?” Khân păng plơ̆ lah: “Păng khư ma nau khĭt.”$b$,false),
('bunong-vn','MAT',26,67,null,$b$Khân păng soh dak diu ta muh măt Brah Yêsu, jêh ri lơh Păng; ƀa ƀă tap ta bom ô băl jêh ri lah:$b$,false),
('bunong-vn','MAT',26,68,null,$b$“Ơ Brah Krist, mbơh hom! Mbu nơm dong may?”$b$,false),
('bunong-vn','MAT',26,69,null,$b$Dôl nây Y-Pêtrôs ăt gŭ pa dih. Du huê oh mon bu ur hăn êp păng jêh ri lah: “Nđâp ma may đŏng gŭ ndrel ma Brah Yêsu, n'gor Galilê.”$b$,true),
('bunong-vn','MAT',26,70,null,$b$Ƀiă lah păng dun ta năp lĕ rngôch jêh ri lah: “Gâp mâu gĭt ôh moh nau ay lah nây.”$b$,false),
('bunong-vn','MAT',26,71,null,$b$Dôl păng du hăn ta mpông, du huê oh mon bu ur êng saơ păng jêh ri lah ma phung gŭ ta nây: “Bunuyh aơ đŏng gŭ ndrel ma Brah Yêsu, ƀon Nasaret.”$b$,false),
('bunong-vn','MAT',26,72,null,$b$Ƀiă lah păng dun tay, jêh ri sân săk lah: “Gâp mâu gĭt năl ôh bunuyh aơ.”$b$,false),
('bunong-vn','MAT',26,73,null,$b$Ƀât lât ta nây phung nây lah ma Y-Pêtrôs: “Nanê̆ may jêng du huê tâm phung bunuyh aơ. Yor lah bâr may ngơi mbơh may nơm.”$b$,false),
('bunong-vn','MAT',26,74,null,$b$Păng ntơm rak rtăp jêh ri sân săk lah: “Gâp mâu năl bunuyh aơ ôh.” Ƀât lât iăr ndrau ro.$b$,false),
('bunong-vn','MAT',26,75,null,$b$Y-Pêtrôs kah gĭt nau Brah Yêsu lah lor jêh ma păng: “Ê lor ta iăr ndrau, may mra dun ma gâp pe tơ̆ .” Jêh ri păng luh, nhĭm rngot ngăn.$b$,true),
('bunong-vn','MAT',27,1,null,$b$Dâk ôi, lĕ rngôch phung n'gâng kôranh ƀư brah, jêh ri phung bu bŭnh bu ranh tâm nchră ma nau ƀư ma Brah Yêsu ŭch nkhĭt lơi ô băl.$b$,true),
('bunong-vn','MAT',27,2,null,$b$Jêh khân păng chăp ô băl, khân păng njŭn leo jao ô băl ma kôranh toyh Pilat.$b$,false),
('bunong-vn','MAT',27,3,null,$b$Rnôk nây Y-Yuđas, nơm rlăng, saơ bu rmal jêh Brah Yêsu geh nau nduyh tâm nuih n'hâm păng. Păng mplơ̆ lơi pe jât rêl prăk ma phung n'gâng kôranh ƀư brah jêh ri ma phung bu bŭnh bu ranh jêh ri lah:$b$,true),
('bunong-vn','MAT',27,4,null,$b$“Gâp tih jêh jao ăn ma khân may mham mâu tih ôh.” Ƀiă lah phung nây plơ̆ lah: “Moh hên chrê? Kđôi may.”$b$,false),
('bunong-vn','MAT',27,5,null,$b$Păng klŭp lơi prăk tâm ntŭk kloh, luh du; jêh ri yông trô ko păng nơm.$b$,false),
('bunong-vn','MAT',27,6,null,$b$Ƀiă lah phung kôranh ƀư brah sŏk prăk nây jêh ri lah: “Mâu vay ôh dơm prăk aơ tâm ntŭk prăp prăk Brah Ndu, yor lah prăk rnoh mham.”$b$,false),
('bunong-vn','MAT',27,7,null,$b$Jêh khân păng tâm nchră, dŏng prăk nây rvăt mir lŏ nơm mon glah, ŭch prăp tâp phung bunuyh bri êng.$b$,false),
('bunong-vn','MAT',27,8,null,$b$Yor nây tât nar aơ bu rnha lŏ nây jêng Lŏ Mham.$b$,false),
('bunong-vn','MAT',27,9,null,$b$Pô ri ƀư nanê̆ jêh nau kôranh nơm mbơh lor Y-Yêrêmi lah: “Khân păng sŏk jêh pe jât rêl prăk, rnoh du huê bunuyh phung Israel veh jêh,$b$,false),
('bunong-vn','MAT',27,10,null,$b$jêh ri khân păng sŏk prăk nây rvăt mir lŏ nơm mon glah, nâm bu Kôranh Brah ntăm jêh.”$b$,false),
('bunong-vn','MAT',27,11,null,$b$Brah Yêsu dâk ta năp kôranh toyh Pilat; jêh ri kôranh toyh ôp Păng pô aơ: “Di lĕ may jêng hađăch Yuđa?” Brah Yêsu lah: “May hŏ lah jêh.”$b$,false),
('bunong-vn','MAT',27,12,null,$b$Dôl phung kôranh ƀư brah jêh ri phung bu bŭnh bu ranh phong Păng, Păng mâu hôm ngơi ôh.$b$,false),
('bunong-vn','MAT',27,13,null,$b$Pilat lah ma Păng: “May mâu tăng hĕ nau khân păng phong may âk ngăn?”$b$,false),
('bunong-vn','MAT',27,14,null,$b$Ƀiă lah Păng mâu ngơi du tong; tât kôranh toyh nây hih rhâl ngăn.$b$,false),
('bunong-vn','MAT',27,15,null,$b$Ăp năm nhêt sa Nau Găn, kôranh toyh vay mƀơk, du huê bu nă tĭng nâm bunuyh ƀon lan dăn.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MAT',27,16,null,$b$Rnôk nây geh du huê bu nă, geh nau tih jru ngăn, amoh păng, Y-Barabas.$b$,false),
('bunong-vn','MAT',27,17,null,$b$Jêh tâm rƀŭn, Pilat lah ma khân păng: “Mbu nơm khân may ŭch gâp mra mƀơk, Y-Barabas mâu lah Brah Yêsu, bu kuăl Brah Krist?”$b$,true),
('bunong-vn','MAT',27,18,null,$b$Yor lah păng gĭt nanê̆ bunuyh jao Brah Yêsu ma păng ma nau nach.$b$,false),
('bunong-vn','MAT',27,19,null,$b$Dôl păng gŭ phat dôih, ur păng njuăl bu lah ma păng pô aơ: “Lơi ƀư ma bunuyh sŏng aơ ôh, yor lah gâp geh nau rŭng ăp nar, yor păng tâm nau gâp mbơi.”$b$,false),
('bunong-vn','MAT',27,20,null,$b$Ƀiă lah phung n'gâng kôranh ƀư brah jêh ri phung bu bŭnh bu ranh nchâp phung bunuyh ƀon lan ăn dăn mƀơk Y-Barabas, jêh ri nkhĭt lơi Brah Yêsu.$b$,false),
('bunong-vn','MAT',27,21,null,$b$Kôranh toyh lah ma khân păng: “Mbu nơm tâm phung bar hê aơ khân may ŭch gâp mƀơk?” Khân păng plơ̆ lah: “Y-Barabas.”$b$,false),
('bunong-vn','MAT',27,22,null,$b$Pilat lah ma khân păng: “Bi ma Brah Yêsu, bu kuăl Brah Krist, mâm gâp mra ƀư?”$b$,false),
('bunong-vn','MAT',27,23,null,$b$Lĕ rngôch bunuyh lah: “Pâng lơi Păng ta si tâm rkăng,” kôranh toyh ôp: “Ƀiă lah moh nau mhĭk Păng mâp ƀư jêh?” Khân păng nter ktang lơn: “Pâng lơi păng ta si tâm rkăng.”$b$,false),
('bunong-vn','MAT',27,24,null,$b$Pilat gĭt păng mâu dơi ôh, ƀiă lah geh nau nteh uh ah lơ hâu lơn, pô ri păng sŏk dak, jêh ri rao ti păng ta năp phung âk nây jêh ri lah: “Gâp mâu tih ôh đah mham bunuyh sŏng aơ; kđôi khân may yơ̆ !”$b$,true),
('bunong-vn','MAT',27,25,null,$b$Lĕ rngôch bunuyh plơ̆ lah: “Ăn mham păng tŭp ta hên jêh ri ta phung kon sau hên!”$b$,false),
('bunong-vn','MAT',27,26,null,$b$Jêh ri Pilat mƀơk ăn ma khân păng Y-Barabas; bi Brah Yêsu, jêh bu dong, bu lơh ô băl ma mâng, păng jao ma bu pâng ô băl ta si tâm rkăng.$b$,true),
('bunong-vn','MAT',27,27,null,$b$Phung ta han kôranh toyh njŭn leo Brah Yêsu ta ngih phat dôih, jêh ri lĕ rngôch tâm rgum jŭm Brah Yêsu.$b$,true),
('bunong-vn','MAT',27,28,null,$b$Khân păng doh lơi ao ô băl, jêh ri nsoh ô băl ao chăng.$b$,false),
('bunong-vn','MAT',27,29,null,$b$Jêh ri khân păng tanh du mlâm đon hađăch ma lok, sâm ndô ta bôk Brah Yêsu, jêh ri dơm du tơm treng tâm ti pa ma Păng, khân păng chon kômâk ta năp Păng jêh ri mưch ma Păng, lah: “Mbah ma hađăch phung Yuđa!”$b$,false),
('bunong-vn','MAT',27,30,null,$b$Khân păng soh dak diu ta ô băl jêh ri sŏk tơm treng lơh ta bôk ô băl.$b$,true),
('bunong-vn','MAT',27,31,null,$b$Jêh khân păng mưch ma ô băl khân păng doh lơi ao chăng, jêh ri nsoh ao ô băl nơm, jêh ri khân păng njŭn leo pâng ô băl ta si tâm rkăng.$b$,false),
('bunong-vn','MAT',27,32,null,$b$Dôl khân păng luh, khân păng saơ du huê bunuyh tă bơh ƀon Siren, amoh păng Y-Simôn; jêh ri khân păng nchâp ô băl tuy si tâm rkăng Brah Yêsu.$b$,true),
('bunong-vn','MAT',27,33,null,$b$Tât ta ntŭk rnha Gôgôtha, nâm bu ntĭt, ntŭk nting bôk.$b$,false),
('bunong-vn','MAT',27,34,null,$b$Khân păng ăn ma Brah Yêsu ndrănh tâm pot đah dak si tăng, ƀiă lah jêh Brah Yêsu chiăm djê̆, Păng mâu ŭch nhêt ôh.$b$,true),
('bunong-vn','MAT',27,35,null,$b$Jêh ri khân păng, pâng ô băl ta si tâm rkăng, khân păng tâm pă bok ao ô băl ma nau nchroh;$b$,false),
('bunong-vn','MAT',27,36,null,$b$jêh ri khân păng gŭ ta nây chiă uănh Brah Yêsu.$b$,false),
('bunong-vn','MAT',27,37,null,$b$Ta klơ bôk ô băl khân păng pla du pŏk sămƀŭt nchih nau bu phat dôih ô băl pô aơ: “Aơ, Brah Yêsu Hađăch Yuđa.”$b$,false),
('bunong-vn','MAT',27,38,null,$b$Rnôk nây bu pâng ndrel ma Brah Yêsu, bar hê bunuyh ntŭng, nguay pa ma, nguay pa chiau.$b$,false),
('bunong-vn','MAT',27,39,null,$b$Phung rgăn ta nây gơm mưch ma Brah Yêsu; khân păng rteh bôk jêh ri lah:$b$,true),
('bunong-vn','MAT',27,40,null,$b$“May ƀư rai ngih brah Yuđa jêh ri ƀư tay tâm pe nar, tâm rklaih hom may nơm! Tơ lah may jêng Kon Brah Ndu, ntrŭnh hom tă bơh si tâm rkăng.”$b$,false),
('bunong-vn','MAT',27,41,null,$b$Phung n'gâng kôranh ƀư brah, phung kôranh nchih sămƀŭt, jêh ri phung bu bŭnh bu ranh lah ma nau mưch tâm ban lĕ:$b$,false),
('bunong-vn','MAT',27,42,null,$b$“Păng tâm rklaih âk bu êng. Mâm ƀư Păng mâu dơi tâm rklaih Păng nơm. Tơ lah Păng jêng hađăch Israel, ăn Păng jŭr aƀaơ ro, tă bơh si tâm rkăng jêh ri he mra chroh ma Păng.$b$,false),
('bunong-vn','MAT',27,43,null,$b$Păng nsing ma Brah Ndu; tơ lah Brah Ndu rŏng ma Păng, ăn Brah Ndu tâm rklaih Păng aƀaơ ro. Yor lah Păng lah: ‘Gâp jêng Kon Brah Ndu.’ ”$b$,false),
('bunong-vn','MAT',27,44,null,$b$Jêh ri phung ntŭng bu pâng ta si tâm rkăng ndrel ma Păng rak suai Păng tâm ban lĕ.$b$,false),
('bunong-vn','MAT',27,45,null,$b$Ntơm bơh nar nklang bôk tât ta pe mông geh nau ngo lam neh ntu.$b$,true),
('bunong-vn','MAT',27,46,null,$b$Ta pe mông Brah Yêsu nter huy ktang ngăn: “Êli, Êli, lama sabaktani?” Nâm bu ntĭt: “Brah Ndu gâp ơi, Brah Ndu gâp ơi, mâm ƀư may cha lơi gâp?”$b$,false),
('bunong-vn','MAT',27,47,null,$b$Ƀa ƀă gŭ dăch ta nây tăng nau nây, khân păng lah: “Păng kuăl Y-Êli.”$b$,false),
('bunong-vn','MAT',27,48,null,$b$Ƀât lât geh du huê tâm phung khân păng nchuăt, hăn sŏk bok, mbŭk tâm dak srat ntôr ta chiông tơm treng, jêh ri ndơ̆ ăn ma Brah Yêsu nhêt.$b$,true),
('bunong-vn','MAT',27,49,null,$b$Ƀiă lah phung êng lah: “Lơi hom! Ăn he gŭ uănh gĭt lah Y-Êli mra văch tâm rklaih Păng?”$b$,false),
('bunong-vn','MAT',27,50,null,$b$Brah Yêsu nter du tong huy ngăn, jêh ri tăch n'hâm.$b$,false),
('bunong-vn','MAT',27,51,null,$b$Jêh ri aơ bok tâm ngih brah Yuđa khêk ntơm bơh klơ tât tâm dâng; jêh ri neh n'găr; lŭ đang;$b$,true),
('bunong-vn','MAT',27,52,null,$b$âk môch pơk jêh ri âk săk jăn phung kloh ueh khĭt jêh dâk rêh tay.$b$,false),
('bunong-vn','MAT',27,53,null,$b$Jêh Brah Yêsu dâk rêh tay phung aơ luh tă bơh môch, lăp tâm ƀon kloh ueh jêh ri tâm mpơl ma âk bunuyh.$b$,false),
('bunong-vn','MAT',27,54,null,$b$Kôranh ta han jêh ri phung chiă Brah Yêsu gŭ ndrel ta nây, tơ lah saơ nau n'găr neh ntu jêh ri lĕ rngôch nau tât jêh, khân păng klach ngăn jêh ri lah: “Nanê̆ bunuyh aơ jêng Kon Brah Ndu!”$b$,false),
('bunong-vn','MAT',27,55,null,$b$Jêh ri geh âk bu ur gŭ uănh tă bơh n'gor Galilê.$b$,true),
('bunong-vn','MAT',27,56,null,$b$Tâm phung bu ur nây geh H'Mari Mađala, H'Mari, mê̆ Y-Yakơ jêh ri Y-Yôsê, geh nđâp ma mê̆ phung kon Y-Sêƀêđê.$b$,false),
('bunong-vn','MAT',27,57,null,$b$Kêng măng geh du huê ndrŏng văch tă bơh ƀon Arimathê, amoh păng Y-Yôsep. Păng yơh jêng oh mon Brah Yêsu.$b$,true),
('bunong-vn','MAT',27,58,null,$b$Păng hăn ta Pilat jêh ri dăn săk jăn khĭt Brah Yêsu. Pilat đă bu ăn ma păng.$b$,false),
('bunong-vn','MAT',27,59,null,$b$Y-Yôsep sŏk săk jăn, sâm nklâm ma bok nglang,$b$,false),
('bunong-vn','MAT',27,60,null,$b$jêh ri njor tâm môch mhe păng nkra jêh ma păng nơm tâm trôm ntu lŭ; păng rlă du mlâm lŭ toyh rdâl ta mpông môch jêh ri păng sĭt.$b$,false),
('bunong-vn','MAT',27,61,null,$b$H'Mari Mađala jêh ri H'Mari êng gŭ ta nây lĕ. Khân păng gŭ ta năp môch.$b$,true),
('bunong-vn','MAT',27,62,null,$b$Ôi taơ, nar pa kơi ma nar nkra, phung n'gâng kôranh ƀư brah jêh ri phung Pharisi hăn ndrel ma Pilat.$b$,true),
('bunong-vn','MAT',27,63,null,$b$Jêh ri lah: “Hơi kôranh, hên kah gĭt ma bunuyh mƀruh sưr nây, dôl păng hôm gŭ rêh lah pô aơ: ‘Tăch pe nar gâp mra dâk rêh.’$b$,false),
('bunong-vn','MAT',27,64,null,$b$Pô ri, ăn may đă bu chiă uănh môch ăn ueh tât ta nar tal pe, klach lah phung oh mon păng văch, sŏk ntŭng săk jăn păng jêh ri lah ma bu: ‘Păng dâk rêh jêh tă bơh phung khĭt’. Nau mƀruh sưr pa kơi nây mra jêng mhĭk lơn pa năp.”$b$,false),
('bunong-vn','MAT',27,65,null,$b$Pilat lah ma khân păng: “Khân may geh jêh phung ta han gak, hăn hom! Jêh ri chiă uănh môch tĭng nâm khân may ŭch.”$b$,false),
('bunong-vn','MAT',27,66,null,$b$Pô ri khân păng hăn hăn rdâl môch jêh ri ăn nau ver mâu ăn bu trâl jêh ri ăn ta han gak ƀư ueh nanê̆.$b$,false),
('bunong-vn','MAT',28,1,null,$b$Lôch jêh nar Saƀat, ơm ôi nar nguay tâm nar ver, H'Mari Mađala jêh ri H'Mari êng hăn chop môch.$b$,true),
('bunong-vn','MAT',28,2,null,$b$Aơ geh nau n'găr neh ntu ktang; yor lah Tông mpăr ueh Kôranh Brah văch tă bơh klơ, nklơ̆ lơi lŭ jêh ri săp gŭ.$b$,false),
('bunong-vn','MAT',28,3,null,$b$Păng jêng ral nâm bu lơp nglaih jêh ri ao Păng nglang nâm bu pler.$b$,false),
('bunong-vn','MAT',28,4,null,$b$Phung ta han chiă klach hâu ngăn, nsâr săk jăn, jêng nâm bu khĭt.$b$,true),
('bunong-vn','MAT',28,5,null,$b$Ƀiă lah Tông mpăr ueh lah ma phung, bu ur nây: “Lơi khân ay klach ôh, yor lah gâp gĭt khân ay joi Brah Yêsu, Nơm bu pâng ta si tâm rkăng.$b$,false),
('bunong-vn','MAT',28,6,null,$b$Păng mâu hôm gŭ ta aơ ôh; yor lah Păng hŏ dâk rêh jêh, nâm bu Păng lah jêh. Văch uănh ntŭk bu njor Păng.$b$,true),
('bunong-vn','MAT',28,7,null,$b$Jêh ri hăn gơnh, lah ma phung oh mon Păng gĭt ma Păng hŏ dâk rêh jêh, jêh ri Păng hăn lor ma khân may tâm n'gor Galilê; ta nây khân may mra saơ Păng. Pô ri, gâp mbơh ma khân may.”$b$,false),
('bunong-vn','MAT',28,8,null,$b$Khân păng hăn ro tă bơh môch, dôl hăn geh nau klach, lơ hâu geh nau răm, jêh ri khân păng nchuăt hăn mbơh nau mhe mhan nây ma phung oh mon Păng.$b$,true),
('bunong-vn','MAT',28,9,null,$b$Aơ, Brah Yêsu tâm mâp đah phung bu ur nây jêh ri lah pô aơ: “Mât ton ma khân ay may!” Khân păng hăn êp Păng, kuăn ta jâng Păng jêh ri păn ta neh mbah ma Păng ro, jêh ri Brah Yêsu lah ma khân păng:$b$,true),
('bunong-vn','MAT',28,10,null,$b$“Lơi klach ôh; hăn mbơh ma phung oh gâp ăn khân păng hăn ta n'gor Galilê, ta nây yơh khân păng mra saơ gâp.” Phung kôranh ƀư brah mƀruh$b$,false),
('bunong-vn','MAT',28,11,null,$b$Dôl khân păng hăn ta trong, geh ƀa ƀă phung ta han chiă plơ̆ ta ƀon toyh, mbơh ma phung n'gâng kôranh ƀư brah lĕ rngôch nau tât jêh.$b$,false),
('bunong-vn','MAT',28,12,null,$b$Phung aơ tâm rgum đah phung bu ranh, jêh ri tâm nchră, khân păng ăn prăk âk ngăn ma phung ta han jêh ri ntăm ma khân păng pô aơ:$b$,false),
('bunong-vn','MAT',28,13,null,$b$“Ăn khân may lah: ‘Phung oh mon păng văch dôl măng ngo ntŭng jêh sŏk săk Brah Yêsu dôl hên bêch.’$b$,false),
('bunong-vn','MAT',28,14,null,$b$Tơ lah kôranh toyh tăng nau nây, hên mra rblang ma păng jêh ri king ma khân may.”$b$,false),
('bunong-vn','MAT',28,15,null,$b$Pô ri phung ta han sŏk prăk jêh ri ƀư tĭng nâm nau nây; nau nây tăng lư lam ntŭk tâm phung Yuđa tât ma nar aơ.$b$,false),
('bunong-vn','MAT',28,16,null,$b$Phung jât ma nguay nuyh oh mon, hăn ta n'gor Galilê, ta yôk Brah Yêsu ntĭm jêh ma khân păng.$b$,true),
('bunong-vn','MAT',28,17,null,$b$Tơ lah khân păng saơ jêh Brah Yêsu, khân păng chon mon ta neh, mbah ma Păng, ƀiă lah ƀa ƀă geh nau đing.$b$,false),
('bunong-vn','MAT',28,18,null,$b$Brah Yêsu hăn êp khân păng jêh ri lah pô aơ: “Lĕ rngôch nau brah tâm trôk jêh ri ta neh ntu bu jao jêh ma gâp.$b$,false),
('bunong-vn','MAT',28,19,null,$b$Hăn hom khân may, njêng phung chroh tâm lĕ rngôch mpôl băl bunuyh, ƀư ƀaptem ma khân păng tâm amoh Brah Mbơ̆ , amoh Brah Kon, jêh ri tâm amoh Brah Huêng Ueh.$b$,false),
('bunong-vn','MAT',28,20,null,$b$Jêh ri sâm nti ăn khân păng tông lĕ nau gâp ntăm jêh ma khân may; jêh ri aơ gâp ăt hôm gŭ ndrel ma khân may ƀa ƀơ tât nar lôch.”$b$,false);
