insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MRK',1,1,null,$b$Nau ntơm ma nau mhe mhan ueh ma Brah Yêsu Krist, Kon Brah Ndu.$b$,true),
('bunong-vn','MRK',1,2,null,$b$Tĭng nâm nau bu nchih jêh tâm ndrom sămƀŭt kôranh nơm mbơh lor Y-Êsai: “Ta aơ, gâp prơh hăn nơm mbơh ma gâp ta năp may, păng mra nkra trong ma may.$b$,false),
('bunong-vn','MRK',1,3,null,$b$Geh bâr nter tâm bri rdah: Nkra hom trong Kôranh Brah, ƀư lâng hom trong Păng.”$b$,true),
('bunong-vn','MRK',1,4,null,$b$Y-Yôhan nơm ƀư ƀaptem văch jêh, tâm bri rdah jêh ri nti nau ƀư ƀaptem ma mbu nơm rmal nau tih, gay dơi geh nau yô̆ an.$b$,false),
('bunong-vn','MRK',1,5,null,$b$Lĕ n'gor bri Yuđa jêh ri lĕ rngôch phung ƀon lan Yêrusalem hăn ma păng. Khân păng mbơh nau tih jêh ri ăn Y-Yôhan ƀư ƀaptem ma khân păng tâm dak krong Yurdan.$b$,true),
('bunong-vn','MRK',1,6,null,$b$Y-Yôhan nsoh ao rsau seh samô, jêh ri păng vân rse bŭt ntâu. Păng sa krah jêh ri dak sŭt bri.$b$,false),
('bunong-vn','MRK',1,7,null,$b$Păng nti kơt aơ: “Du huê mra văch pa kơi gâp, jêng brah lơn ma gâp, jêh ri gâp mâu khư ôh kŭnh doh rse ntâu jot Păng.$b$,false),
('bunong-vn','MRK',1,8,null,$b$Gâp ƀư ƀaptem ma khân may ma dak, ƀiă lah Păng mra ƀư ƀaptem ma khân may đah Brah Huêng Ueh.”$b$,false),
('bunong-vn','MRK',1,9,null,$b$Rnôk nây Brah Yêsu văch tă bơh ƀon Nasaret n'gor Galilê, jêh ri ăn Y-Yôhan ƀư ƀaptem ma Păng tâm dak krong Yurdan.$b$,true),
('bunong-vn','MRK',1,10,null,$b$Dôl Brah Yêsu luh tă bơh dak Păng saơ trôk pơk mpơl jêh ri Brah Huêng Ueh jŭr drâm ta klơ Brah Yêsu nâm bu plŭk.$b$,true),
('bunong-vn','MRK',1,11,null,$b$Jêh ri geh bâr ngơi tă bơh trôk lah: “May jêng kon gâp rŏng ngăn ngên; tâm may gâp geh nau răm maak ngăn.”$b$,false),
('bunong-vn','MRK',1,12,null,$b$Ƀât lât ta nây Brah Huêng Ueh ntrôl Brah Yêsu luh hăn tâm bri rdah.$b$,false),
('bunong-vn','MRK',1,13,null,$b$Păng gŭ tâm bri rdah puăn jât nar, jêh ri Satan ndơm Păng. Păng gŭ ndrel ma mpô mpa bri, jêh ri Tông mpăr ueh Brah Ndu kơl Păng.$b$,false),
('bunong-vn','MRK',1,14,null,$b$Jêh bu nhŭp krŭng Y-Yôhan, Brah Yêsu hăn rlet n'gor Galilê nti nau mhe mhan ueh Brah Ndu,$b$,true),
('bunong-vn','MRK',1,15,null,$b$Păng lah: “Rô̆ aơ tât jêh, jêh ri ƀon bri hađăch Brah Ndu dăch tât jêh. Rmal lơi hom nau tih khân may, jêh ri chroh ma nau mhe mhan ueh.”$b$,false),
('bunong-vn','MRK',1,16,null,$b$Dôl Brah Yêsu hăn rgŏ dak mƀŭt Galilê, Păng saơ Y-Simôn jêh ri Y-Andrê, oh Y-Simôn. Khân păng gŭ seng ka tâm dak mƀŭt; yor lah khân păng jêng bunuyh vay seng jal.$b$,true),
('bunong-vn','MRK',1,17,null,$b$Brah Yêsu lah ma khân păng: “Tĭng hom gâp, jêh ri gâp mra ăn khân may jêng bunuyh seng bunuyh.”$b$,false),
('bunong-vn','MRK',1,18,null,$b$Ƀât lât ta nây khân păng mƀăr lơi jal khân păng, jêh ri khân păng tĭng ndô̆ Brah Yêsu.$b$,false),
('bunong-vn','MRK',1,19,null,$b$Tơ lah păng hăn ngai oi đê̆, păng saơ Y-Yakơ, kon Y-Sêƀêđê, jêh ri Y-Yôhan, oh păng. Phung nây gŭ tâm plŭng nsrêp jal.$b$,false),
('bunong-vn','MRK',1,20,null,$b$Brah Yêsu kuăl khân păng ro; jêh ri khân păng cha lơi êng mbơ̆ khân păng, Y-Sêƀêđê tâm plŭng ndrel ma phung oh mon păng, bi khân păng hăn tĭng Brah Yêsu.$b$,false),
('bunong-vn','MRK',1,21,null,$b$Khân păng hăn ta ƀon Kapernum; jêh ri ta nar Saƀat, Brah Yêsu lăp ro tâm ngih tâm rƀŭn Yuđa jêh ri nti lah ta nây.$b$,true),
('bunong-vn','MRK',1,22,null,$b$Bunuyh gŭ iăt hih rhâl nau păng nti, yor lah Păng nti ma khân păng nâm bu du huê geh nau dơi toyh, mâu di ôh nâm bu phung kôranh nchih sămƀŭt.$b$,false),
('bunong-vn','MRK',1,23,null,$b$Pô ri, ƀât lât ta nây geh tâm ngih rƀŭn Yuđa du huê bunuyh brah mhĭk gŭ tâm păng, jêh ri păng nter kơt aơ:$b$,true),
('bunong-vn','MRK',1,24,null,$b$“Ơ Brah Yêsu, ƀon Nasaret, moh nau may geh đah hên? May văch gay ƀư rai hên ƀơh? Gâp gĭt jêh mbu may jêng, Nơm Kloh Ueh bơh Brah Ndu.”$b$,false),
('bunong-vn','MRK',1,25,null,$b$Ƀiă lah Brah Yêsu buay brah mhĭk nây, lah: “Gŭ rklăk hom may, jêh ri du luh hom bơh bunuyh aơ.”$b$,false),
('bunong-vn','MRK',1,26,null,$b$Jêh nây brah mhĭk du luh ro tă bơh bunuyh nây ma nau nsâr râm săk jăn ô băl, jêh ri ma nau lŭng nter.$b$,false),
('bunong-vn','MRK',1,27,null,$b$Lĕ rngôch khân păng hih rhâl, jêh ri tâm ôp ndrăng khân Păng lah: “Moh nau tât aơ? Nau nti mhe ƀơh! Nơm aơ Păng dŏng nau dơi toyh nđâp ma phung brah mhĭk dơi tông nau Păng da dê.”$b$,false),
('bunong-vn','MRK',1,28,null,$b$Jêh ri amoh Păng lư n'găr lam n'gor Galilê.$b$,false),
('bunong-vn','MRK',1,29,null,$b$Dôl khân păng luh tă bơh ngih rƀŭn Yuđa, khân păng hăn ndrel ma Y-Yakơ jêh ri Y-Yôhan rlet ma ngih Y-Simôn jêh ri Y-Andrê.$b$,true),
('bunong-vn','MRK',1,30,null,$b$Po bu ur Y-Simôn bêch ji kop. Bu mbơh ro nau păng ji nây ma Brah Yêsu.$b$,false),
('bunong-vn','MRK',1,31,null,$b$Brah Yêsu hăn êp bu ur nây, jêh ri kuăn ta ti păng ăn ô băl dâk; ƀât lât ta nây nau ji păng bah ro jêh ri păng n'ho pah kan ma khân păng.$b$,true),
('bunong-vn','MRK',1,32,null,$b$Tât kêng mhaơ, nar lĕ nhâp jêh bu njŭn leo ma Brah Yêsu lĕ rngôch phung ji kuet, jêh ri brah mhĭk lơh.$b$,true),
('bunong-vn','MRK',1,33,null,$b$Lĕ rngôch bunuyh tâm ƀon nây tâm rgum pa năp mpông ngih păng gŭ.$b$,false),
('bunong-vn','MRK',1,34,null,$b$Brah Yêsu ƀư bah âk bunuyh geh nau ji êng êng, jêh ri nsot âk brah mhĭk, mâu hôm geh nau dơi ôh brah mhĭk dơi ngơi, yor lah khân păng lĕ gĭt năl jêh Păng.$b$,false),
('bunong-vn','MRK',1,35,null,$b$Ơm ôi taơ, ƀhit rvi ang, Brah Yêsu dâk jêh ri du luh bơh ngih nây hăn êng, tâm ntŭk bri rdah jêh ri gŭ mbơh sơm ta nây.$b$,true),
('bunong-vn','MRK',1,36,null,$b$Y-Simôn jêh ri phung băl păng tĭng joi Brah Yêsu.$b$,true),
('bunong-vn','MRK',1,37,null,$b$Tơ lah khân păng saơ Brah Yêsu, jêh ri lah: “Lĕ rngôch bunuyh tĭng joi may.”$b$,false),
('bunong-vn','MRK',1,38,null,$b$Brah Yêsu lah: “Hăn hom he tâm nkual ƀon dăch tâm aơ, gay ma gâp dơi nti lah ta nây tâm ban lĕ; yor ma nau nây yơh gâp văch.”$b$,false),
('bunong-vn','MRK',1,39,null,$b$Jêh nây Brah Yêsu hăn lam tâm n'gor Galilê, nti tâm ngih rƀŭn Yuđa jêh ri mprơh nsot brah mhĭk.$b$,false),
('bunong-vn','MRK',1,40,null,$b$Geh du huê bunuyh phŭng sa hăn ran ta Brah Yêsu. Păng chon kômâk jêh ri vơh vơl ma păng: “Lah may ŭch, may dơi ƀư kloh gâp.”$b$,true),
('bunong-vn','MRK',1,41,null,$b$Brah Yêsu geh nau yô̆ klâng, yơr ti rpôt ô băl, jêh ri lah: “Gâp ŭch lĕ, ăn may jêng kloh hom.”$b$,false),
('bunong-vn','MRK',1,42,null,$b$Ƀât lât phŭng păng bah, jêh ri păng jêng kloh.$b$,false),
('bunong-vn','MRK',1,43,null,$b$Brah Yêsu ăn păng sĭt ro jêh ri ntĭnh mprân lơi ma păng:$b$,false),
('bunong-vn','MRK',1,44,null,$b$“Njrăng hom, lơi nkoch nau nây ma bu ôh, ƀiă lah hăn mpơl săk may nơm ma kôranh ƀư brah, jêh ri nhhơr mpa yor nau ƀư kloh may tĭng nâm Y-Môis ntĭnh jêh, jêng nau ăn n'hêl nanê̆ ma phung ƀon lan.”$b$,false),
('bunong-vn','MRK',1,45,null,$b$Ƀiă lah bunuyh nây dak hăn, jêh ri ntơm nkoch bri jêh ri mbơh nau nây lam ntŭk. Yor nây Brah Yêsu mâu hôm dơi lăp tâm ƀon nây. Păng gŭ pa dih ƀon, tâm ntŭk bri rdah, jêh ri lĕ rngôch bunuyh tă bơh lam ntŭk hăn tât ta Păng.$b$,false),
('bunong-vn','MRK',2,1,null,$b$Bar pe nar ta nây, Brah Yêsu plơ̆ sĭt đŏng ma ƀon Kapernum, jêh ri bu gĭt ma Păng gŭ tâm ngih nây.$b$,true),
('bunong-vn','MRK',2,2,null,$b$Khân păng tâm rƀŭn ta nây, geh âk râk bunuyh văch bêng ngih, nđâp ma pa năp mpông ngih kŏ tât mâu hôm geh ntŭk gŭ ôh, Brah Yêsu nti lah nau Brah Ndu ngơi ma khân păng.$b$,false),
('bunong-vn','MRK',2,3,null,$b$Jêh nây geh puăn nuyh bu klâu tung njŭn leo tât ma Păng du huê bunuyh rvĕn.$b$,false),
('bunong-vn','MRK',2,4,null,$b$Ƀiă lah, yor lah âk ir bunuyh, mâu dơi nglăp lăp êp Brah Yêsu ôh, pô ri khân păng plơk chor ngih tra klơ bôk Brah Yêsu, jêh nây, ta trôm nây yơh khân păng yur ntrŭnh ndrel ka mbuk bunuyh rvĕn nây bêch.$b$,false),
('bunong-vn','MRK',2,5,null,$b$Brah Yêsu saơ nau khân păng rnơm, jêh ri Păng lah ma nơm rvĕn nây: “Kon gâp ơi, nau tih may hŏ yô̆ an jêh.”$b$,false),
('bunong-vn','MRK',2,6,null,$b$Ta nây, geh ƀa ƀă kôranh nchih sămƀŭt, jêh ri geh nau mĭn êng tâm nuih n'hâm lah:$b$,false),
('bunong-vn','MRK',2,7,null,$b$“Mâm ƀư bunuyh nây ngơi kơt nây? Păng ngơi sưr yơh! Mbu moh dơi yô̆ an nau tih, knŏng du huê Brah Ndu dơm yơh?”$b$,false),
('bunong-vn','MRK',2,8,null,$b$Brah Yêsu gĭt ro tâm nau mĭn khân păng, ŭch tâm rlăch tâm dun tâm nuih n'hâm khân păng, jêh ri păng ôp: “Mâm ƀư khân may geh nau tâm rlăch tâm nuih n'hâm tâm ban kơt nây?$b$,false),
('bunong-vn','MRK',2,9,null,$b$Mâm nau lah ma bunuyh rvĕn, jêng di lơn: ‘Nau tih may hŏ yô̆ an jêh’, mâu lah, lah: ‘Dâk hom may, sŏk djôt ka mbuk may jêh ri chuat hăn?’$b$,false),
('bunong-vn','MRK',2,10,null,$b$Ƀiă lah gay ma khân may dơi gĭt ma Kon Bunuyh geh nau dơi yô̆ an nau tih ta neh ntu.” Păng n'gĭl ta bunuyh rvĕn jêh ri lah:$b$,false),
('bunong-vn','MRK',2,11,null,$b$“Gâp lah ma may, dâk hom, sŏk djôt ka mbuk may jêh ri sĭt ma ngih may nơm.”$b$,false),
('bunong-vn','MRK',2,12,null,$b$Bunuyh rvĕn dâk ro, sŏk ka mbuk păng jêh ri du luh bơh pa năp lĕ rngôch phung nây; pô ri, lĕ rngôch khân păng hih rhâl jêh ri tâm rnê ma Brah Ndu, lah: “He mâu mâp prot saơ ôh nau nâm bu pô aơ.”$b$,true),
('bunong-vn','MRK',2,13,null,$b$Brah Yêsu plơ̆ hăn ta meng kơh dak mƀŭt, jêh ri lĕ rngôch phung âk văch tâm rƀŭn jŭm Păng; jêh ri Păng nti lah ma khân păng.$b$,true),
('bunong-vn','MRK',2,14,null,$b$Dôl Brah Yêsu găn ta nây Păng saơ Y-Lêvi, kon Y-Alphê, păng gŭ tâm ngih riu pi. Jêh ri Păng lah ma Y-Lêvi: “Tĭng hom gâp.” Pô nây, Y-Lêvi dâk jêh ri tĭng ndô̆ Păng.$b$,false),
('bunong-vn','MRK',2,15,null,$b$Dôl Brah Yêsu gŭ sông sa tâm ngih Y-Lêvi, geh âk phung riu pi jêh ri bunuyh tih gŭ sông sa ndrel ma Brah Yêsu, jêh ri nđâp ma phung oh mon Păng. Yor lah tâm phung nây geh lĕ, âk nơm lĕ tă tĭng jêh Brah Yêsu.$b$,true),
('bunong-vn','MRK',2,16,null,$b$Phung kôranh nchih sămƀŭt jêng mpôl Pharisi, saơ Brah Yêsu gŭ sông sa ndrel ma phung riu pi jêh ri phung tih, khân păng lah ma phung oh mon Brah Yêsu: “Mâm ƀư Păng gŭ sông sa jêh ri nhêt ndrel ma phung riu pi jêh ri phung tih mhĭk pô nây?”$b$,false),
('bunong-vn','MRK',2,17,null,$b$Tơ lah Brah Yêsu tăng nau nây, Păng lah ma khân păng: “Mâu di phung soih săk lăng jăn ôh ŭch ma nai dak si, ƀiă lah phung ji kuet; mâu di gâp văch kuăl phung sŏng ôh, ƀiă lah phung tih.”$b$,false),
('bunong-vn','MRK',2,18,null,$b$Phung oh mon Y-Yôhan jêh ri phung Pharisi ver sông sa. Phung khân păng ôp Brah Yêsu: “Mâm ƀư phung oh mon Y-Yôhan jêh ri phung Pharisi ver sông sa, ƀiă lah phung oh mon may mâu ver ôh?”$b$,true),
('bunong-vn','MRK',2,19,null,$b$Brah Yêsu plơ̆ sĭt lah ma khân păng: “Bi phung oh nâu bu klâu mra gŭ ur, dơi lĕ khân păng ver sông sa dôl păng ăt hôm gŭ ndrel ma khân păng? Dôl bu klâu mra gŭ ur hôm gŭ ndrel ma khân păng, khân păng mâu dơi ver ôh.$b$,true),
('bunong-vn','MRK',2,20,null,$b$Ƀiă lah nar mra tât, tơ lah bu sŏk lơi bu klâu gŭ ur tă bơh khân păng, rnôk nây khân păng mra ver sông sa.$b$,false),
('bunong-vn','MRK',2,21,null,$b$Mâu geh du huê bunuyh jĭm bok mhe ndop đah bok ơm ôh. Lah ƀư pô nây bok mhe mra ƀư prek lơi bok ơm, jêh ri ntŭk hêk mra prek huy lơn.$b$,false),
('bunong-vn','MRK',2,22,null,$b$Tâm ban pô nây lĕ, mâu geh ôh bunuyh troch dak kriăk ƀâu mhe tâm nông ntâu ơm; lah ƀư pô nây, dak kriăk ƀâu mra ƀư rmŭk nông ntâu ơm, jêh ri dak kriăk ƀâu nđâp ma nông ntâu roh lĕ. Bu troch dak kriăk ƀâu mhe tâm nông ntâu mhe.”$b$,false),
('bunong-vn','MRK',2,23,null,$b$Geh du nar Saƀat Brah Yêsu găn prot mir ba me. Dôl hăn phung oh mon păng roih sa đeh ba me.$b$,true),
('bunong-vn','MRK',2,24,null,$b$Phung Pharisi lah ma Păng: “Uănh ri, mâm ƀư phung nây ƀư pô nây, bu lĕ buay jêh tâm nar Saƀat?”$b$,false),
('bunong-vn','MRK',2,25,null,$b$Brah Yêsu lah: “Khân may mâp uănh lĕ tâm ndrom sămƀŭt moh Y-Đavit ƀư tơ lah păng ji ngot kăl e, păng jêh ri phung gŭ ndrel ma păng?$b$,true),
('bunong-vn','MRK',2,26,null,$b$Păng lăp tâm ngih Brah Ndu rô̆ Y-Abiathar, kôranh ƀư brah toyh, jêh ri păng sa kapŭng kloh ueh, knŏng phung kôranh ƀư brah vay sa kapŭng nây, jêh ri Y-Đavit ăn nđâp ma bunuyh hăn ndrel ma păng sa đŏng?”$b$,false),
('bunong-vn','MRK',2,27,null,$b$Pô ri, Brah Yêsu ngơi rkêch đŏng ma khân păng lah: “Bu njêng nar Saƀat prăp ma bunuyh, mâu di bunuyh prăp ma nar Saƀat ôh.$b$,false),
('bunong-vn','MRK',2,28,null,$b$Pô nây yơh kon bunuyh jêng kôranh nđâp ma nar Saƀat lĕ.”$b$,false),
('bunong-vn','MRK',3,1,null,$b$Jêh ri Brah Yêsu lăp tâm ngih rƀŭn Yuđa, ta nây geh du huê bunuyh siăr ti.$b$,true),
('bunong-vn','MRK',3,2,null,$b$Khân păng kâp uănh ma Brah Yêsu gĭt lah Păng mra ƀư bah bunuyh aơ tâm nar Saƀat lĕ, gay dơi joi nau phong păng.$b$,false),
('bunong-vn','MRK',3,3,null,$b$Păng lah ma nơm siăr ti nây: “Dâk hom may bơh ntŭk aơ.”$b$,true),
('bunong-vn','MRK',3,4,null,$b$Jêh nây Brah Yêsu ôp ma khân păng: “Tâm nar Saƀat dơi lĕ ƀư kan ueh mâu lah kan mhĭk? Vay lĕ prăp om nau rêh bunuyh mâu lah ƀư nkhĭt bunuyh?” Ƀiă lah khân păng gŭ răk klăk.$b$,false),
('bunong-vn','MRK',3,5,null,$b$Jêh Păng uănh ma phung nây ma nau ji nuih Păng rngot yor phung nây dăng bôk ngăn. Păng lah ma bunuyh siăr ti nây: “Yơr ti may.” Ô băl yơr ro, jêh ri ti păng bah ro,$b$,false),
('bunong-vn','MRK',3,6,null,$b$Phung Pharisi luh jêh ri tâm chră ro đah phung Hêrôdian, jêh ri joi nau dơi ƀư nkhĭt ô băl.$b$,false),
('bunong-vn','MRK',3,7,null,$b$Pô nây yơh Brah Yêsu du ndrel ma phung oh mon Păng hăn rlet dak mƀŭt, jêh ri geh âk bunuyh tă bơh n'gor Galilê tĭng Brah Yêsu, nđâp ma n'gor Yuđa,$b$,true),
('bunong-vn','MRK',3,8,null,$b$jêh ri tă bơh ƀon Yêrusalem, tă bơh n'gor Iđumê, tă bơh kăl tê̆ dak krong Yurdan, jêh ri văr jŭm ƀon Tyr jêh ri ƀon Sidôn. Âk bunuyh tăng lư lĕ nau Păng ƀư, hăn ran ma Păng da dê,$b$,false),
('bunong-vn','MRK',3,9,null,$b$jêh nây Păng ntăm ma phung oh mon, ăn bu prăp du mlâm plŭng jê̆ ma Păng, klach lah phung âk nây khŭm nchâp Păng.$b$,false),
('bunong-vn','MRK',3,10,null,$b$Yor lah Păng hŏ ƀư bah jêh âk bunuyh, pô nây yơh mbu nơm ji kuet hăn dăch, gay ma Păng pah bi.$b$,false),
('bunong-vn','MRK',3,11,null,$b$Tơ lah phung brah mhĭk saơ Brah Yêsu, khân păng chon mon pa năp Păng, jêh ri nter huy: “May jêng Kon Brah Ndu.”$b$,false),
('bunong-vn','MRK',3,12,null,$b$Ƀiă lah Brah Yêsu buay mprân khân păng lơi ăn bu gĭt năl Păng ôh.$b$,false),
('bunong-vn','MRK',3,13,null,$b$Jêh ta nây, Brah Yêsu hao ta klơ yôk, jêh ri păng kuăl mbu nơm păng ŭch, jêh ri khân păng hăn rlet ma Păng.$b$,true),
('bunong-vn','MRK',3,14,null,$b$Jêh ri Păng njêng khân păng jât ma bar nuyh ăn gŭ ndrel ma Păng, jêh ri bu ntơ phung oh mon, jêh ri prơh hăn nti lah nau chroh,$b$,false),
('bunong-vn','MRK',3,15,null,$b$jêh ri ăn ma khân păng nau dơi mprơh brah mhĭk.$b$,false),
('bunong-vn','MRK',3,16,null,$b$Aơ amoh phung jât ma bar nuyh nây: Y-Simôn bu ntơ amoh đŏng Y-Pêtrôs,$b$,false),
('bunong-vn','MRK',3,17,null,$b$Y-Yakơ, kon Y-Sêƀêđê, jêh ri Y-Yôhan, nâu Y-Yakơ, bar hê aơ Păng ntơ Bôanerjơ, nâm bu ntĭt, phung kon nglaih;$b$,false),
('bunong-vn','MRK',3,18,null,$b$jêh ri Y-Andrê, Y-Philip; Y-Ƀartêlômi, Y-Mathiơ, Y-Thômas, Y-Yakơ, kon Y-Alphê, Y-Thadê, Y-Simôn, bunuyh bri Kanaan.$b$,false),
('bunong-vn','MRK',3,19,null,$b$Jêh ri Y-Yuđas Iskariôt, nơm rlăng ma Păng.$b$,false),
('bunong-vn','MRK',3,20,null,$b$Jêh ri Păng lăp tâm ngih geh phung bunuyh âk râk gŭ tâm rƀŭn ta nây, kŏ tât Păng jêh ri phung oh mon Păng mâu geh sông sa.$b$,true),
('bunong-vn','MRK',3,21,null,$b$Phung mpôl băl păng tăng nau nây, khân păng văch gay sŏk leo Brah Yêsu sĭt jêh ri buay ktang ngăn, yor lah khân păng lah: “Păng lĕ roh nau mĭn jêh.”$b$,false),
('bunong-vn','MRK',3,22,null,$b$Jêh nây phung kôranh nchih sămƀŭt tă bơh ƀon Yêrusalem lah tâm ban lĕ: “Păng geh Bêlsêbul gŭ tâm păng, jêh ri păng dơi nsot phung brah mhĭk ma kon hađăch brah mhĭk.”$b$,true),
('bunong-vn','MRK',3,23,null,$b$Păng kuăl phung nây jêh ri păng lah ma nau ngơi hôr. “Mâm ƀư Satan dơi nsot Satan nơm?$b$,false),
('bunong-vn','MRK',3,24,null,$b$Tơ lah du ƀon bri hađăch tâm nkhah lơi êng păng nơm, ƀon bri hađăch nây mâu dơi gŭ jŏ ôh.$b$,false),
('bunong-vn','MRK',3,25,null,$b$Jêh ri tơ lah du rnăk sa tâm rnglah, rnăk sa nây mâu dơi gŭ jŏ ôh.$b$,false),
('bunong-vn','MRK',3,26,null,$b$Pô nây yơh tơ lah Satan tâm rdâng đah păng nơm, nau nây jêng blah lơi săk păng nơm. Păng mâu dơi gŭ jŏ ôh, ƀiă lah lôch săk păng yơh.$b$,false),
('bunong-vn','MRK',3,27,null,$b$Bu mâu dơi lăp ôh tâm ngih du huê bunuyh dăng suan jêh ri ntŭng ndô ndơ păng, knŏng tơ lah chăp lơi păng lor; kơt nây mơ păng dơi ntŭng ndô ndơ păng.$b$,false),
('bunong-vn','MRK',3,28,null,$b$Gâp lah ma khân may n'hêl nanê̆, Brah Ndu dơi yô̆ an lĕ rngôch nau tih bunuyh, nđâp nau ngơi sưr kđôi lĕ,$b$,true),
('bunong-vn','MRK',3,29,null,$b$ƀiă lah mbu nơm sưr đah Brah Huêng Ueh mâu mra geh nau yô̆ an ôh, ƀiă lah păng tih ƀa ƀơ n'ho ro.”$b$,false),
('bunong-vn','MRK',3,30,null,$b$Yor lah khân păng lah: “Păng geh brah mhĭk.”$b$,false),
('bunong-vn','MRK',3,31,null,$b$Mê̆ jêh ri oh păng tât, gŭ kâp pa dih, ăn bu kuăl Păng.$b$,true),
('bunong-vn','MRK',3,32,null,$b$Phung bunuyh ƀon lan âk râk hôm gŭ jŭm Păng, jêh ri geh bunuyh mbơh ma Păng: “Aơ, mê̆ may jêh ri phung oh may gŭ pa dih joi may.”$b$,false),
('bunong-vn','MRK',3,33,null,$b$Păng plơ̆ sĭt lah: “Mbu nơm mê̆ gâp jêh ri oh gâp?”$b$,false),
('bunong-vn','MRK',3,34,null,$b$Păng nchrâng uănh ma phung âk gŭ jŭm Păng ta nây jêh ri lah: “Aơ, mê̆ gâp jêh ri oh gâp!$b$,false),
('bunong-vn','MRK',3,35,null,$b$Yor lah mbu nơm tông bâr ma Brah Ndu, păng nây yơh oh nâu gâp, oh ruh gâp, jêh ri mê̆ gâp.”$b$,false),
('bunong-vn','MRK',4,1,null,$b$Brah Yêsu ntơm nti lah ta kơh dak mƀŭt, jêh ri geh âk ngăn bunuyh gŭ jŭm Păng, yor ri Păng du gŭ tâm plŭng ta dak mƀŭt, lĕ rngôch phung âk ri gŭ klơ kơh.$b$,true),
('bunong-vn','MRK',4,2,null,$b$Brah Yêsu nti lah ma khân păng âk nau hôr jêh ri lah:$b$,false),
('bunong-vn','MRK',4,3,null,$b$“Iăt hom hơi lĕ rngôch khân may! Geh du huê nơm srih grăp hăn srih.$b$,false),
('bunong-vn','MRK',4,4,null,$b$Dôl păng srih, geh grăp ƀa ƀă tŭp rŏ trong jêh ri sĭm chôk lơi.$b$,false),
('bunong-vn','MRK',4,5,null,$b$Ƀa ƀă tŭp tâm ntŭk neh n'hơ klơ klêr, păng chăt gơnh ngăn yor lah mâu jru neh;$b$,false),
('bunong-vn','MRK',4,6,null,$b$ƀiă lah tât kranh nar, tơm păng klêu păng kro yor lah mâu geh jru reh ôh păng khĭt rsăp.$b$,false),
('bunong-vn','MRK',4,7,null,$b$Ƀa ƀă tŭp tâm ntŭk lok; lok chăt prêh lor, tơm ri nu lok in, mâu geh play.$b$,false),
('bunong-vn','MRK',4,8,null,$b$Ƀa ƀă tŭp tâm neh ueh, hon rêh ueh geh play âk, play păng du ryôk geh pe jât grăp, ƀă prao jât grăp, ƀă du rhiăng grăp.”$b$,true),
('bunong-vn','MRK',4,9,null,$b$Brah Yêsu păng ntop lah: “Mbu nơm geh tôr prăp iăt! Ăn khân ay may djôt prăp nau aơ!”$b$,false),
('bunong-vn','MRK',4,10,null,$b$Lah Brah Yêsu gŭ êng păng, phung jât ma bar nuyh jêh ri bunuyh gŭ ndrel Păng, khân păng ôp Brah Yêsu, ăn Păng rblang nau hôr nây.$b$,true),
('bunong-vn','MRK',4,11,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Ma khân may yơh bu ăn jêh nau khlay ndâp ma ƀon bri hađăch Brah Ndu. Ƀiă lah ma phung pa dih, bu ngơi ma khân păng ma nau hôr da dê.$b$,false),
('bunong-vn','MRK',4,12,null,$b$Gay ăn: Khân păng uănh ăt uănh ƀiă lah mâu saơ. Khân păng tăng ăt tăng ƀiă lah mâu gĭt rbăng ôh. Lah mâu, khân păng saơ jêh ri gĭt rbăng klăp lah khân păng rmal nau tih jêh ri geh nau yô̆ an.”$b$,false),
('bunong-vn','MRK',4,13,null,$b$Brah Yêsu lah: “Lĕ rngôch khân may mâu gĭt rbăng bơh nau hôr ri? Mâm ƀư gay ma khân may dơi gĭt rbăng lĕ rngôch nau ngơi hôr aơ?”$b$,true),
('bunong-vn','MRK',4,14,null,$b$“Bunuyh srih grăp nây srih nau ngơi.$b$,true),
('bunong-vn','MRK',4,15,null,$b$Ƀa ƀă bunuyh dơn grăp bu srih rŏ trong nây jêng bunuyh bu srih grăp tâm nuih n'hâm păng. Ƀiă lah jêh bunuyh nây tăng nau ngơi, Satan văch jêh ri sŏk lơi nau ngơi bơh nuih n'hâm păng.$b$,true),
('bunong-vn','MRK',4,16,null,$b$Tâm ban lĕ phung dơn grăp tâm neh n'gơ klơ klêr, jêh mhe tăng nau nti, khân păng dơn ro ma nau maak.$b$,false),
('bunong-vn','MRK',4,17,null,$b$Ƀiă lah păng mâu geh reh tâm păng ôh. Păng mâu gŭ jŏ ôh, jêh ri tơ lah geh nau rêh ni mâu lah nau bu ƀư mhĭk ma păng yor nau ngơi, păng tŭp ro.$b$,false),
('bunong-vn','MRK',4,18,null,$b$Geh bunuyh ƀa ƀă dơn grăp tâm nklang lok. Phung nây tăng jêh nau nti,$b$,true),
('bunong-vn','MRK',4,19,null,$b$ƀiă lah kan neh ntu aơ nau ndrŏng ndơm, jêh ri kơnh drăp ndơ êng êng, ntŭn lơi nau ngơi jêh ri nau ngơi mâu dơi geh play ôh.$b$,false),
('bunong-vn','MRK',4,20,null,$b$Bi ƀa ƀă bunuyh dơn grăp srih tâm neh ueh nây, khân păng yơh tăng nau ngơi jêh ri djôt prăp. Khân păng nây geh play tâm pe jât mâu lah prao jât, mâu lah du rhiăng tâm du găr.”$b$,false),
('bunong-vn','MRK',4,21,null,$b$Brah Yêsu lah đŏng ma khân păng: “Vay lĕ bu sŏk ŭnh kđen nkŭm lơi ma rbâng mâu lah n'gân tâm dâng sưng bêch? Bu vay yông păng ta klơ n'gâng ŭnh.$b$,true),
('bunong-vn','MRK',4,22,null,$b$Yor lah moh ndơ gŭ tâm ndâp mra mpơl, jêh ri moh ndơ bu pôn mra saơ ang.$b$,false),
('bunong-vn','MRK',4,23,null,$b$Mbu nơm geh tôr prăp iăt, iăt hom!”$b$,false),
('bunong-vn','MRK',4,24,null,$b$Brah Yêsu ntơm lah: “Njrăng hom mâm nau khân may tăng. Bu mra veh njing ma khân may tĭng nâm khân may hŏ veh jêh njing ma bu, jêh ri bu mra ntop ăn ma khân may.$b$,true),
('bunong-vn','MRK',4,25,null,$b$Yor lah mbu nơm geh jêh, bu mra ăn đŏng ma păng, ƀiă lah mbu nơm mâu geh, bu mra sŏk lơi đŏng nđâp ma ndơ păng hŏ geh jêh.”$b$,false),
('bunong-vn','MRK',4,26,null,$b$Brah Yêsu ngơi: “Ƀon bri hađăch Brah Ndu nâm bu ntĭt ma du huê srih grăp tâm neh.$b$,true),
('bunong-vn','MRK',4,27,null,$b$Dôl păng lêt bêch mâu lah kah rngăl, nar jêh ri măng, grăp nây hon jêh ri prêh, ƀiă lah bunuyh nây mâu gĭt rbăng ôh nau nây.$b$,false),
('bunong-vn','MRK',4,28,null,$b$Neh nây jêng êng ba, tơm păng lor, jêh ri nkong, geh grăp rhêh tâm nkong nây lĕ.$b$,false),
('bunong-vn','MRK',4,29,null,$b$Tât păng lĕ dŭm jêh, bu hăn rek ma nhuĕ yor lah yan rek lĕ tât jêh.”$b$,false),
('bunong-vn','MRK',4,30,null,$b$Brah Yêsu lah: “Moh nau đah he ntĭt ƀon bri hađăch Brah Ndu? Mâu lah moh đah nau he dơi ngơi hôr gay tâm mpơl păng?$b$,true),
('bunong-vn','MRK',4,31,null,$b$Ƀon bri hađăch Brah Ndu nâm bu ntĭt du găr mutar jê̆ bu tăm tâm neh. Păng jêng jê̆ lơn ma lĕ rngôch grăp tâm neh ntu aơ.$b$,false),
('bunong-vn','MRK',4,32,null,$b$Ƀiă lah tơ lah bu tăm păng, păng hon ro, păng jêng toyh lơn ma lĕ rngôch tơm trao, jêh ri păng geh n'gĭng toyh, pô nây phung sĭm dơi gŭ tâm dâng gui n'hâm păng.”$b$,false),
('bunong-vn','MRK',4,33,null,$b$Brah Yêsu ngơi đŏng geh âk nau ngơi hôr kơt nây, tĭng nâm phung bunuyh nây dơi gĭt vât.$b$,true),
('bunong-vn','MRK',4,34,null,$b$Păng ngơi ma nau ngơi hôr da dê, ƀiă lah dôl păng gŭ êng ndrel ma phung oh mon păng, păng rblang lĕ rngôch ndơ nây ma khân păng.$b$,false),
('bunong-vn','MRK',4,35,null,$b$Mhaơ nây Brah Yêsu lah ma phung oh mon păng: “Hăn hom he găn kơh tê̆ dak.”$b$,true),
('bunong-vn','MRK',4,36,null,$b$Pô nây tơ lah phung ƀon lan lĕ chah rai sĭt jêh, phung oh mon Păng kuăl Brah Yêsu leo ncho tâm plŭng ndrel ma khân păng nơm. Jêh ri hôm geh plŭng êng tĭng hăn ndrel ma Păng.$b$,true),
('bunong-vn','MRK',4,37,null,$b$Geh phŭt vănh ktang ngăn kŏ tât dak rbuh lăp tâm trôm plŭng jêh ri plŭng bơi ngâm.$b$,false),
('bunong-vn','MRK',4,38,null,$b$Ƀiă lah Brah Yêsu nơm hăk bêch pa kơi tâm plŭng nây, sŏk ka n'hơi dâm bôk. Pô nây, khân păng rlay Brah Yêsu, jêh ri lah: “Hơi Kôranh nơm nti, may mâu rvê ma he bơi khĭt jêh?”$b$,false),
('bunong-vn','MRK',4,39,null,$b$Pô nây Brah Yêsu kah rngăl, jêh ri Păng buay phŭt vănh, jêh ri lah ma dak rbuh nây: “Rngân hom jêh ri đăp mpăn.” Phŭt rngân njop, jêh ri khân păng geh nau đăp mpăn.$b$,false),
('bunong-vn','MRK',4,40,null,$b$Brah Yêsu ôp ma phung oh mon Păng: “Moh nau khân may klach? Khân may mâu geh nau chroh ƀơh?”$b$,true),
('bunong-vn','MRK',4,41,null,$b$Jêh ri phung khân păng klach ngăn, lah ndrăng khân păng: “Pô nây, mbu moh bunuyh aơ? Nđâp ma phŭt jêh ri dak tông bâr ma păng da dê!”$b$,false),
('bunong-vn','MRK',5,1,null,$b$Khân păng tât kơh tê̆ dak nglao tâm ƀon Gađara.$b$,true),
('bunong-vn','MRK',5,2,null,$b$Brah Yêsu mhe tă luh bơh plŭng, ƀât lât geh du huê bunuyh brah mhĭk lơh luh tă bơh môch jêh ri hăn ta năp Păng.$b$,false),
('bunong-vn','MRK',5,3,null,$b$Bunuyh nây vay gŭ tâm ntŭk môch jêh ri bu mâu dơi kât păng ôh, kât ma rse rvăk mâu dơi lĕ.$b$,false),
('bunong-vn','MRK',5,4,null,$b$Geh âk tơ̆ jêh bu nkông păng ma nkông loih jêh ri rse rvăk, ƀiă lah lĕ rngôch rplay rse rvăk klah da dê, jêh ri nkông loih nây rai lĕ đŏng. Mâu hôm geh nơm ktang dơi đăp păng ôh.$b$,false),
('bunong-vn','MRK',5,5,null,$b$Păng vay gŭ ƀa ƀơ nar nâm măng tâm mpông môch, tâm yôk, jêh ri păng vay nter ktang, mbang ji rnglay săk nơm đah lŭ mplanh.$b$,false),
('bunong-vn','MRK',5,6,null,$b$Jêh păng saơ Brah Yêsu ngai đê̆ ta nây, păng nchuăt ran ro jêh ri kŭnh mbah ma Păng,$b$,false),
('bunong-vn','MRK',5,7,null,$b$jêh ri păng nter huy: “Moh nau gâp geh đah may, Ơ Brah Yêsu Kon Brah Ndu Nơm ta klơ lơn? Tâm amoh Brah Ndu gâp vơh vơl ma may, lơi ƀư mhĭk ma gâp ôh.”$b$,false),
('bunong-vn','MRK',5,8,null,$b$Yor lah Brah Yêsu hŏ lah jêh ma păng ndơh: “Brah mhĭk, luh du hom may tă bơh bunuyh aơ.”$b$,false),
('bunong-vn','MRK',5,9,null,$b$Brah Yêsu ôp păng: “Mbu moh săk may?” Păng lah: “Amoh gâp phung âk, yor lah hên jêng phung âk.”$b$,true),
('bunong-vn','MRK',5,10,null,$b$Jêh ri păng dăn ma Brah Yêsu lơi nsot khân păng tă bơh n'gor nây ôh.$b$,false),
('bunong-vn','MRK',5,11,null,$b$Ta njâng yôk nây geh phung sŭr âk râk gŭ sa gơ̆ ta nây.$b$,true),
('bunong-vn','MRK',5,12,null,$b$Pô nây yơh, phung brah mhĭk dăn ma Brah Yêsu: “Ăn phung hên hăn ma phung sŭr nây, jêh ri ăn hên lăp tâm khân păng.”$b$,false),
('bunong-vn','MRK',5,13,null,$b$Brah Yêsu ăn khân păng hăn, phung brah mhĭk nây luh jêh ri lăp tâm phung sŭr. Phung sŭr nây geh klăp lah bar rbăn mlâm. Khân păng nchuăt du tă bơh yôk, nklăch săk tâm dak mƀŭt, jêh ri lĕ rngôch phung sŭr nây khĭt rmok tâm dak.$b$,false),
('bunong-vn','MRK',5,14,null,$b$Phung mât sŭr nchuăt du jêh ri mbơh nau mhe mhan nây tâm lam ƀon toyh ƀon jê̆; phung ƀon lan hăn uănh moh nau tât nây.$b$,true),
('bunong-vn','MRK',5,15,null,$b$Jêh phung bunuyh nây tât ma Brah Yêsu, khân păng saơ du huê bunuyh brah mhĭk lơh ơm bơh kăl e ô băl gŭ đăp mpăn, nsoh kho ao, jêh ri nau mĭn păng ueh đŏng. Lĕ rngôch bunuyh nây klach.$b$,false),
('bunong-vn','MRK',5,16,null,$b$Mbu nơm saơ jêh nau nây nkoch bri ma phung bunuyh âk ma nau tât ma bunuyh brah mhĭk lơh nây, nđâp ma nau tât ma phung sŭr.$b$,false),
('bunong-vn','MRK',5,17,null,$b$Jêh ri phung bunuyh nây ăn Brah Yêsu luh du tă bơh n'gor bri khân păng.$b$,false),
('bunong-vn','MRK',5,18,null,$b$Dôl Brah Yêsu ntơm ncho plŭng du huê bunuyh brah mhĭk lơh nây dăn hăn ndrel ma Păng.$b$,true),
('bunong-vn','MRK',5,19,null,$b$Ƀiă lah Brah Yêsu mâu rom ôh. Brah Yêsu lah ma păng: “Sĭt hom ma ndŭl mpôl may jêh ri mbơh ma khân păng ăp ntil ndơ Kôranh Brah hŏ ƀư jêh ma may, jêh ri nau Păng yô̆ an jêh ma may.”$b$,false),
('bunong-vn','MRK',5,20,null,$b$Bunuyh nây sĭt, jêh ri mbơh tâm n'gor Đêkapôlis ăp ntil nau Brah Yêsu hŏ ƀư ăn jêh ma păng, jêh ri lĕ rngôch bunuyh gŭ iăt hih rhâl.$b$,false),
('bunong-vn','MRK',5,21,null,$b$Brah Yêsu ncho plŭng hăn găn kơh tê̆. Ta nây geh âk bunuyh tâm rƀŭn jŭm Păng. Păng gŭ ta kơh dak mƀŭt nây.$b$,true),
('bunong-vn','MRK',5,22,null,$b$Jêh ri geh du huê kôranh ngih tâm rƀŭn Yuđa, amoh păng Y-Jairus, văch, tơ lah păng saơ Brah Yêsu, păng kuăn ta jâng Brah Yêsu ro.$b$,false),
('bunong-vn','MRK',5,23,null,$b$Jêh ri păng dăn ma Brah Yêsu pô aơ: “Kon bu ur gâp ji bơi khĭt. Gâp dăn may hăn jêh ri bi ăn ti may ta săk jăn păng ăn păng bah jêh ri rêh.”$b$,false),
('bunong-vn','MRK',5,24,null,$b$Brah Yêsu dâk hăn ndrel ma păng. Jêh ri geh âk râk bunuyh tĭng mpet trong Păng.$b$,false),
('bunong-vn','MRK',5,25,null,$b$Ta nây geh du huê bu ur ji rih hŏ jŏ jêh jât ma bar năm.$b$,true),
('bunong-vn','MRK',5,26,null,$b$Păng săm tă bơh âk nai dak si. Păng dŏng roh âk jêh ndô ndơ păng, gay ma bah nau ji, ƀiă lah lơ hâu glăm lơn.$b$,false),
('bunong-vn','MRK',5,27,null,$b$Păng tăng lư bu nkoch bri ma Brah Yêsu. Păng văch ndrel ma phung âk tĭng pa kơi Brah Yêsu, jêh ri păng pah ta ao Brah Yêsu.$b$,false),
('bunong-vn','MRK',5,28,null,$b$Păng lah: “Tơ lah gâp dơi geh pah knŏng ta ao Păng gâp mra bah yơh.”$b$,false),
('bunong-vn','MRK',5,29,null,$b$Ƀât lât ta nây mham păng suăt ro, jêh ri păng gĭt tâm rnglay săk păng nau ji păng hŏ bah jêh.$b$,false),
('bunong-vn','MRK',5,30,null,$b$Jêh ri ƀât lât ta nây Brah Yêsu gĭt ma nau brah ƀư bah luh jêh tă bơh Păng, pô nây yơh păng n'gơr ta phung âk nây, jêh ri ôp: “Mbu moh pah ao gâp?”$b$,false),
('bunong-vn','MRK',5,31,null,$b$Phung oh mon Păng lah ma Păng: “May saơ bơh phung âk aơ mpet may, jêh ri may ôp, mbu moh pah gâp?”$b$,false),
('bunong-vn','MRK',5,32,null,$b$Ƀiă lah Brah Yêsu joi uănh jŭm păng gay ma gĭt năl mbu nơm ƀư pô nây.$b$,false),
('bunong-vn','MRK',5,33,null,$b$Bu ur nây klach nsâr săk jăn, yor lah ô băl gĭt mâm nau tât tâm rnglay săk păng. Pô nây yơh păng văch, kuăn ta jâng Brah Yêsu, jêh ri nkoch bri ma Păng lĕ nau tât khlay ngăn.$b$,false),
('bunong-vn','MRK',5,34,null,$b$Brah Yêsu lah ma păng: “Hơi kon gâp ơi, nau chroh ay yơh ƀư bah ay jêh. Hăn hom đăp mpăn, jêh ri bah hom ay.”$b$,false),
('bunong-vn','MRK',5,35,null,$b$Dôl Brah Yêsu gŭ ngơi, geh bar pe nuyh văch tă bơh jay jêh ri lah ma Y-Jairus, kôranh ngih tâm rƀŭn Yuđa nây: “Kon bu ur may khĭt jêh. Moh nau dăn đŏng ma Kôranh nơm nti?”$b$,true),
('bunong-vn','MRK',5,36,null,$b$Ƀiă lah Brah Yêsu mâu dơn ôh nau khân păng lah pô nây, jêh ri Păng lah ma kôranh ngih tâm rƀŭn Yuđa nây: “Lơi klach ôh, knŏng may chroh, dŭm rĭ dơm.”$b$,false),
('bunong-vn','MRK',5,37,null,$b$Jêh ri Păng mâu ăn bunuyh hăn ndrel ma Păng, knŏng Y-Pêtrôs, phung oh nâu Y-Yakơ jêh ri Y-Yôhan.$b$,true),
('bunong-vn','MRK',5,38,null,$b$Khân păng tât ta ngih kôranh ngih tâm rƀŭn Yuđa nây. Brah Yêsu saơ âk bunuyh ta nây uh ah tah târ. Ƀa ƀă gŭ nhĭm nhhiăng, jêh ri nter nđor.$b$,false),
('bunong-vn','MRK',5,39,null,$b$Brah Yêsu lăp tâm ngih nây Păng lah: “Mâm ƀư khân may ƀư uh ah tah târ jêh ri nhĭm nhhiăng? Bu ur jê̆ aơ bêch, mâu di Păng khĭt ôh.”$b$,true),
('bunong-vn','MRK',5,40,null,$b$Jêh ri geh bunuyh ta nây mưch mach ma Brah Yêsu. Brah Yêsu ăn lĕ rngôch bunuyh du luh tă bơh jrô nây jêh ri Păng kuăl sŏk knŏng mê̆ mbơ̆ bu ur jê̆ nây ndrel ma phung oh mon Păng, jêh ri Păng lăp tâm jrô bu ur jê̆ gŭ bêch.$b$,false),
('bunong-vn','MRK',5,41,null,$b$Brah Yêsu kuăn ta ti păng jêh ri lah: “Talatha kumi” nâm bu ntĭt bu ur jê̆ ơi, dâk hom ay.$b$,false),
('bunong-vn','MRK',5,42,null,$b$Ƀât lât ta nây, bu ur jê̆ nây dâk jêh ri hăn, yor lah păng hŏ geh jêh jât ma bar năm, bunuyh gŭ ta nây hih rhâl ngăn.$b$,false),
('bunong-vn','MRK',5,43,null,$b$Ƀiă lah Brah Yêsu ntăm ma khân păng nanê̆, lơi ăn bu gĭt nau aơ ôh, jêh ri păng lah ma bu ăn bu ur jê̆ nây sông sa hom.$b$,false),
('bunong-vn','MRK',6,1,null,$b$Brah Yêsu luh tă bơh nây jêh ri hăn rlet bri Păng nơm ndrel ma phung oh mon Păng.$b$,true),
('bunong-vn','MRK',6,2,null,$b$Tơ lah tât nar Saƀat Păng ntơm nti lah tâm ngih tâm rƀŭn Yuđa. Âk bunuyh gŭ iăt Păng hih rhâl jêh ri ôp: “Mbah tă luh Păng geh lĕ rngôch nau aơ? Mbu nơm ăn nau blau mĭn nây ma Păng? Jêh ri moh nau dĭng khlay ir ar nau Păng ƀư đah ti Păng?$b$,false),
('bunong-vn','MRK',6,3,null,$b$Di lĕ nơm nây jêng bunuyh trah meh kon H'Mari, nâu phung Y-Yakơ, Y-Yôsê, Y-Yut, jêh ri Y-Simôn? Bi phung oh bu ur păng gŭ ta aơ ndrel he ƀơh?” Pô nây yơh Păng jêng nau ƀư vĭ khân păng.$b$,true),
('bunong-vn','MRK',6,4,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Bu yơk ma phung kôranh nơm mbơh lor, ƀiă lah tâm ƀon lan Păng nơm ndrel đah mê̆ Mbơ̆ Păng tâm ngih Păng nơm, bu mâu ŭch yơk ôh.”$b$,false),
('bunong-vn','MRK',6,5,null,$b$Jêh ta nây Brah Yêsu mâu dơi ƀư nau mbên khlay ôh, knŏng Păng dra ăn ti Păng ta bar, pe nuyh ji jêh ri ƀư bah khân păng.$b$,false),
('bunong-vn','MRK',6,6,null,$b$Jêh ri Brah Yêsu gŭ srŭng dơm yor lah bunuyh ta nây mâu geh nau chroh. Pô nây yơh Brah Yêsu hăn tâm ƀon dăch êp nây jêh ri nti lah.$b$,false),
('bunong-vn','MRK',6,7,null,$b$Jêh ri Brah Yêsu kuăl jât ma bar nuyh nây văch ta Păng, jêh ri prơh njuăl khân păng hăn bar hê bar hê. Păng ăn nau dơi ma khân păng dơi nsot brah mhĭk.$b$,true),
('bunong-vn','MRK',6,8,null,$b$Păng ntăm ma khân păng lơi djôt ndrel ndô ndơ ôh dôl hăn nsong, mâu lah kapŭng, mâu lah dŭng cheng, mâu lah prăk rêl tâm rse bŭt, knŏng mâng jra rĭ dơm;$b$,false),
('bunong-vn','MRK',6,9,null,$b$knŏng nsoh ntâu jot, lơi ta nsoh ao bar tăp ôh.$b$,false),
('bunong-vn','MRK',6,10,null,$b$Brah Yêsu lah ma phung oh mon păng: “Mbu nơm ngih khân may hao, khân may mra gŭ ta nây tât khân may luh tă bơh ƀon nây.$b$,false),
('bunong-vn','MRK',6,11,null,$b$Ta ntŭk bu mâu ŭch rom khân may, mâu lĕ ŭch iăt nau khân may, jêh khân may luh tă bơh ntŭk nây, khân may rtuh lơi ndruyh neh tă bơh jâng khân may, gay geh trong mbơh ma khân păng.”$b$,true),
('bunong-vn','MRK',6,12,null,$b$Pô nây phung oh mon Păng dâk hăn, nti lah ma phung bunuyh ăn khân păng rmal nau tih khân păng nơm.$b$,true),
('bunong-vn','MRK',6,13,null,$b$Khân păng nsot âk brah mhĭk, khân păng mhĭng dak ngi ma âk bunuyh ji, jêh ri ƀư bah lĕ rngôch khân păng.$b$,false),
('bunong-vn','MRK',6,14,null,$b$Hađăch Hêrôt lư n'găr nau bu nkoch bri ma Brah Yêsu, jêh ri păng lah: “Y-Yôhan, nơm ƀư ƀaptem, hŏ dâk rêh jêh bơh nau khĭt; pô nây yơh păng ƀư nau brah khlay.”$b$,true),
('bunong-vn','MRK',6,15,null,$b$Bunuyh ƀa ƀă lah: “Păng jêng Y-Êli”, ƀa ƀă lah: “Păng jêng kôranh nơm mbơh lor, nâm bu du huê toyh tâm phung kôranh nơm mbơh lor nây.”$b$,true),
('bunong-vn','MRK',6,16,null,$b$Ƀiă lah jêh Hêrôt tăng nau nây, păng lah: “Y-Yôhan aơ, lĕ gâp ăn bu koh trô ko jêh. Păng yơh dâk rêh tay.”$b$,false),
('bunong-vn','MRK',6,17,null,$b$Yor lah Hêrôt yơh nơm đă bu chăp Y-Yôhan jêh ri krŭng kât păng tâm ndrung păng đah rse rvăk, yor lah H'Hêrôdias ŭch pô nây H'Hêrôdias nây jêng ur oh Hêrôt, amoh păng Y-Philip. Yor lah Hêrôt gŭ jêh bu ur nây.$b$,true),
('bunong-vn','MRK',6,18,null,$b$Y-Yôhan lah lor jêh ma Hêrôt: “May, mâu vay ôh gŭ ur oh may.”$b$,false),
('bunong-vn','MRK',6,19,null,$b$Pô nây yơh H'Hêrôdias ji nuih mro ma Y-Yôhan jêh ri ŭch ƀư nkhĭt ô băl, ƀiă lah păng mâu dơi ôh.$b$,false),
('bunong-vn','MRK',6,20,null,$b$Yor lah Hêrôt klach ma Y-Yôhan. Păng gĭt jêh păng jêng bunuyh sŏng jêh ri bunuyh ueh ngăn. Pô nây yơh păng sâm king an ô băl. Jêh ri Hêrôt tăng păng nti lah, păng mâu gĭt ôh moh nau păng ƀư, ƀiă lah păng ŭch iăt ma nau maak.$b$,false),
('bunong-vn','MRK',6,21,null,$b$Kah gĭt nar bu deh ma păng, Hêrôt nkra nau nhêt sa toyh ngăn ăn phung kôranh toyh tâm bri hađăch păng. Păng jă phung kôranh ta han, jêh ri phung bunuyh kôranh toyh tâm n'gor Galilê.$b$,true),
('bunong-vn','MRK',6,22,null,$b$Kon bu ur H'Hêrôdias lăp tâm jrô nây jêh ri păng ntlơ̆ ntlơn ƀư maak ngăn ma hađăch Hêrôt, nđâp ma phung gŭ ndrel păng ta nây. Hađăch lah ma bu druh nây: “Dăn hom moh ndơ ay ŭch jêh ri gâp mra ăn ma ay.”$b$,false),
('bunong-vn','MRK',6,23,null,$b$Păng plơ̆ sĭt lah nanê̆: “Moh ndơ ay dăn ma gâp, gâp mra ăn ma ay, kŏ tât n'gul ƀon bri hađăch gâp kđôi lĕ gâp ăn đŏng.”$b$,false),
('bunong-vn','MRK',6,24,null,$b$Bu druh nây luh ro jêh ri ôp mê̆ păng: “Moh ndơ gâp mra dăn ma hađăch?” Mê̆ păng plơ̆ lah: “Ay dăn ma păng bôk Y-Yôhan nơm ƀư ƀaptem nây.”$b$,false),
('bunong-vn','MRK',6,25,null,$b$Bu druh nây lăp gơnh tâm jrô hađăch nây, jêh ri păng dăn: “Gâp ŭch may ăn aƀaơ ro bôk Y-Yôhan, nơm ƀư ƀaptem nây n'gân tâm ngan grưng.”$b$,true),
('bunong-vn','MRK',6,26,null,$b$Hađăch rngot, ƀiă lah yor nau păng ngơi nanê̆ lor jêh, jêh ri yor phung bunuyh gŭ sông sa nhêt ndrel păng ta nây. Păng mâu dơi dun ôh nau păng ton đah bu druh nây.$b$,false),
('bunong-vn','MRK',6,27,null,$b$Hađăch prơh hăn du huê ta han chiă uănh, nchâp păng sŏk leo bôk Y-Yôhan.$b$,false),
('bunong-vn','MRK',6,28,null,$b$Tahan nây hăn koh trô ko Y-Yôhan tâm ndrung ro, jêh ri păng sŏk leo bôk ô băl n'gân tâm ngan grưng, ăn ma bu ur druh nây. Jêh ri bu druh nây ăn ma mê̆ păng.$b$,false),
('bunong-vn','MRK',6,29,null,$b$Phung oh mon Y-Yôhan lư jêh nau nây, khân păng hăn sŏk rnglay săk ô băl njŭn leo tâp tâm môch.$b$,false),
('bunong-vn','MRK',6,30,null,$b$Phung kôranh oh mon nây sĭt jêh ri tâm rƀŭn jŭm Brah Yêsu. Khân păng nkoch bri lĕ rngôch kan khân păng pah jêh ri lĕ rngôch nau khân păng nti.$b$,true),
('bunong-vn','MRK',6,31,null,$b$Brah Yêsu lah ma khân păng: “Hăn hom he lĕ rngôch ta ntŭk nsoih, jêh ri rlu ƀât.” Ƀiă lah geh âk bunuyh nsong sĭt hăn, kŏ tât khân păng mâu ru sông sa ôh.$b$,false),
('bunong-vn','MRK',6,32,null,$b$Pô nây, Păng jêh ri phung oh mon jŭr bơh plŭng ŭch hăn tâm ntŭk bri lach êng khân păng.$b$,false),
('bunong-vn','MRK',6,33,null,$b$Âk bunuyh saơ khân păng dâk hăn, jêh ri bu gĭt năl khân păng; pô nây, âk phung bunuyh ƀon lan nây hăn jâng ngăch ngăn, jêh ri khân păng tât lor lơn ma ntŭk nây.$b$,true),
('bunong-vn','MRK',6,34,null,$b$Tơ lah Brah Yêsu tă luh bơh plŭng, Păng saơ bunuyh âk ngăn ngên, jêh ri nuih n'hâm Păng bêng ma nau yô̆ yach ma khân păng, yor lah khân păng nâm bu phung biăp mâu geh rmăk. Brah Yêsu ntơm dâk nti lah ma khân păng.$b$,true),
('bunong-vn','MRK',6,35,null,$b$Dăch kêng mhaơ jêh, pô nây phung oh mon lah ma Brah Yêsu: “Ntŭk aơ jêng bri lach, jêh ri trôk lĕ măng jêh.$b$,true),
('bunong-vn','MRK',6,36,null,$b$May prơh hăn phung âk aơ hăn ma ƀon lan êp dăch kêng aơ, ăn khân păng rvăt mpa sông sa.”$b$,false),
('bunong-vn','MRK',6,37,null,$b$Brah Yêsu plơ̆ lah: “Dâk khân may nơm, ăn mpa ma khân păng sông sa.” Ƀiă lah khân păng lah ma Brah Yêsu: “Mâm ƀư hên ƀơh, mra hăn rvăt kapŭng tâm bar rhiăng prăk jêh ri ăn khân păng sa?”$b$,true),
('bunong-vn','MRK',6,38,null,$b$Brah Yêsu ôp khân păng: “Ndah âk khân may geh kapŭng? Hăn uănh.” Khân păng hăn uănh jêh ri plơ̆ lah: “Prăm mlâm, jêh ri bar mlâm ka.”$b$,false),
('bunong-vn','MRK',6,39,null,$b$Pô nây, Brah Yêsu ntăm ma khân păng ăn lĕ rngôch nây gŭ rnhuel ta gơ̆ nse nây.$b$,false),
('bunong-vn','MRK',6,40,null,$b$Jêh ri khân păng gŭ dăp mbor, du rhiăng nuyh du mbor; mâu lah prăm jât nuyh du mbor.$b$,false),
('bunong-vn','MRK',6,41,null,$b$Brah Yêsu sŏk prăm mpơng kapŭng, bar mlâm ka, jêh ri n'gơr măt ta klơ, mbơh sơm nau kah gĭt tôr. Păng pêch kapŭng jêh ri nta ăn ma phung oh mon tâm pă ma phung âk. Bar mlâm ka păng tâm pă đŏng ma lĕ rngôch phung khân păng.$b$,false),
('bunong-vn','MRK',6,42,null,$b$Lĕ rngôch bunuyh nây sa hơm da dê.$b$,false),
('bunong-vn','MRK',6,43,null,$b$Jêh ri bu dônh jât ma bar bĭ bêng kapŭng rmeh bu sa nđâp ma ka ndrel nây.$b$,false),
('bunong-vn','MRK',6,44,null,$b$Lĕ rngôch phung bunuyh sa kapŭng nây klăp lah tâm prăm rbăn nuyh bu klâu.$b$,false),
('bunong-vn','MRK',6,45,null,$b$Dôl Brah Yêsu ăn phung ƀon lan sĭt, Păng đă phung oh mon Păng ncho plŭng, rgăn lor pa năp păng hăn rlet kơh tê̆ dak tât ta ƀon Ƀêtsaiđa.$b$,true),
('bunong-vn','MRK',6,46,null,$b$Jêh păng mƀơk phung ƀon lan sĭt, Păng hăn hao ta klơ yôk gay mbơh sơm.$b$,false),
('bunong-vn','MRK',6,47,null,$b$Trôk ntơm ngo jêh, plŭng nây hôm tâm nklang dak mƀŭt, ƀiă lah Brah Yêsu hôm gŭ ta kơh êng Păng.$b$,false),
('bunong-vn','MRK',6,48,null,$b$Brah Yêsu saơ phung oh mon Păng vah plŭng dŭt hŏt ngăn, yor lah drơ sial, sial trâm khân păng. Tât puăn tong iăr ndrau kêng ôi.$b$,false),
('bunong-vn','MRK',6,49,null,$b$Brah Yêsu hăn rlet ma khân păng, chuat hăn ta klơ mpiăt dak mƀŭt Galilê, jêh ri khân păng ntôn lah chiak nhhu, yor ri yơh khân păng nter. Lĕ rngôch khân păng saơ Brah Yêsu jêh ri phit klach ngăn.$b$,false),
('bunong-vn','MRK',6,50,null,$b$Brah Yêsu lah ro ma khân păng: “Gŭ đăp mpăn hom! Gâp yơh aơ! Lơi klach ôh!”$b$,false),
('bunong-vn','MRK',6,51,null,$b$Jêh ri Brah Yêsu hăn hao rlet khân păng ncho tâm plŭng, jêh nây phŭt n'ho rngân yơh. Lĕ khân păng hih rhâl ngăn yơh;$b$,false),
('bunong-vn','MRK',6,52,null,$b$yor lah khân păng mâu gĭt vât ôh nau mbên khlay ngăn ngên Brah Yêsu hŏ ƀư lir jêh kapŭng, yor lah nuih n'hâm khân păng jêng dăng ngăn.$b$,false),
('bunong-vn','MRK',6,53,null,$b$Tơ lah Brah Yêsu jêh ri phung oh mon lĕ găn jêh kơh tê̆ dak mƀŭt, tât ta n'gor Gênêsaret, jêh ri veh njưh plŭng kêng meng kơh.$b$,true),
('bunong-vn','MRK',6,54,null,$b$Dôl khân păng du luh tă bơh plŭng, geh phung bunuyh ƀon lan gĭt năl, Păng ro Brah Yêsu.$b$,false),
('bunong-vn','MRK',6,55,null,$b$Khân păng hăn bra lam nkual nây, jêh ri ta ntŭk bu tăng lư păng njưh, ta nây ro yơh bu tung njŭn phung ji kuet; jêh ri bu tung ma rpê̆, gay ăn Brah Yêsu ƀư bah.$b$,false),
('bunong-vn','MRK',6,56,null,$b$Ăp ntŭk Brah Yêsu tât hăn lăp, tâm ƀon toyh, mâu lah ƀon jê̆, mâu lah tâm mir ba, bu njŭn leo phung ji ta ntŭk nglŏng ƀon, jêh ri khân păng dăn ma Brah Yêsu, gay ăn khân păng pah bi knŏng ta ntôr ao păng. Jêh ri lĕ rngôch mbu nơm pah ta ao Brah Yêsu, păng nây bah ro.$b$,false),
('bunong-vn','MRK',7,1,null,$b$Phung Pharisi, jêh ri phung kôranh nchih sămƀŭt ƀa ƀă tă bơh ƀon Yêrusalem, hăn tâm rƀŭn ndrel ma Brah Yêsu.$b$,true),
('bunong-vn','MRK',7,2,null,$b$Phung khân păng saơ jêh oh mon Brah Yêsu gŭ sông sa ma ti ƀơ̆ , nâm bu ntĭt, mâu rao ti.$b$,false),
('bunong-vn','MRK',7,3,null,$b$(Pô ri, phung Pharisi jêh ri phung Yuđa, mâu sông ôh tơ lah mâu rao ti ăn kloh lor, tĭng nâm nau vay bu bŭnh bu ranh ơm.$b$,false),
('bunong-vn','MRK',7,4,null,$b$Jêh ri tơ lah khân păng sĭt tă bơh ngih tăch drăp; khân păng hăn ŭm lơi, ê lor khân păng sông sa. Phung nây hôm geh âk ntil nau vay êng êng, khân păng tĭng ndô̆, nâm bu ntĭt: Nau rao ngan, jêh ri glah bu mon đah uk mâu lah ma kông).$b$,false),
('bunong-vn','MRK',7,5,null,$b$Phung Pharisi jêh ri phung kôranh nchih sămƀŭt ôp ma păng: “Mâm ƀư phung oh mon may mâu tĭng nau vay phung bu bŭnh bu ranh ơm ôh, ƀiă lah sông sa nđâp ma ti ƀơ̆ .”$b$,true),
('bunong-vn','MRK',7,6,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Di jêh Y-Êsai mbơh lor jêh ma nau rêh khân may hơi phung n'hi săk, tĭng nâm bu nchih jêh pô aơ: ‘Phung ƀon lan aơ yơk ma gâp ma trôm mbung khân păng, ƀiă lah nuih n'hâm khân păng gŭ ngai đah gâp. b$b$,false),
('bunong-vn','MRK',7,7,null,$b$Mâu khlay ôh nau khân păng yơk mbah ma gâp, yor lah khân păng nti lah tĭng nâm lĕ nau vay bunuyh; njêng nau vay nây jêng nau ngăn.’$b$,false),
('bunong-vn','MRK',7,8,null,$b$Khân may cha lơi jêh nau Brah Ndu ntăm, ƀiă lah djôt prăp răp jăp nau vay bunuyh.”$b$,false),
('bunong-vn','MRK',7,9,null,$b$Jêh nây Brah Yêsu lah ma khân păng: “Khân may jut lơi jêh nau vay Brah Ndu, gay tĭng kơt nau vay phung bu bŭnh bu ranh ơm khân may nơm.$b$,true),
('bunong-vn','MRK',7,10,null,$b$Yor lah Y-Môis lah: ‘Yơk hom ma mê̆ mbơ̆ may?’ Jêh ri, ‘Mbu nơm rak rtăp ma mbơ̆ mâu lah mê̆ păng nơm, mra tâm rmal tât khĭt.’$b$,false),
('bunong-vn','MRK',7,11,null,$b$Ƀiă lah khân may lah: ‘Tơ lah du huê bunuyh lah ma mbơ̆ mâu lah ma mê̆ păng. Lĕ ntil ndơ gâp mra dơi kơl ma mê̆ mbơ̆ , ri mơ jêng Kôrban? Nâm bu ntĭt nhhơr jêh ma Brah Ndu.’$b$,false),
('bunong-vn','MRK',7,12,null,$b$Pô nây khân may mâu hôm ŭch ăn ô băl kơl ma mê̆ mbơ̆ ô băl ôh.$b$,false),
('bunong-vn','MRK',7,13,null,$b$Kơt nây đŏng khân may jut lơi nau Brah Ndu ngơi jêng dơm dam lơn đê̆ khlay nau vay khân may njêng. Jêh ri geh âk ntil nau êng đŏng khân may njêng tâm ban kơt nây.”$b$,false),
('bunong-vn','MRK',7,14,null,$b$Jêh ta nây, Brah Yêsu kuăl đŏng phung bunuyh ƀon lan, jêh ri lah: “Ăn ăp nơm tâm phung khân may iăt hom jêh ri gĭt vât.$b$,true),
('bunong-vn','MRK',7,15,null,$b$Mâu geh ôh du ntil ndơ tă pa dih bunuyh lăp tâm săk jăn jêh ri dơi ƀư ƀơ̆ păng; ƀiă lah moh ndơ luh tă bơh bunuyh, ndơ nây yơh ƀư ƀơ̆ păng.$b$,true),
('bunong-vn','MRK',7,16,null,$b$Mbu nơm geh tôr iăt, rkêng tôr iăt hom.”$b$,false),
('bunong-vn','MRK',7,17,null,$b$Tơ lah Păng lăp jêh tâm ngih, lĕ ngai jêh đah phung ƀon lan; phung oh mon ôp Păng tâm nau ngơi hôr nây.$b$,false),
('bunong-vn','MRK',7,18,null,$b$Brah Yêsu lah ma khân păng: “Nđâp ma khân may tâm ban lĕ ê hŏ gĭt vât đŏng ƀơh? Khân may mâu gĭt rbăng ƀơh ndơ tă bơh pa dih aơ lăp tâm bunuyh mâu dơi ƀư ƀơ̆ păng ôh.$b$,false),
('bunong-vn','MRK',7,19,null,$b$Yor lah ndơ nây lăp, mâu di tâm nuih n'hâm păng ôh, ƀiă lah tâm trôm ndŭl, jêh ri n'ho luh du pa dih?” (Pô nây yơh Brah Yêsu dơi ƀư ma lĕ ntil ndơ sa dơi jêng kloh).$b$,false),
('bunong-vn','MRK',7,20,null,$b$Brah Yêsu lah: “Moh ndơ luh tă bơh bunuyh, ndơ nây yơh ƀư ƀơ̆ păng.$b$,false),
('bunong-vn','MRK',7,21,null,$b$Yor lah tă bơh tâm trôm, bơh nuih n'hâm bunuyh, du luh nau mĭn mhĭk, nau văng tĭr, nau ntŭng, nau ƀư khĭt bunuyh, nau ka n'hong,$b$,true),
('bunong-vn','MRK',7,22,null,$b$nau kơnh ma drăp ndơ, nau djơh, nau nchơt, nau sưr jêh ri nau brŭt ndrăng.$b$,false),
('bunong-vn','MRK',7,23,null,$b$Lĕ rngôch nau mhĭk nây luh tă bơh tâm trôm, jêh ri nau nây ƀư ƀơ̆ bunuyh.”$b$,true),
('bunong-vn','MRK',7,24,null,$b$Pô nây, Păng luh tă bơh nây dâk hăn rlet ma nkual ƀon Tir jêh ri ƀon Sidôn. Păng lăp tâm du mbŏng ngih, mâu ăn bu dơi gĭt ôh, ƀiă lah Păng mâu dơi gŭ ndâp ôh.$b$,true),
('bunong-vn','MRK',7,25,null,$b$Ƀât lât du huê bu ur, geh kon bu ur jê̆ păng brah mhĭk lơh, tăng lư bu mbơh geh Brah Yêsu, jêh ri păng hăn păn ta jâng Brah Yêsu.$b$,false),
('bunong-vn','MRK',7,26,null,$b$Bu ur nây jêng du huê Grek bơh n'gor Phênisi bri Siri; jêh ri păng vơl dăn ma Brah Yêsu prơh lơi brah mhĭk luh du bơh kon bu ur păng.$b$,true),
('bunong-vn','MRK',7,27,null,$b$Brah Yêsu lah ma păng: “Ăn ma phung kon sông sa hơm lor ƀât, yor lah mâu di ôh sŏk kapŭng ma phung kon jêh ri mƀăr lơi ma so.”$b$,false),
('bunong-vn','MRK',7,28,null,$b$Ƀiă lah bu ur nây plơ̆ sĭt lah: “Di jêh, ơ Kôranh Brah, ƀiă lah nđâp ma so tâm sưng sông, khân păng sa ndơ djah kapŭng ndăk kon se sa.”$b$,false),
('bunong-vn','MRK',7,29,null,$b$Brah Yêsu lah: “Hăn sĭt hom ay, yor lah nau ngơi nây, brah mhĭk luh du jêh tă bơh kon bu ur ay.”$b$,false),
('bunong-vn','MRK',7,30,null,$b$Tơ lah bu ur nây sĭt ta ngih, saơ kon jê̆ păng lâng bêch ta sưng, jêh ri brah mhĭk lĕ luh du jêh.$b$,false),
('bunong-vn','MRK',7,31,null,$b$Brah Yêsu sĭt tă bơh ƀon Tir, jêh ri găn ƀon Sidôn, jêh ri lăp găn ƀon Dêkapôlis, n'hot tât ta dak mƀŭt Galilê.$b$,true),
('bunong-vn','MRK',7,32,null,$b$Bu njŭn leo ma păng du huê bunuyh tê̆ k jêh ri mlo; jêh ri khân păng vơl dăn ma Brah Yêsu dra ti păng ta nơm nây.$b$,false),
('bunong-vn','MRK',7,33,null,$b$Brah Yêsu leo nơm nây luh pa dih êng du huê păng, hăn ta ntŭk êng jêh ri păng lŏk nglau ti păng ta sŭng tôr ô băl. Păng soh dak diu păng lĭp ta mpiăt ô băl.$b$,false),
('bunong-vn','MRK',7,34,null,$b$Pô ri, Păng n'gơr măt klơ trôk, păng nsôr n'hâm, jêh ri lah ma ô băl: “Êpatha!” nâm bu ntĭt, “Hă hom.”$b$,false),
('bunong-vn','MRK',7,35,null,$b$Ƀât lât ta nây, tôr păng rbăng ro, khay dơ̆ păng pơk ngloh ro, jêh ri ô băl ntơm ngơi kloh rah vah.$b$,false),
('bunong-vn','MRK',7,36,null,$b$Brah Yêsu buay mprân phung nây lơi dah nkoch bri ma bu ôh, ƀiă lah ktang Brah Yêsu buay, lơ hâu lơn đŏng khân păng nkoch bri nau nây lam ntŭk.$b$,false),
('bunong-vn','MRK',7,37,null,$b$Phung nây saơ jêh nau nây hih rhâl ngăn ngên, jêh ri lah: “Păng ƀư lĕ rngôch nau ueh da dê. Păng ăn bunuyh tê̆ k dơi tăng, jêh ri bunuyh mlo dơi ngơi.”$b$,false),
('bunong-vn','MRK',8,1,null,$b$Dôl nar nây, geh phung bunuyh âk ngăn tĭng Brah Yêsu gŭ tâm rƀŭn, jêh ri khân păng mâu geh mpa sông sa ôh, pô ri Brah Yêsu kuăl phung oh mon Păng văch ma Păng, jêh ri lah:$b$,true),
('bunong-vn','MRK',8,2,null,$b$“Gâp yô̆ ngăn ma phung âk aơ: Yor lah khân păng hŏ gŭ ndrel ma gâp pe nar jêh, jêh ri mâu geh mpa sông sa ôh.$b$,false),
('bunong-vn','MRK',8,3,null,$b$Tơ lah gâp mprơh sĭt khân păng hôm ji ngot, khân păng mra khĭt huăr rgŏ trong, jêh ri geh ƀa ƀă tâm phung khân păng hŏ tât jêh tă bơh ntŭk ngai ri.”$b$,false),
('bunong-vn','MRK',8,4,null,$b$Phung oh mon Păng plơ̆ sĭt lah: “Tâm nklang bri lach aơ mâm ƀư dơi geh kapŭng siăm phung aơ sa tât hơm?”$b$,false),
('bunong-vn','MRK',8,5,null,$b$Brah Yêsu ôp ma khân păng: “Ndah âk kapŭng khân may geh aƀaơ ri?” Khân păng lah: “Pơh mlâm.”$b$,false),
('bunong-vn','MRK',8,6,null,$b$Brah Yêsu ntĭnh ăn phung ƀon lan gŭ ta neh. Păng sŏk pơh mlâm kapŭng, jêh ri mbơh sơm tâm rnê ma Brah Ndu, Păng pêch kapŭng ăn phung oh mon păng tâm pă, jêh ri khân păng tâm pă ăn ma phung âk nây.$b$,false),
('bunong-vn','MRK',8,7,null,$b$Phung oh mon geh đŏng bar pe mlâm ka jê̆ jê̆. Brah Yêsu mbơh sơm tâm rnê ma Brah Ndu jêh ri ntĭnh ma phung oh mon păng tâm pă đŏng kan nây tâm ban lĕ ăn ma phung âk.$b$,false),
('bunong-vn','MRK',8,8,null,$b$Phung âk nây sa hơm da dê; jêh ri bu dônh rƀŭn geh pơh bĭ ndơ rmeh.$b$,false),
('bunong-vn','MRK',8,9,null,$b$Phung âk nây geh klăp tâm puăn rbăn nuyh.$b$,false),
('bunong-vn','MRK',8,10,null,$b$Brah Yêsu ăn khân păng sĭt, jêh ri Brah Yêsu n'ho ncho plŭng ndrel ma phung oh mon Păng, jêh ri hăn rlet ma n'gor Đalmanutha.$b$,false),
('bunong-vn','MRK',8,11,null,$b$Phung Pharisi văch ta nây, jêh ri ntơm tâm dun đah Brah Yêsu. Khân păng dăn ma Brah Yêsu ăn du nau mbên khlay tă bơh trôk, gay rlong uănh Păng.$b$,true),
('bunong-vn','MRK',8,12,null,$b$Păng nsôr n'hâm ƀhu jêh ri lah: “Mâm ƀư phung rnôk aƀaơ joi nau tâm mbên? N'hêl nanê̆ gâp lah ngăn ma khân may, bu mâu mra ăn ôh nau tâm mbên ma bunuyh rnôk aơ.”$b$,false),
('bunong-vn','MRK',8,13,null,$b$Jêh ri Brah Yêsu cha lơi phung nây, jêh nây ncho đŏng plŭng hăn n'hot tât kơh tê̆.$b$,true),
('bunong-vn','MRK',8,14,null,$b$Khân păng chuêl djôt leo kapŭng, jêh ri khân păng geh knŏng du mlâm kapŭng ndrel ma khân păng tâm trôm plŭng.$b$,true),
('bunong-vn','MRK',8,15,null,$b$Brah Yêsu ăn khân păng gŭ njrăng, lah: “Njrăng hom ma ndrui phung Pharisi, jêh ndrui Hêrôt.”$b$,true),
('bunong-vn','MRK',8,16,null,$b$Phung oh mon păng tâm lah ndrăng khân păng: “Nây jêng, yor lah, he mâu geh kapŭng.”$b$,false),
('bunong-vn','MRK',8,17,null,$b$Ƀiă lah Brah Yêsu gĭt nau nây, jêh ri lah ma khân păng: “Mâm ƀư khân may tâm lah ndrăng khân may yor ma nau mâu geh kapŭng? Mâm ƀư khân may ê hŏ gĭt, ê hŏ rbăng? Nuih n'hâm khân may ăt hôm dăng ƀơh?$b$,false),
('bunong-vn','MRK',8,18,null,$b$Khân may geh jêh trôm măt ƀiă lah mâu saơ? Khân may geh jêh tôr, ƀiă lah mâu tăng? Jêh ri mâm khân may mâu hôm kah gĭt đŏng?$b$,false),
('bunong-vn','MRK',8,19,null,$b$Tơ lah gâp pêch prăm mlâm kapŭng ăn ma phung prăm rbăn nuyh, ndah âk bĭ bêng ndơ rmeh kapŭng ndăk khân may geh dônh?” Khân păng plơ̆ lah: “Jât ma bar bĭ.”$b$,false),
('bunong-vn','MRK',8,20,null,$b$“Jêh ri pơh mlâm kapŭng ăn ma puăn rbăn nuyh, ndah âk bĭ lĕ bêng ndơ rmeh kapŭng ndăk khân may geh dônh?” Khân păng plơ̆ lah: “Pơh bĭ.”$b$,false),
('bunong-vn','MRK',8,21,null,$b$Brah Yêsu lah: “Khân may ê hŏ gĭt rbăng ƀơh?”$b$,false),
('bunong-vn','MRK',8,22,null,$b$Jêh ta nây, Brah Yêsu jêh ri phung oh mon hăn tât ta ƀon Ƀêtsaiđa. Bu njŭn leo ma Păng du huê bunuyh chieh măt, jêh ri vơl dăn ma Brah Yêsu bi ô băl.$b$,true),
('bunong-vn','MRK',8,23,null,$b$Brah Yêsu kuăn ta ti bunuyh chieh măt, njŭn leo ô băl pa dih mpâr ƀon. Jêh ri tơ lah bu soh dak diu ta trôm măt ô băl, jêh ri dra ti ta ô băl, păng ôp ô băl: “May saơ lĕ ndô ndơ?”$b$,false),
('bunong-vn','MRK',8,24,null,$b$Ô băl n'gơr uănh jêh ri lah: “Gâp saơ bunuyh ƀiă lah khân păng jêng nâm bu tơm si hăn.”$b$,false),
('bunong-vn','MRK',8,25,null,$b$Du tơ̆ đŏng Brah Yêsu dra ti păng ta măt ô băl, jêh ri ô băl uănh mâu mƀrêh jêh ri ô băl saơ ang ro, jêh ri saơ rah vah lĕ rngôch ndô ndơ.$b$,true),
('bunong-vn','MRK',8,26,null,$b$Brah Yêsu ăn ô băl sĭt ta ngih, lah: “Lơi ta lăp ôh tâm ƀon aơ.”$b$,false),
('bunong-vn','MRK',8,27,null,$b$Brah Yêsu hăn ndrel ma phung oh mon păng tâm âk ƀon tâm bri Sêsarê Philip. Dôl khân păng hăn rgŏ trong, Yêsu ôp ma phung oh mon păng: “Mbu nơm gâp jêng tĭng nâm bu lah?”$b$,true),
('bunong-vn','MRK',8,28,null,$b$Khân păng plơ̆ sĭt lah: “Y-Yôhan, nơm ƀư ƀaptem, jêh ri phung êng lah: Y-Êli, jêh ri geh phung êng đŏng lah du huê tâm phung kôranh nơm mbơh lor.”$b$,false),
('bunong-vn','MRK',8,29,null,$b$Jêh nây Brah Yêsu ôp đŏng ma khân păng: “Ƀiă lah mbu nơm gâp jêng tĭng nâm khân may lah?” Y-Pêtrôs plơ̆ sĭt lah ma Păng: “May jêng Brah Krist.”$b$,false),
('bunong-vn','MRK',8,30,null,$b$Jêh ri Brah Yêsu mprân ma khân păng, lơi mbơh ma bu ôh păng jêng.$b$,false),
('bunong-vn','MRK',8,31,null,$b$Brah Yêsu ntơm nti ma khân păng nau Kon Bunuyh mra dơn âk nau rêh ni, jêh ri phung kôranh ma bu ranh, phung n'gâng kôranh ƀư brah, jêh ri phung kôranh nchih sămƀŭt mra nsot lơi Păng, jêh ri ƀư nkhĭt Păng, lôch pe nar Păng mra dâk rêh đŏng.$b$,true),
('bunong-vn','MRK',8,32,null,$b$Brah Yêsu lah nau nây kloh rah vah ngăn ma phung oh mon Păng. Y-Pêtrôs jă Brah Yêsu leo rlet ntŭk êng jêh ri buay king Brah Yêsu, lơi ăn ƀư nau nây ôh.$b$,true),
('bunong-vn','MRK',8,33,null,$b$Ƀiă lah Brah Yêsu rle măt uănh ma phung oh mon Păng, jêh ri nduyh Y-Pêtrôs, lah: “Hơi Satan, rŭch hom pa kơi Gâp; yor lah may mâu gŭ mpeh ma Brah Ndu, ƀiă lah mpeh ma bunuyh.”$b$,false),
('bunong-vn','MRK',8,34,null,$b$Brah Yêsu kuăl phung ƀon lan ndrel phung oh mon Păng jêh ri lah ma khân păng: “Tơ lah mbu nơm ŭch tĭng gâp, ăn ngroh săk nơm, tuy si tâm rkăng păng nơm, ri mơ dơi jêng bunuyh tĭng gâp.$b$,true),
('bunong-vn','MRK',8,35,null,$b$Yor lah mbu nơm ŭch tâm rklaih nau rêh păng nơm mra roh, ƀiă lah mbu nơm ngroh lơi nau rêh păng nơm yor Gâp, jêh ri yor nau mhe mhan ueh, mra geh nau tâm rklaih.$b$,false),
('bunong-vn','MRK',8,36,null,$b$Yor lah moh nau khlay tơ lah du huê bunuyh geh ăp ntil ndơ tâm neh ntu, ƀiă lah nau rêh păng roh huêng?$b$,false),
('bunong-vn','MRK',8,37,null,$b$Moh ndơ bunuyh ăn gay dơi tâm chuai huêng păng?$b$,false),
('bunong-vn','MRK',8,38,null,$b$Yor lah mbu nơm prêng ma gâp jêh ri ma nau gâp ngơi, tâm rnôk noi rô̆ phung văng tĭr ƀư tih aơ; tâm ban lĕ Kon Bunuyh mra prêng ma nơm nây, tơ lah Păng văch tâm nau chrêk rmah Mbơ̆ Păng ndrel ma phung Tông mpăr kloh ueh.”$b$,false),
('bunong-vn','MRK',9,1,null,$b$Jêh ri Brah Yêsu lah ma phung oh mon Păng: “N'hêl nanê̆, gâp lah ngăn ma khân may, geh ƀa ƀă tâm phung gŭ ta aơ, geh nơm mâu mra khĭt ôh lor ma khân păng saơ jêh ƀon bri hađăch Brah Ndu tât ma nau brah.”$b$,true),
('bunong-vn','MRK',9,2,null,$b$Rlau prao nar Brah Yêsu jă leo Y-Pêtrôs, Y-Yakơ, jêh ri Y-Yôhan hao yôk prêh êng khân păng. Jêh ri săk jăn Brah Yêsu geh nau rgâl (njêng săk) ta năp pe nuyh khân păng.$b$,true),
('bunong-vn','MRK',9,3,null,$b$Ao jâr Păng jêng chrêk lơp, nglang ƀhiau ral ngăn ngên, nglang lơn ma nau bu dơi jan ta neh ntu aơ.$b$,false),
('bunong-vn','MRK',9,4,null,$b$Y-Êli jêh ri Y-Môis tâm mpơl ma khân păng. Phung bar hê nây gŭ nkoch bri đah Brah Yêsu.$b$,false),
('bunong-vn','MRK',9,5,null,$b$Y-Pêtrôs lah ma Brah Yêsu: “Hơi Kôranh nơm nti, ueh ngăn hên gŭ ta aơ. Ăn hên ƀư pe mlâm ngih bok, du mlâm ma may, du mlâm ma Y-Môis, jêh ri du mlâm ma Y-Êli.”$b$,false),
('bunong-vn','MRK',9,6,null,$b$Yor lah Y-Pêtrôs mâu gĭt moh nau lah, yor lah lĕ pe khân păng klach ngăn ngên.$b$,false),
('bunong-vn','MRK',9,7,null,$b$Ƀât lât ta nây geh ndâr tŭk nkŭm khân păng jêh ri geh bâr ngơi luh bơh tâm tŭk: “Aơ yơh jêng kon gâp, nơm gâp rŏng ngăn ngên; ăn khân may iăt hom nau Păng.”$b$,false),
('bunong-vn','MRK',9,8,null,$b$Ƀât lât, pe nuyh phung oh mon klep n'gơr uănh văr jŭm, mâu hôm saơ bunuyh, knŏng du huê Brah Yêsu dơm gŭ ndrel ma khân păng.$b$,false),
('bunong-vn','MRK',9,9,null,$b$Tơ lah khân păng trŭnh jêh bơh klơ yôk, Brah Yêsu buay mprân lơi phung oh mon păng, lơi nkoch bri đưn đŏng ma bu ôh lĕ ntil nau khân păng hŏ saơ jêh, ăn tât Kon Bunuyh dâk rêh jêh tă bơh phung khĭt.$b$,true),
('bunong-vn','MRK',9,10,null,$b$Pô nây, khân păng mpôn nau nây gĭt êng khân păng nơm, dôl nây khân păng tâm ôp ndrăng khân păng, nâm bu ntĭt nau dâk rêh tă bơh phung khĭt.$b$,false),
('bunong-vn','MRK',9,11,null,$b$Khân păng ôp ma Brah Yêsu: “Mâm phung kôranh nchih sămƀŭt lah ma Y-Êli mra văch lor?”$b$,false),
('bunong-vn','MRK',9,12,null,$b$Yêsu plơ̆ lah: “Nanê̆ Y-Êli mra văch lor gay nkra tay lĕ rngôch kan. Ƀiă lah mâm ƀư bu nchih jêh ri ma Kon Bunuyh mra dơn âk nau rêh ni jêh ri bu mra mưch ma păng?$b$,true),
('bunong-vn','MRK',9,13,null,$b$Ƀiă lah gâp lah ma khân may, Y-Êli tât jêh, jêh ri khân păng ƀư jêh ma păng tĭng nâm khân păng ŭch, tĭng nâm nau bu nchih jêh di ma păng.”$b$,false),
('bunong-vn','MRK',9,14,null,$b$Brah Yêsu ndrel pe nuyh tât ma phung oh mon ƀa ƀă, saơ phung ƀon lan âk ngăn gŭ nchueng jŭm khân păng, jêh ri geh phung kôranh nchih sămƀŭt tâm rlăch đah phung oh mon nây.$b$,true),
('bunong-vn','MRK',9,15,null,$b$Ƀât lât lĕ rngôch phung ƀon lan âk saơ jêh Brah Yêsu, geh nau hih rhâl ngăn, jêh ri nchuăt hăn ran mbah Brah Yêsu.$b$,false),
('bunong-vn','MRK',9,16,null,$b$Brah Yêsu ôp ma khân păng: “Moh nau khân may tâm rlăch đah phung oh mon aơ?”$b$,false),
('bunong-vn','MRK',9,17,null,$b$Geh du huê tâm phung âk nây lah ma Brah Yêsu: “Hơi Kôranh nơm nti, gâp njŭn leo kon bu klâu gâp ma may, geh brah mhĭk mlo lăp gŭ tâm păng.$b$,false),
('bunong-vn','MRK',9,18,null,$b$Kêng nôk tât, păng ƀư ma ô băl, cha lôt ta neh. Luh mpŭnh dak diu trôm mbung, rket sêk, jêh nây khĭt yơh n'ho dăng jâng ti. Gâp dăn jêh ma phung oh mon may mprơh brah mhĭk nây, ƀiă lah khân păng mâu dơi mprơh ôh.”$b$,false),
('bunong-vn','MRK',9,19,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Hơi ndŭl mpôl mâu chroh ri, ndah klăp jŏ gâp mra gŭ ndrel ma khân may? Ndah klăp jŏ gâp mra srôih ndrel ma khân may hia? Njŭn leo hom kon may ri tât ma gâp.”$b$,false),
('bunong-vn','MRK',9,20,null,$b$Jêh ri khân păng njŭn leo kon se nây ma Brah Yêsu, jêh ri lah brah mhĭk saơ Brah Yêsu ƀât lât ta nây brah mhĭk rgu râm săk jăn ô băl. Ô băl cha lôt ta neh plăch nkŭp mplơt, luh mpŭnh dak diu trôm mbung.$b$,false),
('bunong-vn','MRK',9,21,null,$b$Brah Yêsu ôp mbơ̆ păng: “Ndah hŏ jŏ ô băl geh nau nây?” Păng lah: “Ntơm bơh hôm jê̆.$b$,false),
('bunong-vn','MRK',9,22,null,$b$Ƀa ƀơ brah mhĭk mbŭk ô băl tâm ŭnh mâu lah nkrâm tâm dak gay ƀư nkhĭt ô băl. Ƀiă lah may dơi kơl, yô̆ an ma hên jêh ri sâm kơl hên ƀă.”$b$,false),
('bunong-vn','MRK',9,23,null,$b$Brah Yêsu lah ma păng, “Tơ lah may dơi! Lĕ rngôch nau dơi da dê ma mbu nơm chroh.”$b$,false),
('bunong-vn','MRK',9,24,null,$b$Ƀât lât mbơ̆ kon se nây nter lah: “Gâp chroh yơh; sâm kơl nau chroh gâp rdja!”$b$,false),
('bunong-vn','MRK',9,25,null,$b$Tơ lah Brah Yêsu saơ phung ƀon lan âk ri nchuăt ran, văch tât, pô ri Păng nduyh, lah ma brah mhĭk nây pô aơ: “Hơi brah mlo jêh ri tê̆ k, Gâp đă may luh du tă bơh kon se jê̆ aơ, lơi hôm may lơh njê păng ôh.”$b$,false),
('bunong-vn','MRK',9,26,null,$b$Jêh brah mhĭk nter jêh ri rgu mprâm săk jăn ô băl dŭt ktang ngăn, ri mơ păng luh. Kon se nây lĕ khĭt yơh jêh du ndâm; kŏ tât tâm phung âk nây lah: “Ô băl khĭt jêh.”$b$,false),
('bunong-vn','MRK',9,27,null,$b$Ƀiă lah Brah Yêsu kuăn ta ti ô băl jêh ri rdâk ô băl dâk, jêh ri ô băl n'ho dâk ro.$b$,false),
('bunong-vn','MRK',9,28,null,$b$Brah Yêsu lăp jêh tâm ngih, phung oh mon păng ôp păng dôl păng gŭ êng: “Mâm ƀư hên mâu dơi nsot brah mhĭk nây?”$b$,true),
('bunong-vn','MRK',9,29,null,$b$Brah Yêsu plơ̆ lah ma khân păng, “Ntil brah mhĭk nây bu mâu dơi nsot ôh, knŏng ma nau mbơh sơm yơh dơi.”$b$,true),
('bunong-vn','MRK',9,30,null,$b$Tă bơh ntŭk nây khân păng n'ho hăn găn n'gor Galilê, ƀiă lah mâu ŭch ăn bu gĭt ôh;$b$,true),
('bunong-vn','MRK',9,31,null,$b$yor lah păng nti ma phung oh mon păng, lah ma khân păng: “Bu mra jao Kon Bunuyh tâm ti phung bunuyh khân păng mra ƀư khĭt lơi; jêh bu ƀư nkhĭt, lôch pe nar păng mra dâk rêh.”$b$,false),
('bunong-vn','MRK',9,32,null,$b$Ƀiă lah phung oh mon mâu gĭt rbăng ôh nau ngơi nây, jêh ri khân păng klach hêng mâu janh ôp Brah Yêsu ôh.$b$,false),
('bunong-vn','MRK',9,33,null,$b$Khân păng tât ta ƀon Kapernum. Dôl Păng gŭ tâm ngih, Brah Yêsu ôp ma khân păng: “Moh nau tâm rlăch ndrăng khân may rŏ trong ndơh?”$b$,true),
('bunong-vn','MRK',9,34,null,$b$Ƀiă lah khân păng gŭ răk klăk, yor lah rŏ trong khân păng tâm rlăch jêh ăn gĭt mbu nơm jêng toyh lơn tâm phung khân păng.$b$,false),
('bunong-vn','MRK',9,35,null,$b$Brah Yêsu gŭ jêh ri kuăl phung jât ma bar nuyh; jêh ri lah ma khân păng: “Tơ lah mbu nơm ŭch jêng nơm lor lơn, ăn păng jêng nglĕ dŭt lơn; jêh ri jêng oh mon ma lĕ rngôch bunuyh.”$b$,false),
('bunong-vn','MRK',9,36,null,$b$Pô ri, Brah Yêsu sŏk du huê kon se jê̆, ăn ta nklang phung oh mon păng; jêh nây Păng pư tô̆ ô băl, dôl mbơh ma phung nây:$b$,true),
('bunong-vn','MRK',9,37,null,$b$“Mbu nơm rom du huê kon se jê̆ nâm bu pô aơ ma amoh gâp, nâm bu rom gâp lĕ; jêh ri mbu nơm rom gâp, mâu di rom knŏng gâp ôh, ƀiă lah păng rom nđâp ma Nơm tơm njuăl gâp.”$b$,false),
('bunong-vn','MRK',9,38,null,$b$Y-Yôhan lah ma Brah Yêsu: “Hơi Kôranh nơm nti, hên saơ du huê bunuyh nsot brah mhĭk yor ma amoh may, hên buay păng, păng mâu tĭng he ôh.”$b$,true),
('bunong-vn','MRK',9,39,null,$b$Ƀiă lah Brah Yêsu lah: “Lơi ta buay păng ôh, yor lah mâu geh ôh du huê dơi ƀư nau khlay, tâm amoh gâp mra gơnh ngơi mhĭk ma gâp.$b$,false),
('bunong-vn','MRK',9,40,null,$b$Yor lah mbu nơm mâu tâm rdâng đah he jêng băl he.$b$,true),
('bunong-vn','MRK',9,41,null,$b$Yor nây, n'hêl nanê̆ gâp lah ma khân may, mbu nơm ăn ma khân may nhêt du kchok dak ma amoh gâp, yor lah khân may jêng oh mon Brah Krist, nơm nây mâu mra roh ôh nau nkhôm ma păng.”$b$,false),
('bunong-vn','MRK',9,42,null,$b$“Ƀiă lah mbu nơm nsŭk du huê tâm phung kon se aơ lĕ chroh ma gâp ăn păng cha lơi, ueh lơn ăn bu kât ta trô ko păng du mlâm mpăl lŭ toyh jêh ri nklơ̆ păng tâm dak mƀŭt.$b$,true),
('bunong-vn','MRK',9,43,null,$b$Tơ lah ti may nsŭk may nơm, ăn may ƀư tih, koh lơi păng; ueh lơn may lăp tâm nau rêh geh knŏng du đah ti, ma may geh bar đah ti jêh ri lăp tâm ndrung ŭnh, tâm ŭnh mâu blau nhhât ôh.$b$,false),
('bunong-vn','MRK',9,44,null,$b$Ta nây rahai khân păng mâu blau khĭt ôh; jêh ri ŭnh mâu blau nhhât lĕ.$b$,true),
('bunong-vn','MRK',9,45,null,$b$Jêh ri tơ lah jâng may nsŭk may nơm, ăn may ƀư tih, koh lơi păng, ueh lơn may lăp tâm nau rêh geh knŏng du đah jâng ma may geh bar đah jâng jêh ri bu mƀăr may tâm ndrung ŭnh.$b$,false),
('bunong-vn','MRK',9,46,null,$b$Ta nây rahai khân păng mâu blau khĭt ôh, jêh ri ŭnh mâu blau nhhât lĕ.$b$,false),
('bunong-vn','MRK',9,47,null,$b$Jêh ri tơ lah măt may nsŭk may nơm ăn may ƀư tih, rloch lơi păng; ueh lơn may lăp tâm ƀon bri hađăch Brah Ndu ma du ding măt, ma may geh bar ding măt jêh ri bu mƀăr may tâm ndrung ŭnh.$b$,true),
('bunong-vn','MRK',9,48,null,$b$Ta nây rahai khân păng mâu blau khĭt ôh, jêh ri ŭnh mâu blau nhhât lĕ.$b$,false),
('bunong-vn','MRK',9,49,null,$b$Yor lah bu mra pâr ăp nơm đah ŭnh.$b$,false),
('bunong-vn','MRK',9,50,null,$b$“Boh jêng ndơ kah, ƀiă lah tơ lah boh roh nau kah păng, mâm đah khân may mra ƀư kah đŏng păng? Ăn khân may geh boh tâm nuih n'hâm khân ay may nơm, jêh ri ăn ay may gŭ đăp mpăn ndrăng khân ay may.”$b$,true),
('bunong-vn','MRK',10,1,null,$b$Brah Yêsu luh ntơm bơh nây, hăn rlet ma n'gor Yuđa jêh ri găn kơh tê̆ dak krong Yurdan. Phung ƀon lan âk tâm rƀŭn ta năp păng, jêh ri Păng nti lah ma khân păng kơt kănđai ri lĕ.$b$,true),
('bunong-vn','MRK',10,2,null,$b$Phung Pharisi hăn ma Brah Yêsu jêh ri ôp gay rlong uănh Păng: “Vay lĕ du huê bu klâu cha lơi ur păng?”$b$,false),
('bunong-vn','MRK',10,3,null,$b$Brah Yêsu plơ̆ sĭt lah ma khân păng: “Moh nau Y-Môis ntăm ma khân may?”$b$,false),
('bunong-vn','MRK',10,4,null,$b$Khân păng lah: “Y-Môis ăn bu nchih sămƀŭt nau tâm cha lơi, jêh ri cha lơi ur păng.”$b$,false),
('bunong-vn','MRK',10,5,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Yor nuih n'hâm khân may dăng nau nây yơh păng nchih nau ntăm nây ma khân may.$b$,false),
('bunong-vn','MRK',10,6,null,$b$Ƀiă lah ntơm bơh rhăk njêng neh ntu. ‘Brah Ndu njêng khân păng bu klâu jêh ri bu ur.’$b$,false),
('bunong-vn','MRK',10,7,null,$b$‘Yor nau aơ du huê bu klâu mra cha lơi mê̆ mbơ̆ păng jêh ri tâm rnglăp đah ur păng,$b$,false),
('bunong-vn','MRK',10,8,null,$b$jêh ri bar hê nây mra jêng nguay.’ Pô nây khân păng mâu hôm jêng bar ôh, ƀiă lah knŏng nguay.$b$,false),
('bunong-vn','MRK',10,9,null,$b$Pô nây, đơ ndơ Brah Ndu lĕ tâm rnglăp ndrel jêh, lơi ăn bunuyh tâm nkhah ôh.”$b$,false),
('bunong-vn','MRK',10,10,null,$b$Dôl khân păng gŭ tâm trôm ngih, phung oh mon păng ôp tay ma Brah Yêsu di ma nau nây đŏng.$b$,true),
('bunong-vn','MRK',10,11,null,$b$Brah Yêsu lah ma khân păng: “Mbu nơm cha lơi ur păng jêh ri gŭ ur êng, jêng nau tâm dŏng tĭr đah păng yơh.$b$,false),
('bunong-vn','MRK',10,12,null,$b$Jêh ri tơ lah bu ur nây cha lơi sai păng nơm jêh ri gŭ sai êng, bu ur nây văng tĭr yơh.”$b$,false),
('bunong-vn','MRK',10,13,null,$b$Bu njŭn leo kon se jê̆ ma Brah Yêsu, gay ăn păng pah ti ta phung kon se; ƀiă lah phung oh mon păng buay lơi phung njŭn kon se nây.$b$,true),
('bunong-vn','MRK',10,14,null,$b$Ƀiă lah lah Brah Yêsu saơ nau nây păng nuih, jêh ri lah ma phung oh mon Păng: “Ăn phung kon se văch ma gâp, lơi ta buay khân ô băl ôh; yor lah bri hađăch Brah Ndu prăp ma phung nâm bu khân ô băl.$b$,false),
('bunong-vn','MRK',10,15,null,$b$N'hêl nanê̆ gâp lah ma khân may, mbu nơm mâu sŏk dơn ƀon bri hađăch Brah Ndu nâm bu du huê kon se jê̆ mâu mra lăp ta nây ôh.”$b$,false),
('bunong-vn','MRK',10,16,null,$b$Brah Yêsu ut ra u khân ô băl, jêh ri păng dra ti mât ton nau ueh lăng ma khân ô băl.$b$,false),
('bunong-vn','MRK',10,17,null,$b$Dôl Brah Yêsu ntơm hăn nsong, geh du huê bunuyh nchuăt ran chon kômâk pa năp Păng, jêh ri ôp: “Hơi Kôranh nơm nti ueh, moh gâp mra ƀư gay dơn nau rêh mro mrăng?”$b$,true),
('bunong-vn','MRK',10,18,null,$b$Brah Yêsu lah ma păng: “Mâm ƀư may ntơ ma gâp bunuyh ueh? Mâu geh nơm ueh ôh, knŏng êng Brah Ndu yơh.$b$,false),
('bunong-vn','MRK',10,19,null,$b$May lĕ gĭt jêh nau vay: ‘Lơi ta nkhĭt bunuyh ôh; lơi ta văng tĭr ôh; lơi ta ntŭng ndô ndơ bu ôh; lơi ngơi nchơt ôh; lơi ta ndơm bu ôh, yơk ma mê̆ mbơ̆ may.’ ”$b$,false),
('bunong-vn','MRK',10,20,null,$b$Bu klâu nây lah ma păng: “Hơi Kôranh nơm nti, gâp tông jêh lĕ rngôch nau vay nây ntơm bơh gâp jê̆.”$b$,false),
('bunong-vn','MRK',10,21,null,$b$Brah Yêsu uănh ma păng ma nau rŏng jêh ri lah: “May hôm pah pưt du ntil nau; hăn hom, tăch lơi moh ndơ may geh jêh ri tâm pă ăn ma phung o ach, jêh ri may mra geh drăp khlay tâm trôk. Jêh ri văch hom, tĭng ndô̆ gâp.”$b$,false),
('bunong-vn','MRK',10,22,null,$b$Ƀiă lah bu klâu nây jâk muh măt tăng nau ngơi nây, jêh ri păng dâk hăn bêng ma nau rngot; yor lah păng geh âk drăp ndơ.$b$,false),
('bunong-vn','MRK',10,23,null,$b$Brah Yêsu uănh văr jŭm păng, jêh ri lah ma phung oh mon: “Jêr ngăn ma phung ndrŏng lăp tâm ƀon bri hađăch Brah Ndu!”$b$,true),
('bunong-vn','MRK',10,24,null,$b$Phung oh mon Păng hih rhâl ma nau Păng ngơi nây. Ƀiă lah Brah Yêsu lah đŏng ma khân păng: “Hơi phung kon gâp ơi, jêr ngăn ma phung bunuyh nsing ma nau ndrŏng lăp tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','MRK',10,25,null,$b$Dơh lơn ma du mlâm seh samô lăp tâm trôm nglai đŏng, đah du huê bunuyh ndrŏng lăp tâm ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','MRK',10,26,null,$b$Phung oh mon Păng hih rhâl ngăn jêh ri tâm lah ndrăng Păng: “Pô nây, mbu nơm dơi klaih?”$b$,true),
('bunong-vn','MRK',10,27,null,$b$Brah Yêsu uănh ma phung oh mon Păng, jêh ri lah: “Nau nây bunuyh mâu dơi ƀư ôh, ƀiă lah Brah Ndu mâu geh kơt ri ôh; yor lah Brah Ndu ƀư lĕ rngôch ndô ndơ dơi da dê.”$b$,false),
('bunong-vn','MRK',10,28,null,$b$Y-Pêtrôs ntơm lah ma Brah Yêsu, pô aơ: “Uănh, hên cha lơi lĕ rngôch ndô ndơ jêh ri tĭng ndô̆ may.”$b$,true),
('bunong-vn','MRK',10,29,null,$b$Brah Yêsu plơ̆ lah: “N'hêl nanê̆, gâp lah ma khân may, ăp nơm mbu moh lĕ cha lơi jêh ngih vâl păng mâu lah phung oh nâu, oh nur, mê̆ mbơ̆ , phung kon, mâu lah neh, mir lŏ yor amoh gâp jêh ri yor nau mhe mhan ueh,$b$,false),
('bunong-vn','MRK',10,30,null,$b$păng mra sŏk dơn rnôk aƀaơ du rhiăng tơ̆ âk lơn ma ngih vâl, oh nâu, oh nur, mê̆ mbơ̆ , phung kon, jêh ri neh mir lŏ, ndrel ma nau bu ƀư mhĭk, jêh ri nau rêh n'ho ro tâm rô̆ pa kơi.$b$,false),
('bunong-vn','MRK',10,31,null,$b$Ƀiă lah âk phung lor mra jêng nglĕ dŭt, jêh ri phung nglĕ dŭt mra jêng lor.”$b$,true),
('bunong-vn','MRK',10,32,null,$b$Brah Yêsu jêh ri oh mon Păng dôl hăn trong hăn hao rlet ƀon Yêrusalem, Păng hăn lor pa năp; phung oh mon Păng hih rhâl, jêh ri phung tĭng ndô̆ geh nau klach. Păng jă leo jât ma bar nuyh phung oh mon hăn ndrel Păng, jêh ri ntơm nkoch bri ma khân păng nau mra tât ma Păng.$b$,true),
('bunong-vn','MRK',10,33,null,$b$Păng lah: “Aơ, he hăn hao rlet ƀon Yêrusalem, jêh ri bu mra jao Kon Bunuyh ma phung n'gâng kôranh ƀư brah jêh ri ma phung kôranh nchih sămƀŭt. Khân păng mra phat dôih ăn bu ƀư nkhĭt ô băl, jêh ri jao ô băl ma phung bu năch.$b$,false),
('bunong-vn','MRK',10,34,null,$b$Phung nây mra njrŏ mưch ma ô băl, soh dak diu ma ô băl, dong ô băl đah mâng tak jra, jêh ri ƀư nkhĭt ô băl. Ƀiă lah tăch pe nar Păng dâk rêh đŏng.”$b$,false),
('bunong-vn','MRK',10,35,null,$b$Aơ, geh Y-Yakơ jêh ri Y-Yôhan, bar hê kon bu klâu Y-Sêƀêđê, hăn ma Brah Yêsu jêh ri ôp ma Păng: “Hơi Kôranh nơm nti, hên ŭch may ăn ma hên moh nau hên dăn ma may.”$b$,true),
('bunong-vn','MRK',10,36,null,$b$Brah Yêsu ôp ma khân păng: “Moh nau khân may ŭch gâp ƀư ăn ma khân may?”$b$,false),
('bunong-vn','MRK',10,37,null,$b$Khân păng lah ma Păng: “Ăn hên gŭ du huê mpeh pa ma may jêh ri du huê mpeh pa chiau tâm nau chrêk rmah may.”$b$,false),
('bunong-vn','MRK',10,38,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Khân may mâu gĭt ôh moh nau khân may dăn. Khân may dơi lĕ nhêt kchok gâp nhêt, mâu lah dơi dơn nau ƀaptem gâp dơn?”$b$,true),
('bunong-vn','MRK',10,39,null,$b$Khân păng lah: “Hên dơi lĕ.” Brah Yêsu lah ma khân păng: “Khân may mra nhêt kchok gâp nhêt; jêh ri khân may mra dơn nau ƀaptem bu mra ƀư ma gâp.$b$,true),
('bunong-vn','MRK',10,40,null,$b$Ƀiă lah nau gŭ mpeh pa ma mâu lah mpeh pa chiau gâp, mâu di ôh êng gâp geh nau dơi ăn. Nau nây prăp ma mbu nơm bu nkra jêh.”$b$,false),
('bunong-vn','MRK',10,41,null,$b$Phung jât nuyh oh mon tăng nau nây, khân păng ntơm ji nuih ma Y-Yakơ, jêh ri ma Y-Yôhan.$b$,true),
('bunong-vn','MRK',10,42,null,$b$Ƀiă lah Brah Yêsu kuăl khân păng jêh ri lah: “Khân may gĭt jêh ri phung bu ăn chiă uănh phung bu năch, chiă uănh phung ƀon lan, jêh ri phung kôranh toyh khân păng geh nau khưm chiă uănh khân păng.$b$,false),
('bunong-vn','MRK',10,43,null,$b$Ƀiă lah mâu di pô nây ôh ta nklang khân may. Ma mbu nơm ŭch jêng toyh tâm phung khân may, ăn păng jêng oh mon khân may.$b$,false),
('bunong-vn','MRK',10,44,null,$b$Jêh ri mbu nơm ŭch jêng mrô nguay tâm phung khân may; ăn păng jêng dĭk ma lĕ rngôch.$b$,false),
('bunong-vn','MRK',10,45,null,$b$Yor lah kơt nây lĕ Kon Bunuyh văch jêh mâu di gay bu pah kan ma Păng ôh, ƀiă lah Păng ŭch pah kan ma bu, jêh ri jao nau rêh Păng jêng rnoh tâm chuai ma âk bunuyh.”$b$,false),
('bunong-vn','MRK',10,46,null,$b$Jêh nây, Brah Yêsu jêh ri oh mon păng hăn tât ta ƀon Yêrikô. Dôl Brah Yêsu jêh ri oh mon păng ndrel ma phung ƀon lan âk ri dâk hăn đŏng tă bơh ntŭk nây, geh du huê bunuyh chieh măt amoh păng Y-Bartimê, kon bu klâu Y-Timê, gŭ kêng meng trong, kâp dăn ndơ bu yô̆.$b$,true),
('bunong-vn','MRK',10,47,null,$b$Yor lah păng hŏ tăng lư jêh bu nkoch, nây jêng Brah Yêsu, ƀon Nasaret, păng nter lah: “Ơ Brah Yêsu, kon hađăch Đavit, yô̆ an ma gâp ƀă.”$b$,false),
('bunong-vn','MRK',10,48,null,$b$Geh âk bunuyh buay păng, ăn păng gŭ răk klăk; ƀiă lah păng nter lơ hâu nteh lơn: “Ơ Kon hađăch Y-Đavit, yô̆ yach ma gâp ƀă.”$b$,false),
('bunong-vn','MRK',10,49,null,$b$Brah Yêsu gŭ srŭng jêh ri lah: “Kuăl păng.” Khân păng kuăl bunuyh chieh măt nây, jêh ri lah ma ô băl: “Maak hom may; dâk hom, păng kuăl may.”$b$,false),
('bunong-vn','MRK',10,50,null,$b$Păng doh mƀăr lơi ao jâr păng, dâk ro, jêh ri hăn ma Brah Yêsu,$b$,false),
('bunong-vn','MRK',10,51,null,$b$Brah Yêsu lah ma păng, “Moh nau may ŭch gâp ƀư ăn ma may mih?” Bunuyh chieh măt lah ma Brah Yêsu: “Hơi Kôranh nơm nti, ăn gâp dơi saơ ang.”$b$,false),
('bunong-vn','MRK',10,52,null,$b$Brah Yêsu lah ma păng: “Hăn hom may, nau may chroh ƀư bah jêh may.” Jêh ri păng lĕ saơ ang ro, jêh ri tĭng Brah Yêsu ta trong.$b$,false),
('bunong-vn','MRK',11,1,null,$b$Tơ lah khân păng dăch tât ma ƀon Yêrusalem, ta ƀon Bêtphajê, jêh ri ƀon Bêthani ta yôk Ôlivơ, Brah Yêsu prơh bar hê oh mon păng,$b$,true),
('bunong-vn','MRK',11,2,null,$b$jêh ri lah ma khân păng: “Hăn hom rlet ma ƀon pa năp khân may. Jêh ri khân may lăp ta nây khân may mra saơ ro du mlâm kon seh bri bu kât jêh. Ê hŏ bu prot ncho păng ôh. Doh jêh ri djôt leo păng ta aơ.$b$,false),
('bunong-vn','MRK',11,3,null,$b$Tơ lah bu ôp khân may: ‘Moh nau khân may ƀư kơt nây?’, Ăn khân may lah: ‘Kôranh Brah ŭch ma păng, jêh ri bu mra ăn têk seh bri nây leo ta aơ gơnh.’ ”$b$,false),
('bunong-vn','MRK',11,4,null,$b$Phung oh mon hăn jêh ri saơ du mlâm kon seh bri bu kât jêh ma pa dih tra pa năp mpông ngih, kêng kue trong sâng; jêh ri khân păng doh seh nây.$b$,true),
('bunong-vn','MRK',11,5,null,$b$Phung gŭ ta nây ôp khân păng: “Moh nau khân may ƀư, dĭng khân may doh seh nây?”$b$,false),
('bunong-vn','MRK',11,6,null,$b$Bar hê plơ̆ sĭt lah tĭng nau Brah Yêsu hŏ ntĭnh jêh; ri mơ khân păng ăn hăn djôt têk.$b$,true),
('bunong-vn','MRK',11,7,null,$b$Khân păng têk seh kon djôt sĭt ma Brah Yêsu, jêh ri ntă ao khân păng ta klơ chor kuyh seh; jêh ri Brah Yêsu ncho păng.$b$,false),
('bunong-vn','MRK',11,8,null,$b$Geh âk bunuyh lăk bok ao khân păng rŏ trong; jêh ri phung ƀa ƀă nđaih n'gĭng si khân păng sreh tă bơh mir.$b$,true),
('bunong-vn','MRK',11,9,null,$b$Phung hăn lor pa năp jêh ri phung tĭng groi pa kơi nter huy, lah: “Hôsana! Mât ton ma nơm văch tâm amoh Kôranh Brah!$b$,false),
('bunong-vn','MRK',11,10,null,$b$Mât ton ma ƀon bri hađăch mbơ̆ he Y-Đavit mra tât! Hôsana! Ơ Nơm ta klơ dŭt prêh!”$b$,true),
('bunong-vn','MRK',11,11,null,$b$Brah Yêsu lăp tâm ƀon Yêrusalem jêh ri lăp tâm ngih brah Yuđa. Jêh Păng uănh lĕ rngôch ndơ văr jŭm nây, yor lah lĕ la nar jêh, păng dâk hăn rlet ma ƀon Bêthani ndrel ma jât ma bar nuyh.$b$,true),
('bunong-vn','MRK',11,12,null,$b$Kêng ôi taơ khân păng luh tă bơh ƀon Bêthani, Brah Yêsu ji ngot.$b$,true),
('bunong-vn','MRK',11,13,null,$b$Uănh nđơng bơh ngai păng saơ du tơm play rvi geh âk nkâm n'ha. Pô ri păng hăn uănh ntôn lah geh play tâm tơm păng. Tơ lah păng tât jêh ta nây, Brah Yêsu saơ knŏng n'ha dơm, yor lah ê hŏ tât yan geh play rvi ôh.$b$,false),
('bunong-vn','MRK',11,14,null,$b$Brah Yêsu lah ma tơm play rvi nây: “Bu mâu hôm mra sa play may đŏng ôh.” Jêh ri phung oh mon păng tăng da dê nau nây.$b$,true),
('bunong-vn','MRK',11,15,null,$b$Khân păng tât ma ƀon Yêrusalem; jêh ri Brah Yêsu lăp tâm ngih brah Yuđa, jêh ri ntơm prơh phung tăch drăp tâm ngih brah. Păng nklơ̆ lơi sưng phung tâm rgâl prăk jêh ri rnơl phung tăch plŭk.$b$,true),
('bunong-vn','MRK',11,16,null,$b$Păng mâu ăn bu leo ndô ndơ găn tâm ngih brah Yuđa.$b$,false),
('bunong-vn','MRK',11,17,null,$b$Jêh nây Brah Yêsu ƀăp nti ma khân păng: “Mâu di ƀơh, bu nchih jêh: Ngih gâp bu mra ntơ jêng ngih prăp mbơh sơm ma lĕ rngôch mpôl băl bunuyh? Ƀiă lah khân may njêng ngih aơ ntŭk ma phung ntŭng.”$b$,false),
('bunong-vn','MRK',11,18,null,$b$Phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt tăng nau nây, jêh ri joi trong dơi ƀư nkhĭt Brah Yêsu; yor lah khân păng klach ma Brah Yêsu, yor lah lĕ rngôch phung âk hih rhâl ma nau Păng nti.$b$,false),
('bunong-vn','MRK',11,19,null,$b$Tơ lah trôk dăch măng jêh, Brah Yêsu jêh ri phung oh mon du luh tă bơh ƀon Yêrusalem.$b$,true),
('bunong-vn','MRK',11,20,null,$b$Ơm ôi, dôl khân păng găn êp kêng tơm play rvi nây, ta aơ khân păng saơ lĕ kro jêh tât ta reh păng.$b$,true),
('bunong-vn','MRK',11,21,null,$b$Y-Pêtrôs, kah gĭt ro jêh ri lah ma Brah Yêsu: “Hơi Kôranh nơm nti, uănh hom; tơm play rvi may rtăp nây lĕ kro jêh.”$b$,false),
('bunong-vn','MRK',11,22,null,$b$Brah Yêsu plơ̆ sĭt lah ma khân păng: “Ăn khân may geh nau chroh ma Brah Ndu.$b$,false),
('bunong-vn','MRK',11,23,null,$b$N'hêl nanê̆ gâp lah ma khân may, mbu nơm lah ma yôk aơ: ‘Du hom may jêh ri nsăt tâm dak mƀŭt;’ jêh ri păng mâu đing ôh tâm nuih n'hâm păng, ƀiă lah rnơm ngăn nau păng lah mra tât, bu mra ăn tât ngăn ma păng.$b$,false),
('bunong-vn','MRK',11,24,null,$b$Yor nây gâp lah ma khân may. Moh nau khân may dăn dôl mbơh sơm, ăn he rnơm ma ndơ nây lĕ sŏk dơn jêh, jêh ri khân may mra geh ngăn yơh.$b$,false),
('bunong-vn','MRK',11,25,null,$b$Tơ lah khân may dâk mbơh sơm, lah khân may geh nau mhĭk đah bu, yô̆ an hom; gay ma Mbơ̆ khân may, Nơm gŭ tâm trôk, tâm ban lĕ yô̆ an nau tih khân may.$b$,false),
('bunong-vn','MRK',11,26,null,$b$Ƀiă lah tơ lah khân may mâu yô̆ an ôh, Mbơ̆ khân may tâm trôk mâu mra yô̆ an lĕ nau tih khân may.”$b$,false),
('bunong-vn','MRK',11,27,null,$b$Khân păng hăn đŏng ma ƀon Yêrusalem. Dôl Brah Yêsu hăn tâm ngih brah Yuđa, phung n'gâng kôranh ƀư brah, phung kôranh nchih sămƀŭt, jêh ri phung kôranh ma phung bu ranh hăn ma păng.$b$,true),
('bunong-vn','MRK',11,28,null,$b$Khân păng ôp ma Brah Yêsu: “Tă bơh nau dơi may ƀư nau aơ? Mâu lah mbu nơm ăn ma nau dơi ƀư nau aơ?”$b$,false),
('bunong-vn','MRK',11,29,null,$b$Brah Yêsu lah ma khân păng: “Gâp mra ôp ma khân may du nau. Plơ̆ sĭt lah hom ma gâp, jêh ri gâp mra mbơh ma khân may tă bơh nau dơi gâp ƀư nau aơ.$b$,true),
('bunong-vn','MRK',11,30,null,$b$Nau Y-Yôhan ƀư ƀaptem tă luh bơh trôk lĕ mâu lah tă bơh bunuyh? Plơ̆ sĭt lah hom ma gâp.”$b$,false),
('bunong-vn','MRK',11,31,null,$b$Khân păng tâm dun ndrăng khân păng nơm pô aơ: “Tơ lah he lah: ‘Bơh trôk,’ păng mra lah: ‘Pô nây mâm ƀư khân may mâu chroh ma păng?’$b$,false),
('bunong-vn','MRK',11,32,null,$b$Ƀiă lah tơ lah he lah: ‘Bơh bunuyh,’ ” khân păng klach ma phung ƀon lan, yor lah lĕ rngôch bunuyh chroh ma Y-Yôhan jêng du huê kôranh nơm mbơh lor ngăn.”$b$,false),
('bunong-vn','MRK',11,33,null,$b$Pô nây, khân păng plơ̆ sĭt lah ma Brah Yêsu: “Hên mâu gĭt ôh.” Jêh ri Brah Yêsu lah ma khân păng: “Mâu gâp mra mbơh ma khân may lĕ tă bơh nau dơi gâp ƀư nau aơ.”$b$,false),
('bunong-vn','MRK',12,1,null,$b$Brah Yêsu ntơm ngơi ma khân păng ma nau ngơi hôr: “Du huê bu klâu tăm du lôk mir play kriăk ƀâu. Păng bât n'gar văr jŭm păng, kuyh ntu prăp păt djet dak play kriăk ƀâu, ndâk du mlâm ngih tŭm jêh ri ăn phung êng nkhôm mir nây, jêh ri păng du hăn nkơi ma bri êng.$b$,true),
('bunong-vn','MRK',12,2,null,$b$Tơ lah tât yan pĕ play, păng prơh hăn du huê oh mon păng, gay sŏk nchuăn tă bơh phung nkhôm ƀa ƀă play tă bơh mir nây.$b$,true),
('bunong-vn','MRK',12,3,null,$b$Ƀiă lah phung nây nhŭp ô băl, dong ô băl, jêh ri mprơh sĭt ô băl ti dơm.$b$,true),
('bunong-vn','MRK',12,4,null,$b$Păng prơh hăn đŏng du huê oh mon êng ma phung nây. Phung nây ƀư sôt ô băl jêh ri ƀư mhĭk ma ô băl.$b$,false),
('bunong-vn','MRK',12,5,null,$b$Păng prơh hăn du huê êng. Jêh ri phung nây ƀư nkhĭt ô băl; jêh ri ƀư pô nây đah âk phung êng, ƀa ƀă khân păng dong, ƀa ƀă khân păng ƀư khĭt.$b$,false),
('bunong-vn','MRK',12,6,null,$b$Bu klâu nây hôm geh du huê êng, du huê kon bu klâu păng rŏng. Dăch dŭt bu klâu nây prơh hăn kon păng nơm ma khân păng, lah: ‘Khân păng mra yơk ma kon bu klâu gâp.’$b$,false),
('bunong-vn','MRK',12,7,null,$b$Ƀiă lah phung nkhôm mir kriăk ƀâu nây tâm lah ndrăng khân păng: ‘Aơ yơh jêng nơm ndơn drăp. Kay lŏng he ƀư nkhĭt lơi păng, jêh ri drăp ndơn ma he.’$b$,false),
('bunong-vn','MRK',12,8,null,$b$Khân păng nhŭp jêh ri ƀư nkhĭt păng, jêh ri mƀăr săk jăn păng ta pa dih pĭt mir play kriăk ƀâu.$b$,false),
('bunong-vn','MRK',12,9,null,$b$Moh nơm mir play kriăk ƀâu nây mra ƀư? Păng mra văch ƀư nkhĭt lơi phung kan nkhôm nây, jêh ri jao mir play kriăk ƀâu nây ma phung êng.$b$,false),
('bunong-vn','MRK',12,10,null,$b$Khân may mâu mâp uănh ƀơh nau bu nchih: ‘Lŭ phung ndâk ngih mƀăr lơi, Hŏ jêng jêh lŭ njônh ngih$b$,false),
('bunong-vn','MRK',12,11,null,$b$Nau aơ jêng nau Kôranh Brah ƀư, jêh ri jêng khlay ngăn ngên pa năp măt he’?”$b$,false),
('bunong-vn','MRK',12,12,null,$b$Khân păng joi trong nhŭp chăp Brah Yêsu, ƀiă lah khân păng klach ma phung âk, yor lah khân păng gĭt jêh Brah Yêsu ngơi nau hôr di ma khân păng. Pô nây khân păng cha lơi Brah Yêsu jêh ri du hăn.$b$,true),
('bunong-vn','MRK',12,13,null,$b$Khân păng prơh hăn bar pe nuyh phung Pharisi ndrel ma phung Hêrôt tât ma Brah Yêsu gay geh nau dơi phong tơ lah tih păng ngơi.$b$,true),
('bunong-vn','MRK',12,14,null,$b$Khân păng văch lah ma Brah Yêsu: “Hơi Kôranh nơm nti, hên gĭt ma may jêng ngăn, jêh ri mâu chrê ma bu ôh, yor lah may mâu uănh ma bunuyh pa dih ôh, ƀiă lah nti trong Brah Ndu ma nau n'hêl nanê̆. Dơi lĕ chê̆ pi ăn ma Sêsar mâu lah mâu? Hên dơi chê̆ mâu lah mâu dơi chê̆ ?”$b$,false),
('bunong-vn','MRK',12,15,null,$b$Ƀiă lah Brah Yêsu gĭt jêh nau ma khân păng jan n'hi săk; pô nây păng lah: “Moh nau khân may ŭch rlong uănh gâp? Vơt ăn gâp uănh du rêl prăk đơniê.”$b$,false),
('bunong-vn','MRK',12,16,null,$b$Khân păng ndơ̆ ăn Brah Yêsu du rêl prăk đơniê. Jêh ri Brah Yêsu lah ma khân păng: “Mbu nơm rup aơ jêh ri nau nchih aơ?” Khân păng lah ma Brah Yêsu: “Ndơ Sêsar.”$b$,false),
('bunong-vn','MRK',12,17,null,$b$Brah Yêsu lah ma khân păng: “Mplơ̆ sĭt hom ma Sêsar ndơ Sêsar, jêh ri mplơ̆ hom ma Brah Ndu ndơ Brah Ndu.” Khân păng gŭ hih rhâl ma nau Brah Yêsu ngơi nây.$b$,false),
('bunong-vn','MRK',12,18,null,$b$Geh phung Sađusê, văch ma Brah Yêsu, phung nây lah mâu geh nau khĭt dâk rêh ôh. Khân păng ôp ma Brah Yêsu pô aơ:$b$,true),
('bunong-vn','MRK',12,19,null,$b$“Hơi Kôranh nơm nti, Y-Môis nchih ma he tơ lah du huê nâu khĭt bi ur păng hôm rêh mâu geh kon ôh, oh păng mra ntrok ur păng, gay ma geh noi deh oh nâu khân păng.$b$,false),
('bunong-vn','MRK',12,20,null,$b$Pô ri, geh pơh oh nâu. Nâu bôk rah nsông ur, ƀiă lah khĭt hêng mâu geh kon ôh.$b$,false),
('bunong-vn','MRK',12,21,null,$b$Oh năp păng ntrok noi, jêh ri khĭt mâu geh kon lĕ, nđâp ma oh rơh pe tâm ban lĕ.$b$,false),
('bunong-vn','MRK',12,22,null,$b$Pô nây, lĕ pơh nuyh nây mâu geh kon ôh. Kêng dăch dŭt bu ur nây khĭt tâm ban lĕ.$b$,false),
('bunong-vn','MRK',12,23,null,$b$Tâm nau khĭt dâk rêh du nar kăndơ̆ , păng jêng ur ma mbu nơm, yor lah lĕ pơh nuyh nây jêng sai păng da dê?”$b$,false),
('bunong-vn','MRK',12,24,null,$b$Brah Yêsu lah ma khân păng: “Mâu di aƀaơ ri, khân may lĕ vĭ jêh ƀơh, yor lah khân may mâu gĭt rbăng ôh nau nchih, kŏ khân may mâu gĭt rbăng lĕ nau brah Brah Ndu.$b$,true),
('bunong-vn','MRK',12,25,null,$b$Yor lah tơ lah bu dâk rêh tă bơh phung khĭt, phung bu klâu mâu mra gŭ đŏng ur ôh, phung bu ur mâu lĕ mra gŭ sai đŏng; ƀiă lah khân păng mra jêng nâm bu oh mon ueh tâm trôk.$b$,false),
('bunong-vn','MRK',12,26,null,$b$Bi ma phung khĭt mra dâk rêh, khân may mâu mâp uănh ƀơh tâm ndrom sămƀŭt Y-Môis; mâm nau Brah Ndu lah ma păng; ntŭk păng saơ, dôl hit ŭnh sa rlô lok, Brah Ndu lah ma păng: Y-Isăk, Brah Ndu Y-Yakôp?$b$,false),
('bunong-vn','MRK',12,27,null,$b$Păng mâu jêng ôh Brah Ndu ma phung khĭt, ƀiă lah Brah Ndu ma phung rêh. Khân may lĕ vĭ ngăn.”$b$,false),
('bunong-vn','MRK',12,28,null,$b$Ta aơ, geh du huê kôranh nchih sămƀŭt văch jêh ri tăng nau khân păng tâm dun, jêh ri tăng nau Brah Yêsu plơ̆ sĭt lah ma phung Sađusê lĕ di jêh. Păng ôp ma Brah Yêsu: “Moh nau vay toyh lơn jêng mrô nguay?”$b$,true),
('bunong-vn','MRK',12,29,null,$b$Brah Yêsu plơ̆ lah: “Nau vay toyh lơn jêng, Iăt hom. ‘Hơi phung Israel: Kôranh Brah Ndu he jêng knŏng du huê,$b$,false),
('bunong-vn','MRK',12,30,null,$b$jêh ri ăn may rŏng ma Kôranh Brah Ndu may ma lĕ nuih n'hâm, ma lĕ huêng, ma lĕ nau mĭn, jêh ri ma lĕ n'hâm suan dăng ktang may.’$b$,false),
('bunong-vn','MRK',12,31,null,$b$Aơ nau vay rơh bar, ‘Ăn may rŏng ma nơm chiau meng may nâm bu may nơm lĕ.’ Mâu hôm geh nau vay toyh lơn ma nây ôh.”$b$,false),
('bunong-vn','MRK',12,32,null,$b$Kôranh nchih sămƀŭt nây lah ma Brah Yêsu: “Di jêh, Kôranh nơm nti. May lah di jêh ma Brah Ndu jêng knŏng du huê, jêh ri mâu hôm geh nơm êng ôh.$b$,false),
('bunong-vn','MRK',12,33,null,$b$Jêh ri nau rŏng ma păng ma lĕ nuih n'hâm, ma lĕ nau blau, jêh ri ma lĕ n'hâm suan dăng ktang, jêh ri rŏng ma nơm chiau meng nâm bu he nơm lĕ, jêng khlay lơn ma lĕ rngôch mpa nhhơr gŭch jêh ri mpa ƀư brah.”$b$,false),
('bunong-vn','MRK',12,34,null,$b$Tơ lah Brah Yêsu saơ bunuyh nây plơ̆ lah ma nau blau; Brah Yêsu lah ma păng, “May mâu gŭ ngai ôh bơh ƀon bri hađăch Brah Ndu.” Jêh nau nây mâu hôm geh du huê bunuyh janh ôp ma păng du nau ôh.$b$,false),
('bunong-vn','MRK',12,35,null,$b$Dôl Brah Yêsu gŭ nti tâm ngih brah Yuđa, păng lah: “Mâm ƀư phung kôranh nchih sămƀŭt dơi lah ma Brah Krist jêng Kon bu klâu Y-Đavit?$b$,true),
('bunong-vn','MRK',12,36,null,$b$Y-Đavit nơm đah Brah Huêng Ueh mbơh jêh: ‘Kôranh Brah lah ma Kôranh Brah gâp, Gŭ hom mpeh pa ma gâp, tât gâp dơm phung rlăng may tâm dâng jâng may.’$b$,false),
('bunong-vn','MRK',12,37,null,$b$Y-Đavit nơm ntơ ma păng Kôranh Brah. Pô nây mâm Brah Krist dơi jêng kon bu klâu Y-Đavit?” Jêh ri phung âk tăng Brah Yêsu ma nau răm rhơn.$b$,false),
('bunong-vn','MRK',12,38,null,$b$Dôl Brah Yêsu gŭ nti, păng lah pô aơ: “Njrăng hom ma Kôranh nchih sămƀŭt. Khân păng ŭch ngăn nsoh ao jâr hăn pâl, jêh ri gay ăn bu mbah ma khân păng tâm ngih tăch drăp.$b$,true),
('bunong-vn','MRK',12,39,null,$b$Khân păng săch ntŭk gŭ ueh lơn tâm ngih tâm rƀŭn Yuđa jêh ri ntŭk bu yơk dôl nau nhêt sông.$b$,false),
('bunong-vn','MRK',12,40,null,$b$Khân păng pit sŏk ngih phung bu ur ndrô khĭt sai, jêh ri jan lơh mbơh sơm jŏ. Khân păng mra dơn nau tâm rmal glăm lơn.”$b$,false),
('bunong-vn','MRK',12,41,null,$b$Brah Yêsu gŭ rle ta năp hip prăk tâm ngih brah Yuđa, jêh ri uănh ma phung âk nhhơr prăk tâm hip nây. Âk phung ndrŏng nhhơr âk prăk.$b$,true),
('bunong-vn','MRK',12,42,null,$b$Jêh ri du huê bu ur ndrô khĭt sai o ach văch, jêh ri nhhơr bar kăk jêng du kô̆ puăn rêl.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MRK',12,43,null,$b$Brah Yêsu kuăl phung oh mon păng jêh ri lah ma khân păng: “N'hêl nanê̆ gâp lah: Ma khân may, bu ur ndrô o ach aơ nhhơr jêh tâm hip prăk âk lơn ma lĕ rngôch phung êng.$b$,false),
('bunong-vn','MRK',12,44,null,$b$Yor lah lĕ rngôch khân păng nhhơr bơh prăk khân păng rmeh; ƀiă lah bu ur ndrô nây nhhơr bơh nau păng o ach lĕ ndơ păng geh prăp ma păng gŭ rêh.”$b$,false),
('bunong-vn','MRK',13,1,null,$b$Dôl Brah Yêsu luh du bơh ngih brah Yuđa, du huê tâm phung oh mon păng lah: “Uănh hom, hơi Kôranh nơm nti, âk lŭ toyh jêh ri âk ngih aơ ueh ngăn!”$b$,true),
('bunong-vn','MRK',13,2,null,$b$Brah Yêsu lah ma păng: “May saơ lĕ rngôch ngih toyh aơ? Bu mâu mra cha lơi ôh du mlâm lŭ gŭ ta klơ du mlâm lŭ êng ôh; lĕ rngôch rlâm da dê.”$b$,false),
('bunong-vn','MRK',13,3,null,$b$Păng gŭ ta yôk Ôlivơ êp ngih brah Yuđa, jêh ri Y-Pêtrôs, Y-Yakơ, Y-Yôhan, jêh ri Y-Andrê ôp êng Brah Yêsu lah:$b$,true),
('bunong-vn','MRK',13,4,null,$b$“Mbơh ma hên, mdah jŏ nau nây mra tât? Jêh ri moh mra jêng ăn ma bu gĭt lĕ nau nây mra tât?”$b$,false),
('bunong-vn','MRK',13,5,null,$b$Brah Yêsu ntơm lah ma khân păng: “Njrăng hom, lơi ăn bu ndơm khân may ôh.$b$,false),
('bunong-vn','MRK',13,6,null,$b$Âk bunuyh mra văch nkoch n'hi săk gâp lah: ‘Gâp aơ yơh jêng Brah Krist,’ jêh ri khân păng mra ndơm âk bunuyh.$b$,true),
('bunong-vn','MRK',13,7,null,$b$Jêh ri tơ lah khân may tăng nteh n'găr nau tâm lơh dăch jêh ri tăng lư bu nkoch ma nau tâm lơh mra tât, lơi klach ôh. Nau nây mra tât, ƀiă lah ê hŏ tât rnôk rô̆ dăch dŭt ôh.$b$,false),
('bunong-vn','MRK',13,8,null,$b$Yor lah du ndŭl mpôl bunuyh aơ mra tâm rdâng đah du ndŭl mpôl bunuyh êng, jêh ri du ƀon bri hađăch aơ mra tâm rdâng đah ƀon bri hađăch êng, mra geh nau n'găr neh ntu tâm âk ntŭk, jêh ri mra geh âk tơ̆ nau ât ji ngot. Nau nây jêng knŏng nau ntơm ma nau rêh ni.$b$,true),
('bunong-vn','MRK',13,9,null,$b$“Bi ma phung khân may, ăn khân may njrăng; yor lah bu mra jao khân may ma phung kôranh phat dôih; jêh ri bu mra dong khân may tâm ngih tâm rƀŭn Yuđa. Khân may mra gŭ pa năp kôranh bri jêh ri hađăch yor ma gâp, gay jêng phung mbơh ta năp khân păng.$b$,true),
('bunong-vn','MRK',13,10,null,$b$Jêh ri lor ma rnôk rô̆ dăch dŭt bu mra mbơh nau mhe mhan ueh ma lĕ rngôch ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','MRK',13,11,null,$b$Pô ri, tơ lah bu njŭn leo khân may jao ma nau phat dôih, lơi ta khân may chrê lor ôh ma moh nau khân may mra ngơi; ƀiă lah ta mông nây, ngơi hom moh nau mra mpơl ma khân may; yor lah mâu di khân may nơm ôh mra ngơi, ƀiă lah Brah Huêng Ueh yơh.$b$,false),
('bunong-vn','MRK',13,12,null,$b$Nâu mra jao oh păng nơm ăn bu ƀư nkhĭt, jêh ri mbơ̆ mra jao kon păng nơm. Phung kon mra tâm rdâng đah mê̆ mbơ̆ khân păng, jêh ri ăn bu ƀư nkhĭt lơi khân păng.$b$,false),
('bunong-vn','MRK',13,13,null,$b$Lĕ rngôch bunuyh mra tâm rmot ma khân may yor amoh gâp. Ƀiă lah mbu nơm srôih tât lôch mra klaih.”$b$,false),
('bunong-vn','MRK',13,14,null,$b$“Ƀiă lah tơ lah khân may mra saơ nau bu mưch rmot jêh ri ƀư nau chah rai ta ntŭk păng mâu vay ƀư ôh, mbu uănh sămƀŭt aơ ăn he mĭn rvê, rnôk nây phung gŭ tâm n'gor Yuđa du gŭ mpeh klơ yôk.$b$,true),
('bunong-vn','MRK',13,15,null,$b$Mbu nơm gŭ ta klơ chor bôk pho ngih lơi ăn păng trŭnh ôh, mâu lĕ păng dơi lăp tâm ngih djôt rdu ndô ndơ păng.$b$,true),
('bunong-vn','MRK',13,16,null,$b$Jêh ri lơi ăn nơm gŭ tâm mir sĭt sŏk ao mbâl păng ôh.$b$,false),
('bunong-vn','MRK',13,17,null,$b$Tâm lĕ nar nây, rêh ni ngăn yơh ma phung bu ur ntreo nđâp ma bu ur pu kon!$b$,false),
('bunong-vn','MRK',13,18,null,$b$Ăn khân may mbơh sơm gay ma nau nây lơi tât ôh dôl yan sial puh.$b$,false),
('bunong-vn','MRK',13,19,null,$b$Yor lah tâm nar rnôk nây mra geh nau rêh ni mâu prot geh ôh tâm ban kơt nây ntơm bơh rnôk Brah Ndu rhăk njêng lĕ rngôch mpô mpa n'ho tât ma nar aơ, mâu lĕ hôm mra geh đŏng pa kơi taơ.$b$,false),
('bunong-vn','MRK',13,20,null,$b$Tơ lah Kôranh Brah mâu n'hŭch nar rnôk nây, mâu geh du huê bunuyh mra klaih ôh. Ƀiă lah Păng hŏ n'hŭch jêh đơ nar nây yor phung păng hŏ săch jêh.$b$,false),
('bunong-vn','MRK',13,21,null,$b$Tâm rnôk nây tơ lah bu lah ma khân may: ‘Aơ, ta aơ Brah Krist,’ mâu lah: ‘Păng ta ri’, lơi ta iăt nau nây ôh.$b$,false),
('bunong-vn','MRK',13,22,null,$b$Mra geh phung Brah Krist tih jêh ri phung Kôranh nơm mbơh lor tih. Khân păng mra mpôl nau tâm mbên jêh ri ƀư nau khlay ngăn, gay ndơm tơ lah dơi, nđâp ma phung Brah Ndu hŏ săch jêh.$b$,false),
('bunong-vn','MRK',13,23,null,$b$Ƀiă lah njrăng hom. Ta aơ, gâp mbơh lor jêh nau nây ma khân may.”$b$,false),
('bunong-vn','MRK',13,24,null,$b$“Ƀiă lah tâm nar nây, nau rêh ni nây lĕ rlau jêh măt nar mra jêng ngo, jêh ri khay mâu hôm nchrat ang ôh.$b$,true),
('bunong-vn','MRK',13,25,null,$b$Lĕ rngôch mănh mra tŭp tă bơh trôk, jêh ri phung geh nau brah ta klơ trôk mra mpât n'gơ.$b$,true),
('bunong-vn','MRK',13,26,null,$b$Rnôk nây bu mra saơ Kon Bunuyh văch tâm ndâr tŭk ma nau brah toyh jêh ri nau chrêk rmah;$b$,true),
('bunong-vn','MRK',13,27,null,$b$jêh ri Păng mra prơh hăn phung Tông mpăr ueh, jêh ri tâm rƀŭn phung Brah Ndu hŏ săch jêh tă bơh puăn njônh neh ntu ntơm bơh bôl neh ntu tât ma bôl trôk.”$b$,false),
('bunong-vn','MRK',13,28,null,$b$“Ăn khân may nti nau ngơi hôr bơh tơm play rvi: Tơ lah n'gĭng păng nse jêh ri ntơm chăt nkŭr, khân may gĭt yan ta vai dăch tât jêh.$b$,true),
('bunong-vn','MRK',13,29,null,$b$Tâm ban pô nây lĕ tơ lah khân may saơ lĕ rngôch nau nây tât, khân may mra gĭt ngăn ma Kon Bunuyh dăch tât jêh, păng gŭ ta mpông sâng jêh.$b$,false),
('bunong-vn','MRK',13,30,null,$b$N'hêl nanê̆ gâp mbơh ma khân may, phung bunuyh rnôk nây mâu mra rlau lôch ôh lor ma lĕ nau nây tât.$b$,false),
('bunong-vn','MRK',13,31,null,$b$Trôk jêh ri neh ntu mra rlau lôch, ƀiă lah nau gâp ngơi mâu mra rlau lôch ôh.”$b$,false),
('bunong-vn','MRK',13,32,null,$b$“Ƀiă lah bi ma nar jêh ri mông nây, mâu geh du huê gĭt ôh, nđâp ma phung Tông mpăr ueh tâm trôk, nđâp ma Kon Bunuyh kŏ mâu gĭt lĕ, knŏng êng Mbơ̆ dơm gĭt.$b$,true),
('bunong-vn','MRK',13,33,null,$b$Njrăng hom, gŭ kâp uănh, yor lah khân may mâu gĭt ôh ndah jŏ mông nây mra tât.$b$,true),
('bunong-vn','MRK',13,34,null,$b$Nau nây jêng nâm bu du huê bunuyh hăn nsong. Tơ lah păng luh tă bơh ngih, păng jao kan êng êng ma ăp nơm phung oh mon păng, jêh ri ntĭnh ma nơm chiă mpông pêr gŭ kâp uănh.$b$,true),
('bunong-vn','MRK',13,35,null,$b$Pô nây gŭ kâp uănh hom, yor lah khân may mâu gĭt ôh ndah jŏ kôranh ngih mra tât, gĭt lah kêng mhaơ, mâu lah ta n'gul măng mâu lah kêng ndrau iăr, mâu lah kêng ôi,$b$,false),
('bunong-vn','MRK',13,36,null,$b$klach lah păng tât ƀât lât dơm, ban khân may hăk bêch.$b$,false),
('bunong-vn','MRK',13,37,null,$b$Nau gâp lah ma khân may, gâp lah ma lĕ rngôch đŏng: Gŭ rngeh hom!”$b$,false),
('bunong-vn','MRK',14,1,null,$b$Hôm bar nar ma tât nau nhêt sa Nau Găn jêh ri Kapŭng Mâu Geh Ndrui. Phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt joi trong dơi nhŭp chăp Brah Yêsu ma nau ndâp, jêh ri ƀư nkhĭt Păng.$b$,true),
('bunong-vn','MRK',14,2,null,$b$Yor lah khân păng lah: “Lơi ƀư ôh dôl nau nhêt sa, klach lah phung ƀon lan geh nau uh ah.”$b$,false),
('bunong-vn','MRK',14,3,null,$b$Dôl Brah Yêsu gŭ ta ƀon Bêthani tâm ngih Y-Simôn nơm geh phŭng, dôl păng gŭ sông sa, geh du huê bu ur djôt du mlâm rchŏk ƀư ma lŭ ueh geh dak ƀâu kah nar khlay ngăn. Bu ur nây nchah lơi nông jêh ri lĭng dak ƀâu kah ta klơ bôk Brah Yêsu.$b$,true),
('bunong-vn','MRK',14,4,null,$b$Ƀiă lah geh ƀa ƀă ji nuih, lah ndrăng khân păng: “Mâm ƀư roh dak ƀâu kah tâm ban pô nây?$b$,true),
('bunong-vn','MRK',14,5,null,$b$Yor lah bu dơi tăch dak ƀâu kah aơ ma rnoh pe rhiăng đơniê jêh ri tâm pă ma phung o ach.” Jêh ri khân păng nduyh bu ur nây.$b$,false),
('bunong-vn','MRK',14,6,null,$b$Ƀiă lah Brah Yêsu lah: “Lơi, kđôi păng, mâm ƀư khân may ƀư rkhŭk ô băl? Ô băl ƀư nau ueh ma gâp.$b$,false),
('bunong-vn','MRK',14,7,null,$b$Yor lah khân may geh phung o ach ndrel ma khân may ƀa ƀơ, jêh ri tơ lah khân may ŭch, khân may dơi ƀư nau ueh ma khân păng. Ƀiă lah gâp mâu mra gŭ ndrel ma khân may ƀa ƀơ ôh.$b$,false),
('bunong-vn','MRK',14,8,null,$b$Bu ur aơ ƀư tĭng nâm păng dơi. Păng troch dak ƀâu kah ta săk jăn gâp lor ma bu tâp gâp.$b$,false),
('bunong-vn','MRK',14,9,null,$b$N'hêl nanê̆ gâp lah ma khân may, ta ntŭk bu nti nau mhe mhan ueh tâm lam neh ntu, bu mra nkoch bri nkah nau bu ur aơ hŏ ƀư jêh.”$b$,false),
('bunong-vn','MRK',14,10,null,$b$Jêh ri Y-Yuđas Iskariôt, jêng du huê tâm phung jât ma bar oh mon, hăn ma phung n'gâng kôranh ƀư brah ŭch rlăng jao Brah Yêsu ma khân păng.$b$,true),
('bunong-vn','MRK',14,11,null,$b$Tơ lah khân păng tăng nau nây khân păng răm rhơn ngăn, jêh ri ton ăn prăk ma Y-Yuđas. Pô nây, Y-Yuđas joi nar tâm di dơi rlăng jao Păng.$b$,false),
('bunong-vn','MRK',14,12,null,$b$Nar rơh nguay tâm nau sa Kapŭng Mâu Geh Ndrui, nar bu sreh nkhĭt kon biăp Nau Găn, phung oh mon lah ma Brah Yêsu: “Ta ntŭk may ŭch hên hăn nkra ăn may sa Nau Găn?”$b$,true),
('bunong-vn','MRK',14,13,null,$b$Păng prơh bar hê oh mon păng hăn jêh ri lah ma khân păng: “Hăn hom ma ƀon Yêrusalem, jêh ri khân may mra mâp đah du huê bu klâu yar du mlâm yăng dak, tĭng ndô̆ păng.$b$,false),
('bunong-vn','MRK',14,14,null,$b$Jêh ri ntŭk ngih păng lăp, ăn khân may lah ma nơm ngih nây, Kôranh nơm nti lah, ntŭk jrô gâp mra sa Nau Găn ndrel ma phung oh mon gâp?$b$,false),
('bunong-vn','MRK',14,15,null,$b$Bunuyh nây mra ntĭm an ma khân may du mlâm jrô toyh tal klơ bu rơm nkra ăn jêh.”$b$,false),
('bunong-vn','MRK',14,16,null,$b$Phung oh mon nây hăn ma ƀon Yêrusalem, jêh ri saơ lĕ rngôch ndơ tĭng nâm Brah Yêsu lah jêh ma khân păng. Jêh ri khân păng nkra Nau Găn.$b$,false),
('bunong-vn','MRK',14,17,null,$b$Tât kêng mhaơ, Brah Yêsu văch ndrel ma phung jât ma bar nuyh.$b$,true),
('bunong-vn','MRK',14,18,null,$b$Dôl khân păng gŭ sông sa Brah Yêsu lah: “Nanê̆ ngăn gâp lah ma khân may, du huê tâm phung khân may mra ƀlêp ƀlêr ma gâp, nơm nây gŭ sông sa ndrel ma gâp.”$b$,false),
('bunong-vn','MRK',14,19,null,$b$Khân păng ntơm rngot, jêh ri jêh du huê du huê khân păng lah ma Brah Yêsu: “Di lĕ gâp?”$b$,false),
('bunong-vn','MRK',14,20,null,$b$Brah Yêsu lah ma khân păng: “Nơm nây jêng du huê tâm phung jât ma bar nuyh, nơm mbŭk kapŭng tâm ngan ndrel ma gâp.$b$,false),
('bunong-vn','MRK',14,21,null,$b$Yor lah Kon Bunuyh mra khĭt tĭng nâm bu nchih di jêh ma Păng, ƀiă lah rêh ni yơh ma nơm ƀlêp ƀlêr ma Kon Bunuyh! Ueh lơn mâu bu deh ôh ma nơm nây.”$b$,false),
('bunong-vn','MRK',14,22,null,$b$Dôl khân păng gŭ sông sa, Brah Yêsu sŏk kapŭng, mbơh sơm nau tâm rnê, pêch kapŭng nây, jêh ri ăn ma khân păng, jêh ri lah: “Sŏk hom; aơ jêng nglay săk gâp.”$b$,true),
('bunong-vn','MRK',14,23,null,$b$Jêh ri păng sŏk kchok. Jêh mbơh sơm nau tâm rnê, păng ăn kchok nây ma khân păng, jêh ri lĕ rngôch khân păng nhêt.$b$,false),
('bunong-vn','MRK',14,24,null,$b$Brah Yêsu lah ma khân păng: “Aơ jêng mham gâp, mham ma nau tâm rnglăp, nkhŭt ăn ma âk bunuyh.$b$,false),
('bunong-vn','MRK',14,25,null,$b$N'hêl nanê̆, gâp lah ma khân may, gâp mâu mra nhêt đŏng ôh dak kriăk ƀâu aơ, kŏ tât nar gâp mra nhêt dak kriăk ƀâu mhe tâm ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','MRK',14,26,null,$b$Jêh khân păng mprơ du nau, khân păng du luh hăn ma yôk Ôlivơ.$b$,true),
('bunong-vn','MRK',14,27,null,$b$Brah Yêsu lah ma khân păng: “Lĕ rngôch khân may mra nchuăt du cha lơi gâp; yor lah bu nchih jêh, ‘Gâp mra dong rmăk biăp, jêh ri phung biăp mra chah rai êng êng.’$b$,true),
('bunong-vn','MRK',14,28,null,$b$Ƀiă lah tơ lah gâp dâk rêh jêh, gâp mra tât n'gor Galilê lor pa năp khân may.”$b$,false),
('bunong-vn','MRK',14,29,null,$b$Y-Pêtrôs lah ma khân păng: “Nđâp tơ lah lĕ rngôch khân păng mra cha lơi may, gâp mâu mra cha lơi may ôh.”$b$,true),
('bunong-vn','MRK',14,30,null,$b$Brah Yêsu lah ma păng: “Nanê̆ ngăn gâp lah may, măng aơ ro, ê lor ma iăr ndrau bar tong may mra dun ma gâp pe tơ̆ .”$b$,false),
('bunong-vn','MRK',14,31,null,$b$Ƀiă lah Y-Pêtrôs lah ma nau ktang lơn: “Tơ lah gâp khĭt ndrel ma may kđôi lĕ, gâp mâu mra dun ma may ôh.” Lĕ rngôch khân păng lah kơt nây da dê.$b$,false),
('bunong-vn','MRK',14,32,null,$b$Khân păng hăn rlet ntŭk bu ntơ Gêtsêmanê, jêh ri Brah Yêsu lah ma phung oh mon păng: “Gŭ hom ta aơ dôl gâp mbơh sơm.”$b$,true),
('bunong-vn','MRK',14,33,null,$b$Jêh nây păng jă Y-Pêtrôs, Y-Yakơ, jêh ri Y-Yôhan, pô ri păng ntơm geh nau krit mƀât jêh ri nau rngot.$b$,false),
('bunong-vn','MRK',14,34,null,$b$Păng lah ma pe nuyh, pô aơ: “Nuih n'hâm gâp rngot ngăn bơi ŭch khĭt. Gŭ ta aơ, jêh ri njrăng hom.”$b$,false),
('bunong-vn','MRK',14,35,null,$b$Păng trơn ngai oi đê̆, mprah săk ta neh, jêh ri mbơh sơm lah, Păng gay tơ lah dơi, dăn mông aơ mâu tât ôh ma Păng.$b$,false),
('bunong-vn','MRK',14,36,null,$b$Păng lah: “Aba, nâm bu ntĭt Mbơ̆ . Ơ Mbơ̆ ơi, lĕ rngôch ndô ndơ may dơi ƀư da dê. Sŏk rdu lơi kchok aơ bơh gâp; ƀiă lah mâu di tĭng nau gâp ŭch ôh, ƀiă lah tĭng nâm nau may nơm ŭch.”$b$,true),
('bunong-vn','MRK',14,37,null,$b$Jêh nây Păng plơ̆ văch ma phung oh mon saơ khân păng lêt bêch. Păng lah ma Y-Pêtrôs, “Hơi Y-Simôn, may bêch ƀơh? Mâu ƀơh may dơi rngeh du mông?$b$,false),
('bunong-vn','MRK',14,38,null,$b$Ăn khân may rngeh jêh ri mbơh sơm, gay ma khân may mâu geh nau ndơm ôh. Huêng ŭch ngăn, ƀiă lah rnglay săk jêng rdja.”$b$,false),
('bunong-vn','MRK',14,39,null,$b$Brah Yêsu hăn mbơh sơm đŏng jêh ri nau nâm bu kơt pa năp.$b$,false),
('bunong-vn','MRK',14,40,null,$b$Jêh ri Păng plơ̆ văch đŏng saơ phung oh mon hôm bêch, yor lah khân păng ŭch bêch ngăn. Jêh ri khân păng mâu gĭt moh nau plơ̆ sĭt lah ma Brah Yêsu.$b$,false),
('bunong-vn','MRK',14,41,null,$b$Păng plơ̆ văch đŏng rơh pe, jêh ri lah ma khân păng: “Mâm khân may hôm bêch jêh ri gŭ rlu? Găp jêh; mông tât jêh. Bu rlăng jao Kon Bunuyh tâm ti phung tih.$b$,false),
('bunong-vn','MRK',14,42,null,$b$Dâk hăn hom he. Ta aơ, nơm rlăng ma gâp ntơm tât jêh.”$b$,true),
('bunong-vn','MRK',14,43,null,$b$Ƀât lât dôl Brah Yêsu hôm ngơi, Y-Yuđas, du huê tâm phung jât ma bar nuyh oh mon, văch ndrel phung âk djôt đao jêh ri mâng jra ma phung kôranh ƀư brah, phung kôranh nchih sămƀŭt, jêh ri kôranh phung bu ranh.$b$,true),
('bunong-vn','MRK',14,44,null,$b$Nơm ƀlêp ƀlêr ăn jêh du nau tâm nal, jêh ri lah: “Nơm gâp mra chŭm, nây yơh păng chăp păng jêh ri leo hăn ăn rjăp.”$b$,false),
('bunong-vn','MRK',14,45,null,$b$Pô nây, tơ lah Y-Yuđas tât jêh, păng hăn dăch Brah Yêsu, jêh ri lah: “Hơi Kôranh nơm nti”, jêh ri chŭm Brah Yêsu.$b$,false),
('bunong-vn','MRK',14,46,null,$b$Phung nây nhŭp chăp Brah Yêsu.$b$,true),
('bunong-vn','MRK',14,47,null,$b$Ƀiă lah du huê gŭ dăch tăk đao păng, jêh ri sreh du huê n'gâng kôranh ƀư brah, geh ta tôr kŏ tât tăch.$b$,false),
('bunong-vn','MRK',14,48,null,$b$Brah Yêsu lah ma phung nây: “Di lĕ khân may văch djôt đao jêh ri mâng jra gay nhŭp chăp gâp nâm bu du huê ntŭng?$b$,false),
('bunong-vn','MRK',14,49,null,$b$Ăp nar gâp gŭ ndrel ma khân may, nti tâm ngih brah Yuđa, ƀiă lah khân may mâu nhŭp chăp ôh gâp. Ƀiă lah ăn nanê̆ nau bu nchih jêh.”$b$,false),
('bunong-vn','MRK',14,50,null,$b$Jêh ri lĕ rngôch phung oh mon du cha lơi Brah Yêsu jêh ri nchuăt du lĕ ƀhiau.$b$,false),
('bunong-vn','MRK',14,51,null,$b$Geh knŏng du huê bu klâu ndăm tĭng ndô̆ Brah Yêsu, n'gut knŏng du blah bok mhay.$b$,true),
('bunong-vn','MRK',14,52,null,$b$Khân păng nhŭp bu klâu nây, ƀiă lah ô băl cha lơi bok mhay nây jêh ri nchuăt du săk hưl.$b$,false),
('bunong-vn','MRK',14,53,null,$b$Khân păng njŭn leo Brah Yêsu ma n'gâng kôranh ƀư brah. Lĕ rngôch phung n'gâng kôranh ƀư brah, kôranh phung bu ranh, jêh ri phung kôranh nchih sămƀŭt tâm rƀŭn ndrel.$b$,true),
('bunong-vn','MRK',14,54,null,$b$Y-Pêtrôs tĭng ndô̆ pa kơi gŭ ngai đê̆, lăp tâm nkual ngih n'gâng kôranh ƀư brah. Păng gŭ ndrel ta han gak jêh ri njâr ŭnh ta nây.$b$,false),
('bunong-vn','MRK',14,55,null,$b$Phung n'gâng kôranh ƀư brah jêh ri kôranh phat dôih joi nau phong ma Brah Yêsu gay ƀư nkhĭt ô băl; ƀiă lah khân păng mâu saơ nau ôh.$b$,false),
('bunong-vn','MRK',14,56,null,$b$Yor lah âk bunuyh phong nchơt ma Brah Yêsu, ƀiă lah nau khân păng nchơt nây mâu tâm ban ôh.$b$,true),
('bunong-vn','MRK',14,57,null,$b$Geh ƀa ƀă dâk ro jêh ri nchơt ma Brah Yêsu lah:$b$,false),
('bunong-vn','MRK',14,58,null,$b$“Hên tăng jêh păng lah: ‘Gâp mra ƀư rai lơi ngih brah Yuđa aơ ti bunuyh ƀư, jêh ri tâm pe nar gâp mra ndâk tay du mlâm ngih brah êng, mâu di ti bunuyh ƀư ôh.’ ”$b$,false),
('bunong-vn','MRK',14,59,null,$b$Ƀiă lah nđâp ma nau khân păng mbơh mâu di du ai nau ôh.$b$,false),
('bunong-vn','MRK',14,60,null,$b$N'gâng kôranh ƀư brah dâk ta nklang jêh ri ôp Brah Yêsu: “May mâu geh nau plơ̆ lah ƀơh? Moh nau phung aơ phong may?”$b$,true),
('bunong-vn','MRK',14,61,null,$b$Ƀiă lah Brah Yêsu gŭ rklăk, mâu hôm plơ̆ lah ôh. Du tơ̆ đŏng n'gâng kôranh ƀư brah ôp ma Brah Yêsu: “May jêng Brah Krist lĕ, Kon Brah Ndu Nơm khư ma bu mât ton?”$b$,true),
('bunong-vn','MRK',14,62,null,$b$Brah Yêsu lah: “Gâp yơh nây, jêh ri khân may mra saơ Kon Bunuyh gŭ mpeh pa ma Nơm Brah, jêh ri plơ̆ văch ta ndâr tŭk tâm trôk.”$b$,true),
('bunong-vn','MRK',14,63,null,$b$N'gâng kôranh ƀư brah nkhêk ao jâr păng jêh ri lah: “Moh he hôm ŭch đŏng ma phung mbơh?$b$,true),
('bunong-vn','MRK',14,64,null,$b$Khân may tăng jêh nau păng ngơi sưr đah Brah Ndu. Moh nau khân may mĭn?” Lĕ rngôch khân păng phat dôih Brah Yêsu jêng khư ma nau nkhĭt.$b$,false),
('bunong-vn','MRK',14,65,null,$b$Ƀa ƀă ntơm soh dak diu ma ô băl, put muh măt ô băl, đŏl ô băl jêh ri lah: “Mbơh lor hom!” Jêh ri phung ta han gak tap bom ô băl.$b$,true),
('bunong-vn','MRK',14,66,null,$b$Dôl Y-Pêtrôs gŭ ntŭk tâm dâng, tâm nkual ngih, du huê oh mon bu ur n'gâng kôranh ƀư brah toyh văch.$b$,true),
('bunong-vn','MRK',14,67,null,$b$Dôl Y-Pêtrôs njâr ŭnh, bu ur nây uănh ma păng, jêh ri lah: “May tâm ban lĕ gŭ jêh ndrel ma Brah Yêsu ƀon Nasaret?”$b$,false),
('bunong-vn','MRK',14,68,null,$b$Ƀiă lah Y-Pêtrôs dun nau nây, jêh ri lah: “Gâp mâu gĭt ôh, mâu lĕ gĭt rbăng moh nau may lah nây.” Y-Pêtrôs du luh hăn rlet ma mpông pêr. Rnôk nây du mlâm iăr nkuăng ndrau.$b$,false),
('bunong-vn','MRK',14,69,null,$b$Oh mon bu ur nây saơ păng jêh ri ntơm lah đŏng ma phung bunuyh gŭ dăch. “Bu klâu aơ jêng du huê tâm phung khân păng.”$b$,true),
('bunong-vn','MRK',14,70,null,$b$Ƀiă lah Y-Pêtrôs dun đŏng nau nây. Ƀât lât ta nây phung gŭ dăch lah ma Y-Pêtrôs: “Nanê̆ ngăn may jêng du huê tâm phung nây; yor lah may jêng bunuyh n'gor Galilê ngăn.”$b$,true),
('bunong-vn','MRK',14,71,null,$b$Ƀiă lah Y-Pêtrôs ntơm rak săk jêh ri ton: “Gâp mâu gĭt năl ôh bunuyh khân ay may lah nây.”$b$,true),
('bunong-vn','MRK',14,72,null,$b$Ƀât lât iăr ndrau rơh bar, Y-Pêtrôs kah gĭt ma nau Brah Yêsu lah jêh ma păng: “Lor ma iăr ndrau rơh bar may dun ma gâp pe tơ̆ .” Jêh ri păng kah gĭt ƀrư̆ ma nau nây jêh ri nhĭm.$b$,true),
('bunong-vn','MRK',15,1,null,$b$Tât kêng ôi phung n'gâng kôranh ƀư brah, kôranh phung bu ranh, kôranh nchih sămƀŭt, jêh ri lĕ rngôch phung kôranh phat dôih tâm chră. Khân păng nkông Brah Yêsu jêh ri njŭn leo jao păng ma Pilat.$b$,true),
('bunong-vn','MRK',15,2,null,$b$Pilat ôp ma Brah Yêsu: “May jêng hađăch phung Yuđa ƀơh?” Brah Yêsu plơ̆ lah ma păng: “May lah jêh nau nây.”$b$,false),
('bunong-vn','MRK',15,3,null,$b$Jêh ri phung n'gâng kôranh ƀư brah phong Brah Yêsu âk ntil nau.$b$,false),
('bunong-vn','MRK',15,4,null,$b$Pilat ôp đŏng ma Brah Yêsu: “May mâu hôm plơ̆ lah ƀơh? Uănh ri nau khân păng phong may âk ngăn.”$b$,false),
('bunong-vn','MRK',15,5,null,$b$Ƀiă lah Brah Yêsu mâu hôm plơ̆ lah ôh. Pô nây, tât Pilat hih rhâl.$b$,true),
('bunong-vn','MRK',15,6,null,$b$Dôl nau nhêt sa Pilat vay mƀơk ma khân păng du huê bu nă mbu nơm khân păng dăn,$b$,true),
('bunong-vn','MRK',15,7,null,$b$Tâm phung tâm rdâng bu krŭng jêh, geh du huê bunuyh, amoh păng Y-Barabas ƀư nkhĭt bunuyh dôl geh nau tâm rdâng nây.$b$,false),
('bunong-vn','MRK',15,8,null,$b$Phung âk văch ntơm dăn ma Pilat ăn păng ƀư nâm bu păng vay ƀư.$b$,false),
('bunong-vn','MRK',15,9,null,$b$Pilat plơ̆ sĭt lah ma khân păng: “Khân may ŭch lĕ gâp mƀơk ma khân may Hađăch phung Yuđa?”$b$,false),
('bunong-vn','MRK',15,10,null,$b$Yor lah păng gĭt jêh ma phung n'gâng kôranh ƀư brah jao jêh Brah Yêsu yor nau nach.$b$,true),
('bunong-vn','MRK',15,11,null,$b$Ƀiă lah phung n'gâng kôranh ƀư brah nsônh phung âk gay ma Pilat pơk Y-Barabas ma khân păng ntrok ma Brah Yêsu.$b$,false),
('bunong-vn','MRK',15,12,null,$b$Jêh ri Pilat lah ma khân păng: “Pô nây, mâm gâp mra ƀư ma bunuyh nơm khân may ntơ Hađăch phung Yuđa?”$b$,false),
('bunong-vn','MRK',15,13,null,$b$Jêh ri khân păng nter, lah: “Pâng lơi păng ta si tâm rkăng!”$b$,false),
('bunong-vn','MRK',15,14,null,$b$Pilat lah ma khân păng: “Mâm ƀư, moh nau mhĭk păng lĕ ƀư jêh?” Ƀiă lah khân păng nter ktang lơ hâu lơn: “Pâng lơi păng ta si tâm rkăng.”$b$,false),
('bunong-vn','MRK',15,15,null,$b$Pô nây, yor Pilat ŭch ƀư maak ma phung âk nây, păng pơk Y-Barabas ma khân păng. Jêh ri păng ăn bu dong Brah Yêsu ma mâng, păng jao Brah Yêsu ăn bu pâng păng ta si tâm rkăng.$b$,false),
('bunong-vn','MRK',15,16,null,$b$Phung ta han njŭn Brah Yêsu lăp tâm ngih kôranh bri nâm bu ntĭt ngih phat dôih; jêh ri khân păng kuăl rgum lĕ rngôch mpôl ta han ndrel du ai.$b$,true),
('bunong-vn','MRK',15,17,null,$b$Khân păng ăn nsoh ao rvanh ma Brah Yêsu, jêh ri khân păng ăn ndô klơ bôk Brah Yêsu du mlâm đon ma lok khân păng pêng;$b$,false),
('bunong-vn','MRK',15,18,null,$b$jêh nây mbah ma Păng: “Mbah ma may, Hơi Hađăch phung Yuđa!”$b$,false),
('bunong-vn','MRK',15,19,null,$b$Khân păng sŏk tơm treng mbang ta bôk ô băl, soh ô băl ma dak diu, jêh ri chon kômâk mbah ma ô băl.$b$,false),
('bunong-vn','MRK',15,20,null,$b$Jêh khân păng mưch ma ô băl, khân păng doh lơi ao rvanh, plơ̆ nsoh ao păng nơm. Jêh ri khân păng njŭn leo ô băl gay pâng ô băl ta si tâm rkăng.$b$,false),
('bunong-vn','MRK',15,21,null,$b$Geh du huê bunuyh, amoh păng Y-Simôn tă bơh bri Siren, mbơ̆ Y-Aleksandrơ jêh ri Y-Ruphus văch tă bơh pa dih ƀon găn ta nây. Khân păng nchâp ô băl tuy si tâm rkăng Brah Yêsu.$b$,true),
('bunong-vn','MRK',15,22,null,$b$Khân păng njŭn leo Brah Yêsu rlet ma ntŭk bu ntơ Gôgôtha, (nâm bu ntĭt Ntŭk Nting Bôk.)$b$,false),
('bunong-vn','MRK',15,23,null,$b$Khân păng nta ma Brah Yêsu nhêt dak kriăk ƀâu tâm pot lai đah dak si tăng, ƀiă lah ô băl dun mâu nhêt ôh.$b$,false),
('bunong-vn','MRK',15,24,null,$b$Khân păng pâng ô băl ta si tâm rkăng, jêh ri tâm pă bok ao ô băl ma nau chroh n'hôr, gay ŭch gĭt mbu nơm geh.$b$,false),
('bunong-vn','MRK',15,25,null,$b$Ta sĭn mông ôi khân păng pâng Brah Yêsu ta si tâm rkăng.$b$,false),
('bunong-vn','MRK',15,26,null,$b$Bu nchih nau bu phong pô aơ: “Hađăch ma phung Yuđa.”$b$,false),
('bunong-vn','MRK',15,27,null,$b$Khân păng pâng ta si tâm rkăng ndrel ma Brah Yêsu bar hê bunuyh ntŭng, du huê pa ma, du huê pa chiau Brah Yêsu.$b$,false),
('bunong-vn','MRK',15,28,null,$b$Pô nây ăn nanê̆ nau bu nchih jêh pô aơ: “Bu kơp păng ndrel ma phung tih.”$b$,false),
('bunong-vn','MRK',15,29,null,$b$Phung brot ta nây nsŭch ma Brah Yêsu, rteh bôk jêh ri lah: “Hơ hơ! Hơi nơm ŭch rơih ngih brah Yuđa, jêh ri rdâk tay đŏng păng tâm pe nar,$b$,true),
('bunong-vn','MRK',15,30,null,$b$lŏng may rklaih hom may nơm nây jêh ri jŭr tă bơh si tâm rkăng.”$b$,false),
('bunong-vn','MRK',15,31,null,$b$Phung n'gâng kôranh ƀư brah ndrel ma kôranh nchih sămƀŭt tâm ban lĕ tâm lah ndrăng khân păng lah: “Păng tâm rklaih jêh bu êng; ƀiă lah păng mâu dơi tâm rklaih ôh păng nơm.$b$,true),
('bunong-vn','MRK',15,32,null,$b$Ăn Brah Krist, Hađăch Phung Israel, jŭr hom aƀaơ ri tă bơh si tâm rkăng, gay ăn he saơ jêh ri chroh ma păng!” Bar hê bu pâng ta si tâm rkăng ndrel ma Brah Yêsu suai rak ma păng tâm ban lĕ.$b$,false),
('bunong-vn','MRK',15,33,null,$b$Tơ lah tât nklang bôk nar jêh, geh nau ngo klĕng lam neh ntu tât pe mông mhaơ.$b$,true),
('bunong-vn','MRK',15,34,null,$b$Ta pe mông mhaơ Brah Yêsu nter ktang: “Êli, Êli, lama sabaktani?” Nâm bu ntĭt: “Ơ Brah Ndu gâp, Ơ Brah Ndu gâp, mâm ƀư may cha lơi gâp?”$b$,true),
('bunong-vn','MRK',15,35,null,$b$Ƀa ƀă tâm phung gŭ dăch ta nây tăng nau nây, jêh ri lah: “Uănh ri, păng kuăl Y-Êli.”$b$,false),
('bunong-vn','MRK',15,36,null,$b$Geh du huê bunuyh nchuăt hăn sŏk mli, mbŭk tâm dak srat, kât ta chiông tơm treng, nta ăn Brah Yêsu nhêt, jêh ri lah: “Kâp ƀât, ăn he rlong nâl uănh gĭt lah Y-Êli mra văch ntrŭnh păng.”$b$,false),
('bunong-vn','MRK',15,37,null,$b$Jêh ri Brah Yêsu nter huy dŭt dăng jêh ri tăch n'hâm.$b$,true),
('bunong-vn','MRK',15,38,null,$b$Jêh ri bok bu nching tâm trôm ngih brah Yuđa khêk bar buh ntơm bơh klơ njŭr tât tâm dâng.$b$,true),
('bunong-vn','MRK',15,39,null,$b$Du huê kôranh ta han gŭ mpeh pa năp Brah Yêsu, tăng lĕ mâm Păng nter jêh ri saơ păng tăch n'hâm, păng lah: “N'hêl nanê̆ bunuyh aơ jêng Kon Brah Ndu!”$b$,false),
('bunong-vn','MRK',15,40,null,$b$Geh lĕ phung bu ur gŭ bơh ngai n'gơr uănh. Tâm phung nây geh H'Mari Mađala, H'Mari mê̆ Y-Yakơ jê̆, jêh ri Y-Yôsê, manh H'Salômê.$b$,true),
('bunong-vn','MRK',15,41,null,$b$Khân păng pe nuyh hŏ tă tĭng pah kan jêh ma Brah Yêsu dôl Păng gŭ tâm N'gor Galilê. Tâm ban lĕ, geh âk phung bu ur êng văch ndrel ma Brah Yêsu rlet ma ƀon Yêrusalem.$b$,false),
('bunong-vn','MRK',15,42,null,$b$Rnôk nây jêng nar ndrăp nkra, nâm bu ntĭt lor ma nar Saƀat; tơ lah trôk dăch kêng măng,$b$,true),
('bunong-vn','MRK',15,43,null,$b$geh du huê amoh Y-Yôsep, gŭ ƀon Arimathê, jêng du huê nơm tâm chră tâm phung phat dôih, bu yơk ngăn, păng nơm nây lĕ jêng nơm kâp gân ma ƀon bri hađăch Brah Ndu, ƀư nau nănh hăn ma Pilat jêh ri dăn săk jăn Brah Yêsu.$b$,false),
('bunong-vn','MRK',15,44,null,$b$Ƀiă lah Pilat hih rhâl ma Brah Yêsu khĭt gơnh kơt nây. Păng kuăl kôranh ta han rlong nâl ôp păng gĭt lah Brah Yêsu khĭt lĕ jŏ jêh.$b$,false),
('bunong-vn','MRK',15,45,null,$b$Jêh păng lĕ gĭt nanê̆ ma Brah Yêsu lĕ khĭt tĭng nâm kôranh ta han mbơh, păng jao săk jăn Brah Yêsu ma Y-Yôsep.$b$,false),
('bunong-vn','MRK',15,46,null,$b$Y-Yôsep rvăt du blah bok mhay, ntrŭnh săk jăn Brah Yêsu bơh si tâm rkăng, put nklâm Păng ma bok mhay nây, jêh ri njor Păng tâm môch bu lôk jêh tâm lŭ. Jêh ri bu rlă lŭ mlâm rdâl bâr môch.$b$,false),
('bunong-vn','MRK',15,47,null,$b$Pô ri, H'Mari Mađala, n'hanh H'Mari, mê̆ Y-Yôsê hŏ saơ da dê ntŭk bu njor Brah Yêsu.$b$,false),
('bunong-vn','MRK',16,1,null,$b$Tơ lah nar Saƀat lĕ rlau jêh, H'Mari Mađala, H'Mari mê̆ Y-Yakơ, jêh ri H'Salômê rvăt dak si ƀâu kah gay hăn mhĭng săk jăn Brah Yêsu.$b$,true),
('bunong-vn','MRK',16,2,null,$b$Nar rơh nguay tâm du nar ver (nâm bu ntĭt ơm ôi nar pơh), ơm ôi, tô dôl luh nar, pe nuyh tât ntŭk môch.$b$,false),
('bunong-vn','MRK',16,3,null,$b$Tâm lah ndrăng khân păng: “Mbu nơm mra sâm rlă lŭ tă bơh bâr môch ăn ma he?”$b$,false),
('bunong-vn','MRK',16,4,null,$b$Lah khân păng n'gơr uănh, saơ ro lŭ lĕ rlă jêh ri tă bơh bâr môch; pô ri, lŭ nây toyh ngăn.$b$,false),
('bunong-vn','MRK',16,5,null,$b$Dôl khân păng lăp tâm trôm môch, saơ du huê bu klâu ndăm gŭ mpeh pa ma, nsoh ao jâr nglang, Brah Krist ngăn.$b$,false),
('bunong-vn','MRK',16,6,null,$b$Ƀiă lah ô băl lah ma khân păng: “Lơi klach ôh khân ay joi Brah Yêsu ƀon Nasaret, jêng Nơm bu pâng ta si tâm rkăng; Păng lĕ dâk rêh jêh, mâu hôm ta aơ ôh; uănh hom ntŭk bu njor păng.$b$,true),
('bunong-vn','MRK',16,7,null,$b$Ƀiă lah hăn mbơh hom ma oh mon Păng nđâp ma Y-Pêtrôs, Brah Yêsu lĕ hăn tât ta n'gor Galilê lor ma khân may. Ta nây khân may mra saơ Brah Yêsu, nâm bu Păng hŏ mbơh jêh ma khân may.”$b$,false),
('bunong-vn','MRK',16,8,null,$b$Jêh nây khân păng luh tă bơh trôm môch, jêh ri nchuăt du, yor lah khân păng klach nsâr săk jăn krit mƀât ngăn; mâu janh nkoch ma bu ôh, yor lah khân păng klach ngăn.$b$,false),
('bunong-vn','MRK',16,9,null,$b$Pô ri, Brah Yêsu dâk rêh ơm ôi nar rơh nguay tâm nar ver nây (nâm bu ntĭt ơm ôi nar pơh nây), Păng tâm mpơl păng nơm lor lơn ma H'Mari Mađala. Bu ur nây, jêng nơm Brah Yêsu mprơh ngluh jêh pơh nuyh brah mhĭk.$b$,true),
('bunong-vn','MRK',16,10,null,$b$H'Mari Mađala hăn mbơh nau nây ma phung gŭ jêh ndrel ma Brah Yêsu, dôl khân păng klâng khĭt geh nau nhĭm nhhiăng.$b$,false),
('bunong-vn','MRK',16,11,null,$b$Ƀiă lah lah khân păng tăng jêh ma Brah Yêsu lĕ dâk rêh, jêh ri bu ur nây saơ jêh Brah Yêsu, khân păng mâu chroh ôh ma nau nây.$b$,false),
('bunong-vn','MRK',16,12,null,$b$Jêh ta nây, Brah Yêsu sŏk muh măt êng tâm mpơl ma bar hê tâm mpôl oh mon dôl hăn trong sĭt rlet ma ƀon.$b$,true),
('bunong-vn','MRK',16,13,null,$b$Bar hê nây plơ̆ sĭt mbơh nau nây ma phung oh mon êng, ƀiă lah khân păng mâu chroh ôh ma nau khân păng mbơh.$b$,false),
('bunong-vn','MRK',16,14,null,$b$Pa kơi jêh nây Brah Yêsu tâm mpơl đŏng păng nơm ma phung jât ma nguay nuyh dôl khân păng gŭ sông sa. Brah Yêsu nduyh khân păng yor nau khân păng mâu chroh ôh, jêh ri yor nuih n'hâm păng dăng; yor lah khân păng mâu chroh ôh ma phung lĕ saơ jêh Păng, jêh Păng dâk rêh tay.$b$,true),
('bunong-vn','MRK',16,15,null,$b$Brah Yêsu lah ma khân păng: “Hăn hom lam neh ntu jêh ri nti nau mhe mhan ueh ma lĕ rngôch ndŭl mpôl bunuyh.$b$,false),
('bunong-vn','MRK',16,16,null,$b$Mbu nơm chroh jêh ri dơn nau ƀaptem mra klaih; ƀiă lah mbu nơm mâu chroh ôh mra dơn nau tâm rmal.$b$,true),
('bunong-vn','MRK',16,17,null,$b$Pô nây, bu mra ăn nau tâm mbên ma phung chroh kơt aơ: Ma amoh săk gâp khân păng mra mprơh brah mhĭk; khân păng mra ngơi nau bu năch;$b$,false),
('bunong-vn','MRK',16,18,null,$b$khân păng mra djôt bih, jêh ri tơ lah nhêt dak kăch păng, khân păng mâu mra khêh ôh; khân păng mra dra ti ta bunuyh ji kuet, jêh ri khân păng mra bah.”$b$,false),
('bunong-vn','MRK',16,19,null,$b$Pô nây, jêh Brah Yêsu ngơi kơt nây jêh ma khân păng, Brah Ndu chông păng rlet klơ trôk, jêh ri păng gŭ mpeh pa ma Brah Ndu.$b$,true),
('bunong-vn','MRK',16,20,null,$b$Jêh ri khân păng hăn nsong mbơh lam neh ntu, dôl Kôranh Brah pah kan ndrel ma khân păng jêh ri ăn nanê̆ nau păng nti ma nau tâm mbên.$b$,false);
