insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'LUK', $b$Y-Luk$b$, $b$["Nau Mhe Mhan Ueh Tĭng Nâm", "Y-LUK"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','LUK',1,1,null,$b$Geh âk jêh bunuyh pah kan ŭch nchih nkoch bri nau tât tâm phung he,$b$,true),
('bunong-vn','LUK',1,2,null,$b$tĭng nâm phung nây njuăl jêh ma he bơh lor, ri khân păng jêng phung saơ, jêh ri phung nơm nti Nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','LUK',1,3,null,$b$Gâp tâm ban lĕ, mĭn ueh. Hơi Y-Thêôphil, nơm ueh ngăn, jêh gâp sek nanê̆ lĕ rngôch nau nây ntơm bơh tơm, ŭch nchih may ma nau di.$b$,false),
('bunong-vn','LUK',1,4,null,$b$Pô nây may mra gĭt ngăn ma lĕ nau may tăng jêh.$b$,true),
('bunong-vn','LUK',1,5,null,$b$Rnôk Hêrôt jêng hađăch phung Yuđa, geh du huê kôranh ƀư brah amoh păng Y-Sakari, tă bơh phung Abia Ur păng tă bơh mpôl băl Y-Arôn amoh păng H'Êlisabet.$b$,true),
('bunong-vn','LUK',1,6,null,$b$Lĕ khân păng bar hê gŭ sŏng ta năp Brah Ndu, khân păng tĭng ndô̆ nau ngăn lĕ nau vay jêh ri nau Kôranh Brah ntăm.$b$,false),
('bunong-vn','LUK',1,7,null,$b$Ƀiă lah khân păng mâu geh kon ôh, yor lah H'Êlisabet jêng bu ur mâu dơi deh kon, jêh ri lĕ khân păng bar hê ranh jêh da dê.$b$,false),
('bunong-vn','LUK',1,8,null,$b$Pô nây Y-Sakari tĭng lor, nglĕ tâm băl păng, gay ma ƀư Kôranh ƀư brah ta năp Brah Ndu,$b$,true),
('bunong-vn','LUK',1,9,null,$b$tĭng nâm nau vay phung kôranh ƀư brah, kan di ma păng ăn lăp gŭch ndơ ƀâu kah tâm ntŭk kloh Kôranh Brah.$b$,false),
('bunong-vn','LUK',1,10,null,$b$Jêh ri lĕ rngôch pa dih gŭ mbơh sơm dôl gŭch ndơ ƀâu kah.$b$,false),
('bunong-vn','LUK',1,11,null,$b$Ƀât lât geh du huê Tông mpăr ueh Kôranh Brah dâk mpeh bơh ma nơng gŭch ndơ ƀâu kah tâm mpơl ma Y-Sakari.$b$,false),
('bunong-vn','LUK',1,12,null,$b$Jêh saơ Tông mpăr ueh nây păng geh nau uh ah jêh ri klach ngăn.$b$,false),
('bunong-vn','LUK',1,13,null,$b$Ƀiă lah Tông mpăr ueh lah ma păng: “Lơi klach ôh hơi Y-Sakari, yor lah Brah Ndu tăng jêh nau may mbơh sơm, ur may H'Êlisabet mra deh ma du huê kon se jêh ri may mra tâm amoh păng Y-Yôhan.$b$,false),
('bunong-vn','LUK',1,14,null,$b$May mra geh nau răm jêh ri maak ngăn yor nau deh ma păng.$b$,false),
('bunong-vn','LUK',1,15,null,$b$Yor lah păng mra jêng toyh ta năp Kôranh Brah. Păng mâu mra nhêt ndrănh ôh mâu lah dak ƀa ƀă vay ƀư nhŭl bunuyh, jêh ri păng mra bêng ma Brah Huêng Ueh ntơm bơh ndŭl mê̆.$b$,false),
('bunong-vn','LUK',1,16,null,$b$Păng mra njŭn leo âk phung kon Israel ma Kôranh Brah Ndu khân păng.$b$,false),
('bunong-vn','LUK',1,17,null,$b$Păng mra sak nsong ta năp Kôranh Brah, ma nau mĭn jêh ri nau brah Y-Êli gay ma tâm rle nuih n'hâm phung mbơ̆ đah phung kon khân păng, jêh ri phung dăng bôk ma nau gĭt mĭn phung nuih sŏng, gay ma nkra du phung mpôl băl ăn ueh ma Kôranh Brah.”$b$,false),
('bunong-vn','LUK',1,18,null,$b$Y-Sakari lah ma Tông mpăr ueh nây: “Mâm gâp dơi gĭt nau nây? Yor lah gâp ranh jêh, jêh ri ur gâp ranh lĕ.”$b$,false),
('bunong-vn','LUK',1,19,null,$b$Tông mpăr ueh plơ̆ lah ma păng: “Gâp jêng Gabriel, nơm gŭ ta năp Brah Ndu. Njuăl gâp văch mbơh ma may nau mhe mhan ueh aơ.$b$,false),
('bunong-vn','LUK',1,20,null,$b$Nĕ, aơ may mra jêng mlo, jêh ri mâu dơi ngơi ôh tơ lah nau nây tât, yor lah may mâu chroh ma nau gâp ngơi. Nau nây mra jêng ngăn tơ lah tât nar păng.”$b$,false),
('bunong-vn','LUK',1,21,null,$b$Dôl nây bunuyh ƀon lan gŭ kâp Y-Sakari, jêh ri hih rhâl mâm ƀư păng gŭ jŏ tâm ntŭk kloh.$b$,true),
('bunong-vn','LUK',1,22,null,$b$Tơ lah păng du luh păng mâu dơi ngơi đah bu ôh, jêh ri bu gĭt păng hŏ geh nau bu tâm mpơl tâm ntŭk kloh. Păng tâm ntĭt ma phung nây jêh ri păng hôm jêng mlo.$b$,false),
('bunong-vn','LUK',1,23,null,$b$Tơ lah lôch nar păng pah kan ƀư brah, păng sĭt ta ngih păng.$b$,false),
('bunong-vn','LUK',1,24,null,$b$Jŏ djê̆ ma nây, ur păng H'Êlisabet ntreo. Păng gŭ pôn dôl tâm prăm khay, jêh ri păng lah:$b$,false),
('bunong-vn','LUK',1,25,null,$b$“Kôranh Brah ƀư nau yô̆ ma gâp, gay sŏk lơi nau prêng tă bơh gâp ta năp bunuyh.”$b$,false),
('bunong-vn','LUK',1,26,null,$b$Prao khay pa kơi Brah Ndu njuăl Gabriel Tông mpăr ueh păng hăn ta du ƀon tâm n'gor Galilê tâm moh ƀon Nasaret.$b$,true),
('bunong-vn','LUK',1,27,null,$b$Păng hăn ta du huê bu ur druh, tâm mbloh jêh đah du huê, moh Y-Yôsep, tâm mpôl băl Y-Đavit. Bu tâm amoh bu ur druh nây H'Mari.$b$,true),
('bunong-vn','LUK',1,28,null,$b$Tông mpăr ueh lăp tâm ngih păng jêh ri lah ma păng: “Gâp mbah ay, nơm Brah Ndu yô̆, Kôranh Brah gŭ ndrel ma ay!”$b$,false),
('bunong-vn','LUK',1,29,null,$b$Tơ lah H'Mari tăng nau ngơi nây păng geh nau hih rhâl jêh ri ôp êng păng nơm, mâm ƀư geh nau mbah pô nây.$b$,false),
('bunong-vn','LUK',1,30,null,$b$Tông mpăr ueh lah ma păng: “Lơi klach ôh, hơi H'Mari yor lah ay geh jêh nau yô̆ ta năp Brah Ndu.$b$,true),
('bunong-vn','LUK',1,31,null,$b$Nĕ aơ, ay mra ntreo jêh ri deh ma du huê kon ay mra amoh Păng jêng Yêsu.$b$,false),
('bunong-vn','LUK',1,32,null,$b$Păng jêng toyh jêh ri bu mra kuăl ma Păng Kon Nơm Klơ Lơn, jêh ri Brah Ndu mra ăn ma Păng sưng hađăch Y-Đavit, Mbơ̆ Păng.$b$,false),
('bunong-vn','LUK',1,33,null,$b$Păng mra jêng hađăch ƀa ƀơ n'ho ro tâm mpôl băl Y-Yakôp jêh ri ƀon bri hađăch păng mâu blau lôch mâu blau dŭt ôh.”$b$,false),
('bunong-vn','LUK',1,34,null,$b$H'Mari lah ma Tông mpăr ueh nây: “Mâm ƀư nau nây dơi tât? Yor lah gâp ê geh sai?”$b$,false),
('bunong-vn','LUK',1,35,null,$b$Tông mpăr ueh plơ̆ lah ma păng: “Brah Huêng Ueh mra ăn ma ay, jêh ri nau brah tă bơh Nơm Klơ Lơn mra nkŭm ay; yor nây bu mra kuăl Kon Brah Ndu ma Kon Kloh Ueh ay mra deh!$b$,false),
('bunong-vn','LUK',1,36,null,$b$Tari prao khay jêh du huê mpôl băl ay H'Êlisabet ntreo tâm ban lĕ ma du huê kon. Dôl păng lĕ ranh. Păng yơh bu lah jêng bu ur mâu dơi deh kon.$b$,false),
('bunong-vn','LUK',1,37,null,$b$Yor lah mâu geh du ntil ndơ Brah Ndu mâu dơi ƀư.”$b$,false),
('bunong-vn','LUK',1,38,null,$b$H'Mari plơ̆ lah: “Gâp jêng oh mon bu ur ma Kôranh Brah. Ăn nau nây mra tât tĭng nâm nau may lah jêh.” Jêh ri Tông mpăr ueh luh du.$b$,false),
('bunong-vn','LUK',1,39,null,$b$Dôl nây H'Mari dâk hăn ngăch tâm ntŭk yôk ta du ƀon n'gor Yuđa.$b$,true),
('bunong-vn','LUK',1,40,null,$b$Păng lăp tâm ngih Y-Sakari jêh ri mbah ma H'Êlisabet.$b$,false),
('bunong-vn','LUK',1,41,null,$b$Tơ lah H'Êlisabet tăng nau H'Mari mbah, kon păng tâm ndŭl mpât răm rhơn, jêh ri H'Êlisabet bêng ma Brah Huêng Ueh.$b$,false),
('bunong-vn','LUK',1,42,null,$b$Dôl nây păng ngơi huy: “Ay yơh geh nau ueh maak tâm phung bu ur jêh ri kon tă bơh ndŭl ay mra geh nau ueh uĭn!$b$,false),
('bunong-vn','LUK',1,43,null,$b$Mâm ƀư nau aơ tât ma gâp, kŏ mê̆ Kôranh Brah gâp văch dăch ma gâp?$b$,false),
('bunong-vn','LUK',1,44,null,$b$Yor lah tơ lah jêh gâp tăng nau ay mbah ma gâp, kon jê̆ tâm ndŭl gâp mpât rhơn.$b$,false),
('bunong-vn','LUK',1,45,null,$b$Ueh maak yơh ma bu ur geh nau chroh, yor lah nau Kôranh Brah mbơh jêh ma păng mra tât ngăn.”$b$,false),
('bunong-vn','LUK',1,46,null,$b$Jêh ri H'Mari lah: “Nuih n'hâm gâp mĭn ŭch mât ton ma Kôranh Brah.$b$,false),
('bunong-vn','LUK',1,47,null,$b$Jêh ri huêng gâp geh nau maak tâm Brah Ndu, Nơm Tâm Rklaih gâp.$b$,true),
('bunong-vn','LUK',1,48,null,$b$Yor lah păng uănh jêh nau phung Tông mpăr bu ur tông yơk. Aơ lĕ ngôch mpôl băl ma nar kăndơ̆ mra lah ma gâp geh nau răm maak.$b$,true),
('bunong-vn','LUK',1,49,null,$b$Yor lah Nơm Brah ngăn ƀư jêh nau khlay ngăn ma gâp, Amoh Păng kloh ngăn.$b$,true),
('bunong-vn','LUK',1,50,null,$b$Nau Păng yô̆ tât tâm lĕ rngôch rnôk ma phung klach yơk mbah ma Păng.$b$,true),
('bunong-vn','LUK',1,51,null,$b$Păng tâm mpơl jêh nau ktang tă bơh ti Păng, Păng mprơh jêh phung geh nau mĭn sưr.$b$,true),
('bunong-vn','LUK',1,52,null,$b$Păng tŭn ăn tŭp lơi phung ktang tă bơh sưng hađăch khân păng. Jêh ri Păng n'hao phung blau mbah yơk.$b$,true),
('bunong-vn','LUK',1,53,null,$b$Păng n'hơm phung ji ngot ma ndơ kah. Jêh ri Păng mprơh phung ndrŏng jêng dơm dam.$b$,true),
('bunong-vn','LUK',1,54,null,$b$Păng kơl jêh Israel, Tông mpăr Păng. Jêh ri Păng kah gĭt nau Păng yô̆.$b$,true),
('bunong-vn','LUK',1,55,null,$b$Tâm ban ma Păng lah jêh ma phung mbơ̆ he, ma Y-Abraham jêh ri ma phung kon sau Păng ƀa ƀơ ƀa ƀơ.”$b$,true),
('bunong-vn','LUK',1,56,null,$b$H'Mari gŭ ndrel ma H'Êlisabet tâm pe khay. Jêh ri păng plơ̆ sĭt ta ngih păng nơm.$b$,true),
('bunong-vn','LUK',1,57,null,$b$Nar H'Êlisabet n'gơch tât jêh. Păng deh ma du huê kon.$b$,true),
('bunong-vn','LUK',1,58,null,$b$Phung chiau meng jêh ri phung ndŭl mpôl păng tăng nau Kôranh Brah tâm mpơl jêh ma păng, âk nau yô̆ jêh ri khân păng răm maak ndrel ma păng.$b$,false),
('bunong-vn','LUK',1,59,null,$b$Tâm nar pham khân păng văch ŭch koh ntâu kon se jê̆ nây, jêh ri khân păng tâm amoh Y-Sakari, kơt amoh mbơ̆ păng.$b$,true),
('bunong-vn','LUK',1,60,null,$b$Ƀiă lah mê̆ păng lah: “Mâu! Tâm amoh păng Y-Yôhan.”$b$,false),
('bunong-vn','LUK',1,61,null,$b$Bu lah ma păng: “Mâu geh du huê tâm phung khân ay may geh amoh tâm ban pô nây.”$b$,false),
('bunong-vn','LUK',1,62,null,$b$Pô ri khân păng tâm ntĭt ma mbơ̆ păng ŭch gĭt mâm păng ŭch tâm amoh kon se jê̆ nây.$b$,false),
('bunong-vn','LUK',1,63,null,$b$Y-Sakari dăn kđar jê̆ jêh ri nchih pô aơ: “Amoh păng Y-Yôhan.” Jêh ri lĕ rngôch khân păng hih rhâl.$b$,false),
('bunong-vn','LUK',1,64,null,$b$Ƀât lât păng hă mbung, mpiăt păng mpât mprơ, ngơi tâm rnê mât ton ma Brah Ndu.$b$,false),
('bunong-vn','LUK',1,65,null,$b$Lĕ rngôch bunuyh tâm ƀon chiau meng geh nau klach, jêh ri bu nkoch bri ma lĕ rngôch nau nây tâm n'gor yôk Yuđa.$b$,false),
('bunong-vn','LUK',1,66,null,$b$Lĕ rngôch phung tăng nau aơ djôt prăp tâm nuih n'hâm khân păng, jêh ri lah: “Mâm kon se nây mra jêng!” Jêh ri ti Kôranh Brah gŭ ndrel ma păng.$b$,false),
('bunong-vn','LUK',1,67,null,$b$Y-Sakari, mbơ̆ păng bêng ma Brah Huêng Ueh, mbơh lor pô aơ:$b$,true),
('bunong-vn','LUK',1,68,null,$b$“Mât ton ma Kôranh Brah Ndu Israel, yor lah Păng khâl jêh ri tâm chuai jêh phung mpôl băl Păng.$b$,false),
('bunong-vn','LUK',1,69,null,$b$Jêh ri Păng ăn ma he du huê Nơm Tâm Rklaih ma ngih Y-Đavit, oh mon păng.$b$,true),
('bunong-vn','LUK',1,70,null,$b$Tâm ban ma Păng mbơh jêh ma bâr mbung phung Kôranh nơm mbơh lor gŭ ueh ntơm bơh kăl e ri.$b$,true),
('bunong-vn','LUK',1,71,null,$b$Nau rklaih he bơh phung rlăng jêh ri bơh ti lĕ rngôch phung tâm rmot đah he.$b$,true),
('bunong-vn','LUK',1,72,null,$b$Pô ri yơh, Păng tâm mpơl nau Păng yô̆ âk ma phung mbơ̆ he, jêh ri kah gĭt ma nau păng tâm rnglăp kloh ueh.$b$,true),
('bunong-vn','LUK',1,73,null,$b$Tĭng nâm nau păng sân săk đah Y-Abraham, mbơ̆ he.$b$,true),
('bunong-vn','LUK',1,74,null,$b$Jêh Păng ăn he jêng kon me tă bơh ti phung rlăng, Păng mra ăn ma he dơi pah kan ma Păng mâu geh nau klach ôh.$b$,true),
('bunong-vn','LUK',1,75,null,$b$Dôl hăn ta năp Păng tâm nau kloh ueh jêh ri nau sŏng lĕ nar he gŭ rêh.$b$,true),
('bunong-vn','LUK',1,76,null,$b$Bi may, hơi kon se jê̆, bu mra kuăl ma may kôranh nơm mbơh lor ma Nơm ta klơ: Yor lah may mra hăn ta năp Kôranh Brah gay nkra trong Păng.$b$,true),
('bunong-vn','LUK',1,77,null,$b$Ŭch ăn ma phung mpôl băl Păng nau gĭt rbăng ma nau tâm rklaih ma nau yô̆ an nau tih khân păng.$b$,true),
('bunong-vn','LUK',1,78,null,$b$Yor nau yô̆ rdơ̆ rbăn bơh Brah Ndu he. Nar luh jêh ma he tă bơh klơ trôk.$b$,true),
('bunong-vn','LUK',1,79,null,$b$Gay ma sol phung gŭ tâm nau ngo, jêh ri tâm dâng gui nau khĭt. Jêh ri gay ma njŭn leo he hăn tâm trong đăp mpăn.”$b$,true),
('bunong-vn','LUK',1,80,null,$b$Pô ri kon se jê̆ nây văch ma toyh, jêh ri nuih n'hâm mĭn jêng ktang. Păng gŭ tâm bri rdah tât nar păng tâm mpơl păng nơm ma phung Israel.$b$,true),
('bunong-vn','LUK',2,1,null,$b$Rnôk nây Sêsar Ôgust ntăm, đă kơp lĕ rngôch bunuyh tâm neh ntu.$b$,true),
('bunong-vn','LUK',2,2,null,$b$Nau kơp lor lơn nây, dôl Y-Kirinius jêng kôranh toyh chiă uănh n'gor Siri.$b$,false),
('bunong-vn','LUK',2,3,null,$b$Jêh ri lĕ rngôch bu nuyh hăn ta ƀon khân păng nơm, gay đă bu nchih amoh khân păng.$b$,false),
('bunong-vn','LUK',2,4,null,$b$Y-Yôsep tâm ban lĕ tă bơh n'gor Galilê ƀon Nasaret, hăn ta n'gor Yuđa ta ƀon Y-Đavit. Bu rnha ƀon nây Ƀêtlêhem, yor lah păng jêng kon sau jêh ri ndŭl mpôl Y-Đavit,$b$,true),
('bunong-vn','LUK',2,5,null,$b$gay ma nchih amoh păng ndrel ma H'Mari hŏ ndrôi jêh đah Y-Yôsep, păng ntreo jêh.$b$,false),
('bunong-vn','LUK',2,6,null,$b$Dôl khân păng gŭ ta nây, nar H'Mari deh dăch jêh.$b$,false),
('bunong-vn','LUK',2,7,null,$b$Păng deh ma du huê kon bôk rah, păng put ma bok jêh ri lâng tâm hip gơ̆ ndrôk yor lah mâu tŏng ntŭk ma khân păng.$b$,false),
('bunong-vn','LUK',2,8,null,$b$Tâm n'gor nây geh phung rmăk biăp gŭ tâm ntŭk rdah, gŭ rngeh măng, chiă biăp khân păng.$b$,true),
('bunong-vn','LUK',2,9,null,$b$Aơ, geh du huê Tông mpăr ueh Kôranh Brah tâm mpơl ma khân păng. Nau chrêk rmah Kôranh Brah nchrat ang jŭm khân păng, jêh ri khân păng klach hâu ngăn.$b$,false),
('bunong-vn','LUK',2,10,null,$b$Ƀiă lah Tông mpăr ueh lah ma khân păng: “Lơi klach ôh, gâp mbơh ma khân may, nau mhe mhan ueh mra ƀư maak ma lĕ rngôch bunuyh$b$,false),
('bunong-vn','LUK',2,11,null,$b$nar aơ tâm ƀon Y-Đavit, bu deh jêh ma khân may du huê Nơm Tâm Rklaih jêng Brah Krist, Kôranh Brah.$b$,false),
('bunong-vn','LUK',2,12,null,$b$Jêh ri pô aơ, nau khân may tâm mbên, khân may mra saơ du huê kon se jê̆ put ma bok gŭ bêch tâm hip gơ̆ ndrôk.”$b$,false),
('bunong-vn','LUK',2,13,null,$b$Ƀât lât geh ndrel ma Tông mpăr ueh nây rmưn rsen phung tă bơh trôk, mât ton tâm rnê ma Brah Ndu jêh ri lah:$b$,false),
('bunong-vn','LUK',2,14,null,$b$“Tâm rnê ma Brah Ndu tâm ntŭk dŭt prêh klơ, ăn nau đăp mpăn ma lĕ rngôch kon bunuyh ma phung ueh măt Păng uănh!”$b$,false),
('bunong-vn','LUK',2,15,null,$b$Tơ lah phung Tông mpăr ueh plơ̆ sĭt ta klơ trôk, phung rmăk biăp tâm lah ndrăng khân păng: “Kay lŏng he hăn tât ta ƀon Ƀêtlêhem, uănh nau hŏ tât jêh, tĭng nâm Kôranh Brah mbơh jêh ma he.”$b$,true),
('bunong-vn','LUK',2,16,null,$b$Khân păng hăn ma nau ndal, tât ta ƀon jêh ri khân păng saơ H'Mari, Y-Yôsep, jêh ri kon se jê̆ gŭ bêch tâm hip gơ̆ ndrôk.$b$,false),
('bunong-vn','LUK',2,17,null,$b$Jêh saơ, khân păng nkoch bri mâm nau bu mbơh jêh ma khân păng, di ma kon se jê̆ nây.$b$,false),
('bunong-vn','LUK',2,18,null,$b$Lĕ rngôch phung tăng nau phung rmăk biăp nkoch bri, geh nau hih rhâl da dê.$b$,false),
('bunong-vn','LUK',2,19,null,$b$Ƀiă lah H'Mari djôt prăp lĕ nau nkoch bri nây tâm nuih n'hâm păng.$b$,false),
('bunong-vn','LUK',2,20,null,$b$Phung rmăk biăp plơ̆ sĭt, khân păng mât ton tâm rnê ma Brah Ndu, yor lĕ nau khân păng tăng jêh ri saơ di tĭng nâm nau bu mbơh jêh ma khân păng.$b$,false),
('bunong-vn','LUK',2,21,null,$b$Ta nar pham bu koh ntâu kon se jê̆ nây, jêh ri tâm amoh Păng jêng Yêsu tĭng nâm Tông mpăr ueh mbơh jêh lor ma mê̆ Păng dôl ntreo.$b$,true),
('bunong-vn','LUK',2,22,null,$b$Tơ lah tât nar khân păng ƀư nau kloh, tĭng nâm nau vay Y-Môis, Y Yôsep ndrel ma H'Mari njŭn leo Păng ta ƀon Yêrusalem gay ma nhhơr ma Kôranh Brah.$b$,true),
('bunong-vn','LUK',2,23,null,$b$(Tâm ban ma bu nchih jêh tâm nau vay Kôranh Brah: “Lĕ ngôch kon bôk rah, bu mra rnha kloh ueh ma Kôranh Brah”)$b$,false),
('bunong-vn','LUK',2,24,null,$b$Jêh ri gay ma nhhơr ndơ ƀư brah tĭng nâm nau vay Kôranh Brah ntăm, bar mlâm plŭk mâu lah bar mlâm ntơp.$b$,false),
('bunong-vn','LUK',2,25,null,$b$Ta ƀon Yêrusalem geh du huê amoh păng Y-Simêôn. Păng jêng sŏng srăng jêh ri kloh ueh. Păng gŭ kâp nau bonh leng phung Israel, jêh ri Brah Huêng Ueh gŭ ta klơ păng.$b$,true),
('bunong-vn','LUK',2,26,null,$b$Brah Huêng Ueh mbơh jêh ma păng mâu mra khĭt ôh lor ma saơ Brah Krist, Kôranh Brah.$b$,false),
('bunong-vn','LUK',2,27,null,$b$Brah Huêng Ueh ntrôl păng hăn ta ngih brah Yuđa, dôl mê̆ mbơ̆ păng njŭn kon se jê̆, Brah Yêsu ŭch ƀư tĭng nâm nau vay hŏ ntăm jêh,$b$,false),
('bunong-vn','LUK',2,28,null,$b$Păng chông kon se jê̆ nây tâm ti, tâm rnê ma Brah Ndu jêh ri lah:$b$,false),
('bunong-vn','LUK',2,29,null,$b$“Aƀaơ, Ơi Kôranh Brah, ăn oh mon may hăn ma nau đăp mpăn, tĭng nâm nau may hŏ ngơi jêh.$b$,false),
('bunong-vn','LUK',2,30,null,$b$Yor lah măt gâp saơ jêh nau tâm rklaih bơh may.$b$,true),
('bunong-vn','LUK',2,31,null,$b$May nkra jêh ta năp lĕ rngôch bunuyh.$b$,true),
('bunong-vn','LUK',2,32,null,$b$Nau ang mra sol phung bu năch jêh ri nau chrêk rmah phung Israel, mpôl băl may.”$b$,true),
('bunong-vn','LUK',2,33,null,$b$Mê̆ mbơ̆ Păng hih rhâl, yor nau bu lah ma khân păng.$b$,true),
('bunong-vn','LUK',2,34,null,$b$Y-Simêôn mât ton ma khân păng jêh ri lah ma H'Mari, mê̆ Păng: “Aơ, săch jêh ma kon aơ, ăn Păng njŭn âk phung Israel ma nau tŭp, jêh ri ma nau rdâk tay. Jêh ri jêng nau tâm mbên ăn bu tâm rdâng.$b$,false),
('bunong-vn','LUK',2,35,null,$b$Jêh ri ma may nơm, du n'gâr đao gưm bu ntâp huêng ay. Gay ma nau mĭn tâm âk nuih n'hâm bunuyh mra tâm mpơl.”$b$,false),
('bunong-vn','LUK',2,36,null,$b$Jêh ri geh lĕ du huê Kôranh nơm mbơh lor bu ur H'An, kon bu ur Y-Panuel mpôl băl Aser. Păng ranh ngăn jêh gŭ ndrel sai păng pơh năm ntơm bơh păng druh,$b$,true),
('bunong-vn','LUK',2,37,null,$b$jêh ri jêng bu ur ndrô tât păng geh pham jât ma puăn năm. Păng mâu mâp luh du tă bơh ngih brah Yuđa ôh, jêh ri yơk tâm rnê ma Brah Ndu măng nâm nar, ma nau ver sông sa jêh ri mbơh sơm.$b$,false),
('bunong-vn','LUK',2,38,null,$b$Jêh ri tâm mông nây lĕ păng văch tâm rnê ma Brah Ndu, jêh ri ngơi đah Brah Yêsu ma lĕ rngôch phung gŭ kâp nau kon me, ma ƀon Yêrusalem.$b$,false),
('bunong-vn','LUK',2,39,null,$b$Jêh khân păng ƀư lĕ tĭng nâm nau vay Kôranh Brah, Y-Yôsep ndrel ma H'Mari plơ̆ sĭt ta n'gor Galilê, ƀon Nasaret, ƀon khân păng nơm.$b$,true),
('bunong-vn','LUK',2,40,null,$b$Kon se jê̆ nây văch ma toyh, jêng ktang, bêng ma nau gĭt mĭn jêh ri nau Brah Ndu yô̆ gŭ ndrel ma Păng.$b$,false),
('bunong-vn','LUK',2,41,null,$b$Ăp năm mê̆ mbơ̆ Brah Yêsu hăn ta ƀon Yêrusalem tâm nar nhêt sa Nau Găn.$b$,true),
('bunong-vn','LUK',2,42,null,$b$Dôl nôk Brah Yêsu tât jât ma bar năm jêh, khân păng hăn ta ƀon Yêrusalem tĭng nau vay.$b$,false),
('bunong-vn','LUK',2,43,null,$b$Tơ lah nau nhêt sa lôch jêh, dôl khân păng sĭt, Brah Yêsu gŭ ta ƀon Yêrusalem, jêh ri mê̆ mbơ̆ Păng mâu gĭt ôh nau nây.$b$,true),
('bunong-vn','LUK',2,44,null,$b$Khân păng ntôn lah Brah Yêsu hăn ndrel ma phung băl păng rŏ trong, pô ri khân păng hăn lĕ du nar jêh ri joi Brah Yêsu tâm phung băl păng gĭt năl.$b$,true),
('bunong-vn','LUK',2,45,null,$b$Lah khân păng mâu saơ Brah Yêsu, khân păng plơ̆ ta ƀon Yêrusalem joi Brah Yêsu.$b$,false),
('bunong-vn','LUK',2,46,null,$b$Rlau tâm pe nar mê̆ mbơ̆ Păng saơ Brah Yêsu tâm ngih Brah Yuđa gŭ tâm nklang Kôranh nơm nti toyh. Păng gŭ iăt nau phung nây nti, jêh ri Păng ôp.$b$,false),
('bunong-vn','LUK',2,47,null,$b$Jêh ri lĕ rngôch phung gŭ iăt nau phung ngơi hih rhâl ngăn, ma nau Păng blau mĭn jêh ri ma nau Păng plơ̆ lah.$b$,false),
('bunong-vn','LUK',2,48,null,$b$Lah saơ Brah Yêsu, khân păng hih rhâl jêh ri mê̆ Păng lah: “Hơi nâu, mâm ƀư may ƀư ma hên nâm nđĕ? Aơ, gâp ndrel mbơ̆ may tĭng joi may ma nau rngot rvê ngăn.”$b$,true),
('bunong-vn','LUK',2,49,null,$b$Brah Yêsu lah ma khân păng: “Mâm ƀư khân ay may joi gâp? Khân ay may mâu gĭt hĕ gâp pah kan ma Mbơ̆ gâp?”$b$,true),
('bunong-vn','LUK',2,50,null,$b$Ƀiă lah khân păng mâu gĭt rbăng ôh mâm nau Păng lah.$b$,false),
('bunong-vn','LUK',2,51,null,$b$Jêh ri Brah Yêsu hăn ndrel ma khân păng ta ƀon Nasaret, Păng tông nau mbơ̆ mê̆ Păng. Mê̆ Păng djôt prăp lĕ nau kon păng ngơi tâm nuih n'hâm păng.$b$,true),
('bunong-vn','LUK',2,52,null,$b$Brah Yêsu văch ma toyh tâm nau gĭt mĭn, tâm săk jăn, jêh ri tâm nau yô̆ ta năp Brah Ndu jêh ri ta năp bunuyh.$b$,true),
('bunong-vn','LUK',3,1,null,$b$Tâm năm jât ma prăm, Sêsar Tiber chiă uănh, tơ lah Pôns Pilat jêng Kôranh toyh ma n'gor Yuđa, Hêrôt chiă uănh n'gor Galilê jêh ri oh păng, Y-Philip chiă uănh n'gor Iturê jêh ri n'gor Trakônit Y-Lisanius chiă uănh n'gor Abilen,$b$,true),
('bunong-vn','LUK',3,2,null,$b$tâm rnôk Y-Anas jêh ri Y-Kaip jêng Kôranh ƀư brah toyh. Brah Ndu ngơi ma Y-Yôhan, kon Y-Sakari, tâm bri rdah.$b$,false),
('bunong-vn','LUK',3,3,null,$b$Jêh ri păng hăn lĕ n'gor jŭm dak krong Yurdan, nti lah nau ƀaptem ma nau rmal nau tih, gay geh nau yô̆ an nau tih,$b$,false),
('bunong-vn','LUK',3,4,null,$b$tĭng nâm nau nchih jêh tâm ndrom sămƀŭt kôranh nơm mbơh lor Y-Êsai: “Geh bâr nter tâm bri rdah: Nkra hom trong Kôranh Brah, ƀư ăn lâng trong păng.$b$,false),
('bunong-vn','LUK',3,5,null,$b$Lĕ rngôch rlŭng mra bŏl lơi, lĕ rngôch yôk jêh ri kô neh mra jêng lâng, jêh ri ndơ kue mra jêng sŏng. Jêh ri trong nduh ndăp mra ƀư ăn lâng.$b$,true),
('bunong-vn','LUK',3,6,null,$b$Jêh ri lĕ rngôch ntil nglay săk mra saơ nau tâm rklaih tă bơh Brah Ndu.”$b$,true),
('bunong-vn','LUK',3,7,null,$b$Pô ri Yôhan lah ma phung âk, văch gay ma đă păng ƀư ƀaptem: “Hơi mpôl băl bêh rmâng, mbu đă khân may der nau Brah Ndu nuih mra tât?$b$,true),
('bunong-vn','LUK',3,8,null,$b$Ăn khân may geh rplay khlay, khư ma nau tâm rmal nau tih, jêh ri lơi lah tâm khân may nơm: ‘Hên geh Y-Abraham jêng mbơ̆ hên,’ yor lah gâp mbơh ma khân may, Brah Ndu dơi njêng lŭ aơ jêng kon sau Y-Abraham.$b$,false),
('bunong-vn','LUK',3,9,null,$b$Yor ri bu dơm jêh sung ta reh si, tơm si mâu geh play ueh, bu mra kăl lơi, su tâm ŭnh?”$b$,false),
('bunong-vn','LUK',3,10,null,$b$Phung âk nây ôp păng pô aơ: “Mâm hên mra ƀư mih?”$b$,true),
('bunong-vn','LUK',3,11,null,$b$Păng plơ̆ lah ma phung nây: “Mbu nơm geh bar blah ao mbâl ăn păng tâm pă ma nơm mâu hŏ geh; jêh ri mbu nơm geh ndơ sông sa ƀư tâm ban lĕ.”$b$,false),
('bunong-vn','LUK',3,12,null,$b$Phung riu pi văch tâm ban lĕ gay ma dơn nau ƀaptem, jêh ri khân păng lah ma Y-Yôhan: “Hơi Kôranh nơm nti, mâm hên mra ƀư?”$b$,true),
('bunong-vn','LUK',3,13,null,$b$Păng plơ̆ lah ma phung nây: “Lơi sŏk âk ir ma rnoh bu hŏ ntăm jêh ma khân may.”$b$,false),
('bunong-vn','LUK',3,14,null,$b$Phung ta han ôp ma păng tâm ban lĕ: “Bi hên, mâm hên mra ƀư?” Păng plơ̆ lah: “Lơi ta sŏk nchâp mâu lĕ dơi sŏk ndơ bu ma nau ndơm, jêh ri dơn ma nau maak, prăk khay khân may hŏ geh jêh.”$b$,false),
('bunong-vn','LUK',3,15,null,$b$Dôl phung âk kâp gân, jêh ri lĕ rngôch bunuyh tâm ôp êng tâm nuih n'hâm khân păng nơm gĭt Y-Yôhan jêng Brah Krist.$b$,true),
('bunong-vn','LUK',3,16,null,$b$Y-Yôhan lah ma lĕ ngôch: “Gâp ƀư ƀaptem ma khân may ma dak, ƀiă lah geh du huê brah lơn ma gâp mra văch jêh ri gâp mâu khư ôh doh rse ntâu jot Păng. Păng mra ƀư ƀaptem ma khân may ma Brah Huêng Ueh, jêh ri ma ŭnh.$b$,true),
('bunong-vn','LUK',3,17,null,$b$Ti păng djôt dông nsiăng, gay ma mpruh ăn kloh ntŭk Păng plên ba, jêh ri păng rgum ba tâm jay Păng, ƀiă lah, Păng mra su lơi njôk ma ŭnh mâu blau ngôm ôh.”$b$,false),
('bunong-vn','LUK',3,18,null,$b$Pô ri âk ntil ƀa ƀă păng nti lah nau mhe mhan ueh ma phung ƀon lan.$b$,true),
('bunong-vn','LUK',3,19,null,$b$Ƀiă lah yor Y-Yôhan nduyh Hêrôt ma nau đah H'Hêrôdias ur oh păng, ndrel ma âk nau mhĭk păng ƀư,$b$,false),
('bunong-vn','LUK',3,20,null,$b$Hêrôt ntop đŏng lĕ nau tih ƀa ƀă, nau păng nhŭp Y-Yôhan krŭng tâm ndrung.$b$,false),
('bunong-vn','LUK',3,21,null,$b$Jêh lĕ rngôch bunuyh dơn nau ƀaptem, nđâp ma Brah Yêsu dơn nau ƀaptem tâm ban lĕ, jêh ri dôl Păng mbơh sơm trôk pơk tâm mpôl,$b$,true),
('bunong-vn','LUK',3,22,null,$b$jêh ri Brah Huêng Ueh jŭr ta Păng tâm ban ma du mlâm plŭk, jêh ri bu tăng bâr ngơi tă bơh trôk pô aơ: “May jêng Kon gâp rŏng hâu ngăn, tâm may gâp geh nau maak hâu ngăn.”$b$,false),
('bunong-vn','LUK',3,23,null,$b$Brah Yêsu geh klăp lah tâm pe jât năm, tơ lah dôl Păng ntơm nti lah. Tĭng nâm bu mĭn, Păng jêng kon Y-Yôsep, Y-Yôsep jêng kon Y-Hêli.$b$,true),
('bunong-vn','LUK',3,24,null,$b$Y Hêli jêng kon Y-Mathat, Y-Mathat jêng kon Y-Lêvi, Y-Lêvi jêng kon Y-Mêlki, Y-Mêlki jêng kon Y-Yanai, Y-Yanai jêng kon Y-Yôsep,$b$,false),
('bunong-vn','LUK',3,25,null,$b$Y-Yôsep jêng kon Y-Matathias, Y-Matathias jêng kon Y-Amôs, Y-Amôs jêng kon Y-Nahum, Y-Nahum jêng kon Y-Êsli, Y-Êsli jêng kon Y-Nagai,$b$,false),
('bunong-vn','LUK',3,26,null,$b$Y-Nagai jêng kon Y-Math, Y-Math jêng kon Y-Matathias, Y-Matathias jêng kon Y-Sêmi, Y-Sêmi jêng kon Y-Yôsek, Y-Yôsek jêng kon Y-Yôda,$b$,false),
('bunong-vn','LUK',3,27,null,$b$Y-Yôda jêng kon klâu Y-Yôanan, Y-Yôanan jêng kon Y-Rêsa, Y-Rêsa jêng kon Y-Sôrôƀaƀel, Y-Sôrôƀaƀel jêng kon Y-Salathiel, Y-Salathiel jêng kon Y-Nêri.$b$,false),
('bunong-vn','LUK',3,28,null,$b$Y-Nêri jêng kon Y-Mêlki, Y-Mêlki jêng kon Y-Adi, Y-Adi jêng kon Y-Kôsan, Y-Kôsan jêng kon Y-Êlmadam, Y-Êlmadam jêng kon Y-Er,$b$,true),
('bunong-vn','LUK',3,29,null,$b$Y-Er jêng kon Y-Yêsu, Y-Yêsu kon Y-Êliêsar, Y-Êliêsar jêng kon Yôrim, Yôrim jêng kon Y-Mathat, Y-Mathat jêng kon Y-Lêvi,$b$,false),
('bunong-vn','LUK',3,30,null,$b$Y-Lêvi jêng kon Y-Simêôn, Y-Simêôn jêng kon Y-Yuđas, Y-Yuđas jêng kon Y-Yôsep, Y-Yôsep jêng kon Y-Yônam, Y-Yônam jêng kon Y-Êliakim,$b$,false),
('bunong-vn','LUK',3,31,null,$b$Y-Êliakim jêng kon Y-Mêlêa, Y-Mêlêa jêng kon Y-Mêna, Y-Mêna jêng kon Matatha, Y-Matatha jêng kon Y-Nathan, Y-Nathan jêng kon Y-Đavit,$b$,false),
('bunong-vn','LUK',3,32,null,$b$Y-Đavit jêng kon Y-Yêsê, Y-Yêsê jêng kon Y-Ôbet, Y-Ôbet jêng kon Y-Bôas, Y-Bôas jêng kon Y-Salmôn, Y-Salmôn jêng kon Y-Nahsôn, Y-Nahsôn jêng kon Y-Aminadap,$b$,false),
('bunong-vn','LUK',3,33,null,$b$Y-Aminadap jêng kon Y-Armin, Y-Armin jêng kon Y Êsrôm, Y-Êsrôm jêng kon Y-Parês, Y-Parês jêng kon Y-Yuđa,$b$,false),
('bunong-vn','LUK',3,34,null,$b$Y-Yuđa jêng kon Y-Yakôp, Y-Yakôp jêng kon Y-Isăk, Y-Isăk jêng kon Y-Abraham, Y-Abraham jêng kon Y-Têra, Y-Têra jêng kon Y-Nakôr,$b$,false),
('bunong-vn','LUK',3,35,null,$b$Y-Nakôr jêng kon Y-Sêruk, Y-Sêruk jêng kon Y-Rêu, Y-Rêu jêng kon Y-Palek, Y-Palek jêng kon Y-Êber, Y-Êber jêng kon Y-Sala,$b$,false),
('bunong-vn','LUK',3,36,null,$b$Y-Sala jêng kon Y-Kainan, Y-Kainan jêng kon Y-Arpasal, Y-Arpasal jêng kon Y-Sem, Y-Sem jêng kon Y-Nôê, Y-Nôê jêng kon Y-Lamek,$b$,false),
('bunong-vn','LUK',3,37,null,$b$Y-Lamek jêng kon Y-Mêthusêla, Y-Mêthusêla jêng kon Y-Ênok, Y-Ênok jêng kon Y-Mahalalel, Y-Mahalalel jêng kon Y-Kainan,$b$,false),
('bunong-vn','LUK',3,38,null,$b$Y-Kainan jêng kon Y-Ênôs, Y-Ênôs jêng kon Y Set, Y Seth jêng kon Y-Ađam, Y-Ađam jêng kon Brah Ndu.$b$,false),
('bunong-vn','LUK',4,1,null,$b$Brah Yêsu bêng ma Brah Huêng Ueh, sĭt tă bơh dak krong Yurdan, jêh ri Brah Huêng Ueh njŭn leo Păng tâm bri rdah.$b$,true),
('bunong-vn','LUK',4,2,null,$b$Ta nây brah mhĭk ndơm Păng tâm puăn jât nar. Păng mâu geh sông sa ôh tâm puăn jât nar nây, jêh ri lôch nar nây Păng ji ngot.$b$,false),
('bunong-vn','LUK',4,3,null,$b$Brah mhĭk lah ma Păng: “Tơ lah may jêng Kon Brah Ndu, đă lŭ aơ plăch tay jêng kapŭng.”$b$,false),
('bunong-vn','LUK',4,4,null,$b$Brah Yêsu plơ̆ lah ma păng: “Bu nchih jêh pô aơ: ‘Bunuyh gŭ rêh mâu di knŏng sa kapŭng ôh.’ ”$b$,false),
('bunong-vn','LUK',4,5,null,$b$Brah mhĭk chông Păng ta klơ, ntĭm ma Păng lĕ rngôch ƀon bri hađăch tâm neh ntu jêh ri lah:$b$,false),
('bunong-vn','LUK',4,6,null,$b$“Gâp mra ăn ma may lĕ nau dơi aơ jêh ri nau chrêk rmah phung ƀon bri hađăch nây, yor lah bu jao jêh ma gâp, jêh ri gâp ăn ma mbu nơm gâp ŭch.$b$,false),
('bunong-vn','LUK',4,7,null,$b$Pô ri tơ lah may yơk mbah ta năp gâp, gâp mra ăn lĕ ma may.”$b$,false),
('bunong-vn','LUK',4,8,null,$b$Brah Yêsu plơ̆ lah ma păng. Bu hŏ nchih jêh pô aơ: “May mra mbah yơk ma kôranh Brah Ndu may, jêh ri may knŏng pah kan ma păng yơh.”$b$,true),
('bunong-vn','LUK',4,9,null,$b$Jêh nây brah mhĭk njŭn leo Păng ta ƀon Yêrusalem, ăn Păng hao ta klơ ngih Brah Yuđa, jêh ri lah: “Tơ lah may jêng kon Brah Ndu, may ntŭp săk tă bơh aơ tât ta neh.$b$,false),
('bunong-vn','LUK',4,10,null,$b$Yor lah bu hŏ nchih jêh pô aơ: ‘Păng mra ntăm ma phung Tông mpăr ueh păng đă mât mơh may,’$b$,false),
('bunong-vn','LUK',4,11,null,$b$‘jêh ri khân păng mra chông may tâm ti khân păng, klach lah nchênh jâng may ma lŭ.’$b$,false),
('bunong-vn','LUK',4,12,null,$b$Brah Yêsu plơ̆ lah ma Păng: “Bu nchih jêh pô aơ: ‘Lơi ta may rlong uănh kôranh Brah Ndu may ôh.’ ”$b$,false),
('bunong-vn','LUK',4,13,null,$b$Jêh păng ndơm ma lĕ nau nây, brah mhĭk du tă bơh Păng dôl kâp tâm mông găl.$b$,false),
('bunong-vn','LUK',4,14,null,$b$Ma nau Brah tă bơh Brah Huêng Ueh Brah Yêsu, plơ̆ sĭt ta n'gor Galilê, jêh ri bu tăng lư Păng lam n'gor dơh dăch.$b$,true),
('bunong-vn','LUK',4,15,null,$b$Păng nti lah tâm ngih brah Yuđa khân păng, jêh ri lĕ rngôch bunuyh mât ton tâm rnê ma Păng.$b$,false),
('bunong-vn','LUK',4,16,null,$b$Păng sĭt ta ƀon Nasaret, ntŭk bu mât rong Păng, jêh ri tĭng nâm nau vay Păng, nar Saƀat Păng lăp tâm ngih rƀŭn phung Yuđa. Păng gŭ dâk ŭch uănh sămƀŭt.$b$,true),
('bunong-vn','LUK',4,17,null,$b$Bu ăn ma Păng, ndrom sămƀŭt kôranh nơm mbơh lor Y-Êsai. Păng pơk ndrom sămƀŭt nây, saơ geh nau nchih pô aơ:$b$,false),
('bunong-vn','LUK',4,18,null,$b$“Huêng Brah, Kôranh Brah gŭ tâm gâp. Yor lah Păng tŏ dak ngi ta gâp jêh ri gâp mbơh nau mhe mhan ueh ma phung o ach.$b$,false),
('bunong-vn','LUK',4,19,null,$b$Păng njuăl gâp gay ma mbơh phung bu krŭng dơi luh du, phung chieh măt dơi saơ ang, phung bu tŭn jot dơi jêng kon me, jêh ri mbơh nôk Kôranh Brah mra tâm rklaih phung ƀon lan Păng.”$b$,true),
('bunong-vn','LUK',4,20,null,$b$Jêh ri Păng klôt lơi ndrom sămƀŭt ăn ma du huê nơm mât mray, jêh ri gŭ. Lĕ rngôch phung tâm ngih rƀŭn Yuđa gŭ uănh ma Păng da dê.$b$,true),
('bunong-vn','LUK',4,21,null,$b$Păng lah ma phung nây pô aơ: “Nar aơ tât jêh nau khân păng tăng tă bơh nau bu hŏ nchih aơ.”$b$,false),
('bunong-vn','LUK',4,22,null,$b$Lĕ rngôch mbơh nau Păng, jêh ri hih rhâl ma nau ngơi yô̆ luh bơh bâr mbung Păng, khân păng lah: “Mâu di hĕ Păng jêng kon Y-Yôsep?”$b$,true),
('bunong-vn','LUK',4,23,null,$b$Brah Yêsu lah ma khân păng: “Nanê̆ khân may mra lah, nau hôr aơ ma gâp. Hơi Kôranh dak si, ƀư bah hom may nơm; ƀư ta aơ, tâm n'gor may nơm, lĕ nau hên tăng ƀư jêh ta ƀon Kapernum.”$b$,false),
('bunong-vn','LUK',4,24,null,$b$Jêh ri Păng lah: “Nanê̆ gâp lah ma khân may: Mâu geh du huê kôranh nơm mbơh lor, bu mâp rom ueh tâm n'gor Păng nơm.$b$,true),
('bunong-vn','LUK',4,25,null,$b$Ƀiă lah gâp lah ma khân may nanê̆, rnôk Y-Êli geh âk phung bu ur khĭt sai tâm n'gor Israel, dôl trôk prăng pe năm prao khay, jêh ri geh nau ji ngot toyh lam bri neh;$b$,true),
('bunong-vn','LUK',4,26,null,$b$ƀiă lah bu mâu njuăl Y-Êli ma khân păng ôh, knŏng ma du huê bu ur khĭt sai ta ƀon Sêrêpta tâm n'gor Sidôn.$b$,false),
('bunong-vn','LUK',4,27,null,$b$Geh âk bunuyh phŭng sa tâm n'gor Israel rnôk Y-Êlisê, kôranh nơm mbơh lor, ƀiă lah mâu geh du huê tâm phung khân păng bu ƀư kloh, knŏng Y-Naman tă bơh n'gor Siri.”$b$,false),
('bunong-vn','LUK',4,28,null,$b$Jêh khân păng tăng nau nây, lĕ rngôch khân păng tâm ngih tâm rƀŭn Yuđa, bêng ma nau nuih janh da dê.$b$,true),
('bunong-vn','LUK',4,29,null,$b$Khân păng nhŭp Brah Yêsu, njŭn leo ta klơ chor yôk, ntŭk khân păng ƀư ƀon, gay ma nklơ̆ ăn tŭp tâm dâng.$b$,false),
('bunong-vn','LUK',4,30,null,$b$Ƀiă lah Brah Yêsu, rgăn ta nklang khân păng jêh ri du.$b$,false),
('bunong-vn','LUK',4,31,null,$b$Păng jŭr hăn ta ƀon Kapernum tâm n'gor Galilê, jêh ri nar Saƀat Păng nti.$b$,true),
('bunong-vn','LUK',4,32,null,$b$Bu hih rhâl ngăn ma nau Păng nti, yor lah Păng ngơi ma nau dơi!$b$,false),
('bunong-vn','LUK',4,33,null,$b$Tâm ngih rƀŭn phung Yuđa geh du huê bunuyh brah mhĭk ƀơ̆ lơh, păng nter huy ngăn,$b$,true),
('bunong-vn','LUK',4,34,null,$b$“Moh nau hên geh đah may hơi Brah Yêsu ƀon Nasaret? May văch gay ma ƀư rai hên bơh? Gâp gĭt mbu may jêng, Nơm Kloh Ueh bơh Brah Ndu!”$b$,false),
('bunong-vn','LUK',4,35,null,$b$Brah Yêsu buay păng jêh ri lah: “May gŭ rklăk hŏ luh du hom may bơh bunuyh aơ!” Jêh brah mhĭk nklơ̆ păng ta nklang phung gŭ rƀŭn, păng luh du tă bơh bunuyh nây, mâu geh ƀư du ntil nau mhĭk ma bunuyh nây.$b$,false),
('bunong-vn','LUK',4,36,null,$b$Lĕ rngôch khân păng hih rhâl ngăn jêh ri tâm lah ndrăng khân păng: “Moh nau ngơi aơ.” Ma nau dơi jêh ri nau brah Păng lah ma phung brah mhĭk ƀơ̆ , jêh ri khân păng luh du.$b$,true),
('bunong-vn','LUK',4,37,null,$b$Pô ri yơh bu tăng lư ma Păng ăp ntŭk dăch.$b$,false),
('bunong-vn','LUK',4,38,null,$b$Păng luh tă bơh ngih tâm rƀŭn Yuđa, hăn ta ngih Y-Simôn. Po bu ur Y-Simôn geh nau ji ktang ngăn, khân păng vơh vơl ma Brah Yêsu kơl an.$b$,true),
('bunong-vn','LUK',4,39,null,$b$Păng hăn dăch buay lơi nau ji, jêh ri nơm nây bah ro. Ƀât lât păng dâk dơi pah kan nâm ơm.$b$,false),
('bunong-vn','LUK',4,40,null,$b$Tât nar nhâp, lĕ phung geh bunuyh ji kuet, geh nau ji êng êng, njŭn leo ma kôranh Brah Yêsu. Păng Pah ma ti ta săk ăp nơm, jêh ri lĕ rngôch dơi bah da dê.$b$,true),
('bunong-vn','LUK',4,41,null,$b$Nđâp ma brah mhĭk luh du tă bơh âk bunuyh nter, jêh ri lah: “May jêng Kon Brah Ndu!” Ƀiă lah Brah Yêsu buay khân păng mâu ăn ngơi ôh. Yor lah Păng gĭt năl phung nây, gĭt jêh Păng jêng Brah Krist.$b$,false),
('bunong-vn','LUK',4,42,null,$b$Tât nar luh, Păng hăn tâm ntŭk bri rdah. Geh âk bunuyh joi Păng. Khân păng ban Brah Yêsu, kân păng gŭ mâu ŭch ăn Păng du ôh.$b$,true),
('bunong-vn','LUK',4,43,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Gâp mbơh lĕ nau mhe mhan ueh, ƀon bri hađăch Brah Ndu ma ƀon êng, yor lah ma nau nây yơh bu njuăl gâp văch.”$b$,false),
('bunong-vn','LUK',4,44,null,$b$Jêh ri Păng nti tâm ngih rƀŭn phung Yuđa n'gor Galilê.$b$,true),
('bunong-vn','LUK',5,1,null,$b$Dôl Brah Yêsu gŭ dăch dak nglao Gênêsaret, geh âk bunuyh gŭ rƀŭn jŭm Păng, ŭch iăt Nau Brah Ndu Ngơi.$b$,true),
('bunong-vn','LUK',5,2,null,$b$Păng saơ ta kơh dak nglao geh bar mlâm duk, ƀiă lah phung seng jal du luh jêh gay ma rao lơi jal khân păng.$b$,false),
('bunong-vn','LUK',5,3,null,$b$Păng ncho tâm du mlâm duk, ndơ̆ Y-Simôn jêh ri đă păng vah duk bơh ngai đah kơh. Păng gŭ tâm duk, nti lah ma phung bunuyh âk.$b$,false),
('bunong-vn','LUK',5,4,null,$b$Jêh Păng nti, Păng lah ma Y-Simôn: “May vah duk hăn tâm dak jru jêh ri seng hom.”$b$,true),
('bunong-vn','LUK',5,5,null,$b$Y-Simôn plơ̆ lah ma Păng: “Hơi Kôranh, hên seng jêh lĕ du măng, ƀiă lah mâu geh du mlâm ka ôh, ƀiă lah tĭng nau may lah, gâp mra seng tay.”$b$,true),
('bunong-vn','LUK',5,6,null,$b$Jêh seng, khân păng geh ka âk ngăn, kŏ hêk jal.$b$,false),
('bunong-vn','LUK',5,7,null,$b$Khân păng vơch ti ma phung ncho duk êng, gay ma kơl khân păng. Phung nây hăn jêh ri lĕ bar mlâm duk tâm dak.$b$,false),
('bunong-vn','LUK',5,8,null,$b$Tơ lah Y-Simôn Pêtrôs saơ nau nây, păng chon mon ta jâng Brah Yêsu lah: “Ơ Kôranh Brah, ăn may du ngai đah gâp, yor lah gâp jêng bunuyh tih.”$b$,false),
('bunong-vn','LUK',5,9,null,$b$Yor lah nau klach tât ma păng, nđâp ma lĕ rngôch phung ndrel ma păng, yor lah nau khân păng seng nây.$b$,true),
('bunong-vn','LUK',5,10,null,$b$Geh nau tât tâm ban pô nây lĕ, ma Y-Yakơ jêh ri Y-Yôhan phung kon Y-Sêƀêđê, băl Y-Simôn. Jêh ri Brah Yêsu lah ma Y-Simôn: “Lơi klach ôh, ntơm bơh aƀaơ may mra seng bunuyh.”$b$,false),
('bunong-vn','LUK',5,11,null,$b$Jêh khân păng vah plŭng ta kơh, khân păng cha lơi lĕ jêh ri tĭng ndô̆ Brah Yêsu.$b$,true),
('bunong-vn','LUK',5,12,null,$b$Dôl Brah Yêsu gŭ tâm du ƀon, geh du huê bunuyh phung sa saơ Păng. Nơm nây kŭp măt ta neh, jêh ri vơh vơl ma Păng: “Hơi Kôranh, tơ lah may ŭch, dăn may ƀư bah an gâp.”$b$,true),
('bunong-vn','LUK',5,13,null,$b$Brah Yêsu yơr ti pah ta păng, jêh ri lah: “Gâp ŭch nau nây jêng kloh hom may.” Ƀât lât phŭng păng bah ro.$b$,true),
('bunong-vn','LUK',5,14,null,$b$Jêh ri Brah Yêsu ntăm ma păng lơi ta nkoch ma bu ôh, ƀiă lah: “Hăn may tâm mpơl hom ma Kôranh ƀư brah jêh ri nhhơ ma nau ƀư kloh may tĭng nâm nau Y-Môis ntăm jêh, gay geh nau mbơh ma khân păng.”$b$,false),
('bunong-vn','LUK',5,15,null,$b$Bu tăng lư Păng lơ hâu âk, jêh ri âk bunuyh văch ŭch iăt nau Păng nti lah, jêh ri gay ma bơh nau ji kuet.$b$,true),
('bunong-vn','LUK',5,16,null,$b$Ƀiă lah Păng hăn du tâm bri rdah jêh ri mbơh sơm.$b$,false),
('bunong-vn','LUK',5,17,null,$b$Du nar Brah Yêsu gŭ nti lah. Geh phung Pharisi jêh ri phung Kôranh nơm nti nau vay tă bơh lĕ ƀon tâm n'gor Galilê, n'gor Yuđa jêh ri tă bơh ƀon Yêrusalem khân păng gŭ ta nây, jêh ri nau brah Kôranh Brah tâm mpơl tâm nau păng ƀư bah.$b$,true),
('bunong-vn','LUK',5,18,null,$b$Aơ, geh bunuyh tung du huê bunuyh rvĕn ma sưng bêch, joi nau gay ma dơi lăp jêh ri dơm ta năp Brah Yêsu.$b$,true),
('bunong-vn','LUK',5,19,null,$b$Yor lah khân păng mâu gĭt mbah ntŭk bu nglăp păng, yor lah geh âk ir bunuyh. Khân păng hao ta chor bôk pho ta du ntŭk trôm khân păng ntrôl njŭr nđâp ma sưng bêch, ta nklang phung tâm rƀŭn ta năp Brah Yêsu.$b$,false),
('bunong-vn','LUK',5,20,null,$b$Saơ nau chroh khân păng, Brah Yêsu lah: “Hơi may, nau tih may hŏ yô̆ an jêh.”$b$,false),
('bunong-vn','LUK',5,21,null,$b$Phung Kôranh nchih sămƀŭt jêh ri phung Pharisi mĭn jêh ri lah: “Mbu nơm aơ, ngơi nau sưr ir? Mbu nơm dơi yô̆ nau tih, knŏng Brah Ndu bơh?”$b$,true),
('bunong-vn','LUK',5,22,null,$b$Brah Yêsu gĭt jêh nau mĭn khân păng jêh ri lah: “Moh nau khân may mĭn tâm nuih n'hâm khân may?$b$,true),
('bunong-vn','LUK',5,23,null,$b$Moh nau nơih lơn lah: Nau tih may yô̆ an jêh, mâu lah, lah: Dâk hom may, jêh ri hăn?$b$,false),
('bunong-vn','LUK',5,24,null,$b$Pô ri, gay ma khân may gĭt ta neh ntu aơ, Kon bunuyh dơi geh nau yô̆ an nau tih.” Păng lah ma bunuyh rvĕn: “Dâk hom, sŏk sưng bêch may, sĭt hom ta ngih may nơm!”$b$,false),
('bunong-vn','LUK',5,25,null,$b$Jêh ri ƀât lât, păng dâk ta năp phung nây, sŏk sưng păng, jêh ri hăn sĭt ta ngih, tâm rnê ma Brah Ndu.$b$,true),
('bunong-vn','LUK',5,26,null,$b$Lĕ rngôch hih rhâl ngăn, jêh ri tâm rnê ma Brah Ndu. Bêng ma nau klach khân păng lah: “Hên saơ jêh, aơ ndơ khlay ngăn.”$b$,false),
('bunong-vn','LUK',5,27,null,$b$Jêh nau nây Brah Yêsu luh, jêh ri saơ du huê bunuyh riu pi amoh păng Y-Lêvi, gŭ ta ntŭk riu pi. Păng lah ma nơm nây: “Tĭng gâp.”$b$,true),
('bunong-vn','LUK',5,28,null,$b$Păng cha lơi lĕ, dâk jêh ri tĭng ndô̆ Brah Yêsu.$b$,false),
('bunong-vn','LUK',5,29,null,$b$Y-Lêvi jă sông sa tâm ngih păng, jêh ri âk phung riu pi, nđâp ma bunuyh êng gŭ sông sa ndrel ma khân păng.$b$,true),
('bunong-vn','LUK',5,30,null,$b$Phung Pharisi jêh ri phung kôranh nchih sămƀŭt ngơi ƀŭk dŭk suyh, jêh ri lah ma phung oh mon Păng: “Mâm ƀư khân may gŭ sông sa, jêh ri nhêt ndrel ma phung riu pi, jêh ri phung tih?”$b$,false),
('bunong-vn','LUK',5,31,null,$b$Brah Yêsu lah ma khân păng: “Mâu di phung ngăch prăl ôh ŭch ma kôranh dak si, ƀiă lah phung ji kuet.$b$,true),
('bunong-vn','LUK',5,32,null,$b$Gâp mâu văch kuăl phung sŏng ôh rmal nau tih?”$b$,false),
('bunong-vn','LUK',5,33,null,$b$Phung nây lah ma păng: “Phung oh mon Y-Yôhan, nđâp ma phung oh mon Pharisi ver sông sa ƀa ƀơ jêh ri mbơh sơm, ƀiă lah phung khân may sông sa jêh ri nhêt.”$b$,true),
('bunong-vn','LUK',5,34,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Dơi lĕ khân may ăn phung mĭt jiăng gŭ ur, ver sông sa dôl păng gŭ ndrel ma phung nây?$b$,true),
('bunong-vn','LUK',5,35,null,$b$Ƀiă lah tât nar, ndăm gŭ ur mra luh du bơh phung nây. Lĕ nar nây khân păng ver sông sa.”$b$,true),
('bunong-vn','LUK',5,36,null,$b$Jêh ri Brah Yêsu ngơi nau hôr đah khân păng: “Bu mâu nkhêk ôh du blah bok tă bơh ao mhe gay jĭm ndop ta ao mŭnh; lah ƀư pô nây păng mra ƀư sat bok mhe, jêh ri blah bok păng sŏk mâu tâm gop ôh đah bok mŭnh.$b$,true),
('bunong-vn','LUK',5,37,null,$b$Jêh ri bu mâu dơ dak play kriăk ƀâu mhe, tâm dŭng ntâu mŭnh, tơ lah pô nây dak play kriăk ƀâu mhe mra ƀư prek dŭng ntâu mŭnh nây, hŭk lĕ, jêh ri dŭng roh hêk lĕ.$b$,false),
('bunong-vn','LUK',5,38,null,$b$Ƀiă lah bu dơ dak play kriăk ƀâu mhe tâm dŭng ntâu mhe.$b$,false),
('bunong-vn','LUK',5,39,null,$b$Jêh ri bu mâu hôm dăn ôh dak play kriăk ƀâu mhe, tơ lah jêh nhêt dak play kriăk ƀâu ơm, yor păng lah: ‘Dak play kriăk ƀâu ơm kah lơn.’ ”$b$,false),
('bunong-vn','LUK',6,1,null,$b$Tâm nar Saƀat Kôranh Brah Yêsu hăn rgăn mir ba sêng, phung oh mon Păng tôch ba, tro tâm mpang ti jêh ri sa.$b$,true),
('bunong-vn','LUK',6,2,null,$b$Geh ƀa ƀă phung Pharisi lah ma khân păng: “Mâm ƀư khân may ƀư nau bu vay ver tâm nar Saƀat?”$b$,true),
('bunong-vn','LUK',6,3,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Khân may mâu mâp uănh hĕ nau Y-Đavit ƀư tơ lah păng ji ngot, păng jêh ri phung ndrel ma păng.$b$,true),
('bunong-vn','LUK',6,4,null,$b$Mâm ƀư păng lăp tâm ngih Brah Ndu sŏk kapŭng prăp nhhơr ma Brah Ndu, păng sa jêh ri ăn ma phung ndrel ma păng? Nanê̆ kapŭng nây knŏng phung kôranh ƀư brah dơi sa.”$b$,false),
('bunong-vn','LUK',6,5,null,$b$Jêh ri Brah Yêsu lah ma khân păng: “Kon bunuyh jêng Kôranh nđâp ma nar Saƀat.”$b$,true),
('bunong-vn','LUK',6,6,null,$b$Geh nar Saƀat êng, Brah Yêsu lăp tâm ngih rƀŭn phung Yuđa jêh ri nti lah. Ta nây geh du huê bunuyh siăr ti pa ma.$b$,true),
('bunong-vn','LUK',6,7,null,$b$Phung kôranh nchih sămƀŭt jêh ri phung Pharisi kâp uănh ma Brah Yêsu, gĭt lah Păng mra ƀư bah tâm nar Saƀat, gay ma geh nau phong Păng.$b$,false),
('bunong-vn','LUK',6,8,null,$b$Ƀiă lah Brah Yêsu gĭt nau mĭn khân păng jêh ri lah ma bunuyh siăr ti: “Dâk hom may jêh ri gŭ râng ta nklang aơ.” Păng dâk jêh ri gŭ râng.$b$,false),
('bunong-vn','LUK',6,9,null,$b$Jêh ri Brah Yêsu lah ma khân păng: “Tâm nar Saƀat, gĭt lah dơi ƀư nau ueh mâu lah nau mhĭk, tâm rklaih nau rêh mâu lah nkhĭt lơi păng?”$b$,false),
('bunong-vn','LUK',6,10,null,$b$Păng uănh ma lĕ rngôch phung nây jêh ri lah ma bunuyh nây: “Yơr hom ti may.” Păng yơr, jêh ri ti păng bah ro.$b$,true),
('bunong-vn','LUK',6,11,null,$b$Khân păng bêng ma nau ji nuih jêh ri tâm nchră ma nau khân păng ŭch ƀư ma Brah Yêsu.$b$,true),
('bunong-vn','LUK',6,12,null,$b$Dôl nây Brah Yêsu hao yôk, ŭch mbơh sơm, jêh ri Păng gŭ mbơh sơm ma Brah Ndu lĕ du măng.$b$,true),
('bunong-vn','LUK',6,13,null,$b$Tât nar luh Brah Yêsu kuăl phung oh mon Păng jêh ri săch jât ma bar nuyh tâm phung nây. Phung nây Păng rnha Kôranh phung oh mon.$b$,false),
('bunong-vn','LUK',6,14,null,$b$Y-Simôn păng trơn amoh Y-Pêtrôs, Y-Andrê oh păng, Y-Yakơ, Y-Yôhan, Y-Philip, Y-Ƀartêlômi,$b$,false),
('bunong-vn','LUK',6,15,null,$b$Y-Mathiơ, Y-Thômas, Y-Yakơ kon Y-Alphê, Y-Simôn bu rnha Nơm Hŭch Rhŭl.$b$,false),
('bunong-vn','LUK',6,16,null,$b$Yut kon Y-Yakơ, jêh ri Y-Yuđas Iskariôt jêng nơm rlăng.$b$,false),
('bunong-vn','LUK',6,17,null,$b$Păng jŭr ndrel ma phung nây jêh ri gŭ jưh ta ntŭk neh lâng. Ta nây geh âk phung oh mon Păng jêh ri âk bunuyh bơh n'gor Yuđa, bơh ƀon Yêrusalem, jêh ri tă bơh n'gor dăch kơh rlai ƀon Tyr jêh ri ƀon Sidôn. Khân păng văch gay ma iăt nau Brah Yêsu nti lah, jêh ri gay ma ƀư bah nau ji kuet khân păng.$b$,true),
('bunong-vn','LUK',6,18,null,$b$Phung bunuyh rêh ni yor brah djơh lơh, bơh lĕ.$b$,false),
('bunong-vn','LUK',6,19,null,$b$Lĕ rngôch phung âk ŭch pah tă Păng yor nau brah luh tă bơh Păng jêh ri ƀư bah lĕ rngôch khân păng.$b$,false),
('bunong-vn','LUK',6,20,null,$b$Jêh ri Brah Yêsu uănh ma phung oh mon Păng jêh ri lah: “Ueh maak yơh ma phung khân may o ach, yor lah ƀon bri hađăch Brah Ndu prăp ma khân may.$b$,true),
('bunong-vn','LUK',6,21,null,$b$Ueh maak yơh ma phung khân may ji ngot aƀaơ ri, yor lah khân may mra hơm răm.$b$,true),
('bunong-vn','LUK',6,22,null,$b$“Ueh maak yơh ma phung khân may tơ lah bu nsot khân may, suai rak khân may, jêh ri dun amoh khân may, kơp jêng mhĭk yor Kon Bunuyh!$b$,true),
('bunong-vn','LUK',6,23,null,$b$Maak hom khân may tâm nar nây jêh ri nsăt hom yor nau răm nau maak, yor lah nau nkhôm khân may mra jêng toyh ngăn tâm trôk; Yor tâm ban pô nây yơh phung mbơ̆ khân păng ƀư jêh ma phung Kôranh nơm mbơh lor.$b$,false),
('bunong-vn','LUK',6,24,null,$b$Ƀiă lah rêh ni yơh ma khân may, hơi phung ndrŏng, yor lah khân may geh jêh nau bonh.$b$,true),
('bunong-vn','LUK',6,25,null,$b$Rêh ni yơh ma khân may, hơi phung hơm jêh, yor lah khân may mra ji ngot. Rêh ni yơh ma khân may, hơi phung hơm aƀaơ, yor lah khân may mra gŭ tâm nau klâng ndrê jêh ri nau nhĭm nhhiăng.$b$,true),
('bunong-vn','LUK',6,26,null,$b$Rêh ni yơh ma khân may tơ lah lĕ rngôch bunuyh nkoch bri ma khân may jêng ueh, yor lah tâm ban pô nây lĕ phung mbơ̆ khân păng ƀư ma phung kôranh nơm mbơh lor tih.”$b$,true),
('bunong-vn','LUK',6,27,null,$b$“Ƀiă lah gâp lah ma khân may, phung iăt gâp, rŏng hom ma phung rlăng đah khân may. Ƀư ueh hom ma phung tâm rmot ma khân may.$b$,true),
('bunong-vn','LUK',6,28,null,$b$Mât ton hom ma phung rtăp rak khân may. Mbơh sơm hom ma phung ƀư mhĭk ma khân may.$b$,false),
('bunong-vn','LUK',6,29,null,$b$Tơ lah du huê tap may ta bom du đah, ăn păng tap tay đŏng bom du đah. Tơ lah du huê pit ao gleh may, lơi buay ôh lah păng sŏk đŏng ao jong mbâl may.$b$,false),
('bunong-vn','LUK',6,30,null,$b$Ăn ma mbu nơm dăn ndơ may, jêh ri lơi hôm sŏk sĭt ôh ndơ may, lah lĕ bu pit.$b$,false),
('bunong-vn','LUK',6,31,null,$b$Moh nau khân may ŭch bu ƀư ma khân may, ăn khân may ƀư an ma bu tâm ban lĕ.$b$,true),
('bunong-vn','LUK',6,32,null,$b$“Tơ lah khân may rŏng ma phung rŏng ma khân may, moh nau ueh bu kah gĭt tôr ma khân may? Phung tih tâm ban lĕ, rŏng ma phung rŏng ma khân păng.$b$,true),
('bunong-vn','LUK',6,33,null,$b$Tơ lah khân may ƀư ueh ma phung ƀư ueh ma khân may, moh nau ueh bu mra kah gĭt tôr ma khân may? Phung tih ƀư tâm ban lĕ.$b$,false),
('bunong-vn','LUK',6,34,null,$b$Jêh ri tơ lah khân may ăn chan ma phung khân may kâp gân dơi mplơ̆ sĭt, moh nau ueh bu mra kah gĭt tôr ma khân may? Phung tih tâm ban lĕ, ăn ma phung tih chan, gay sŏk dơn ndơ tâm ban.$b$,false),
('bunong-vn','LUK',6,35,null,$b$Ƀiă lah ăn khân may, ƀư ueh jêh ri ăn khân păng chan, lơi hôm sŏk sĭt ôh, pô ri nau nkhôm khân may mra jêng toyh, jêh ri khân may mra jêng kon Nơm Klơ Lơn, yor lah păng jêng ueh ma phung mâu gĭt tôr jêh ri ma phung ƀai.$b$,false),
('bunong-vn','LUK',6,36,null,$b$Ăn khân may blau yô̆, tâm ban ma Mbơ̆ khân may blau yô̆.”$b$,false),
('bunong-vn','LUK',6,37,null,$b$“Lơi phat ôh dôih ma bu, gay bu mâu phat dôih khân may. Lơi ta kơp ôh bu jêng khư ma nau tâm rmal, gay ma bu mâu kơp khân may khư ma nau tâm rmal. Yô̆ hom nau tih bu, ri mơ Brah Ndu yô̆ nau tih khân may.$b$,true),
('bunong-vn','LUK',6,38,null,$b$Ăn ma bu, gay ma bu ăn ma khân may. Bu mra nkhŭt ma khân may, jêh ri mbêng ăn ler. Yor lah bu mra veh ma khân may, tĭng nâm khân may mra veh ma bu.”$b$,false),
('bunong-vn','LUK',6,39,null,$b$Păng ngơi nau hôr aơ ma khân păng: “Du huê bunuyh chieh măt, dơi lĕ păng njŭn leo du huê bunuyh êng? Di lĕ bar hê khân păng mra tŭp tâm ntu?$b$,true),
('bunong-vn','LUK',6,40,null,$b$“Phung oh mon mâu jêng toyh lơn ma kôranh nơm nti ôh, ƀiă lah lĕ rngôch oh mon ngăn mra jêng tâm ban ma kôranh nơm nti păng.$b$,true),
('bunong-vn','LUK',6,41,null,$b$Mâm ƀư may saơ ndruyh tâm trôm măt oh nâu may, ƀiă lah mâu saơ ôh rda tơm si tâm trôm măt may nơm?$b$,false),
('bunong-vn','LUK',6,42,null,$b$Mâu lah, mâm may dơi lah ma oh nâu may: ‘Hơi oh nâu, ăn gâp sŏk lơi ndruyh tâm trôm măt may,’ ƀiă lah mâu dơi saơ rda tơm si tâm trôm măt may nơm? Hơi bunuyh nuih n'hâm mŭr lor lơn sŏk lơi rda tơm si tâm trôm măt may, pô ri may mra dơi saơ ang dơi sŏk ndruyh tă bơh trôm măt oh nâu may.”$b$,true),
('bunong-vn','LUK',6,43,null,$b$“Mâu geh ôh tơm si ueh geh play mhĭk, mâu lĕ geh tơm si mhĭk geh play ueh.$b$,true),
('bunong-vn','LUK',6,44,null,$b$Yor lah bu dơi năl ăp tơm si ta play păng. Bu mâu pĕ ôh play rvi ta rtau lok, mâu lĕ bu pĕ play kriăk ƀâu tâm pŭm lok.$b$,false),
('bunong-vn','LUK',6,45,null,$b$Bunuyh ueh ngluh ndơ ueh tă bơh ntŭk ueh tâm nuih n'hâm păng, jêh ri bunuyh mhĭk ngluh ndơ mhĭk tă bơh ntŭk mhĭk păng; yor lah rmeh ler tă nuih n'hâm yơh mbung ngơi.”$b$,false),
('bunong-vn','LUK',6,46,null,$b$“Mâm ƀư khân may kuăl gâp: ‘Hơi Kôranh, Hơi Kôranh,’ ƀiă lah khân may mâu ƀư tĭng nâm nau gâp lah ôh?$b$,true),
('bunong-vn','LUK',6,47,null,$b$Gâp mra tâm mpơl ma khân may ma nau dơi tâm ntĭt lĕ bunuyh văch ta gâp, iăt nau gâp ngơi jêh ri tông.$b$,false),
('bunong-vn','LUK',6,48,null,$b$Păng jêng tâm ban ma du huê bunuyh ƀư ngih. Păng kuyh neh ăn ueh jêh ri ƀư tur ta klơ lŭ. Tât dak lip jêh ri dak thăng rchoh ƀiă lah mâu dơi n'gơ ôh, yor lah bu ƀư păng nâp ngăn.$b$,false),
('bunong-vn','LUK',6,49,null,$b$Ƀiă lah mbu tăng jêh ri mâu tông, păng jêng tâm ban ma du huê bunuyh ƀư ngih ta klơ neh mâu geh tur ngih nây. Ƀât lât păng cha lôt jêh ri rai lĕ.”$b$,false),
('bunong-vn','LUK',7,1,null,$b$Jêh lôch Brah Yêsu ngơi lĕ nau nây ta năp phung gŭ iăt. Păng lăp tâm ƀon Kapernum.$b$,true),
('bunong-vn','LUK',7,2,null,$b$Du huê kôranh ta han geh du huê oh mon păng rŏng ngăn, ji dăch khĭt.$b$,true),
('bunong-vn','LUK',7,3,null,$b$Tăng bu nkoch geh Kôranh Brah Yêsu, păng njuăl phung bu bŭnh bu ranh tâm phung Yuđa hăn dăn ma Brah Yêsu gay ma hăn ƀư bah oh mon păng.$b$,false),
('bunong-vn','LUK',7,4,null,$b$Phung aơ hăn tât ta Brah Yêsu jêh ri vơh vơl lah pô aơ: “Păng geh nau khư đă may ƀư nau nây ma păng.$b$,false),
('bunong-vn','LUK',7,5,null,$b$Yor lah păng rŏng ma ndŭl mpôl he, jêh ri păng yơh nơm ƀư ma he du mlâm ngih tâm rƀŭn Yuđa.”$b$,true),
('bunong-vn','LUK',7,6,null,$b$Pô ri Brah Yêsu hăn ndrel ma khân păng. Dăch tât ta ngih, kôranh ta han njuăl băl păng gay lah ma Brah Yêsu pô aơ: “Hơi kôranh lơi ta mpŭng suan may ôh, yor lah gâp mâu geh nau khư rom may lăp tâm ngih gâp ôh.$b$,true),
('bunong-vn','LUK',7,7,null,$b$Gâp mĭn ma gâp nơm tâm ban lĕ, mâu dơi khư hăn ta may. Ƀiă lah ăn may ngơi du tong jêh ri oh mon gâp bah ro.$b$,false),
('bunong-vn','LUK',7,8,null,$b$Yor lah gâp nơm gŭ tâm dâng phung kôranh gâp. Jêh ri gâp geh ta han tâm dâng gâp. Gâp lah ma du huê: Hăn hom, jêh ri păng hăn; ma du huê êng: Văch hom, jêh ri păng văch, jêh ri ma phung oh mon gâp: Ƀư hom nâm nđĕ jêh ri păng ƀư yơh.”$b$,false),
('bunong-vn','LUK',7,9,null,$b$Tơ lah Brah Yêsu tăng nau ngơi nây, Păng tâm rnê ma kôranh ta han nây, jêh ri păng n'gĭl uănh ma phung âk tĭng ndô̆ Păng, jêh ri lah pô aơ: “Gâp lah ma khân may, nđâp ma n'gor Israel, gâp mâu mâp saơ ôh nau chroh toyh tâm ban pô nây.”$b$,false),
('bunong-vn','LUK',7,10,null,$b$Phung bunuyh kôranh ta han njuăl nây plơ̆ sĭt tât ta ngih, saơ nơm ji hŏ bah jêh.$b$,false),
('bunong-vn','LUK',7,11,null,$b$Nar ôi taơ Brah Yêsu hăn tâm du ƀon, amoh ƀon Nain. Phung oh mon Păng jêh ri âk bunuyh hăn ndrel ma Păng.$b$,true),
('bunong-vn','LUK',7,12,null,$b$Lah Păng dăch tât ta mpông pêr ƀon, saơ bu tung du huê bunuyh khĭt, kon bu ur khĭt sai. Păng geh knŏng du huê kon nây dơm. Geh âk bunuyh tă bơh ƀon hăn ndrel ma bu ur nây.$b$,false),
('bunong-vn','LUK',7,13,null,$b$Saơ bu ur nây Brah Yêsu yô̆ ma păng jêh ri lah: “Lơi nhĭm ôh.”$b$,true),
('bunong-vn','LUK',7,14,null,$b$Păng hăn dăch, pah ta băng, jêh ri phung tung gŭ ƀât, păng lah: “Hơi ndăm, gâp lah ma may, dâk hom!”$b$,false),
('bunong-vn','LUK',7,15,null,$b$Nơm khĭt nây dâk, jêh ri ntơm blau ngơi. Brah Yêsu jao păng ma mê̆ păng nơm.$b$,true),
('bunong-vn','LUK',7,16,null,$b$Lĕ rngôch bunuyh klach da dê, jêh ri tâm rnê ma Brah Ndu lah: “Du huê Kôranh nơm mbơh lor toyh tâm mpơl jêh tâm phung he, jêh ri Brah Ndu văch khâl jêh ma phung ƀon lan Păng.”$b$,true),
('bunong-vn','LUK',7,17,null,$b$Nau bu nkoch bri ma Kôranh Brah Yêsu nsong hăn lam tâm n'gor dơh dăch ta nây.$b$,true),
('bunong-vn','LUK',7,18,null,$b$Y-Yôhan gĭt lĕ nau nây bơh oh mon păng.$b$,true),
('bunong-vn','LUK',7,19,null,$b$Păng kuăl bar hê tâm phung oh mon păng jêh ri njuăl khân păng hăn ta Brah Yêsu, ăn ôp pô aơ: “Di lĕ may jêng Brah mra tât, mâu lah hên gŭ kâp tay du huê êng đŏng?”$b$,false),
('bunong-vn','LUK',7,20,null,$b$Tât ta Brah Yêsu khân păng lah: “Y-Yôhan nơm ƀư ƀaptem njuăl hên văch ta may gay ôp pô aơ: ‘May jêng nơm mra văch ƀơh, mâu lah hên gŭ kâp gân tay du huê nơm êng đŏng?’ ”$b$,true),
('bunong-vn','LUK',7,21,null,$b$Rnôk nây lĕ Brah Yêsu ƀư bah âk phung ji kuet, jêh ri bunuyh brah mhĭk lơh, jêh ri Păng ăn âk bunuyh chieh măt dơi saơ ang đŏng.$b$,true),
('bunong-vn','LUK',7,22,null,$b$Păng lah ma phung nây: “Hăn mbơh ma Y Yôhan moh nau khân may saơ jêh ri hŏ tăng jêh. Phung chieh măt dơi saơ ang, phung kuet blau hăn, phung phŭng sa dơi bah, phung tê̆ k dơi tăng, phung khĭt dơi dâk rêh, jêh ri nau mhe mhan ueh mbơh jêh ma phung o ach.$b$,false),
('bunong-vn','LUK',7,23,null,$b$Ueh maak yơh ma mbu nơm mâu geh prah ôh yor gâp.”$b$,false),
('bunong-vn','LUK',7,24,null,$b$Tơ lah phung hăn mbơh Y-Yôhan hŏ sĭt jêh, Brah Yêsu ntơm ngơi ma phung âk ma nau Y-Yôhan: “Moh ndơ khân may hŏ uănh jêh, tâm bri rdah? Du tơm treng geh sial khôm rgu lĕ?$b$,true),
('bunong-vn','LUK',7,25,null,$b$Moh ndơ khân may hŏ uănh jêh? Du huê bunuyh soh ao dŭt ueh? Aơ phung soh ao dŭt ueh jêh ri sông sa kah gŭ tâm ngih phung hađăch.$b$,false),
('bunong-vn','LUK',7,26,null,$b$Moh ndơ khân may hŏ uănh jêh? Du huê kôranh nơm mbơh lor lĕ. Ơ, gâp lah ma khân may, toyh lơn ma kôranh nơm mbơh lor.$b$,false),
('bunong-vn','LUK',7,27,null,$b$Ma Păng yơh bu nchih jêh pô aơ: ‘Aơ gâp njuăl du huê bunuyh mbơh gâp ta năp may, gay nkra trong ma may.’$b$,false),
('bunong-vn','LUK',7,28,null,$b$Gâp lah ma khân may, đơ phung bunuyh deh tă bơh bu ur, mâu geh nơm toyh lơn ma Y-Yôhan ôh. Ƀiă lah nơm jê̆ lơn tâm ƀon bri hađăch Brah Ndu jêng toyh lơn ma păng.”$b$,false),
('bunong-vn','LUK',7,29,null,$b$Lĕ rngôch phung tăng nau nây, nđâp ma phung riu pi mbơh Brah Ndu sŏng, yor lah khân păng dơn jêh nau ƀaptem Y-Yôhan.$b$,true),
('bunong-vn','LUK',7,30,null,$b$Ƀiă lah phung Pharisi jêh ri phung kôranh nchih sămƀŭt dun nau Brah Ndu ŭch ma khân păng yor lah khân păng mâu mâp dơn ôh nau ƀaptem Y-Yôhan.$b$,true),
('bunong-vn','LUK',7,31,null,$b$“Pô ri mâm gâp mra tâm ntĭt phung bunuyh rnôk aơ, ma mbu păng tâm ban?$b$,true),
('bunong-vn','LUK',7,32,null,$b$Khân păng jêng tâm ban ma phung kon se gŭ tâm ngih tăch drăp jêh ri nter ma phung băl păng pô aơ: ‘Hên uh jêh n'hôm ma khân may ƀiă lah khân may mâu ŭch ntlơ̆ ntlơn ôh, hên mprơ jêh nau rngot, ƀiă lah khân may mâu ŭch nhĭm ôh!’$b$,true),
('bunong-vn','LUK',7,33,null,$b$Yor lah Y-Yôhan nơm ƀư ƀaptem văch jêh mâu sa kapŭng, jêh ri mâu nhêt dak play kriăk ƀâu ôh, ƀiă lah khân may lah. Păng geh brah mhĭk.$b$,false),
('bunong-vn','LUK',7,34,null,$b$Kon bunuyh văch jêh. Păng sông sa jêh ri nhêt, ƀiă lah khân may lah: ‘Păng bunuyh hay sa jêh ri vay nhŭl ndrănh, mĭt jiăng đah phung riu pi jêh ri phung tih!’$b$,false),
('bunong-vn','LUK',7,35,null,$b$Ƀiă lah bu kơp nau gĭt mĭn jêng sŏng tĭng nâm lĕ rngôch kan Păng.”$b$,false),
('bunong-vn','LUK',7,36,null,$b$Du huê Pharisi jă Brah Yêsu sông sa ndrel ma păng. Brah Yêsu lăp tâm ngih păng, gŭ sông sa ndrel.$b$,true),
('bunong-vn','LUK',7,37,null,$b$Jêh ri, aơ geh du huê bu ur tih tâm ƀon nây gĭt Brah Yêsu gŭ sông sa tâm ngih du huê Pharisi nây, djôt leo du mlâm nông khlay, dơ bêng dak ƀâu kah.$b$,false),
('bunong-vn','LUK',7,38,null,$b$Păng gŭ pa kơi ta jâng Brah Yêsu. Păng nhĭm jêh ri truh dak măt bĕ jâng Brah Yêsu, jêh ri jut ma sŏk păng, chŭm jêh ri nkhŭt mhĭng ma dak si ƀâu kah.$b$,false),
('bunong-vn','LUK',7,39,null,$b$Tơ lah du huê Pharisi nơm jă Brah Yêsu, saơ nau nây, păng mĭn pô aơ: “Tơ lah bunuyh aơ jêng kôranh nơm mbơh lor, Păng mra gĭt năl mbu, jêh ri amoh bu ur, nơm pah ta Păng. Păng mra gĭt bu ur nây jêng bu ur tih.”$b$,false),
('bunong-vn','LUK',7,40,null,$b$Brah Yêsu ngơi, jêh ri lah ma păng: “Hơi Y-Simôn, gâp geh nau ŭch lah ma may.” Păng lah: “Hơi Kôranh nơm nti, ngơi hom.”$b$,false),
('bunong-vn','LUK',7,41,null,$b$“Du huê bunuyh, geh bar hê iang rnon ma păng, du huê iang prăm rhiăng prăk jêh ri du huê êng prăm jât.$b$,true),
('bunong-vn','LUK',7,42,null,$b$Ƀiă lah khân păng mâu geh prăk chê̆. Nơm rnon ngroh lơi rnon nây ma lĕ bar hê khân păng. Mbu nơm mra rŏng ma păng âk lơn?”$b$,false),
('bunong-vn','LUK',7,43,null,$b$Y-Simôn plơ̆ lah: “Gâp mĭn, nơm păng ngroh âk lơn!” Brah Yêsu lah ma păng: “May mĭn di ngăn.”$b$,false),
('bunong-vn','LUK',7,44,null,$b$Jêh ri Păng n'gĭl uănh ma bu ur nây jêh ri lah ma Y Simôn: “May saơ lĕ bu ur aơ? Gâp lăp jêh tâm ngih may ƀiă lah may mâu ăn dak ma gâp rao jâng. Bi bu ur aơ, păng ƀư bĕ jêh jâng gâp ma dak măt păng jêh ri jut ma sŏk.$b$,false),
('bunong-vn','LUK',7,45,null,$b$May mâu mâp chŭm gâp ôh, ƀiă lah ntơm bơh gâp lăp, mâu mâp rlu ôh păng chŭm jâng gâp.$b$,false),
('bunong-vn','LUK',7,46,null,$b$May mâu mâp troch ôh dak ngi ta bôk gâp, ƀiă lah păng troch dak si ƀâu kah ta jâng gâp.$b$,true),
('bunong-vn','LUK',7,47,null,$b$Yor nây, Gâp lah ma may, nau tih bu ur aơ âk ngăn, hŏ yô̆ an lĕ jêh yor ri nơm nây rŏng âk. Ƀiă lah ma nơm dơi yô̆ djê̆ rĭ dĭng rŏng djê̆.”$b$,false),
('bunong-vn','LUK',7,48,null,$b$Jêh ri Păng lah ma bu ur nây: “Nau tih ay dơi yô̆ an jêh.”$b$,false),
('bunong-vn','LUK',7,49,null,$b$Phung gŭ sông sa ndrel ma Păng mĭn pô aơ: “Mbu Păng aơ, yô̆ an nđâp ma nau tih bu?”$b$,true),
('bunong-vn','LUK',7,50,null,$b$Ƀiă lah Brah Yêsu lah ma bu ur nây: “Nau chroh ay tâm rklaih ay jêh. Hăn hom đăp mpăn.”$b$,false),
('bunong-vn','LUK',8,1,null,$b$Jêh ri Brah Yêsu hăn rgăn ƀon toyh jêh ri ƀon jê̆, nti lah jêh ri mbơh nau mhe mhan ueh ma ƀon bri hađăch Brah Ndu. Phung jât ma bar nuyh oh mon nsong ndrel ma Păng,$b$,true),
('bunong-vn','LUK',8,2,null,$b$jêh ri geh ƀa ƀă phung bu ur klaih jêh nau ji kuet. H'Mari Mađala, tă bơh păng yơh pơh nuyh brah mhĭk luh du.$b$,false),
('bunong-vn','LUK',8,3,null,$b$H'Yôana, ur Y-Kusa, kôranh chiă uănh ngih Hêrôt, H'Susan jêh ri geh âk phung êng kơl păng ma drăp ndơ.$b$,true),
('bunong-vn','LUK',8,4,null,$b$Tơ lah âk bunuyh tâm rƀŭn jêh, jêh ri geh âk bunuyh tât tă bơh âk ƀon êng êng, Brah Yêsu ngơi hôr pô aơ:$b$,true),
('bunong-vn','LUK',8,5,null,$b$“Geh du huê bunuyh srih grăp, hăn srih. Dôl păng srih, ƀa ƀă grăp tŭp rŏ trong. Bu jot lơi jêh ri phung sĭm chôk lơi.$b$,false),
('bunong-vn','LUK',8,6,null,$b$Ƀa ƀă tŭp tâm neh lŭ. Jêh păng hon, păng kro, yor lah mâu geh jru reh.$b$,false),
('bunong-vn','LUK',8,7,null,$b$Ƀa ƀă tŭp tâm ntŭk lok. Lok hon ndrel, jêh ri in lơi ba nây.$b$,false),
('bunong-vn','LUK',8,8,null,$b$Geh ƀa ƀă tŭp tâm neh ueh, jêh păng hon, geh play du rhiăng rnglay.” Jêh ngơi nau nây Brah Yêsu lah huy ktang: “Mbu nơm geh tôr rkêng iăt hom!”$b$,false),
('bunong-vn','LUK',8,9,null,$b$Phung oh mon Păng ôp Păng nâm bu ntĭt nau hôr aơ.$b$,true),
('bunong-vn','LUK',8,10,null,$b$Păng plơ̆ lah: “Bu ăn ma khân may dơi gĭt rbăng nau khlay ndâp, ma ƀon bri hađăch Brah Ndu, ƀiă lah ma phung êng, bu ngơi ma khân păng ma nau hôr. Pô nây yơh, dôl khân păng uănh, khân păng mâu saơ ôh, jêh ri dôl khân păng gŭ iăt khân păng mâu gĭt rbăng ôh.$b$,false),
('bunong-vn','LUK',8,11,null,$b$“Aơ nau rblang ma nau hôr aơ. Grăp tâm ntĭt ma nau hôr aơ.$b$,true),
('bunong-vn','LUK',8,12,null,$b$Grăp tŭp rŏ trong tâm ntĭt ma phung gŭ iăt, brah mhĭk văch sŏk pit lơi nau ngơi tă bơh nuih n'hâm khân păng, klach khân păng chroh jêh ri geh nau tâm rklaih.$b$,false),
('bunong-vn','LUK',8,13,null,$b$Grăp tŭp ta ntŭk neh lŭ tâm ntĭt ma phung gŭ iăt nau ngơi ma nau maak, ƀiă lah mâu geh reh ôh, chroh knŏng ƀât lât, jêh ri khân păng tŭp ro, tơ lah geh nau bu ndơm.$b$,false),
('bunong-vn','LUK',8,14,null,$b$Grăp tŭp tâm neh ntŭk lok tâm ntĭt ma phung iăt jêh, du sĭt jêh ri nau rngot, nau ndrŏng jêh ri nau maak bơh nau rêh aơ, tŭn khân păng jêh ri khân păng mâu geh play tât dŭm ôh.$b$,false),
('bunong-vn','LUK',8,15,null,$b$Grăp tŭp tâm neh ueh tâm ntĭt ma phung gŭ iăt ma nau sŏng jêh ri ueh, djôt prăp jêh ri geh play ma nau srôih.$b$,false),
('bunong-vn','LUK',8,16,null,$b$Mâu geh ôh bunuyh jêh mpoh ŭnh kđen, kŭp lơi ma glah mâu lah ăn tâm dâng sưng bêch, ƀiă lah bu yông păng ta n'gâng, pô nây mơ, mbu lăp tâm ngih mra saơ ang.$b$,true),
('bunong-vn','LUK',8,17,null,$b$Yor lah mâu geh ôh ndơ pôn jêh, bu mâu mra mpơl, mâu geh ndơ ndâp ôh, bu mâu mra gĭt jêh ri saơ.$b$,true),
('bunong-vn','LUK',8,18,null,$b$Pô ri, njrăng hom ma nau khân may gŭ iăt, yor lah bu mra ăn ma mbu nơm geh, ƀiă lah ma nơm mâu geh bu sŏk lơi ndơ păng geh jêh.”$b$,false),
('bunong-vn','LUK',8,19,null,$b$Rnôk nây mê̆ jêh ri phung oh Brah Yêsu joi Păng, ƀiă lah khân păng mâu dơi hăn dăch ma Păng ôh yor lah bunuyh âk.$b$,true),
('bunong-vn','LUK',8,20,null,$b$Bu lah ma Păng: “Mê̆ may jêh ri oh may gŭ pa dih, ŭch tâm mâp đah may.”$b$,false),
('bunong-vn','LUK',8,21,null,$b$Ƀiă lah păng plơ̆ lah: “Mbu nơm tăng nau Brah Ndu ngơi jêh ri tông, phung nây jêng mê̆ jêh ri phung oh gâp.”$b$,false),
('bunong-vn','LUK',8,22,null,$b$Du nar Brah Yêsu ncho duk ndrel ma phung oh mon Păng. Păng lah ma phung nây “He hăn rgăn kăl tê̆ dak nglao.” Jêh ri khân păng hăn.$b$,true),
('bunong-vn','LUK',8,23,null,$b$Dôl khân păng vah duk Brah Yêsu gŭ bêch geh sial ktang tâm dak nglao. Duk băm dak, jêh ri khân păng gŭ tâm nau krit klach hâu ngăn.$b$,false),
('bunong-vn','LUK',8,24,null,$b$Khân păng rlay Brah Yêsu lah: “Hơi Kôranh, hơi Kôranh, khĭt ngăn he aơ taơ!” Brah Yêsu kah rngăl buay sial jêh ri dak njach. Pô ri phŭt sial bah, jêh ri geh nau đăp mpăn yơh.$b$,false),
('bunong-vn','LUK',8,25,null,$b$Jêh ri Păng lah ma phung oh mon Păng: “Mbah ăn nau chroh khân may?”, Khân păng bêng ma nau klach jêh ri nau hih rhâl, jêh ri tâm lah ndrăng nơm: “Mbu nơm bunuyh aơ, buay nđâp ma sial nđâp ma dak, lĕ ndơ nây iăt nau Păng da dê.”$b$,false),
('bunong-vn','LUK',8,26,null,$b$Khân păng tât ta n'gor Gađara tham pa lơ n'gor Galilê.$b$,true),
('bunong-vn','LUK',8,27,null,$b$Tơ lah Brah Yêsu jŭr ta neh geh du huê bunuyh tă bơh ƀon toyh hăn ta năp Păng. Bunuyh geh âk brah mhĭk lơh. Bơh jŏ jêh păng gŭ săk lưn jêh ri mâu mâp gŭ tâm ngih, ƀiă lah gŭ tâm môch mro.$b$,false),
('bunong-vn','LUK',8,28,null,$b$Jêh saơ Brah Yêsu, păng nter cha lôt ta jâng Brah Yêsu jêh ri lah huy ktang: “Moh nau gâp geh đah may. Ơ Brah Yêsu Kon Brah Ndu Nơm Ta Klơ Lơn? Gâp vơh vơl ma may, lơi ăn gâp geh nau rêh ni ôh.”$b$,false),
('bunong-vn','LUK',8,29,null,$b$Yor lah Brah Yêsu buay jêh brah mhĭk, ăn luh du tă bơh bunuyh nây. Brah mhĭk nhŭp pit păng bơh jŏ năm jêh. Bu mât chiă păng kât ma rse, jêh ri brah mhĭk leo păng tâm bri rdah.$b$,true),
('bunong-vn','LUK',8,30,null,$b$Brah Yêsu ôp păng: “Mâm moh may?” Păng plơ̆ lah: “Phung âk yơh.” Yor lah geh âk brah mhĭk lăp jêh tâm păng.$b$,false),
('bunong-vn','LUK',8,31,null,$b$Jêh ri khân păng vơh vơl ma Brah Yêsu, lơi ăn khân păng lăp tâm trôm jru.$b$,true),
('bunong-vn','LUK',8,32,null,$b$Tâm yôk nây geh âk sŭr joi sa jêh ri phung brah mhĭk dăn ma Brah Yêsu ăn khân păng lăp tâm phung sŭr nây. Brah Yêsu ăn lĕ.$b$,true),
('bunong-vn','LUK',8,33,null,$b$Phung brah mhĭk luh tă bơh bunuyh nây, lăp tâm phung sŭr. Phung sŭr nchuăt ta jreng yôk, nsăt tâm dak nglao jêh ri rmok lĕ.$b$,false),
('bunong-vn','LUK',8,34,null,$b$Phung rmăk sŭr, saơ nau tât nây, du jêh ri mbơh nau mhe nây tâm ƀon jêh ri tâm ntŭk ta mpâr ƀon.$b$,false),
('bunong-vn','LUK',8,35,null,$b$Âk bunuyh hăn uănh nau tât nây. Khân păng hăn dăch Brah Yêsu, jêh ri saơ du huê bunuyh klaih jêh tă bơh brah mhĭk, gŭ ta jâng Brah Yêsu, soh kho ao jêh ri jêng bunuyh ueh. Jêh ri khân păng klach hâu ngăn.$b$,true),
('bunong-vn','LUK',8,36,null,$b$Phung saơ jêh nau tât nây, nkoch bri ma bu saơ bunuyh brah mhĭk lơh nây bah jêh.$b$,false),
('bunong-vn','LUK',8,37,null,$b$Lĕ rngôch phung ƀon lan n'gor Gađara dăn ăn Brah Yêsu du ngai đah khân păng, yor lah khân păng klach hâu ngăn ngên. Pô ri Brah Yêsu hao duk hăn sĭt.$b$,true),
('bunong-vn','LUK',8,38,null,$b$Bunuyh brah mhĭk lơh lĕ bah, dăn nau dơi gŭ ndrel ma Păng. Ƀiă lah Brah Yêsu lah:$b$,false),
('bunong-vn','LUK',8,39,null,$b$“Sĭt hom ta ngih may nơm, jêh ri nkoch bri lĕ nau Brah Ndu ƀư jêh ma may.” Păng hăn mbơh lĕ nau Brah Yêsu ƀư jêh ma păng.$b$,false),
('bunong-vn','LUK',8,40,null,$b$Lah Brah Yêsu plơ̆ sĭt, âk bunuyh rom Păng, yor lah lĕ rngôch gŭ kâp păng da dê.$b$,true),
('bunong-vn','LUK',8,41,null,$b$Jêh ri, aơ geh du huê bunuyh moh păng Y-Jairus văch tât. Păng jêng kôranh ngih rƀŭn phung Yuđa păng chon mon ta jâng Brah Yêsu jêh ri vơh vơl dăn Brah Yêsu lăp tâm ngih păng.$b$,true),
('bunong-vn','LUK',8,42,null,$b$Yor lah păng geh knŏng du huê kon bu ur, klăp lah geh tâm jât ma bar năm, ji dăch khĭt. Dôl Brah Yêsu hăn, âk bunuyh ƀư hăt trong Păng.$b$,false),
('bunong-vn','LUK',8,43,null,$b$Dôl nây geh du huê bu ur ji rih geh jât ma bar năm jêh, jêh ri âk jêh huach drăp ndơ păng ma phung kôranh dak si ƀiă lah mâu geh du huê dơi ƀư bah nau ji păng ôh.$b$,true),
('bunong-vn','LUK',8,44,null,$b$Păng hăn dăch pa kơi Brah Yêsu, pah ta nchiăng ao păng. Ƀât lât mham păng mâu hôm truh ôh.$b$,true),
('bunong-vn','LUK',8,45,null,$b$Jêh ri Brah Yêsu lah: “Mbu moh pah gâp?” Lĕ rngôch lah mâu gĭt. Dôl nây geh Y-Pêtrôs ndrel ma phung băl păng lah: “Hơi Kôranh, phung âk gŭ jŭm may, ƀư bâp may, jêh ri may lah: Mbu pah gâp?”$b$,false),
('bunong-vn','LUK',8,46,null,$b$Ƀiă lah Brah Yêsu plơ̆ lah: “Geh du huê pah gâp jêh, yor lah gâp gĭt năl nau brah luh jêh bơh gâp.”$b$,true),
('bunong-vn','LUK',8,47,null,$b$Bu ur nây gĭt păng mâu hôm dơi pôn ôh, hăn ma nau sâr săk jăn, chon mon ta jâng Brah Yêsu, jêh ri lah ta năp măt lĕ rngôch bunuyh, mâm nau păng pah Brah Yêsu, jêh ri mâm ƀư păng hŏ bah jêh.$b$,false),
('bunong-vn','LUK',8,48,null,$b$Brah Yêsu lah ma păng: “Hơi kon bu ur gâp, nau chroh ay yơh ƀư bah ay, hăn hom đăp mpăn.”$b$,false),
('bunong-vn','LUK',8,49,null,$b$Dôl păng gŭ ngơi, geh du huê tă bơh kôranh ngih tâm rƀŭn Yuđa nây lah: “Kon bu ur may khĭt jêh, lơi hôm ƀư rsuak kôranh nơm nti ôh.”$b$,true),
('bunong-vn','LUK',8,50,null,$b$Ƀiă lah Brah Yêsu tăng nau nây, lah ma kôranh ngih rƀŭn phung Yuđa nây: “Lơi klach ôh, knŏng chroh jêh ri păng mra bah.”$b$,false),
('bunong-vn','LUK',8,51,null,$b$Tơ lah Brah Yêsu tât ta ngih, Păng mâu ăn bu lăp ndrel ma Păng ôh, knŏng Y-Pêtrôs, Y-Yôhan, Y-Yakơ jêh ri mê̆ mbơ̆ kon se nây.$b$,false),
('bunong-vn','LUK',8,52,null,$b$Lĕ rngôch nhĭm nhhiăng klâng rngot ma kon se nây. Jêh ri Brah Yêsu lah: “Lơi nhĭm nhhiăng ôh, păng mâu geh khĭt ôh, păng bêch.”$b$,false),
('bunong-vn','LUK',8,53,null,$b$Jêh ri phung nây mưch ma Păng yor lah gĭt ma kon se nây khĭt jêh.$b$,false),
('bunong-vn','LUK',8,54,null,$b$Brah Yêsu kuăn ta ti păng, jêh ri lah ma bâr huy ktang: “Hơi kon se jê̆, dâk hom ay.”$b$,false),
('bunong-vn','LUK',8,55,null,$b$Jêh ri huêng păng plơ̆ sĭt ta păng nơm, ƀât lât păng dâk ro. Brah Yêsu đă bu ăn păng sông sa.$b$,false),
('bunong-vn','LUK',8,56,null,$b$Phung mê̆ mbơ̆ bu ur jê̆ nây hih rhâl ngăn ƀiă lah Brah Yêsu ntăm ma khân păng, lơi nkoch bri ma bu ôh nau tât aơ.$b$,false),
('bunong-vn','LUK',9,1,null,$b$Jêh Brah Yêsu tâm rƀŭn jât ma bar nuyh oh mon, Păng ăn nau brah jêh ri nau dơi lĕ rngôch đah brah mhĭk, jêh ri nau dơi ƀư bah nau ji kuet.$b$,true),
('bunong-vn','LUK',9,2,null,$b$Păng njuăl phung nây nti lah ma nau ƀon bri hađăch Brah Ndu, jêh ri ƀư bah nau ji kuet.$b$,false),
('bunong-vn','LUK',9,3,null,$b$Păng lah ma phung oh mon Păng: “Lơi ta djôt leo ndơ ndrel ma khân may. Lơi ta djôt mâng jra, dŭng kapŭng, prăk, mâu lah bar blah ao ôh.$b$,false),
('bunong-vn','LUK',9,4,null,$b$Moh vâl khân may lăp, gŭ ta nây tât khân may hăn đŏng.$b$,false),
('bunong-vn','LUK',9,5,null,$b$Jêh ri tơ lah bu mâu rom khân may, tơ lah luh tă bơh ƀon nây, ăn khân may rtuh ndruyh jâng khân may, jêng nau mbơh tâm rdâng đah khân păng.”$b$,false),
('bunong-vn','LUK',9,6,null,$b$Khân păng hăn, jêh ri rgăn âk ƀon, mbơh nau mhe mhan ueh jêh ri ƀư bah bunuyh ji lam ntŭk.$b$,false),
('bunong-vn','LUK',9,7,null,$b$Hađăch Hêrôt tăng lĕ nau bu nkoch bri ma nau tât, jêh ri păng mâu gĭt mâm mĭn ôh, yor lah ƀa ƀă lah ma Y-Yôhan dâk rêh đŏng.$b$,true),
('bunong-vn','LUK',9,8,null,$b$Phung êng ƀa ƀă lah Y-Êli plơ̆ tâm mpơl tay, jêh ri phung êng mĭn ma du huê tâm phung Kôranh nơm mbơh lor ơm hŏ dâk rêh jêh.$b$,false),
('bunong-vn','LUK',9,9,null,$b$Ƀiă lah Hêrôt lah: “Gâp đă bu koh jêh trô ko Y-Yôhan, pô ri, mbu nơm nây? Tâm păng nây geh tăng lư âk nau khlay ngăn.” Jêh ri păng joi ŭch uănh Brah Yêsu.$b$,false),
('bunong-vn','LUK',9,10,null,$b$Tơ lah phung kôranh oh mon sĭt, khân păng nkoch bri ma Brah Yêsu lĕ nau khân păng hŏ ƀư jêh. Brah Yêsu jă nđâp ma phung nây ndrel ma Păng jêh ri hăn ta du ntŭk dăch ƀon Ƀêtsaiđa.$b$,true),
('bunong-vn','LUK',9,11,null,$b$Phung âk năl Păng jêh ri tĭng Păng. Brah Yêsu rom khân păng jêh ri nti khân păng ma ƀon bri hađăch Brah Ndu. Păng ăn phung ŭch nau bah ji.$b$,false),
('bunong-vn','LUK',9,12,null,$b$Trôk dăch măng jêh, jêh ri lah ma Păng: “Ăn phung aơ hăn sĭt, pô ri khân păng dơi hăn tâm ƀon jêh ri lĕ ntŭk dăch, dơi bêch măng jêh ri geh ndơ sông sa, yor lah he gŭ ta aơ tâm bri rdah.”$b$,false),
('bunong-vn','LUK',9,13,null,$b$Brah Yêsu lah ma khân păng: “Ăn khân may siăm phung âk nây.” Khân păng plơ̆ lah: “Hên geh knŏng prăm mlâm kapŭng jêh ri bar mlâm ka, tơ lah hên mâu hăn rvăt ndơ sông sa ma lĕ phung âk aơ.”$b$,false),
('bunong-vn','LUK',9,14,null,$b$Yor lah geh tâm prăm rbăn nuyh. Brah Yêsu lah ma phung oh mon păng: “Ăn khân păng gŭ dăp, du phung prăm jât nuyh.”$b$,false),
('bunong-vn','LUK',9,15,null,$b$Phung oh mon ƀư pô nây jêh ri ăn lĕ rngôch khân păng gŭ.$b$,false),
('bunong-vn','LUK',9,16,null,$b$Brah Yêsu sŏk prăm mlâm kapŭng jêh ri bar mlâm ka, n'gơr măt klơ trôk, mbơh sơm nau ueh prăp an, nkêch kapŭng nây, jêh ri ăn ma phung âk.$b$,true),
('bunong-vn','LUK',9,17,null,$b$Lĕ rngôch sa hơm da dê, jêh ri bu mplơ̆ sĭt jât ma bar bĭ kapŭng rmeh.$b$,false),
('bunong-vn','LUK',9,18,null,$b$Du nar, tơ lah Brah Yêsu gŭ mbơh sơm êng Păng nơm, ndrel ma phung oh mon Păng, Păng ôp ma phung oh mon Păng pô aơ: “Mâm, bu lah gâp jêng?”$b$,true),
('bunong-vn','LUK',9,19,null,$b$Khân păng plơ̆ lah, Y-Yôhan nơm ƀư ƀaptem, ƀa ƀă lah Y-Êli, ƀa ƀă êng lah, du huê tâm phung kôranh nơm mbơh lor ơm, dâk rêh đŏng.$b$,false),
('bunong-vn','LUK',9,20,null,$b$Jêh ri Brah Yêsu ôp khân păng: “Bi khân may, mbu khân may lah gâp jêng?” Y-Pêtrôs lah: “Brah Krist tă bơh Brah Ndu.”$b$,true),
('bunong-vn','LUK',9,21,null,$b$Brah Yêsu buay khân păng mâu ăn nkoch bri nau nây ma bu ôh.$b$,false),
('bunong-vn','LUK',9,22,null,$b$Păng lah: “Kon Bunuyh mra dơn âk nau rêh ni ji klâng, jêh ri phung bu bŭnh bu ranh, phung n'gâng kôranh ƀư brah, jêh ri phung kôranh nchih sămƀŭt mra dun Păng. Bu mra nkhĭt Păng jêh ri tăch pe nar Păng mra dâk rêh đŏng.”$b$,false),
('bunong-vn','LUK',9,23,null,$b$Jêh ri Păng lah ma lĕ rngôch: “Mbu nơm ŭch tĭng ndô̆ gâp, ăn păng dun nau păng nơm ŭch, tuy si tâm rkăng păng ăp nar jêh ri tĭng ndô̆ gâp.$b$,true),
('bunong-vn','LUK',9,24,null,$b$Yor lah mbu ŭch prăp nau rêh păng, mra roh, ƀiă lah mbu nơm ŭch ngroh lơi nau rêh păng yor gâp, mra prăp an.$b$,false),
('bunong-vn','LUK',9,25,null,$b$Jêh ri moh nau khlay du huê bunuyh geh lĕ neh ntu, tơ lah păng rai mâu lah ngroh lơi săk păng nơm?$b$,false),
('bunong-vn','LUK',9,26,null,$b$Yor lah mbu nơm mra prêng đah gâp jêh ri ma nau gâp ngơi, Kon Bunuyh mra prêng ma Păng tơ lah Păng plơ̆ văch tâm nau chrêk rmah Păng. Mbơ̆ Păng, jêh ri phung Tông mpăr kloh ŭch Păng.$b$,false),
('bunong-vn','LUK',9,27,null,$b$Gâp lah ma khân may nanê̆ ngăn, geh ƀa ƀă phung gŭ ta aơ mâu mra khĭt ôh lor ma khân păng saơ ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','LUK',9,28,null,$b$Tâm pham nar jêh Păng ngơi nau nây, Brah Yêsu jă ndrel Păng Y-Pêtrôs, Y-Yôhan, Y-Yakơ, hao klơ yôk mbơh sơm.$b$,true),
('bunong-vn','LUK',9,29,null,$b$Dôl Păng mbơh sơm, muh măt Păng rgâl jêh ri bok ao Păng jêng nglang ang rah vah ngăn.$b$,false),
('bunong-vn','LUK',9,30,null,$b$Jêh ri, aơ bar hê Y-Môis jêh ri Y-Êli, ngơi ndrel đah Păng.$b$,true),
('bunong-vn','LUK',9,31,null,$b$Khân păng tâm mpơl tâm nau chrêk rmah jêh ri ngơi ma nau Păng mra hăn yor kan Păng ŭch ƀư ăn ta ƀon Yêrusalem.$b$,false),
('bunong-vn','LUK',9,32,null,$b$Y-Pêtrôs jêh ri phung ndrel ma Păng jâk ir nau bêch, ƀiă lah dôl khân păng rngeh khân păng saơ nau chrêk rmah. Brah Yêsu jêh ri bar hê ndrel ma Păng.$b$,false),
('bunong-vn','LUK',9,33,null,$b$Dôl bar hê nây ntơm nkhah du đah Brah Yêsu, Y-Pêtrôs lah ma Păng: “Hơi Kôranh, ueh ngăn he gŭ ta aơ. He ndâk pe mlâm ngih bok, du mlâm ma may, du mlâm ma Y-Môis jêh ri du mlâm ma Y-Êli.” Păng mâu gĭt ôh, mâm păng lah.$b$,false),
('bunong-vn','LUK',9,34,null,$b$Dôl Păng ngơi pô nây, geh ndâr tŭk nkŭm phung nây jêh ri phung oh mon klach hâu ngăn.$b$,false),
('bunong-vn','LUK',9,35,null,$b$Dôl saơ phung nây lăp tâm ndâr tŭk geh bâr ngơi lah pô aơ: “Nơm aơ jêng Kon gâp săch jêh. Ăn khân may iăt Păng.”$b$,false),
('bunong-vn','LUK',9,36,null,$b$Jêh tăng bâr ngơi, Brah Yêsu gŭ êng Păng. Phung oh mon gŭ rklăk mâu nkoch bri ma bu ôh nau khân păng saơ jêh tâm nar nây.$b$,false),
('bunong-vn','LUK',9,37,null,$b$Ôi taơ, tơ lah Brah Yêsu jŭr jêh tă bơh yôk, âk bunuyh hăn ta năp Brah Yêsu.$b$,true),
('bunong-vn','LUK',9,38,null,$b$Jêh ri, aơ, tă tâm nklang phung âk du huê nter lah: “Hơi Kôranh nơm nti, gâp vơh vơl ma may, dăn may uănh an kon gâp, yor lah gâp geh knŏng du huê aơ.$b$,false),
('bunong-vn','LUK',9,39,null,$b$Brah mhĭk lơh păng, jêh ri ƀât lât păng nter, jêh ri brah mhĭk rgu ktang ngăn, luh mpŭnh dak diu ta trôm mbung, păng luh ma nau jêr ngăn, yor lah păng lĕ glăm jêh, păng ƀư âk nau mhĭk.$b$,false),
('bunong-vn','LUK',9,40,null,$b$Gâp vơh vơl ma phung oh mon may, gay mprơh brah mhĭk aơ, ƀiă lah khân păng mâu dơi mprơh ôh.”$b$,false),
('bunong-vn','LUK',9,41,null,$b$Brah Yêsu lah: “Hơi phung mpôl mâu geh nau chroh jêh ri tih mhĭk! Ndah hôm jŏ gâp mra gŭ ndrel jêh ri nsrôih đah khân may? Njŭn leo păng ta aơ.”$b$,false),
('bunong-vn','LUK',9,42,null,$b$Tât păng hăn dăch, brah mhĭk nklơ̆ păng ta neh jêh ri ƀư sâr, rgu săk hâu ngăn. Ƀiă lah Brah Yêsu buay brah mhĭk ƀơ̆ . Păng ƀư bah kon se nây, jêh ri jao ma mbơ̆ păng nơm.$b$,false),
('bunong-vn','LUK',9,43,null,$b$Jêh ri lĕ rngôch hih rhâl ma nau Brah Ndu. Dôl ăp năm tâm rnê ma lĕ nau Brah Yêsu ƀư jêh, Păng lah ma phung oh mon:$b$,true),
('bunong-vn','LUK',9,44,null,$b$“Ăn khân may iăt ăn ueh nau aơ, bu mra jao Kon Bunuyh tâm ti phung bunuyh.”$b$,false),
('bunong-vn','LUK',9,45,null,$b$Ƀiă lah phung oh mon mâu gĭt rbăng ôh nau ngơi nây. Nau nây ndâp ma khân păng, mâu ăn khân păng gĭt rbăng ôh, jêh ri khân păng klach ôp Brah Yêsu ma nau nây.$b$,true),
('bunong-vn','LUK',9,46,null,$b$Jêh ri geh nau tâm rlăch ndrăng khân păng, ŭch gĭt mbu nơm jêng toyh lơn tâm phung khân păng.$b$,true),
('bunong-vn','LUK',9,47,null,$b$Tơ lah Brah Yêsu gĭt nau khân păng mĭn tâm nuih n'hâm, Păng sŏk du huê kon se jê̆, ăn păng ta meng,$b$,false),
('bunong-vn','LUK',9,48,null,$b$jêh ri lah pô aơ: “Mbu nơm rom kon se jê̆ aơ tâm amoh gâp, tâm ban ma rom gâp lĕ; jêh ri mbu rom gâp jêh ri rom Nơm tơm njuăl gâp, yor lah mbu nơm jêng jê̆ lơn tâm phung khân may lĕ rngôch, nơm nây yơh jêng toyh lơn.”$b$,false),
('bunong-vn','LUK',9,49,null,$b$Y-Yôhan ngơi jêh ri lah: “Hơi Kôranh hên saơ jêh du huê bunuyh mprơh brah mhĭk tâm amoh may, jêh ri hên buay păng yor lah păng mâu tĭng ndô̆ he ôh.”$b$,true),
('bunong-vn','LUK',9,50,null,$b$Brah Yêsu plơ̆ lah: “Lơi buay păng ôh, yor lah mbu nơm mâu geh tâm rdâng đah khân may, jêng phung khân may.”$b$,false),
('bunong-vn','LUK',9,51,null,$b$Tơ lah dăch tât nar Păng hao sĭt klơ. Brah Yêsu ŭch hăn ta ƀon Yêrusalem.$b$,true),
('bunong-vn','LUK',9,52,null,$b$Păng njuăl ta năp Păng phung bunuyh mbơh. Khân păng hăn jêh ri lăp tâm du ƀon phung Samari gay nkra ntŭk ma Păng.$b$,true),
('bunong-vn','LUK',9,53,null,$b$Ƀiă lah bu mâu rom Păng ôh, yor lah gĭt Păng ŭch hăn ta ƀon Yêrusalem.$b$,true),
('bunong-vn','LUK',9,54,null,$b$Tơ lah saơ nau nây phung oh mon Y-Yakơ jêh ri Y-Yôhan lah pô aơ: “Ơ Kôranh Brah, may ŭch lĕ hên dăn ŭnh tă klơ trôk jŭr su lơi khân păng?”$b$,false),
('bunong-vn','LUK',9,55,null,$b$Brah Yêsu n'gĭl uănh ma khân păng jêh ri, lah: “Khân may mâu gĭt mâm nau mĭn khân may geh.$b$,false),
('bunong-vn','LUK',9,56,null,$b$Yor lah kon bunuyh văch mâu di ŭch ƀư roh huêng bunuyh ôh. Ƀiă lah gay tâm rklaih.” Jêh ri khân păng hăn ta du ƀon êng.$b$,false),
('bunong-vn','LUK',9,57,null,$b$Dôl khân păng hăn rŏ trong, geh du huê lah ma Păng: “Ơ Kôranh Brah, gâp mra tĭng ndô̆ lam ntŭk, ta ntŭk may mra hăn.”$b$,true),
('bunong-vn','LUK',9,58,null,$b$Brah Yêsu plơ̆ lah ma păng: “Phung mpik geh sŭng, phung sĭm geh rsuăn, ƀiă lah kon bunuyh mâu geh ndơ dâm bôk păng ôh.”$b$,true),
('bunong-vn','LUK',9,59,null,$b$Păng lah ma du huê nơm êng: “Tĭng ndô̆ gâp.” Jêh ri nơm nây plơ̆ lah: “Ơ Kôranh Brah, ăn gâp hăn brôi mbơ̆ gâp lor.”$b$,true),
('bunong-vn','LUK',9,60,null,$b$Ƀiă lah Brah Yêsu lah ma păng: “Ăn phung khĭt tâm brôi ndrăng phung khĭt nơm, bi may, hăn mbơh ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','LUK',9,61,null,$b$Du huê êng đŏng: “Gâp mra tĭng ndô̆ may, Hơi Kôranh, ƀiă lah ăn gâp hăn tâm khâl đah mpôl băl gâp lor.”$b$,true),
('bunong-vn','LUK',9,62,null,$b$Brah Yêsu plơ̆ lah ma păng: “Mbu nơm kuăn ta ti kau kai, jêh ri uănh pa kơi, mâu khư ma ƀon bri hađăch Brah Ndu ôh.”$b$,false),
('bunong-vn','LUK',10,1,null,$b$Jêh nau nây Kôranh Brah săch pơh jât nuyh phung oh mon êng, jêh ri Păng njuăl hăn bar hê lor ma Păng, hăn ta ntŭk Păng ŭch hăn tâm ăp mƀon.$b$,true),
('bunong-vn','LUK',10,2,null,$b$Păng lah ma phung oh mon: “Geh âk jêh ba dŭm, ƀiă lah geh djê̆ ngăn bunuyh rek. Pô ri dăn ma nơm mir njuăl âk bunuyh hăn rek.$b$,true),
('bunong-vn','LUK',10,3,null,$b$Hăn hom, aơ gâp njuăl khân may tâm ban ma phung kon biăp tâm nklang phung so bri.$b$,false),
('bunong-vn','LUK',10,4,null,$b$Lơi ta djôt prăk, dŭng, ntâu jot jêh ri hăn rŏ trong lơi ta mbah ma bu ôh.$b$,false),
('bunong-vn','LUK',10,5,null,$b$Tâm mbu ngih khân may mra lăp, lah pô aơ ro: ‘Ăn geh nau đăp mpăn ma ngih aơ.’$b$,true),
('bunong-vn','LUK',10,6,null,$b$Tơ lah ta nây geh bunuyh ŭch dơn nau đăp mpăn, nau đăp mpăn khân may mra gŭ tâm păng. Tơ lah mâu geh pô nây, nau đăp mpăn nây mra plơ̆ sĭt ma khân may nơm.$b$,false),
('bunong-vn','LUK',10,7,null,$b$Gŭ hom tâm ngih nây, sông sa jêh ri nhêt, moh ndơ bu mra ăn ma khân may, yor lah bunuyh pah kan khư ma nau nkhôm. Lơi hăn tă bơh ngih aơ rlau ngih êng ôh.$b$,false),
('bunong-vn','LUK',10,8,null,$b$Mbu ƀon khân may lăp jêh ri mbah ntŭk bu mra rom khân may, ăn khân may sông sa hom, moh ndơ bu thai ma khân may,$b$,true),
('bunong-vn','LUK',10,9,null,$b$ƀư bah phung ji kuet geh ta nây, jêh ri lah ma khân păng. Ƀon bri hađăch Brah Ndu dăch tât ma khân may.$b$,false),
('bunong-vn','LUK',10,10,null,$b$Ƀiă lah tâm nau ƀon khân may mra lăp, jêh ri ta ntŭk bu mâu mra rom khân may, hăn hom tâm trong ƀon nây jêh ri lah:$b$,false),
('bunong-vn','LUK',10,11,null,$b$‘Hên rtuh, nđâp ma ndruyh ƀon khân may krêp ta jâng hên, gay ma tâm rdâng đah khân may, ăn khân may gĭt ma ƀon bri hađăch Brah Ndu dăch tât jêh.’$b$,false),
('bunong-vn','LUK',10,12,null,$b$Gâp lah ma khân may tâm nar nây ƀon Sôdôm mra dơn nau tâm rmal n'gơch lơn ma ƀon nây.”$b$,false),
('bunong-vn','LUK',10,13,null,$b$“Rêh ni yơh ma may, hơi ƀon Kôrasin! Rêh ni yơh ma may, hơi ƀon Ƀêtsaiđa! Yor lah nau khlay bu ƀư ta nklang phung khân may. Tơ lah bu ƀư jêh tâm ƀon Tyr jêh ri ƀon Sidôn, jŏ jêh khân păng soh ao ƀau jêh ri mbrui ŭnh buh, tâm rmal ma nau tih khân păng.$b$,true),
('bunong-vn','LUK',10,14,null,$b$Yor ri tâm nar phat dôih ƀon Tyr jêh ri ƀon Sidôn mra dơn nau tâm rmal n'gơch lơn ma khân may.$b$,false),
('bunong-vn','LUK',10,15,null,$b$Jêh ri may, hơi ƀon Kapernum, bu n'hao jêh may tât klơ trôk đŏng? May mra jŭr tât ta ƀon phung khĭt.$b$,false),
('bunong-vn','LUK',10,16,null,$b$Mbu nơm iăt nau khân may, jêng iăt nau gâp yơh, jêh ri mbu nơm dun khân may, jêng dun gâp yơh, jêh ri mbu dun gâp jêng dun Nơm tơm njuăl gâp tâm ban lĕ.”$b$,false),
('bunong-vn','LUK',10,17,null,$b$Phung pơh jât nuyh plơ̆ sĭt răm maak jêh ri lah: “Ơ Kôranh Brah, nđâp ma phung brah mhĭk tông ma hên tâm ban lĕ tâm amoh may!”$b$,true),
('bunong-vn','LUK',10,18,null,$b$Brah Yêsu lah ma khân păng: “Gâp saơ jêh Satan tŭp tă bơh trôk tâm ban ma lơp.$b$,false),
('bunong-vn','LUK',10,19,null,$b$Aơ, gâp ăn jêh ma khân may nau brah, dơi hăn ta klơ phung bêh jêh ri phung ndŭr vơng, jêh ri ta klơ lĕ nau brah nơm rlăng, jêh ri mâu geh ndơ dơi ƀư mhĭk ma khân may ôh.$b$,false),
('bunong-vn','LUK',10,20,null,$b$Ƀiă lah lơi ta răm ôh yor phung brah mhĭk tông ma khân may, ƀiă lah răm maak hom yor amoh khân may nchih jêh tâm trôk.”$b$,false),
('bunong-vn','LUK',10,21,null,$b$Rnôk nây lĕ Brah Yêsu geh nau răm tă bơh Brah Huêng Ueh jêh ri lah: “Gâp tâm rnê ma may, Ơ Mbơ̆ , kôranh trôk jêh ri neh ntu, yor lah may pôn jêh nau nây ma phung blau mĭn jêh ri gĭt rbăng, ƀiă lah may tâm mpơl jêh ma phung kon se, Ơ Mbơ̆ , yor lah nau nây ƀư maak ma may.$b$,true),
('bunong-vn','LUK',10,22,null,$b$Lĕ rngôch ndơ Mbơ̆ ăn jêh ma gâp. Mâu geh nơm gĭt năl Kon ôh, knŏng Mbơ̆ gĭt, mâu lĕ geh nơm dơi năl Mbơ̆ , knŏng Kon gĭt, jêh ri ma mbu nơm Kon rŏng tâm mpơl Mbơ̆ Păng.”$b$,false),
('bunong-vn','LUK',10,23,null,$b$Jêh ri păng n'gĭl uănh ma phung oh mon, jêh ri lah ma khân păng êng êng: “Ueh maak yơh ma măt saơ, nau khân may saơ!$b$,true),
('bunong-vn','LUK',10,24,null,$b$Yor lah gâp lah ma khân may, geh âk phung kôranh nơm mbơh lor, jêh ri phung hađăch ŭch uănh nau khân may saơ, ƀiă lah mâu saơ ôh, gay ŭch tăng nau khân may tăng, ƀiă lah mâu tăng ôh.”$b$,false),
('bunong-vn','LUK',10,25,null,$b$Geh du huê kôranh nchih sămƀŭt dâk, jêh ri ôp Brah Yêsu, ŭch rlong uănh Păng: “Hơi Kôranh nơm nti, moh nau gâp mra ƀư gay ma dơn nau rêh n'ho ro?”$b$,true),
('bunong-vn','LUK',10,26,null,$b$Brah Yêsu lah ma păng: “Moh ndơ bu nchih jêh tâm nau vay? Moh may saơ tâm nây?”$b$,false),
('bunong-vn','LUK',10,27,null,$b$Păng plơ̆ lah: “May mra rŏng ma kôranh Ndu may ma lĕ nuih n'hâm, ma lĕ huêng, ma lĕ nuih n'hâm ktang, jêh ri ma lĕ nau mĭn may, jêh ri rŏng ma phung chiau meng may tâm ban ma may nơm lĕ.”$b$,false),
('bunong-vn','LUK',10,28,null,$b$Brah Yêsu lah ma păng: “Nau may plơ̆ lah ueh jêh, ƀư pô nây jêh ri may mra rêh.”$b$,false),
('bunong-vn','LUK',10,29,null,$b$Ƀiă lah păng ŭch ƀư sŏng păng nơm, lah ma Brah Yêsu: “Mbu jêng nơm chiau meng gâp?”$b$,true),
('bunong-vn','LUK',10,30,null,$b$Brah Yêsu plơ̆ lah: “Du huê jŭr tă bơh ƀon Yêrusalem leo hăn ta ƀon Yêrikô. Păng tâm mâp đah phung ntŭng. Phung nây pit sŏk lơi drăp ndơ păng lĕ, dong păng ktang ngăn tât khĭt yơh, jêh ri nây du.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','LUK',10,31,null,$b$Geh du huê kôranh ƀư brah rgăn ta nĕ tâm ban lĕ. Saơ nây, păng veh uănh jêh ri n'hot hăn.$b$,false),
('bunong-vn','LUK',10,32,null,$b$Geh du huê Lêvi tât tâm ban lĕ ta ntŭk nây, saơ jêh ri n'hot du.$b$,false),
('bunong-vn','LUK',10,33,null,$b$Ƀiă lah geh du huê Samari dôl nsong tât ta ntŭk nây. Tơ lah păng saơ nơm nây păng geh nau yô̆.$b$,false),
('bunong-vn','LUK',10,34,null,$b$Păng hăn dăch jêh ri put an ntŭk sôt, nkhŭt dak ngi jêh ri lah: ‘Ăn may mât uănh păng.’$b$,false),
('bunong-vn','LUK',10,35,null,$b$Ôi taơ păng sŏk bar rêl prăk, ăn ma kôranh ngih jưh jêh ri lah: ‘Dăn may mât moh păng jêh ri moh ndơ may mra dâk dŏng, gâp mra trok ma may tơ lah gâp sĭt.’$b$,false),
('bunong-vn','LUK',10,36,null,$b$Mbu nơm tâm phung pe nuyh nây, may mĭn jêng nơm chiau meng ma nơm mâp phung ntŭng nây?”$b$,false),
('bunong-vn','LUK',10,37,null,$b$Kôranh nơm nti nau vay plơ̆ lah: “Nơm tâm mpơl jêh nau yô̆ ma păng yơh.” Jêh ri Brah Yêsu lah ma păng: “Hăn hom may, jêh ri ƀư tâm ban pô nây lĕ.”$b$,false),
('bunong-vn','LUK',10,38,null,$b$Dôl khân păng hăn nsong, păng lăp tâm du ƀon jêh ri geh du huê bu ur tâm amoh păng H'Mathê rom Păng lăp tâm ngih.$b$,true),
('bunong-vn','LUK',10,39,null,$b$Păng geh du huê oh bu ur amoh păng H'Mari. H'Mari gŭ ta jâng Kôranh Brah ŭch iăt nau Păng ngơi.$b$,true),
('bunong-vn','LUK',10,40,null,$b$Ƀiă lah H'Mathê geh âk kan nkra ndơ sông sa, văch jêh ri lah: “Ơ Kôranh Brah mâm ƀư may njê ma oh gâp, ƀŏng êng gâp nkra ndơ sông sa? Lah an ma păng ăn păng kơl gâp.”$b$,false),
('bunong-vn','LUK',10,41,null,$b$Kôranh Brah plơ̆ lah ma păng: “Hơi H'Mathê, Hơi H'Mathê, ay rngot jêh ri jêng uh ah ma âk ndơ.$b$,false),
('bunong-vn','LUK',10,42,null,$b$Geh knŏng du ntil nau jêng khlay. H'Mari săch dơn jêh nau ueh nây, jêh ri bu mâu mra dơi pit sŏk bơh păng ôh.”$b$,false),
('bunong-vn','LUK',11,1,null,$b$Du nar Brah Yêsu mbơh sơm tâm du ntŭk. Tơ lah lôch jêh du huê tâm phung oh mon lah ma Păng: “Hơi Kôranh, sâm nti an hên mbơh sơm, nâm bu Y-Yôhan nti jêh phung oh mon păng.”$b$,true),
('bunong-vn','LUK',11,2,null,$b$Brah Yêsu lah ma khân păng: “Tơ lah khân may mbơh sơm, khân may lah pô aơ: ‘Ơ Mbơ̆ hên gŭ tâm trôk ơi. Ăn amoh may bu yơk ăn ueh. Ăn ƀon bri hađăch may gơnh tât. Ăn nau may ŭch mra jêng ta neh ntu tâm ban ma klơ trôk.$b$,false),
('bunong-vn','LUK',11,3,null,$b$Ăn ma hên mpa sông sa ăp nar ăn tŏng.$b$,false),
('bunong-vn','LUK',11,4,null,$b$Yô̆ an nau tih hên, tâm ban ma hên yô̆ an jêh ma bunuyh ƀư tih đah hên, lơi ta njŭn leo hên tâm nau ndơm ôh, ƀiă lah ăn may rklaih hên bơh nau tih mhĭk.’ ”$b$,false),
('bunong-vn','LUK',11,5,null,$b$Brah Yêsu lah ma khân păng: “Mbu nơm tâm phung khân may mra geh du huê mĭt jiăng hăn tâm n'gul măng jêh ri lah: ‘Hơi jiăng, gâp dăn ma may pe mlâm ƀănh,$b$,true),
('bunong-vn','LUK',11,6,null,$b$yor lah du huê jiăng gâp mhe tât ta ngih gâp, gâp mâu geh ndơ ăn păng sa ôh,’$b$,false),
('bunong-vn','LUK',11,7,null,$b$nơm nây gŭ tâm trôm ngih jêh ri plơ̆ lah ma păng pô aơ. Lơi rsuak gâp ôh, mpông lĕ nchăng jêh, phung kon gâp jêh ri gâp nơm lĕ bêch jêh.$b$,false),
('bunong-vn','LUK',11,8,null,$b$Gâp mâu dơi dâk ăn kapŭng ma may ôh, yor jiăng păng, ƀiă lah yor nau tâm rsuak, yor ri păng dâk jêh ri ăn nŭm dŭm ndơ ŭch dŏng.$b$,false),
('bunong-vn','LUK',11,9,null,$b$Gâp lah ma khân may. Dăn hom dĭng geh, joi hom dĭng saơ, goh hom mpông dĭng bu ma pơk an ma khân may.$b$,false),
('bunong-vn','LUK',11,10,null,$b$Yor lah mbu nơm dăn mra geh, mbu nơm joi mra saơ, jêh ri bu mra pơk an ma mbu nơm goh.$b$,false),
('bunong-vn','LUK',11,11,null,$b$Mbu nơm tâm phung khân may jêng mbơ̆ bu, ăn ma kon du glo lŭ, tơ lah kon păng dăn kapŭng? Mâu lah, tơ lah păng dăn ka, păng ăn du mlâm bêh nsro ka lĕ.$b$,true),
('bunong-vn','LUK',11,12,null,$b$Mâu lah kon păng dăn du mlâm tăp iăr, păng ăn ma kon păng du mlâm ndŭr vơng hĕ?$b$,true),
('bunong-vn','LUK',11,13,null,$b$Tơ lah khân may jêng phung djơh, ăt gĭt ăn ndơ ueh ma phung kon khân may, lơ hâu ma nĕ đŏng Mbơ̆ khân may klơ trôk mra ăn Brah Huêng Ueh ma mbu nơm dăn ma Păng.”$b$,false),
('bunong-vn','LUK',11,14,null,$b$Brah Yêsu mprơh du huê brah mhĭk mlo. Tơ lah brah mhĭk du luh jêh, bunuyh mlo blau ngơi, jêh ri phung âk gŭ hih rhâl.$b$,true),
('bunong-vn','LUK',11,15,null,$b$Ƀiă lah ƀa ƀă lah: “Ma Bêlsêbul kon hađăch phung brah mhĭk, phung nsot phung brah mhĭk.”$b$,false),
('bunong-vn','LUK',11,16,null,$b$Jêh ri phung êng ŭch rlong uănh păng, dăn ma păng du ntil nau tâm mbên tă bơh trôk.$b$,false),
('bunong-vn','LUK',11,17,null,$b$Tơ lah Păng gĭt nau mĭn khân păng, Brah Yêsu lah pô aơ: “Ăp ƀon bri hađăch tâm pă, tâm rdâng ndrăng khân păng nơm rai jêh, jêh ri du mlâm ngih rlâm ta klơ du rplay ngih êng.$b$,true),
('bunong-vn','LUK',11,18,null,$b$Pô nây, tơ lah Satan tâm nkhah, ndrăng păng nơm, mâm ƀư ƀon bri hađăch păng dơi hôm kơn? Yor lah khân may lah, gâp mprơh phung brah mhĭk ma Bêlsêbul.$b$,false),
('bunong-vn','LUK',11,19,null,$b$Jêh ri tơ lah gâp mprơh brah mhĭk ma Bêlsêbul, ma mbu nơm kon khân may mprơh khân păng? Yor nây khân păng nơm mra jêng kôranh phat dôih khân may.$b$,false),
('bunong-vn','LUK',11,20,null,$b$Ƀiă lah, tơ lah ma nglau ti Brah Ndu, gâp mprơh phung brah mhĭk, ƀon bri hađăch Brah Ndu tât jêh ma khân may.$b$,true),
('bunong-vn','LUK',11,21,null,$b$Tơ lah du huê bunuyh ktang geh jêh ndơ tâm lơh chiă uănh ngih păng nơm, ndơ păng geh gŭ ueh yơh.$b$,false),
('bunong-vn','LUK',11,22,null,$b$Ƀiă lah tơ lah du huê ktang lơn ma păng văch jêh ri dơi chăp păng, nơm nây sŏk ndơ tâm lơh păng rnơm, jêh ri tâm pă lĕ drăp ndơ păng.$b$,false),
('bunong-vn','LUK',11,23,null,$b$“Mbu nơm mâu gŭ ndrel ma gâp, tâm rdâng đah gâp, jêh ri mbu nơm mâu tâm rnglăp đah gâp, nkhah du êng êng.$b$,true),
('bunong-vn','LUK',11,24,null,$b$Tơ lah brah mhĭk ƀơ̆ du luh jêh tă bơh du huê bunuyh, păng hăn tâm ntŭk sơh, ŭch joi ntŭk rlu; mâu saơ ntŭk ôh, păng lah: ‘Gâp mra plơ̆ sĭt ta ngih, bơh nây gâp du luh jêh!’$b$,false),
('bunong-vn','LUK',11,25,null,$b$Tơ lah păng tât, păng saơ ngih nây bu mpêh jêh ri rep păng ueh jêh.$b$,false),
('bunong-vn','LUK',11,26,null,$b$Pô ri păng hăn jêh ri sŏk ndrel ma păng pơh nuyh brah mhĭk êng, janh ƀai lơn ma păng. Khân păng lăp tâm ngih, gŭ ta nây. Pô ri bunuyh nây jêng djơh lơn ma sa ơm.”$b$,false),
('bunong-vn','LUK',11,27,null,$b$Dôl Brah Yêsu ngơi pô nây, geh du huê bu ur nter tâm nklang phung âk, lah ma Brah Yêsu: “Ueh maak yơh ma ndŭl ntreo kôranh Brah. Jêh ri toh ăn may pu jêh!”$b$,true),
('bunong-vn','LUK',11,28,null,$b$Ƀiă lah Brah Yêsu lah: “Ueh maak lơn ma phung iăt nau Brah Ndu ngơi jêh ri djôt prăp!”$b$,true),
('bunong-vn','LUK',11,29,null,$b$Tơ lah geh bunuyh âk râk, Brah Yêsu ntơm lah: “Phung rnôk aơ jêng phung ƀai; khân păng dăn du ntil nau khlay, ƀiă lah bu mâu mra ăn ma khân păng nau khlay êng ôh, knŏng nau khlay Y-Yônas.$b$,true),
('bunong-vn','LUK',11,30,null,$b$Tâm ban ma Y-Yônas jêng du ntil nau tâm mbên ma phung Ninivơ, tâm ban pô nây lĕ, kon bunuyh mra jêng du nau tâm mbên ma phung rnôk aƀaơ.$b$,true),
('bunong-vn','LUK',11,31,null,$b$Hađăch bu ur bơh rđŭng mra dâk ta nar phat dôih ndrel ma phung rnôk aơ, jêh ri mra phong khân păng, yor lah khân păng văch tă bơh dŭt bri dŭt neh gay ma iăt nau blau mĭn hađăch Salômôn; jêh ri aơ, geh du huê ta aơ toyh lơn ma Salômôn.$b$,false),
('bunong-vn','LUK',11,32,null,$b$Phung bunuyh ƀon Ninivơ mra dâk tâm nar phat dôih ndrel ma phung rnôk aơ jêh ri mra phong khân păng, yor lah jêh tăng nau Y-Yônas nti lah phung Ninivơ rmal nau tih, jêh ri aơ geh du huê toyh lơn ma Y-Yônas tât jêh.$b$,false),
('bunong-vn','LUK',11,33,null,$b$“Bu mâu mpoh ôh ŭnh kđen gay ma ăn ta ntŭk ndâp mâu lah tâm dâng trôm mbung, ƀiă lah bu yông ta n'gâng, gay ma mbu nơm lăp, dơi saơ nau ang.$b$,true),
('bunong-vn','LUK',11,34,null,$b$Măt may jêng ŭnh kđen ma săk jăn may; tơ lah măt may gŭ ueh, lĕ săk jăn may geh nau ang; ƀiă lah tơ lah măt may jêng mhĭk, săk jăn may gŭ tâm nau ngo.$b$,false),
('bunong-vn','LUK',11,35,null,$b$Pô ri, njrăng hom, lơi ăn nau ang tâm may jêng ngo.$b$,false),
('bunong-vn','LUK',11,36,null,$b$Tơ lah lĕ săk jăn may geh nau ang, mâu geh du kô̆ gŭ tâm nau ngo ôh, păng mra geh nau ang lam tâm ban ma ŭnh kđen sol may ma nau ang păng.”$b$,false),
('bunong-vn','LUK',11,37,null,$b$Dôl Brah Yêsu gŭ ngơi, du huê Pharisi jă Păng sông sa tâm ngih păng. Păng lăp jêh ri ntơm sông sa.$b$,true),
('bunong-vn','LUK',11,38,null,$b$Du huê Pharisi nây hih rhâl yor lah lor ma sông sa păng mâu geh rao ti.$b$,false),
('bunong-vn','LUK',11,39,null,$b$Ƀiă lah Kôranh Brah lah ma păng: “Phung Pharisi khân may ƀư kloh ngan jêh ri jam knŏng klơ ntâu ƀiă lah tâm trôm khân may bêng ma nau ndơm jêh ri nau ƀai.$b$,false),
('bunong-vn','LUK',11,40,null,$b$Phung rluk yơh! Mbu ƀư pa dih, păng mâu ƀư nđâp ma tâm trôm?$b$,false),
('bunong-vn','LUK',11,41,null,$b$Ƀiă lah ăn khân may nhhơr nau yô̆ ndơ khân may geh tâm trôm; pô ri lĕ rngôch ndơ mra jêng kloh ma khân may.$b$,true),
('bunong-vn','LUK',11,42,null,$b$Ƀiă lah rêh ni yơh ma phung khân may Pharisi! Yor lah khân may nhhơr du kô̆ tâm jât klôih, tơm play ƀâu kah jêh ri lĕ n'ha trau, ƀiă lah khân may chuêl ma nau sŏng, jêh ri ma nau rŏng Brah Ndu, ma nau aơ yơh ăn khân may tông dôl mâu dun ôh nau êng.$b$,false),
('bunong-vn','LUK',11,43,null,$b$Rêh ni yơh ma phung khân may, Pharisi! Yor lah khân may rŏng ntŭk khlay tâm ngih tâm rƀŭn Yuđa, jêh ri nau bu mbah tâm ngih tăch drăp.$b$,false),
('bunong-vn','LUK',11,44,null,$b$Rêh ni yơh ma khân may jêng nâm bu môch mâu mpơl, jêh ri bu hăn jot ta klơ môch ƀiă lah mâu gĭt năl ôh.”$b$,false),
('bunong-vn','LUK',11,45,null,$b$Du huê tâm phung nchih sămƀŭt ngơi ma Păng pô aơ: “Hơi Kôranh nơm nti, tơ lah may ngơi pô nây, may nduyh nđâp ma hên lĕ.”$b$,true),
('bunong-vn','LUK',11,46,null,$b$Jêh ri Brah Yêsu plơ̆ lah: “Rêh ni nđâp ma khân may tâm ban lĕ, hơi phung kôranh nchih sămƀŭt! Yor lah khân may ăn bu anh ndơ jâk, ƀiă lah khân may nơm mâu pah bi du nglau ti ôh.$b$,false),
('bunong-vn','LUK',11,47,null,$b$Rêh ni yơh ma khân may! Yor lah khân may nkra môch phung kôranh nơm mbơh lor, phung mbơ̆ khân may nkhĭt lơi jêh.$b$,false),
('bunong-vn','LUK',11,48,null,$b$Pô ri khân may dơn jêh nau khân păng ƀư. Yor lah khân may nkhĭt jêh phung kôranh nơm mbơh lor jêh ri khân păng.$b$,false),
('bunong-vn','LUK',11,49,null,$b$Yor nây nau gĭt mĭn Brah Ndu lah jêh: ‘Gâp mra njuăl ma khân păng phung kôranh mbơh lor jêh ri phung kôranh oh mon. Ƀa ƀă khân păng mra nkhĭt lơi, ƀa ƀă khân păng ƀư mhĭk.’$b$,false),
('bunong-vn','LUK',11,50,null,$b$Gay dăn ma phung bunuyh rnôk aơ, mham lĕ rngôch phung kôranh nơm mbơh lor nkhŭt jêh tâm rnôk ntơm rhăk njêng neh ntu.$b$,false),
('bunong-vn','LUK',11,51,null,$b$Ntơm bơh mham Y-Abel tât ta mham Y-Sakari bu nkhĭt ta vah vang nơng ƀư brah ma ngih Brah Ndu. Ơ, gâp lah ma khân may, bu mra dăn mham nây ma phung rnôk aƀaơ.$b$,false),
('bunong-vn','LUK',11,52,null,$b$Rêh ni yơh ma khân may, Hơi phung kôranh nchih sămƀŭt! Yor lah khân may pit sŏk lơi khŏa nau gĭt rbăng; khân may nơm mâu mâp lăp ôh, jêh ri khân may buay nđâp ma phung ŭch lăp lĕ.”$b$,false),
('bunong-vn','LUK',11,53,null,$b$Tơ lah păng luh jêh tă bơh ntŭk nây, phung kôranh nchih sămƀŭt jêh ri phung Pharisi ntơm ôp mpet Păng ktang ngăn, jêh ri ăn Păng ngơi ma âk ntil ndơ.$b$,true),
('bunong-vn','LUK',11,54,null,$b$Kâp iăt Păng, gay sŏk nau ngơi ŭch phong Păng.$b$,false),
('bunong-vn','LUK',12,1,null,$b$Dôl nây tơ lah geh âk rbăn bunuyh tâm rƀŭn, kŏ tâm tŭn tâm jot ndrăng băl nơm, Brah Yêsu ngơi ma phung oh mon Păng pô aơ: “Njrăng hom ma ndrui phung Pharisi nâm bu ntĭt, nuih n'hâm mŭr.$b$,true),
('bunong-vn','LUK',12,2,null,$b$Mâu geh ndơ pôn mra mâu dơi mpơl, mâu lĕ dơi geh nau ndâp bu mâu mra dơi gĭt.$b$,true),
('bunong-vn','LUK',12,3,null,$b$Yor nây lĕ nau khân may lah tâm ntŭk ngo, bu mra tăng tâm ntŭk ang, jêh ri moh nau khân may lah lăp tâm trôm tôr, tâm jrô ndâp bu mra mbơh ta klơ bôk pho.”$b$,true),
('bunong-vn','LUK',12,4,null,$b$“Gâp lah ma khân may phung jiăng Gâp, lơi klach ôh ma phung nkhĭt săk jăn, jêh nây mâu hôm dơi ƀư đŏng ôh.$b$,true),
('bunong-vn','LUK',12,5,null,$b$Gâp mra mbơh ma mbu nơm khân may mra klach, ăn khân may klach ma Nơm, jêh Păng nkhĭt săk jăn, hôm geh nau dơi mƀăr tâm n'gar ŭnh. Ơ, gâp lah ma khân may, klach hom ma Păng!$b$,false),
('bunong-vn','LUK',12,6,null,$b$“Bu mâu tăch hĕ prăm mlâm sĭm srai rnoh bar rêl? Ƀiă lah mâu geh du mlâm ôh tâm phung khân păng Brah Ndu chuêl.$b$,true),
('bunong-vn','LUK',12,7,null,$b$Nđâp ma sŏk ta klơ bôk khân may kơp lĕ jêh. Pô ri lơi klach ôh, khân may jêng khlay lơn ma phung sĭm srai.$b$,true),
('bunong-vn','LUK',12,8,null,$b$“Gâp lah ma khân may, mbu nơm mbơh gâp ta năp bunuyh, Kon Bunuyh mra mbơh khân păng tâm ban lĕ ta năp phung Tông mpăr ueh Brah Ndu;$b$,true),
('bunong-vn','LUK',12,9,null,$b$Ƀiă lah mbu nơm mra dun gâp ta năp bunuyh. Gâp mra dun păng ta năp phung Tông mpăr ueh Brah Ndu.”$b$,false),
('bunong-vn','LUK',12,10,null,$b$“Mbu nơm ngơi tâm rdâng đah Kon Bunuyh mra geh nau yô̆ an ma păng; Ƀiă lah mbu nơm sưr rlau đah Brah Huêng Ueh mâu mra geh nau yô̆ an ôh.$b$,true),
('bunong-vn','LUK',12,11,null,$b$“Tơ lah bu njŭn leo khân may ta năp ngih rƀŭn phung Yuđa, phung kôranh phat dôih, jêh ri phung kôranh chiă uănh, lơi ta rngot ôh ma nau khân may n'gang ma khân may nơm, mâu lah ma nau khân may mra lah.$b$,true),
('bunong-vn','LUK',12,12,null,$b$Yor lah Brah Huêng Ueh mra nti an ma khân may ta mông khân may mra lah.”$b$,false),
('bunong-vn','LUK',12,13,null,$b$Du huê tâm phung âk nây lah ma Brah Yêsu: “Hơi kôranh nơm nti, lah an ma oh gâp tâm pă drăp ndơn hên geh.”$b$,true),
('bunong-vn','LUK',12,14,null,$b$Brah Yêsu plơ̆ lah ma păng: “Hơi jiăng, mbu ăn gâp jêng kôranh phat dôih ma khân may, mâu lah nơm pă an drăp ndơ khân may?”$b$,true),
('bunong-vn','LUK',12,15,null,$b$Jêh ri Păng lah ma phung nây: “Njrăng hom, lơi kơnh ma drăp ndơ, yor lah nau rêh du huê bunuyh mâu jêng yor ma drăp ndơ păng geh âk rmeh ôh!”$b$,false),
('bunong-vn','LUK',12,16,null,$b$Păng nkoch ntĭt du nau hôr pô aơ: “Neh mir du huê bunuyh ndrŏng geh âk ba;$b$,true),
('bunong-vn','LUK',12,17,null,$b$jêh ri păng mĭn êng tâm nuih n'hâm: ‘Mâm gâp mra ƀư? Yor lah gâp mâu hôm geh ntŭk prăp ba ôh?’$b$,false),
('bunong-vn','LUK',12,18,null,$b$Păng lah: ‘Gâp mra ƀư pô aơ, gâp mra rơih lĕ jay ba gâp, jêh ri ƀư toyh lơn đŏng, gâp mra bun nkrem ba gâp jêh ri drăp ndơ gâp tâm nĕ.$b$,false),
('bunong-vn','LUK',12,19,null,$b$Jêh ri gâp mra lah ma huêng gâp, hơi huêng gâp, may geh âk drăp ndơ prăp jêh âk năm, rlu hom may, sông sa nhêt jêh ri răm maak hom may.’$b$,false),
('bunong-vn','LUK',12,20,null,$b$Ƀiă lah Brah Ndu lah ma păng: ‘Hơi bunuyh rluk! Măng aơ lĕ gâp mra nhŭp huêng may jêh ri ndơ may nkra jêh, mbu mra ndơn đŏng?’$b$,false),
('bunong-vn','LUK',12,21,null,$b$Mbu nơm bun prăp âk drăp ndơ ma păng nơm jêh ri mâu jêng ndrŏng tâm Brah Ndu ăt tâm ban pô nây đŏng.”$b$,false),
('bunong-vn','LUK',12,22,null,$b$Jêh ri Brah Yêsu lah ma phung oh mon Păng: “Yor nây gâp lah ma khân may, lơi yor nau rêh rvê ir ma ndơ sông sa, mâu lĕ yor săk jăn rvê ir ma ndơ nsoh n'gut.$b$,true),
('bunong-vn','LUK',12,23,null,$b$Nau rêh khlay lơn ma ndơ sông sa, jêh ri săk jăn khlay lơn ma kho ao.$b$,true),
('bunong-vn','LUK',12,24,null,$b$Uănh hom ma phung nđak, khân păng mâu mâp srih, mâu lĕ mâp rek. Khân păng mâu geh jay, ƀiă lah Brah Ndu siăm khân păng. Dŭm tơ̆ khân may jêng khlay lơn ma phung sĭm nây!$b$,false),
('bunong-vn','LUK',12,25,null,$b$Mbu tâm phung khân may ma nau rngot dơi ntop nar ma nau rêh păng?$b$,false),
('bunong-vn','LUK',12,26,null,$b$Pô nây, tơ lah khân may mâu dơi ƀư ndơ jê̆, mâm ƀư khân may rngot ma ndơ êng?$b$,true),
('bunong-vn','LUK',12,27,null,$b$Uănh hom mâm ƀư kao luh; khân păng mâu mâp pah kan, mâu lĕ mâp rui tanh, ƀiă lah gâp lah ma khân may, hađăch Salômôn tâm lĕ nau chrêk rmah păng mâu mâp soh n'gut bok ao tâm ban ma phung kao nây ôh.$b$,false),
('bunong-vn','LUK',12,28,null,$b$Tơ lah Brah Ndu sâm nsoh păng, nar aơ păng gŭ tâm mir jêh ri ôi taơ bu mra klŭp tâm ŭnh năk, rlau lơn ma nây Brah Ndu mra nsoh khân may. Hơi phung geh djê̆ lê̆ nau chroh.$b$,false),
('bunong-vn','LUK',12,29,null,$b$Jêh ri lơi ta khân may joi ndơ khân may mra sông sa mâu lah nhêt ôh, jêh ri lơi rngot klâng ôh.$b$,false),
('bunong-vn','LUK',12,30,null,$b$Yor lah lĕ rngôch ndơ nây phung neh ntu joi, mbơ̆ khân may gĭt jêh moh ndơ khân may pưt.$b$,false),
('bunong-vn','LUK',12,31,null,$b$Ƀiă lah lor lơn ăn joi ƀon bri hađăch Păng, jêh ri lĕ rngôch ndơ nây bu mra ntop an ma khân may.”$b$,false),
('bunong-vn','LUK',12,32,null,$b$“Lơi klach ôh, hơi phung jê̆, yor lah mbơ̆ khân may mĭn ueh, ăn ma khân may ƀon bri hađăch Păng.$b$,true),
('bunong-vn','LUK',12,33,null,$b$Tăch hom drăp ndơ khân may geh, jêh ri ăn yô̆. Joi hom dŭng mâu blau mŭnh, nau ndrŏng tâm trôk mâu blau lĕ ôh. Ta nây bunuyh ntŭng mâu dơi ƀư rai păng ôh.$b$,false),
('bunong-vn','LUK',12,34,null,$b$Yor lah ta ntŭk drăp ndơ may gŭ, nuih n'hâm may gŭ ta nây lĕ.”$b$,false),
('bunong-vn','LUK',12,35,null,$b$“Ăn khân may rêt rse bŭt khân may, jêh ri mpoh ŭnh kđen khân may.$b$,true),
('bunong-vn','LUK',12,36,null,$b$Ăn khân may jêng tâm ban ma bunuyh gŭ kâp kôranh khân păng plơ̆ văch bơh nau nhêt sông tâm nsông ur sai, kâp pơk mpông ma păng ro, tơ lah păng tât goh mpông.$b$,false),
('bunong-vn','LUK',12,37,null,$b$Ueh maak yơh ma phung oh mon nây tơ lah kôranh păng tât, jêh ri saơ khân păng gŭ njrăng. Gâp lah ma khân may, nanê̆ păng mra rêt rse bŭt, ăn khân păng gŭ jêh ri njŭn ndơ sông sa.$b$,false),
('bunong-vn','LUK',12,38,null,$b$Tơ lah păng tât klong măng mâu lah dăch kêng ôi, ueh maak yơh ma phung oh mon nây, tơ lah kôranh saơ khân păng gŭ njrăng!$b$,false),
('bunong-vn','LUK',12,39,null,$b$Ăn khân may gĭt nau aơ ăn ueh, tơ lah kôranh ngih dơi gĭt mông bunuyh ntŭng tât, păng mra njrăng jêh ri mâu mra ăn ôh bu lôk ngih păng.$b$,false),
('bunong-vn','LUK',12,40,null,$b$Khân may tâm ban lĕ njrăng hom, yor lah Kon Bunuyh mra văch tâm mông khân may mâu mĭn ôh.”$b$,true),
('bunong-vn','LUK',12,41,null,$b$Y-Pêtrôs lah ma păng: “Ơ Kôranh Brah, ma hên lĕ, mâu lah ma lĕ rngôch nau may ngơi hôr aơ?”$b$,true),
('bunong-vn','LUK',12,42,null,$b$Jêh ri Brah Yêsu lah: “Mbu nơm oh mon răp jăp jêh ri blau njrăng, kôranh ăn păng jêng nơm tâm pă ndơ sông sa di mông ma phung oh mon êng.$b$,false),
('bunong-vn','LUK',12,43,null,$b$Ueh maak yơh ma phung nây, tơ lah kôranh păng tât jêh ri saơ păng ƀư pô nây.$b$,false),
('bunong-vn','LUK',12,44,null,$b$Gâp lah nau ngăn ma khân may, kôranh mra ăn păng chiă uănh lĕ drăp ndơ păng.$b$,false),
('bunong-vn','LUK',12,45,null,$b$Ƀiă lah tơ lah oh mon nây lah tâm nuih n'hâm păng: ‘Kôranh gâp văch nkai,’ pô nây, păng ntơm dong phung oh mon nđâp bu ur, jêh ri nhêt sa tât nhŭl ndrănh.$b$,false),
('bunong-vn','LUK',12,46,null,$b$Kôranh oh mon nây mra văch ta nar păng mâu geh njrăng, jêh ri ta mông păng mâu gĭt ôh. Păng mra tâm rmal oh mon nây ktang, jêh ri kơp păng ndrel ma phung mâu chroh.$b$,false),
('bunong-vn','LUK',12,47,null,$b$Oh mon gĭt jêh nau kôranh păng ŭch ƀiă lah mâu nkra jêh ri mâu ŭch ƀư ôh tĭng nâm kôranh păng ŭch, mra geh nau dong âk tơ̆ .$b$,false),
('bunong-vn','LUK',12,48,null,$b$Ƀiă lah mbu nơm mâu mâp gĭt, jêh ri ƀư nau khư tâm rmal, mra geh nau dong djê̆. Bu mra dăn âk ma nơm bu ăn âk, jêh ri bu mra dăn âk lơn ma nơm bu jao jêh âk.”$b$,true),
('bunong-vn','LUK',12,49,null,$b$“Gâp văch jêh gay nkhŭt ŭnh ta neh ntu, jêh ri gay ma ŭnh nây hit!$b$,true),
('bunong-vn','LUK',12,50,null,$b$Geh nau ƀaptem gâp mra dơn, jêh ri gâp srôih gŭ mĭn lĕ ma gâp văch nau đăp mpăn ta neh ntu?$b$,false),
('bunong-vn','LUK',12,51,null,$b$Gâp lah ma khân may, mâu di ôh, ƀiă lah nau tâm pă;$b$,false),
('bunong-vn','LUK',12,52,null,$b$Yor lah rlet aơ pa năp, tâm du mlâm ngih geh prăm nuyh mra geh nau tâm nkhah, pe nuyh tâm rdâng đah bar jêh ri bar tâm rdâng đah pe.$b$,false),
('bunong-vn','LUK',12,53,null,$b$Mbơ̆ tâm rdâng đah kon, jêh ri kon tâm rdâng đah mbơ̆ , mê̆ tâm rdâng đah kon bu ur jêh ri kon bu ur tâm rdâng đah mê̆. Po bu ur, tâm rdâng đah ƀăn, jêh ri ƀăn tâm rdâng đah po bu ur.”$b$,false),
('bunong-vn','LUK',12,54,null,$b$Păng lah đŏng ma phung âk: “Tơ lah khân may saơ ndâr tŭk tă bơh dâng khân may lah ro: Trôk mra mih, jêh ri tât ngăn.$b$,true),
('bunong-vn','LUK',12,55,null,$b$Jêh ri tơ lah khân may saơ sial khôm tă bơh rđŭng, khân may lah: Mra duh nar; jêh ri tât ngăn.$b$,true),
('bunong-vn','LUK',12,56,null,$b$Hơi phung nuih n'hâm mŭr! Khân may gĭt mbên nau neh jêh ri trôk jêng. Mâm ƀư khân may mâu gĭt mbên tâm rnôk aơ?$b$,false),
('bunong-vn','LUK',12,57,null,$b$Jêh ri mâm ƀư khân may mâu gĭt ma khân may nơm moh nau jêng sŏng?”$b$,false),
('bunong-vn','LUK',12,58,null,$b$“Tơ lah may hăn ta năp phung kôranh phat dôih, ndrel ma nơm phong may, ăn may joi nau tâm njĭr đah păng, klach ma păng njŭn leo ta năp kôranh phat dôih, jêh ri kôranh phat dôih jao may ma kôranh bu nă, jêh ri kôranh bu nă mra krŭng may.$b$,true),
('bunong-vn','LUK',12,59,null,$b$Gâp lah ma may, may mâu mra luh ôh tă bơh ndrung tât may chê̆ lĕ dôih.”$b$,true),
('bunong-vn','LUK',13,1,null,$b$Rnôk nây lĕ ƀa ƀă bunuyh ta nây nkoch bri ma Brah Yêsu nau tât jêh ma phung Galilê, Pilat tâm rlŭk mham khân păng ndrel ma ndơ khân păng ƀư brah.$b$,true),
('bunong-vn','LUK',13,2,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Khân may chroh lĕ ma phung Galilê nây jêng phung tih, toyh lơn ma phung Galilê êng yor lah khân păng dơn nau rêh ni pô nây?$b$,false),
('bunong-vn','LUK',13,3,null,$b$Gâp lah ma khân may, Mâu; ƀiă lah tơ lah khân may mâu tâm rmal nau tih khân may, khân may rai lôch tâm ban lĕ.$b$,false),
('bunong-vn','LUK',13,4,null,$b$Mâu lah phung jât ma pham nuyh ngih prêh Silôê nklân, jêh ri khĭt lĕ rngôch, khân may mĭn lĕ khân păng, jêng phung tih toyh lơn ma phung êng tâm ƀon Yêrusalem?$b$,true),
('bunong-vn','LUK',13,5,null,$b$Gâp lah ma khân may, mâu! Ƀiă lah tơ lah khân may mâu rmal nau tih khân may, khân may mra rai lôch tâm ban lĕ.”$b$,true),
('bunong-vn','LUK',13,6,null,$b$Păng ngơi nau hôr aơ: “Du huê bunuyh geh du tơm rvi tăm tâm mir play kriăk ƀâu păng, păng hăn joi play ta nây, ƀiă lah mâu saơ ôh.$b$,true),
('bunong-vn','LUK',13,7,null,$b$Pô ri păng lah ma nơm chiă mir play kriăk ƀâu! Geh pe năm jêh gâp hăn joi play tâm rvi aơ, ƀiă lah mâu saơ ôh. Kăl lơi păng mâm ƀư păng in neh dơm dam?$b$,false),
('bunong-vn','LUK',13,8,null,$b$Nơm chiă plơ̆ lah ma păng: Hơi kôranh, om păng ƀât du năm aơ. Gâp mra n'hao neh jŭm tơm păng, jêh ri suy ek ndrôk.$b$,true),
('bunong-vn','LUK',13,9,null,$b$Klăp lah năm pa kơi taơ păng mra geh play. Tơ lah mâu geh, may mra kăl lơi păng!”$b$,false),
('bunong-vn','LUK',13,10,null,$b$Brah Yêsu nti lah tâm du mlâm ngih rƀŭn phung Yuđa nar Saƀat.$b$,true),
('bunong-vn','LUK',13,11,null,$b$Geh ta nây du huê bu ur brah mhĭk lơh tât jêng rvĕn geh jêh tâm jât ma pham năm. Ndŭr kơi păng đŭn, mâu hôm dơi nsŏng săk jăn ôh.$b$,false),
('bunong-vn','LUK',13,12,null,$b$Tơ lah Brah Yêsu saơ păng, tâm ngơi đah păng jêh ri lah: “Hơi bu ur, ay klaih jêh đah nau rvĕn ay.”$b$,true),
('bunong-vn','LUK',13,13,null,$b$Păng pah ma ti Păng. Ƀât lât bu ur nây ndŭr kơi plơ̆ sŏng tay, jêh ri tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','LUK',13,14,null,$b$Ƀiă lah kôranh ngih rƀŭn Yuđa ji nuih ma Brah Yêsu ƀư bah bu ur nây tâm nar Saƀat, jêh ri lah ma phung âk: “Geh prao nar pah kan, pô ri văch ƀư bah khân may nơm tâm nar nây yơh, ƀiă lah mâu geh nar Saƀat ôh!”$b$,false),
('bunong-vn','LUK',13,15,null,$b$Brah Yêsu plơ̆ lah ma păng: “Hơi phung nuih n'hâm mŭr, di lĕ tâm nar Saƀat ăp nơm khân may mâu doh ôh ndrôk mâu lah seh păng tă bơh ndrung, gay ma leo khân păng nhêt dak?$b$,false),
('bunong-vn','LUK',13,16,null,$b$Jêh ri bu ur aơ jêng kon Y-Abraham, jêh ri Satan kât păng geh jât ma pham năm jêh, mâu dơi hĕ tâm rklaih păng tă bơh rse rvăk aơ tâm nar Saƀat?”$b$,true),
('bunong-vn','LUK',13,17,null,$b$Dôl Păng ngơi pô nây, lĕ rngôch phung rlăng đah Păng bêk da dê, ƀiă lah phung âk răm maak ma lĕ nau khlay ngăn Păng ƀư nây.$b$,false),
('bunong-vn','LUK',13,18,null,$b$Brah Yêsu lah: “Mâm đah dơi tâm ntĭt ƀon bri hađăch Brah Ndu, jêh ri ma moh ndơ gâp dơi ƀư tâm ban ma păng?$b$,true),
('bunong-vn','LUK',13,19,null,$b$Păng jêng nâm bu găr trau, du huê dônh klŭp tâm đang trau păng, păng hon jêng du tơm si toyh, jêh ri phung sĭm drâm ta nthan păng.”$b$,false),
('bunong-vn','LUK',13,20,null,$b$Păng lah đŏng: “Mâm đah gâp tâm ntĭt ƀon bri hađăch Brah Ndu?$b$,true),
('bunong-vn','LUK',13,21,null,$b$Păng jêng tâm ban ma ndrui, du huê bu ur sŏk chê̆ tâm pe rbâng rnih, gay ma pot lai ndrel.”$b$,false),
('bunong-vn','LUK',13,22,null,$b$Brah Yêsu rgăn ƀon toyh jêh ri ƀon jê̆ nti lah dôl hăn ta ƀon Yêrusalem.$b$,true),
('bunong-vn','LUK',13,23,null,$b$Geh du huê lah ma Păng: “Ơ Kôranh Brah, di lĕ geh djê̆ bunuyh dơi klaih?”$b$,false),
('bunong-vn','LUK',13,24,null,$b$Păng plơ̆ lah ma phung nây: “Ăn khân may srôih lăp tâm mpông pêr hăt. Yor lah gâp lah ma khân may, âk bunuyh joi ŭch lăp, ƀiă lah mâu dơi ôh.$b$,false),
('bunong-vn','LUK',13,25,null,$b$Tơ lah kôranh ngih dâk, jêh ri nchăng lơi mpông pêr, jêh ri phung khân may gŭ pa dih, mra goh mpông, lah: Hơi kôranh, hơi kôranh, pơk mpông ma hên ƀă. Păng mra plơ̆ lah ma khân may, gâp mâu gĭt mbah tă khân may luh.$b$,false),
('bunong-vn','LUK',13,26,null,$b$Pô ri khân may lah: ‘Hên sông sa jêh ri nhêt jêh ta năp măt may, jêh ri may nti lah jêh tâm trong hên!’$b$,false),
('bunong-vn','LUK',13,27,null,$b$Ƀiă lah păng plơ̆ lah: ‘Gâp lah ma khân may, gâp mâu gĭt mbah tă khân may. Du hom khân may, tă bơh gâp. Hơi lĕ rngôch phung pah kan tih!’$b$,false),
('bunong-vn','LUK',13,28,null,$b$Ta nây yơh mra geh nau nhĭm nhhiăng jêh ri nau rket sêk tơ lah khân may mra saơ Y-Abraham, Y-Isăk, Y-Yakôp jêh ri lĕ rngôch phung kôranh nơm mbơh lor tâm ƀon bri hađăch Brah Ndu, jêh ri bu mra klŭp khân may pa dih.$b$,false),
('bunong-vn','LUK',13,29,null,$b$Mra geh phung văch tă pa lơ, pa dâng, luh nar, jêh ri nhâp nar mra gŭ sông sa tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','LUK',13,30,null,$b$Kơt nĕ ngăn, geh phung nglĕ mra jêng lor jêh ri phung lor mra jêng nglĕ.”$b$,true),
('bunong-vn','LUK',13,31,null,$b$Nôk nây đŏng, geh phung Pharisi văch lah ma Păng: “Du hom may tă bơh ntŭk aơ, yor Hêrôt ŭch nkhĭt may.”$b$,true),
('bunong-vn','LUK',13,32,null,$b$Păng plơ̆ lah ma phung nây: “Hăn lah ma mpik nây, aơ, gâp mprơh brah mhĭk jêh ri ƀư bah âk bunuyh nar aơ, ôi taơ, jêh ri nar tal pe gâp mra ƀư jêh kan gâp.$b$,false),
('bunong-vn','LUK',13,33,null,$b$Ƀiă lah gâp ăt mra hăn nsong tay nar aơ, ôi taơ jêh ri nklak, yor lah mâu dơi ôh ma du huê kôranh nơm mbơh lor khĭt pa dih ƀon Yêrusalem?$b$,false),
('bunong-vn','LUK',13,34,null,$b$“Hơi Yêrusalem, Yêrusalem, ƀon tâm nkhĭt phung kôranh nơm mbơh lor, jêh ri klŭp lŭ ma phung bu njuăl ma may. Âk tơ̆ jêh gâp ŭch tâm rƀŭn phung kon may tâm ban ma du mlâm iăr me, gay ma rgum kon păng tâm dâng nting năr păng, jêh ri khân may mâu ŭch ôh.$b$,true),
('bunong-vn','LUK',13,35,null,$b$Aơ, bu mra lơi ngih khân may! Ƀiă lah gâp lah ma khân may, khân may mâu mra saơ gâp ôh tât khân may mra lah: ‘Mât ton ma Nơm văch ma amoh Kôranh Brah!’ ”$b$,false),
('bunong-vn','LUK',14,1,null,$b$Du nar Saƀat Brah Yêsu lăp tâm ngih du huê kôranh phung Pharisi gay ma sông sa ndrel, jêh ri phung Pharisi nđôi n'hêl nanê̆ Păng.$b$,true),
('bunong-vn','LUK',14,2,null,$b$Jêh ri du huê bunuyh ji môr ndŭl, gŭ ta năp Păng.$b$,false),
('bunong-vn','LUK',14,3,null,$b$Brah Yêsu ngơi jêh ri lah ma phung kôranh nchih sămƀŭt jêh ri ma phung Pharisi. “Dơi lĕ ƀư bah tâm nar Saƀat mâu lah mâu dơi?”$b$,false),
('bunong-vn','LUK',14,4,null,$b$Khân păng gŭ rklăk. Pô ri Brah Yêsu yơr ti ma bunuyh nây, ƀư bah păng jêh ri ăn păng sĭt.$b$,true),
('bunong-vn','LUK',14,5,null,$b$Jêh ri Păng lah ma phung nây: “Mbu nơm tâm phung khân may, tơ lah seh bri mâu lah ndrôk tŭp tâm ntu dak mâu sŏk lơi păng ro nar Saƀat?”$b$,false),
('bunong-vn','LUK',14,6,null,$b$Jêh ri khân păng mâu hôm dơi plơ̆ lah nau nây.$b$,false),
('bunong-vn','LUK',14,7,null,$b$Păng ngơi nau hôr ma phung gŭ sông sa ndrel, tơ lah Păng saơ phung nây săch ntŭk ueh lơn, jêh ri lah:$b$,true),
('bunong-vn','LUK',14,8,null,$b$“Tơ lah bu jă may sông sa nau tâm nkol ur sai, lơi may gŭ ôh ta ntŭk ueh lơn, klach lah geh tâm phung păng jă du huê khlay lơn ma may.$b$,false),
('bunong-vn','LUK',14,9,null,$b$Jêh ri nơm jă khân may lah, nĕ ntŭk may, păng aơ gŭ jêh ri may mra prêng hăn gŭ ta ntŭk pĭt lôch.$b$,true),
('bunong-vn','LUK',14,10,null,$b$Ƀiă lah, pô nây mơ, tơ lah nơm jă may tât păng lah ma may: Hơi jiăng, hao ta ntŭk ueh lơn! Nây jêng nau yơk ma may ta năp lĕ rngôch phung sông ndrel ma may. Ƀiă lah tơ lah bu jă may, hăn gŭ hom ta ntŭk pĭt lôch.$b$,false),
('bunong-vn','LUK',14,11,null,$b$Yor lah mbu nơm n'hao păng nơm bu mra trŭnh, jêh ri mbu nơm ntrŭnh păng nơm bu mra n'hao păng.”$b$,false),
('bunong-vn','LUK',14,12,null,$b$Păng lah lĕ ma nơm jă păng sông sa: “Tơ lah may nkra nau sông sa, mâu lah nau sông sa toyh, lơi jă ôh phung mĭt jiăng may, phung oh nâu may, mê̆ mbơ̆ may, chiau meng may ndrŏng, klach lah khân păng mra jă khân may tâm ban lĕ, jêh ri mplơ̆ nau tâm ban ma may.$b$,true),
('bunong-vn','LUK',14,13,null,$b$Ƀiă lah tơ lah may nkra nau sông sa toyh, jă hom phung o ach, phung rvĕn, phung lŭt jâng ti, jêh ri phung chieh măt.$b$,false),
('bunong-vn','LUK',14,14,null,$b$May mra ueh maak yơh, yor lah khân păng mâu dơi ôh nsĭt ma may nau tâm ban, yor lah mra nsĭt ma may ta nar phung sŏng dâk rêh.”$b$,false),
('bunong-vn','LUK',14,15,null,$b$Du huê tâm phung gŭ sông sa ta nây, jêh tăng nau ngơi nây lah ma Brah Yêsu: “Ueh maak yơh mbu nơm mra sông sa tâm ƀon bri hađăch Brah Ndu!”$b$,true),
('bunong-vn','LUK',14,16,null,$b$Ƀiă lah Brah Yêsu plơ̆ lah ma păng: “Du huê bunuyh nkra nau sông sa toyh jêh ri âk bunuyh.$b$,false),
('bunong-vn','LUK',14,17,null,$b$Tât mông sông sa păng njuăl phung oh mon păng lah ma phung păng jă: ‘Văch hom yor lah lĕ rngôch ndơ nkra jêh.’$b$,true),
('bunong-vn','LUK',14,18,null,$b$Ƀiă lah lĕ rngôch dun da dê. Nơm lor, lah ma păng: ‘Gâp mhe rvăt mir lŏ, jêh ri gâp ŭch hăn uănh păng. Gâp dăn ma may yô̆ an ma gâp.’$b$,false),
('bunong-vn','LUK',14,19,null,$b$Du huê êng lah: ‘Gâp mhe rvăt jât mlâm ndrôk gâp hăn uănh khân păng. Gâp dăn ma may yô̆ an gâp!’$b$,false),
('bunong-vn','LUK',14,20,null,$b$Geh du huê êng lah: ‘Gâp mhe gŭ ur, yor ri gâp mâu dơi hăn.’$b$,false),
('bunong-vn','LUK',14,21,null,$b$Oh mon nây plơ̆ sĭt mbơh nau nây ma kôranh păng. Jêh ri kôranh ngih, ji nuih, lah ma oh mon păng: ‘Hăn ro tâm ntŭk trong toyh jêh ri trong jê̆, jă ta aơ phung o ach, phung rvĕn, phung chieh măt jêh ri phung lŭt jâng ti.’$b$,false),
('bunong-vn','LUK',14,22,null,$b$Oh mon lah: ‘Hơi kôranh, gâp ƀư jêh nau may ntăm ƀiă lah ăt hôm geh ntŭk lĕ.’$b$,false),
('bunong-vn','LUK',14,23,null,$b$Jêh ri kôranh lah ma oh mon: ‘Hăn tâm trong jê̆ njŏ pĭt mpêr, mbu may mra saơ, nchâp khân păng lăp gay ma bêng ngih gâp.$b$,false),
('bunong-vn','LUK',14,24,null,$b$Yor lah gâp lah ma khân may, mâu geh du huê tâm phung bunuyh gâp jă nây mra sông sa ndrel ma gâp!’ ”$b$,false),
('bunong-vn','LUK',14,25,null,$b$Âk bunuyh hăn ndrel ma Brah Yêsu, Brah Yêsu n'gĭl uănh jêh ri lah ma khân păng:$b$,true),
('bunong-vn','LUK',14,26,null,$b$“Tơ lah du huê văch ta gâp jêh ri mâu tâm rmot ma mê̆ mbơ̆ păng, ma ur kon păng ma phung oh nâu, oh ruh păng jêh ri nđâp ma nau rêh păng nơm, păng mâu dơi jêng oh mon gâp ôh.$b$,false),
('bunong-vn','LUK',14,27,null,$b$Jêh ri mbu nơm păng mâu tuy si tâm rkăng păng nơm mâu tĭng ndô̆ gâp, mâu dơi jêng oh mon gâp ôh.$b$,false),
('bunong-vn','LUK',14,28,null,$b$“Yor lah mbu nơm tâm phung khân may, tơ lah păng ŭch ƀư ngih toyh mâu tĭng, kơp lor lơn gay ma gĭt rnoh huach, gĭt lah dơi ƀư jêh mâu lah mâu?$b$,true),
('bunong-vn','LUK',14,29,null,$b$Klach lah jêh păng nkra tur, păng mâu dơi ƀư jêh ôh, jêh ri lĕ rngôch phung saơ nau nây, mưch ma păng jêh ri lah:$b$,false),
('bunong-vn','LUK',14,30,null,$b$‘Bunuyh aơ ntơm ƀư ngih ƀiă lah păng mâu dơi ƀư jêh ôh.’$b$,false),
('bunong-vn','LUK',14,31,null,$b$Mâu lah, mbu hađăch geh nau tâm lơh đah hađăch êng mâu gŭ lor ŭch sek uănh gĭt lah păng dơi sŏk jât rbăn nuyh, hăn tâm mâp ma nơm văch tâm lơh đah păng, geh bar jât rbăn?$b$,false),
('bunong-vn','LUK',14,32,null,$b$Tơ lah păng mâu dơi, păng mra njuăl du huê oh mon gay dăn nau đăp mpăn, dôl nơm nây gŭ ngai.$b$,false),
('bunong-vn','LUK',14,33,null,$b$Pô nây lĕ, mbu nơm tâm phung khân may mâu dun ôh, ma lĕ ndơ păng geh, păng mâu dơi jêng oh mon gâp ôh.$b$,false),
('bunong-vn','LUK',14,34,null,$b$“Boh jêng ndơ kah ngăn, ƀiă lah boh lĕ roh nau kah păng, ma moh ndơ bu mra ƀư păng ăn kah?$b$,true),
('bunong-vn','LUK',14,35,null,$b$Boh nây mâu hôm khlay ma neh lŏ ôh, mâu lah tâm pot ma buh sui, bu nkhŭt lơi pa dih. Mbu nơm geh tôr prăp iăt hom.”$b$,false),
('bunong-vn','LUK',15,1,null,$b$Lĕ rngôch phung riu pi jêh ri phung tih hăn dăch ta Brah Yêsu, gay ma iăt nau Păng.$b$,true),
('bunong-vn','LUK',15,2,null,$b$Phung Pharisi jêh ri phung kôranh nchih sămƀŭt ngơi ƀŭk dŭk suyh lah: “Bunuyh aơ rom phung tih jêh ri sông sa ndrel ma phung tih.”$b$,false),
('bunong-vn','LUK',15,3,null,$b$Ƀiă lah Brah Yêsu ngơi nau hôr aơ ma khân păng:$b$,true),
('bunong-vn','LUK',15,4,null,$b$“Mbu nơm tâm phung khân may, tơ lah păng geh du rhiăng mlâm biăp, jêh ri roh du mlâm, mâu cha lat phung sĭn jât ma sĭn mlâm hôm tâm bri rdah gay ma hăn joi du mlâm biăp roh jêh, jêh ri tât dơi saơ păng.$b$,false),
('bunong-vn','LUK',15,5,null,$b$Tơ lah păng saơ jêh biăp nây, păng tuy ta săng nglik păng bêng ma nau răm.$b$,false),
('bunong-vn','LUK',15,6,null,$b$Jêh tât ta ngih păng kuăl phung mĭt jiăng jêh ri lah: ‘Maak hom khân may ndrel ma gâp, yor lah gâp hŏ saơ jêh biăp gâp roh.’$b$,false),
('bunong-vn','LUK',15,7,null,$b$Gâp lah ma khân may tâm ban lĕ, mra geh âk lơn nau maak tâm trôk yor du huê bunuyh tih tâm rmal ma nau tih păng, đah sĭn jât ma sĭn nuyh sŏng mâu ŭch rmal nau tih.$b$,false),
('bunong-vn','LUK',15,8,null,$b$“Mâu lah mbu bu ur, tơ lah păng geh jât rnglay prăk jêh ri roh du rnglay, mâu mpoh ŭnh kđen, mâu mpêh ngih, jêh ri mâu joi nanê̆ tât păng dơi saơ prăk?$b$,true),
('bunong-vn','LUK',15,9,null,$b$Tơ lah păng saơ prăk nây, păng kuăl phung mĭt jiăng, jêh ri phung chiau meng păng, jêh ri lah: ‘Maak hom khân may ndrel ma gâp, yor lah gâp hŏ saơ jêh rnglay prăk gâp roh.’$b$,false),
('bunong-vn','LUK',15,10,null,$b$Gâp lah ma khân may tâm ban lĕ, geh nau răm ta năp phung Tông mpăr ueh Brah Ndu, yor du huê bunuyh tih rmal nau tih păng.”$b$,false),
('bunong-vn','LUK',15,11,null,$b$Păng lah tay: “Du huê bunuyh geh bar hê kon bu klâu;$b$,true),
('bunong-vn','LUK',15,12,null,$b$nơm jêng oh ngơi đah mbơ̆ păng: ‘Hơi mbơ̆ ăn hom ma gâp drăp may mra pă ma gâp!’ Jêh ri mbơ̆ păng pă ro ma khân păng.$b$,false),
('bunong-vn','LUK',15,13,null,$b$Jêh nây mâu ir jŏ, oh nây, jêh sŏk lĕ drăp, hăn nsong ta du n'gor ngai. Ta nây păng ƀư roh drăp păng, dâk lĕ jêh prăk, nau sa sât ji ngot toyh tât lam n'gor nây.$b$,false),
('bunong-vn','LUK',15,14,null,$b$Nơm nây njuăl păng tâm mir gay ăn chiă sŭr.$b$,false),
('bunong-vn','LUK',15,15,null,$b$Păng ŭch ngăn sa tuh bu siăm sŭr, ƀiă lah bu mâu ăn păng sa ôh. Jêh ri păng ntơm pưt ndơ.$b$,false),
('bunong-vn','LUK',15,16,null,$b$Pô ri păng hăn pah kan ma du huê bunuyh tâm n'gor nây.$b$,false),
('bunong-vn','LUK',15,17,null,$b$Tơ lah păng mĭn tâm nuih n'hâm păng jêh ri lah: ‘Geh âk bunuyh pah kan ma mbơ̆ gâp, geh kapŭng sa âk rmeh, ƀiă lah gâp ta aơ ntơm khĭt ji ngot.$b$,false),
('bunong-vn','LUK',15,18,null,$b$Gâp mra hăn plơ̆ sĭt ta mbơ̆ gâp, jêh ri lah ma păng: Hơi mbơ̆ gâp ƀư tih jêh đah trôk, jêh ri đah may.$b$,false),
('bunong-vn','LUK',15,19,null,$b$Gâp mâu hôm khư ăn may kuăl kon, ƀiă lah ăn may kơp gâp jêng du huê bunuyh pah kan may nkhôm.’$b$,true),
('bunong-vn','LUK',15,20,null,$b$Jêh ri păng dâk hăn ma mbơ̆ păng, dôl păng hôm ngai, mbơ̆ păng saơ păng jêh ri bêng ma nau yô̆ păng, păng nchuăt ran ut ta trô ko jêh ri chŭm păng.$b$,false),
('bunong-vn','LUK',15,21,null,$b$Pô ri kon păng lah ma păng: ‘Hơi mbơ̆ gâp ƀư tih jêh đah trôk jêh ri đah may nơm, mâu hôm khư ôh ăn may kuăl gâp jêng kon may.’$b$,false),
('bunong-vn','LUK',15,22,null,$b$Ƀiă lah mbơ̆ lah ma phung kơl kan păng: ‘Sŏk ndơ̆ gơnh ao jâr ueh lơn sâm nsoh an păng. Ntrŭp rgên ta nglau ti păng, jêh ri sâm ntrŭp ntâu jot ma păng.$b$,false),
('bunong-vn','LUK',15,23,null,$b$Têk kon ndrôk lay jêh ri gŭch. Sông sa răm maak hom he.$b$,true),
('bunong-vn','LUK',15,24,null,$b$Yor lah kon gâp aơ tâm ban ma khĭt jêh, ƀiă lah dâk rêh đŏng. Păng roh jêh hôm saơ đŏng.’ Jêh ri khân păng răm maak yơh.$b$,false),
('bunong-vn','LUK',15,25,null,$b$“Bi kon toyh gŭ tâm mir. Tơ lah păng sĭt dăch tât ta ngih păng tăng nau mprơ jêh ri nau ntlơ̆ ntlơn.$b$,true),
('bunong-vn','LUK',15,26,null,$b$Păng kuăl du huê tâm phung oh mon jêh ri ôp: ‘Moh nau ƀư nây?’$b$,false),
('bunong-vn','LUK',15,27,null,$b$Oh mon nây lah ma păng: ‘Oh may hŏ sĭt jêh, jêh ri mbơ̆ may gŭch du mlâm kon ndrôk lay, yor lah mbơ̆ may saơ oh may geh nau ngăch prăl.’$b$,false),
('bunong-vn','LUK',15,28,null,$b$Păng ntơm ji nuih ro, jêh ri mâu ŭch lăp tâm ngih. Mbơ̆ păng du luh jêh ri dăn ma păng lăp,$b$,false),
('bunong-vn','LUK',15,29,null,$b$ƀiă lah păng plơ̆ lah ma mbơ̆ păng: ‘Aơ, jŏ năm jêh gâp pah kan ma may, mâu mâp rlau bâr may ôh, ƀiă lah may mâu mâp ăn du mlâm kon be ma gâp, ăn gâp ƀư nau maak đah phung mĭt jiăng gâp.$b$,false),
('bunong-vn','LUK',15,30,null,$b$Ƀiă lah tơ lah kon may dâk lĕ drăp ndơ may, đah bu ur văng tĭr plơ̆ sĭt, may gŭch ma păng du mlâm ndrôk lay.’$b$,false),
('bunong-vn','LUK',15,31,null,$b$Mbơ̆ păng lah ma păng: ‘Hơi nâu, may gŭ ndrel ma gâp mro, jêh ri lĕ ndơ gâp geh jêng ndơ may.$b$,false),
('bunong-vn','LUK',15,32,null,$b$Ƀiă lah di jêh ƀư nau răm jêh ri maak, yor lah oh may aơ tâm ban ma khĭt jêh, ƀiă lah păng dâk rêh đŏng. Păng roh jêh ƀiă lah saơ tay đŏng.’ ”$b$,false),
('bunong-vn','LUK',16,1,null,$b$Brah Yêsu lah lĕ ma phung oh mon Păng: “Du huê bunuyh ndrŏng geh du huê bunuyh chiă drăp păng, jêh ri bu phong nơm nây ăn roh drăp păng.$b$,true),
('bunong-vn','LUK',16,2,null,$b$Păng kuăl, lah ma nơm nây: ‘Moh nau gâp tăng bu nkoch bri ma may? Mbơh ma nau may chiă uănh, yor lah may mâu mra dơi chiă uănh drăp gâp ôh.’$b$,false),
('bunong-vn','LUK',16,3,null,$b$Oh mon nây lah tâm nuih n'hâm păng: ‘Moh gâp mra ƀư yor lah kôranh gâp mâu hôm ăn gâp chiă drăp păng ôh? Gâp mâu dơi ƀư mir, jêh ri gâp bêk nsong ƀư dan.$b$,false),
('bunong-vn','LUK',16,4,null,$b$Gâp gĭt jêh moh gâp mra ƀư gay ma geh bunuyh mra rom gâp tâm ngih khân păng, tơ lah kôranh gâp mâu hôm dŏng gâp!’$b$,false),
('bunong-vn','LUK',16,5,null,$b$Pô ri păng kuăl ăp nơm phung iang rnon kôranh păng. Jêh ri lah ma nơm lor: ‘Ndah âk may iang rnon kôranh gâp?’$b$,false),
('bunong-vn','LUK',16,6,null,$b$Nơm iang rnon plơ̆ lah: ‘Du rhiăng nông dak ngi.’ Păng lah ma nơm nây: ‘Sŏk sămƀŭt may. May gŭ nchih gơnh prăm jât.’$b$,false),
('bunong-vn','LUK',16,7,null,$b$Păng lah ma du huê nơm êng: ‘Bi may, dŭm âk may iang rnon?’ Nơm nây plơ̆ lah: ‘Du rhiăng kilô ba.’ Păng lah: ‘Sŏk sămƀŭt may jêh ri nchih, pham jât.’$b$,false),
('bunong-vn','LUK',16,8,null,$b$Kôranh păng tâm rnê ma păng yor lah păng ƀư jêh ma nau njrăng, yor lah phung kon rnôk aơ tâm nau khân păng ƀư ma phung băl khân păng jêng blau mĭn lơn, ma phung kon nau ang.$b$,false),
('bunong-vn','LUK',16,9,null,$b$Jêh ri gâp lah ma khân may: Ăn khân may ƀư mĭt jiăng ma ndô ndơ mâu sŏng gay ma tơ lah may pưt ndô ndơ, khân păng mra rom khân may tâm ngih n'ho ro.$b$,false),
('bunong-vn','LUK',16,10,null,$b$“Mbu nơm jêng răp jăp tâm ndơ jê̆ jănh, mra răp jăp tâm ban lĕ tâm ndơ toyh, jêh ri mbu nơm jêng kue tâm ndô ndơ jê̆ jănh mra jêng kue tâm ban lĕ tâm ndơ toyh.$b$,true),
('bunong-vn','LUK',16,11,null,$b$Tơ lah khân may mâu răp jăp tâm ndô ndơ mâu sŏng, mbu mra jao ma khân may ndô ndơ ngăn?$b$,false),
('bunong-vn','LUK',16,12,null,$b$Jêh ri tơ lah khân may mâu răp jăp tâm ndơ bu, mbu mra ăn ma khân may ndơ khân may nơm?$b$,false),
('bunong-vn','LUK',16,13,null,$b$Mâu geh du huê oh mon dơi pah kan ma bar hê kôranh, yor lah păng mra tâm rmot ma du huê êng, mâu lah păng mra rŏng ma du huê, jêh ri mra tâm rmot ma du huê êng. Khân may mâu dơi pah kan ma Brah Ndu jêh ri ma brah rŏng ma ndô ndơ ôh.”$b$,false),
('bunong-vn','LUK',16,14,null,$b$Phung Pharisi, jêng phung rŏng ma prăk, tăng, lĕ nau nây jêh ri mưch ma Brah Yêsu.$b$,true),
('bunong-vn','LUK',16,15,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Khân may joi ŭch jêng sŏng ta năp bunuyh, ƀiă lah Brah Ndu gĭt năl nuih n'hâm khân may, yor lah mbu nơm bu yơk ta năp bunuyh, Brah Ndu tâm rmot ma păng.$b$,false),
('bunong-vn','LUK',16,16,null,$b$Nau vay jêh ri phung kôranh nơm mbơh lor ăt hôm tât ta rnôk Y-Yôhan, ntơm bơh nây bu mbơh jêh, ƀon bri hađăch Brah Ndu jêh ri ăp nơm pit ŭch lăp ta nây.$b$,false),
('bunong-vn','LUK',16,17,null,$b$Ƀiă lah dơh lơn ma trôk jêh ri neh ntu rlau lôch ma du rup tâm sămƀŭt nau vay jêng hĕ dơm dam.$b$,false),
('bunong-vn','LUK',16,18,null,$b$Mbu nơm cha lơi ur păng, jêh ri gŭ bu ur êng, păng văng tĭr jêh, jêh ri mbu nơm gŭ du huê bu ur sai păng cha lơi jêh, păng văng tĭr tâm ban lĕ.”$b$,false),
('bunong-vn','LUK',16,19,null,$b$“Geh jêh du huê bunuyh ndrŏng soh ao chăng krăk tanh ma rse mhay rhên, jêh ri gŭ răm maak ăp nar.$b$,true),
('bunong-vn','LUK',16,20,null,$b$Du huê o ach amoh păng Y-Lasar, bêch ta bôk mpông ngih păng, săk jăn păng toh, ok da dê.$b$,false),
('bunong-vn','LUK',16,21,null,$b$Păng ŭch sa ndơ sông sa ndăk rŭng tă bơh sưng ndrŏng dôl gŭ sông sa, nđâp ma phung so ŭch ler ntŭk sôt ok păng.$b$,false),
('bunong-vn','LUK',16,22,null,$b$Nơm o ach nây khĭt, Tông mpăr ueh Brah Ndu chông păng ăn ta klơ ntang ntơh Y-Abraham. Bunuyh ndrŏng khĭt tâm ban lĕ bu tâp păng.$b$,false),
('bunong-vn','LUK',16,23,null,$b$Tâm ƀon phung khĭt păng n'gơr măt uănh dôl păng gŭ rêh ni. Bơh ngai păng saơ Y-Abraham, jêh ri Y-Lasar gŭ ta ntang ntơh păng.$b$,false),
('bunong-vn','LUK',16,24,null,$b$Păng nter lah: ‘Hơi mbơ̆ Y-Abraham, yô̆ nđach an gâp ƀă, jêh ri njuăl Y-Lasar mbŭk nglau ti tâm dak jêh ri gay nđik ta mpiăt, yor lah gâp rêh ni hâu ngăn ngên yơh gŭ tâm mpiăt ŭnh aơ.’$b$,true),
('bunong-vn','LUK',16,25,null,$b$Y-Abraham plơ̆ lah: ‘Hơi kon gâp, ăn may kah gĭt may geh âk drăp ndơ, dôl may gŭ rêh, jêh ri Y-Lasar geh âk nau ji, dôl păng gŭ rêh ƀiă lah ta aơ păng geh nau bonh leng jêh ri may geh nau ji.$b$,false),
('bunong-vn','LUK',16,26,null,$b$Jêh ri brŏng jru toyh vah vang may đah hên, pô nây mbu nơm ŭch găn hăn leo ta may, mâu lah tă bơh may, văch ta hên mâu mra dơi ôh.’$b$,false),
('bunong-vn','LUK',16,27,null,$b$Bunuyh ndrŏng lah: ‘Gâp vơh vơl ma may, hơi mbơ̆ , dăn ma may njuăl păng hăn ta ngih mbơ̆ gâp, yor lah gâp geh prăm nuyh oh,$b$,false),
('bunong-vn','LUK',16,28,null,$b$gay ma păng mbơh nau aơ, pô ri mơ khân păng mâu mra văch ta ntŭk rêh ni aơ.’$b$,false),
('bunong-vn','LUK',16,29,null,$b$Y-Abraham plơ̆ lah: ‘Khân păng geh jêh Y-Môis jêh ri phung kôranh nơm mbơh lor. Ăn khân păng iăt nau phung nây.’$b$,false),
('bunong-vn','LUK',16,30,null,$b$Jêh ri păng lah: ‘Mâu! Hơi mbơ̆ Y-Abraham, ƀiă lah tơ lah du huê tâm phung khĭt hăn ta khân păng, ri mơ khân păng tâm rmal nau tih khân păng.’$b$,false),
('bunong-vn','LUK',16,31,null,$b$Jêh ri Y-Abraham lah ma păng: ‘Tơ lah khân păng mâu iăt Y-Môis jêh ri phung kôranh nơm mbơh lor, mâu lĕ khân păng chroh, nđâp tơ lah geh phung khĭt dâk rêh đŏng.’ ”$b$,false),
('bunong-vn','LUK',17,1,null,$b$Brah Yêsu lah ma phung oh mon Păng: “Nau tâm chêh yor tă bơh nau tih mra tât ngăn, ƀiă lah rêh ni yơh ma nơm ƀư chêh bu.$b$,true),
('bunong-vn','LUK',17,2,null,$b$Ueh lơn bu dơm ta trô ko păng du glo lŭ mpăl jêh ri klŭp păng tâm dak mƀŭt, ma nau păng chêh du huê tâm phung jê̆ jănh aơ.$b$,false),
('bunong-vn','LUK',17,3,null,$b$“Njrăng hom ma khân may nơm. Tơ lah oh nâu may ƀư tih, buay hom păng jêh ri tơ lah păng rmal nau tih, yô̆ hom nau tih păng;$b$,true),
('bunong-vn','LUK',17,4,null,$b$jêh ri tơ lah păng ƀư tih đah may pơh tơ̆ tâm du nar, jêh ri pơh tơ̆ păng plơ̆ tay ma may, lah: ‘Gâp rmal nau tih gâp,’ jêh ri ăn may yô̆ an nau tih păng.”$b$,false),
('bunong-vn','LUK',17,5,null,$b$Phung kôranh oh mon lah ma Kôranh Brah: “Sâm n'hao an nau chroh hên!”$b$,true),
('bunong-vn','LUK',17,6,null,$b$Jêh ri Brah Yêsu lah: “Tơ lah khân may geh nau chroh jê̆ tâm ban ma găr trau, khân may mra lah ma tơm si sikamôr aơ: ‘Đôk hom, jêh ri hon reh tâm dak mƀŭt,’ jêh ri păng mra tông bâr may.$b$,false),
('bunong-vn','LUK',17,7,null,$b$“Mbu nơm tâm phung khân may geh du huê oh mon ƀư mir mâu lah chiă biăp mra lah ma păng, tơ lah păng sĭt tă bơh mir: ‘Văch gơnh jêh ri sông sa hom?’$b$,true),
('bunong-vn','LUK',17,8,null,$b$Mâm ƀư păng mâu lah ma nơm nây pô aơ: ‘Nkra hom ndơ sông sa, rêt rse bŭt, jêh ri njŭn ma gâp sông sa! Pô nây mơ, may mra sông sa jêh ri nhêt?’$b$,false),
('bunong-vn','LUK',17,9,null,$b$Păng mra kah gĭt tôr lĕ ma oh mon nây yor lah păng ƀư lĕ nau gâp ntăm?$b$,false),
('bunong-vn','LUK',17,10,null,$b$Khân may tâm ban lĕ, tơ lah khân may ƀư jêh lĕ nau bu ntăm ma khân may, lah hom: ‘Hên jêng phung oh mon mâu khlay; hên ƀư knŏng tĭng nâm bu đă hên.’ ”$b$,true),
('bunong-vn','LUK',17,11,null,$b$Dôl Brah Yêsu hăn ta ƀon Yêrusalem Păng rgăn ntŭk vah vang n'gor Samari đah n'gor Galilê.$b$,true),
('bunong-vn','LUK',17,12,null,$b$Nôk Păng lăp tâm du ƀon, geh jât nuyh phŭng sa văch tâm mâp đah Păng.$b$,false),
('bunong-vn','LUK',17,13,null,$b$Khân păng gŭ ngai oi đah Brah Yêsu, jêh ri nter lah: “Ơ Brah Yêsu, Kôranh Brah, yô̆ an ma hên ƀă.”$b$,false),
('bunong-vn','LUK',17,14,null,$b$Dôl Brah Yêsu saơ khân păng, Păng lah pô aơ: “Hăn hom khân may mpơl ma phung kôranh ƀư brah.” Jêh ri dôl khân păng hăn, khân păng dơi bah.$b$,true),
('bunong-vn','LUK',17,15,null,$b$Du huê tâm phung khân păng, saơ hŏ geh nau bah jêh, plơ̆ sĭt ro, mât ton tâm rnê ma Brah Ndu ma bâr huy ktang.$b$,false),
('bunong-vn','LUK',17,16,null,$b$Păng kŭnh bôk ta năp dăch jâng Brah Yêsu jêh ri tâm rnê ma Păng. Nơm nây jêng du huê Samari,$b$,false),
('bunong-vn','LUK',17,17,null,$b$Brah Yêsu lah pô aơ: “Mâu di hĕ phung jât nuyh dơi bah jêh? Mbah ntŭk sĭn nuyh nĕ?$b$,false),
('bunong-vn','LUK',17,18,null,$b$Knŏng du huê bu năch aơ bah, plơ̆ văch mât ton ma Brah Ndu?”$b$,false),
('bunong-vn','LUK',17,19,null,$b$Jêh ri Păng lah ma nơm bah nây: “Dâk hom may, hăn hom, nau chroh may tâm rklaih may jêh.” Ƀon bri hađăch Brah Ndu jêh ri nau Kon Bunuyh mra plơ̆ .$b$,false),
('bunong-vn','LUK',17,20,null,$b$Phung Pharisi ôp Brah Yêsu: “Ndah jŏ mra tât ƀon bri hađăch Brah Ndu.” Păng plơ̆ lah: “Ƀon bri hađăch Brah Ndu mâu mra văch ôh ma nau tâm mbên tâm mpơl.$b$,true),
('bunong-vn','LUK',17,21,null,$b$Bu mâu lah ôh: Păng ta aơ! Mâu lah: Păng ta ri! Yor lah aơ, ƀon bri hađăch Brah Ndu gŭ ta nklang phung khân may.”$b$,true),
('bunong-vn','LUK',17,22,null,$b$Jêh ri Păng lah ma phung oh mon: “Geh nar mra tât, khân may mra ŭch uănh nar Kon Bunuyh, ƀiă lah khân may mâu mra saơ păng ôh.$b$,false),
('bunong-vn','LUK',17,23,null,$b$Bu mra lah ma khân may: ‘Păng ta aơ!’ Mâu lah: ‘Păng ta ri!’ Lơi hăn ôh. Lơi nchuăt ôh.$b$,false),
('bunong-vn','LUK',17,24,null,$b$Yor lah nâm bu lơp nchrat, ntơm bơh du n'gar trôk tât ma n'gar êng, tâm ban pô nây đŏng Kon Bunuyh mra jêng tâm nar Păng plơ̆ văch.$b$,false),
('bunong-vn','LUK',17,25,null,$b$Ƀiă lah lor lơn Păng mra dơn nau rêh ni jêh ri phung rnôk aơ mra dun Păng.$b$,false),
('bunong-vn','LUK',17,26,null,$b$Nau tât jêh tâm rnôk Y-Nôê mra tât tâm ban lĕ tâm nar Kon Bunuyh.$b$,false),
('bunong-vn','LUK',17,27,null,$b$Phung bunuyh nhêt sông, tâm gŭ ur sai, jêh ri ăn phung oh kon khân păng tâm gŭ ur sai, tât nar Y-Nôê lăp tâm kŭmpăn, dak lip tât, jêh ri ƀư rai khân păng.$b$,false),
('bunong-vn','LUK',17,28,null,$b$Nau tât jêh tâm rnôk Y-Lot mra tât tâm ban lĕ. Phung bunuyh nhêt, sông, rvăt rgâl, tuch tăm, nkra ngih vâl.$b$,false),
('bunong-vn','LUK',17,29,null,$b$Ƀiă lah nar Y-Lot luh tă bơh ƀon Sôdôm geh mih ŭnh jêh ri lŭ mô tŭp tă bơh trôk, jêh ri ƀư rai khân păng.$b$,false),
('bunong-vn','LUK',17,30,null,$b$Mra tât tâm ban lĕ tâm nar Kon Bunuyh mra tâm mpơl.$b$,false),
('bunong-vn','LUK',17,31,null,$b$Tâm nar nây mbu nơm gŭ ta klơ chor bôk pho, jêh ri geh drăp ndơ păng tâm ngih, lơi jŭr hăn sŏk ôh; jêh ri mbu nơm gŭ tâm mir, lơi hôm sĭt ôh.$b$,true),
('bunong-vn','LUK',17,32,null,$b$Ăn khân may kah gĭt ma ur Y-Lot.$b$,false),
('bunong-vn','LUK',17,33,null,$b$Mbu nơm joi gay tâm rklaih nau rêh păng, mra roh rai, jêh ri mbu nơm ƀư roh nau rêh păng nơm, păng mra saơ nau rêh.$b$,false),
('bunong-vn','LUK',17,34,null,$b$Gâp lah ma khân may, tâm măng nây, bar hê bunuyh gŭ bêch tâm du mlâm sưng, du huê bu mra sŏk, du huê bu mra lơi.$b$,false),
('bunong-vn','LUK',17,35,null,$b$Bar hê bu ur gŭ peh ndrel du huê bu sŏk, du huê bu lơi.$b$,false),
('bunong-vn','LUK',17,36,null,$b$Bar hê gŭ tâm du lôk mir; du huê bu sŏk, du huê bu lơi.”$b$,false),
('bunong-vn','LUK',17,37,null,$b$Phung oh mon lah ma Păng: “Mbah ntŭk. Ơ Kôranh Brah?” Jêh ri Brah Yêsu plơ̆ lah: “Ta ntŭk geh săk jăn khĭt, ta nây phung klang mra tâm rƀŭn.”$b$,false),
('bunong-vn','LUK',18,1,null,$b$Brah Yêsu ngơi hôr gay tâm mpơl ma khân păng nau khlay, mbơh sơm ƀa ƀơ lơi rdja nuih ôh.$b$,true),
('bunong-vn','LUK',18,2,null,$b$Păng lah: “Geh tâm du ƀon toyh geh du huê kôranh phat dôih mâu klach yơk mbah ma Brah Ndu jêh ri mâu chrê ma bu ôh.$b$,false),
('bunong-vn','LUK',18,3,null,$b$Tâm ƀon nây geh du huê bu ur ndrô khĭt sai lah ma păng: ‘Phat an dôih nơm ƀư rlăng ma gâp.’$b$,false),
('bunong-vn','LUK',18,4,null,$b$Jŏ jêh păng dun ƀiă lah păng lah êng tâm nuih n'hâm păng nơm pô aơ:$b$,false),
('bunong-vn','LUK',18,5,null,$b$‘Nđâp tơ lah gâp mâu klach, mâu yơk ma Brah Ndu, jêh ri mâu chrê ma bu, ƀiă lah bu ur ndrô aơ ƀư rsuak gâp ƀa ƀơ, pô ri gâp phat an dôih kơl păng, gay ma păng mâu hôm hăn ƀư rsĭk tôr gâp.’ ”$b$,false),
('bunong-vn','LUK',18,6,null,$b$Jêh ri Brah Yêsu lah đŏng: “Iăt hom moh nau kôranh phat dôih kue lah.$b$,false),
('bunong-vn','LUK',18,7,null,$b$Nâm pô nây lĕ bơh Brah Ndu phat dôih sŏng gay ma kơl phung Păng ƀa ƀơ măng nâm nar? Păng ƀư mbrĕ mbrơi lĕ kơl phung nây?$b$,true),
('bunong-vn','LUK',18,8,null,$b$Gâp lah ma khân may, păng gơnh ro gay ma kơl phung nây. Ƀiă lah tơ lah Nơm Tâm Tang Kon Bunuyh văch ta neh ntu aơ, mâm ƀư, păng tâm ban lĕ phung hôm srôih nsing rnơm ma Brah Ndu?”$b$,false),
('bunong-vn','LUK',18,9,null,$b$Păng ngơi tay nau hôr aơ ma phung bunuyh mĭn khân păng nơm sŏng, jêh ri tâm rmot ma phung êng:$b$,true),
('bunong-vn','LUK',18,10,null,$b$“Bar hê bunuyh hăn ta ngih brah Yuđa ŭch mbơh sơm. Du huê jêng Pharisi jêh ri du huê êng jêng nơm riu pi.$b$,false),
('bunong-vn','LUK',18,11,null,$b$Du huê Pharisi nây dâk, mbơh sơm ma păng nơm pô aơ: ‘Ơ Brah Ndu gâp lah ueh ma may, yor lah gâp mâu jêng tâm ban ma bu êng ôh. Khân păng jêng phung sa drăp, kue, văng tĭr mâu lah tâm ban ma du huê nơm riu pi aơ.$b$,false),
('bunong-vn','LUK',18,12,null,$b$Gâp ver sông sa bar tơ̆ tâm du pơh. Gâp ăn du kô̆ tâm jât lĕ ndơ gâp geh.’$b$,false),
('bunong-vn','LUK',18,13,null,$b$Nơm riu pi gŭ ngai ngai đah păng, mâu janh n'gơr măt klơ trôk, ƀiă lah păng tap ntang ntơh jêh ri lah: ‘Ơ Brah Ndu yô̆ an ma gâp ƀă, gâp jêng du huê bunuyh tih!’$b$,false),
('bunong-vn','LUK',18,14,null,$b$Gâp mbơh ma khân may, nơm aơ sĭt ta ngih geh nau kơp sŏng, bi du huê Pharisi, mâu; yor lah mbu n'hao êng păng nơm păng mra jŭr, ƀiă lah mbu nơm ntrŭnh păng nơm păng mra hao.”$b$,false),
('bunong-vn','LUK',18,15,null,$b$Bu njŭn leo ma Păng nđâp ma kon se jê̆ gay ma Păng pah ma ti ƀiă lah phung oh mon saơ nau nây, buay lơi phung njŭn kon se.$b$,true),
('bunong-vn','LUK',18,16,null,$b$Ƀiă lah Brah Yêsu kuăl khân păng jêh ri lah: “Ăn phung kon se jê̆ văch ta gâp, lơi ta buay khân păng ôh, yor lah ƀon bri hađăch Brah Ndu prăp ma phung jêng tâm ban ma khân păng.$b$,false),
('bunong-vn','LUK',18,17,null,$b$Nanê̆ gâp mbơh nau aơ ma khân may, mbu nơm mâu sŏk dơn ƀon bri hađăch Brah Ndu, tâm ban ma du huê kon se jê̆, păng mâu mra lăp tâm ƀon nây ôh.”$b$,false),
('bunong-vn','LUK',18,18,null,$b$Du huê kôranh ôp Brah Yêsu pô aơ: “Hơi Kôranh nơm nti ueh, mâm gâp mra ƀư gay ma dơn nau rêh n'ho ro?”$b$,true),
('bunong-vn','LUK',18,19,null,$b$Brah Yêsu plơ̆ lah ma păng: “Mâm ƀư may kuăl ma gâp ueh? Geh knŏng du huê ueh, Brah Ndu yơh.$b$,false),
('bunong-vn','LUK',18,20,null,$b$May gĭt jêh nau vay: ‘Lơi may văng tĭr ôh, lơi may nkhĭt bunuyh ôh. Lơi may ntŭng, lơi may mƀruh. Yơk ma mê̆ mbơ̆ may.’ ”$b$,false),
('bunong-vn','LUK',18,21,null,$b$Nây lah: “Gâp tông lĕ jêh nau vay nây ntơm bơh gâp hôm ndăm.”$b$,false),
('bunong-vn','LUK',18,22,null,$b$Tơ lah Brah Yêsu tăng nau nây, păng lah: “Geh du ntil ndơ may ê ƀư. Tăch lĕ ndơ may geh, jêh ri tâm pă prăk ma phung o ach, jêh ri may mra geh drăp tâm trôk, jêh ri văch hom, tĭng ndô̆ gâp.”$b$,false),
('bunong-vn','LUK',18,23,null,$b$Tơ lah păng tăng nau nây păng rngot yor lah păng ndrŏng ngăn.$b$,false),
('bunong-vn','LUK',18,24,null,$b$Brah Yêsu saơ păng rngot, lah: “Jêr ngăn phung ndrŏng lăp tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','LUK',18,25,null,$b$Yor lah nơih lơn ma du mlâm seh samô lăp tâm trôm nglai, ma du huê nơm ndrŏng lăp tâm ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','LUK',18,26,null,$b$Phung tăng nau nây, lah ma Păng: “Mbu dơi klaih?”$b$,false),
('bunong-vn','LUK',18,27,null,$b$Brah Yêsu plơ̆ lah: “Moh nau bunuyh mâu dơi ƀư, Brah Ndu dơi!”$b$,false),
('bunong-vn','LUK',18,28,null,$b$Pêtrôs lah: “Bi hên cha lơi lĕ jêh ndơ, jêh ri tĭng ndô̆ may.”$b$,true),
('bunong-vn','LUK',18,29,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Gâp mbơh ma khân may nanê̆ ngăn, mâu mâp geh ôh bunuyh cha lơi ngih, ur, oh nâu, mê̆ mbơ̆ mâu lah kon păng yor ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','LUK',18,30,null,$b$Jêh ri păng mâu mra geh hĕ âk lơn tâm rnôk aơ jêh ri tâm nar kăndơ̆ nau rêh n'ho ro.”$b$,false),
('bunong-vn','LUK',18,31,null,$b$Brah Yêsu sŏk phung jât ma bar nuyh dăch Păng jêh ri lah ma khân Păng: “Aơ, he hăn ta ƀon Yêrusalem. Lĕ nau phung kôranh nơm mbơh lor nchih jêh ma Kon Bunuyh mra ƀư nanê̆.$b$,true),
('bunong-vn','LUK',18,32,null,$b$Yor lah bu mra jao Păng ma phung bu năch, bu mra mưch ma Păng, suai rak ma Păng, soh dak diu ta Păng.$b$,false),
('bunong-vn','LUK',18,33,null,$b$Jêh ri, jêh bu dong Păng ma mâng, bu mra nkhĭt Păng jêh ri, tăch pe nar Păng mra rêh.”$b$,false),
('bunong-vn','LUK',18,34,null,$b$Ƀiă lah khân păng mâu gĭt rbăng ôh nau nây. Brah Yêsu ngơi nau ndâp ma khân păng, khân păng mâu gĭt rbăng ôh.$b$,false),
('bunong-vn','LUK',18,35,null,$b$Tơ lah Brah Yêsu dăch tât ta ƀon Yêrikô, geh du huê bunuyh chieh măt gŭ ta meng trong dăn ndơ bu ăn yô̆.$b$,true),
('bunong-vn','LUK',18,36,null,$b$Păng tăng phung âk ngăn ta nây jêh ri ôp moh nau nây.$b$,false),
('bunong-vn','LUK',18,37,null,$b$Bu lah ma păng: “Brah Yêsu ƀon Nasaret prot ta nây.”$b$,false),
('bunong-vn','LUK',18,38,null,$b$Pô ri păng nter lah: “Ơ Brah Yêsu, kon Y Đavit, yô̆ nđach an ma gâp ƀă!”$b$,false),
('bunong-vn','LUK',18,39,null,$b$Phung hăn pa năp buay păng ăn păng gŭ rklăk, ƀiă lah păng nter lơ hâu huy: “Ơ Kon Y Đavit, yô̆ an ma gâp ƀă!”$b$,true),
('bunong-vn','LUK',18,40,null,$b$Brah Yêsu gŭ, đă bu njŭn leo nơm nây ma Păng jêh păng tât ta nây, păng ôp: “Moh may ŭch gâp ƀư ma may?”$b$,false),
('bunong-vn','LUK',18,41,null,$b$Păng plơ̆ lah: “Ơ Kôranh Brah, ăn măt gâp dơi saơ ang.”$b$,false),
('bunong-vn','LUK',18,42,null,$b$Brah Yêsu lah ma păng: “Ang hom! Nau chroh may ƀư bah jêh may!”$b$,false),
('bunong-vn','LUK',18,43,null,$b$Ƀât lât păng saơ ang, jêh ri tĭng ndô̆ Brah Yêsu mât ton tâm rnê ma Brah Ndu, lĕ rngôch bunuyh saơ nau nây tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','LUK',19,1,null,$b$Tơ lah Brah Yêsu lăp jêh tâm ƀon Yêrikô, păng rgăn ƀon nây.$b$,true),
('bunong-vn','LUK',19,2,null,$b$Geh du huê bunuyh ndrŏng amoh păng Y-Sachê. Păng jêng du huê kôranh tâm phung riu pi.$b$,false),
('bunong-vn','LUK',19,3,null,$b$Păng joi ŭch uănh Brah Yêsu, ƀiă lah mâu dơi, yor lah bunuyh âk, păng jêng bunuyh gleh.$b$,false),
('bunong-vn','LUK',19,4,null,$b$Păng nchuăt pa năp jêh ri hao ta klơ tơm si sikamôr ŭch uănh Brah Yêsu rgăn ta nây.$b$,false),
('bunong-vn','LUK',19,5,null,$b$Tơ lah Brah Yêsu tât ta ntŭk nây, păng n'gơr măt uănh jêh ri lah: “Hơi Y-Sachê trŭnh hom gơnh!”$b$,false),
('bunong-vn','LUK',19,6,null,$b$Yor lah nar aơ gâp mra gŭ tâm ngih may Y-Sachê trŭnh ro, jêh ri rom Brah Yêsu ma nau răm.$b$,false),
('bunong-vn','LUK',19,7,null,$b$Saơ pô nây lĕ rngôch bunuyh ngơi ƀŭk dŭk suyh jêh ri lah: “Păng hăn gŭ tâm ngih du huê bunuyh tih.”$b$,false),
('bunong-vn','LUK',19,8,null,$b$Ƀiă lah Y-Sachê gŭ râng ta năp Kôranh Brah jêh ri lah ma păng: “Ơ Kôranh Brah, aơ gâp ăn ma phung o ach n'gul vah drăp ndơ gâp, tơ lah gâp sa ndơ bu, gâp ntrok plơ̆ ma păng puăn tơ̆ âk lơn.”$b$,false),
('bunong-vn','LUK',19,9,null,$b$Brah Yêsu lah ma păng: “Nar aơ nau tâm rklaih lăp jêh tâm ngih aơ, yor lah nơm aơ jêng kon Y-Abraham.$b$,false),
('bunong-vn','LUK',19,10,null,$b$Yor lah kon bunuyh văch ŭch joi jêh ri tâm rklaih mbu nơm roh jêh.”$b$,false),
('bunong-vn','LUK',19,11,null,$b$Dôl khân păng tăng nau nây, Brah Yêsu ngơi du ntil nau hôr yor lah păng gŭ dăch ƀon Yêrusalem, yor lah khân păng mĭn, ƀon bri hađăch Brah Ndu dăch tât jêh,$b$,true),
('bunong-vn','LUK',19,12,null,$b$Pô nây păng lah: “Du huê bunuyh ndrŏng hăn nsong bri ngai, ŭch sŏk dơn nau dơi jêng hađăch jêh ri plơ̆ sĭt.$b$,false),
('bunong-vn','LUK',19,13,null,$b$Păng kuăl jât nuyh tâm phung oh mon păng. Păng ăn ma phung nây jât rêl jêh ri lah: ‘Ăn khân may dâk prăk aơ tât gâp plơ̆ sĭt.’$b$,false),
('bunong-vn','LUK',19,14,null,$b$Ƀiă lah phung ƀon lan păng tâm rmot ma păng. Jêh păng hăn, khân păng njuăl du huê oh mon ktang, đă păng lah pô aơ: ‘Hên mâu ŭch ôh ma bunuyh aơ chiă uănh hên!’$b$,false),
('bunong-vn','LUK',19,15,null,$b$Tơ lah păng plơ̆ sĭt, jêh păng geh nau dơi jêng hađăch, păng kuăl ăn phung oh mon văch dăch păng. Ma phung nây păng ăn jêh prăk, jêh ri ŭch gĭt mâm ƀư ăp nơm dŏng prăk nây.$b$,false),
('bunong-vn','LUK',19,16,null,$b$Oh mon mrô nguay văch jêh ri lah: ‘Hơi kôranh, prăk may hŏ dơi geh n'hao kao tât jât.’$b$,false),
('bunong-vn','LUK',19,17,null,$b$Kôranh lah ma păng: ‘Di jêh, hơi oh mon ueh, yor lah may răp jăp ngăn tâm kan jê̆, may mra geh nau chiă uănh jât ƀon.’$b$,false),
('bunong-vn','LUK',19,18,null,$b$Oh mon mrô bar văch jêh ri lah: ‘Hơi kôranh, prăk may hŏ dơi geh n'hao kao jêng prăm.’$b$,false),
('bunong-vn','LUK',19,19,null,$b$Păng lah đŏng ma păng: ‘May tâm ban lĕ ăn may chiă uănh prăm ƀon.’$b$,false),
('bunong-vn','LUK',19,20,null,$b$Oh mon êng văch jêh ri lah: ‘Hơi kôranh, aơ prăk may, gâp nklâm tâm bok, yor gâp klach ma may,$b$,false),
('bunong-vn','LUK',19,21,null,$b$yor lah may jêng bunuyh dăng, may sŏk ndơ may mâu mâp dơm, jêh ri may rek ndơ may mâu mâp srih.’$b$,false),
('bunong-vn','LUK',19,22,null,$b$Kôranh lah ma păng: ‘Hơi oh mon ƀai, gâp phat dôih may tĭng nâm bu nau may ngơi. May gĭt jêh gâp jêng du huê bunuyh dăng, sŏk ndơ gâp mâu mâp dơm, jêh ri rek ndơ gâp mâu mâp srih.$b$,false),
('bunong-vn','LUK',19,23,null,$b$Pô ri mâm ƀư may mâu prăp prăk gâp tâm ngih prăp prăk? Tơ lah gâp plơ̆ sĭt gâp mra sŏk păng ma nau kao?’$b$,false),
('bunong-vn','LUK',19,24,null,$b$Jêh ri păng lah ma phung gŭ ta nây: ‘Sŏk sĭt lơi prăk tă bơh păng, ăn ma nơm geh jêh jât rêl.’$b$,false),
('bunong-vn','LUK',19,25,null,$b$Khân păng plơ̆ lah: ‘Hơi kôranh, păng geh jêh jât rêl!’$b$,false),
('bunong-vn','LUK',19,26,null,$b$Gâp lah ma khân may: ‘Bu mra ăn ma mbu nơm hŏ geh, bu mra sŏk lơi nđâp ma ndơ păng hŏ geh jêh.$b$,false),
('bunong-vn','LUK',19,27,null,$b$Bi ma phung rlăng đah gâp, njŭn leo khân păng ta aơ. Khân păng mâu ŭch ma gâp jêng hađăch, khân păng nkhĭt lơi khân păng ta năp gâp.’ ”$b$,false),
('bunong-vn','LUK',19,28,null,$b$Jêh păng ngơi pô nây Brah Yêsu hăn ta năp phung âk, gay ma hăn hao ta ƀon Yêrusalem.$b$,false),
('bunong-vn','LUK',19,29,null,$b$Tơ lah Păng dăch tât ta ƀon Bêtphajê jêh ri ƀon Bêthani, mpeh yôk Ôlivơ, Păng njuăl bar hê oh mon Păng, jêh ri lah:$b$,true),
('bunong-vn','LUK',19,30,null,$b$“Hăn ta ƀon pa năp khân may. Tơ lah khân may lăp ta nây khân may mra saơ du mlâm kon seh bri bu kât jêh. Seh nây mâu hŏ mâp bu ncho ôh. Doh têk păng leo ta gâp.$b$,false),
('bunong-vn','LUK',19,31,null,$b$Tơ lah bu ôp khân may: ‘Mâm ƀư khân may doh seh nây?’ Khân may mra plơ̆ lah ma khân păng: ‘Kôranh Brah ŭch ma păng.’ ”$b$,false),
('bunong-vn','LUK',19,32,null,$b$Phung nây hăn yơh jêh ri saơ mpa tâm ban ma Brah Yêsu hŏ lah jêh ma khân păng.$b$,false),
('bunong-vn','LUK',19,33,null,$b$Tơ lah khân păng doh kon seh nây, nơm seh lah: “Mâm ƀư khân may doh kon seh nây?”$b$,false),
('bunong-vn','LUK',19,34,null,$b$Khân păng plơ̆ lah: “Kôranh Brah ŭch ma păng.”$b$,false),
('bunong-vn','LUK',19,35,null,$b$Jêh ri khân păng têk kon seh ma Brah Yêsu, khân păng ntă bok ao ta klơ ndŭr kơi seh, jêh ri ăn Brah Yêsu ncho.$b$,false),
('bunong-vn','LUK',19,36,null,$b$Tơ lah Brah Yêsu ncho seh hăn, âk bunuyh lăk bok aơ khân păng rŏ trong.$b$,false),
('bunong-vn','LUK',19,37,null,$b$Tơ lah păng dăch tât ta ƀon Yêrusalem, dăch jreng yôk Ôlivơ, lĕ rngôch phung tĭng groi Păng ma nau răm maak, tâm rnê ma Brah Ndu, ma bâr huy ktang, yor lĕ nau khlay ngăn khân păng saơ jêh.$b$,false),
('bunong-vn','LUK',19,38,null,$b$Khân păng lah: “Mât ton ma hađăch văch ma amoh Kôranh Brah! Nau đăp mpăn tâm trôk, jêh ri nau chrêk rmah tâm ntŭk prêh lơn.”$b$,false),
('bunong-vn','LUK',19,39,null,$b$Geh ƀa ƀă phung Pharisi ta nklang phung âk lah ma Brah Yêsu: “Hơi Kôranh nơm nti, buay phung tĭng ndô̆ may!”$b$,true),
('bunong-vn','LUK',19,40,null,$b$Păng plơ̆ lah: “Gâp lah ma khân may, tơ lah khân păng gŭ rklăk lŭ mra nter.”$b$,false),
('bunong-vn','LUK',19,41,null,$b$Lah păng dăch tât ta ƀon, Brah Yêsu saơ ƀon nây, păng nhĭm jêh ri lah:$b$,false),
('bunong-vn','LUK',19,42,null,$b$“Gâp ŭch nar aơ may dơi gĭt ndơ dơi ăn nau đăp mpăn ma may!$b$,false),
('bunong-vn','LUK',19,43,null,$b$Ƀiă lah aƀaơ păng jêng ndâp ma măt may, dôl nây phung rlăng mra kuyh ntu jŭm may, gŭ jŭm may, jêh ri kâp may lam ntŭk.$b$,false),
('bunong-vn','LUK',19,44,null,$b$Phung rlăng đah may mra ƀư rai may, nđâp ma phung kon may tâm nklang may, jêh ri khân păng mâu mra cha lơi ôh tâm may du mlâm lŭ ta klơ lŭ êng yor lah may mâu gĭt ôh rnôk geh nau khâl jêh đah may.”$b$,false),
('bunong-vn','LUK',19,45,null,$b$Păng lăp tâm ngih brah Yuđa, jêh ri mprơh phung tăch drăp ta nây. Păng lah ma phung nây:$b$,true),
('bunong-vn','LUK',19,46,null,$b$“Geh nau nchih jêh pô aơ: ‘Ngih gâp jêng ngih prăp ma nau mbơh sơm.’ Ƀiă lah khân ay may njêng trôm ma phung ntŭng gŭ.”$b$,false),
('bunong-vn','LUK',19,47,null,$b$Păng nti lah ăp nar tâm ngih brah Yuđa, phung n'gâng kôranh ƀư brah, phung kôranh nchih sămƀŭt jêh ri phung bu bŭnh bu ranh joi nau ŭch nkhĭt Păng.$b$,true),
('bunong-vn','LUK',19,48,null,$b$Ƀiă lah khân păng mâu gĭt, mâm mra ƀư, yor lah lĕ rngôch bunuyh ƀon lan gŭ iăt Păng ma nau hih rhâl.$b$,false),
('bunong-vn','LUK',20,1,null,$b$Geh du nar, dôl Brah Yêsu nti ma phung bunuyh âk tâm ngih brah Yuđa jêh ri mbơh nau mhe mhan ueh, phung n'gâng kôranh ƀư brah, phung kôranh nchih sămƀŭt ndrel ma phung bu bŭnh bu ranh văch lah ma Păng:$b$,true),
('bunong-vn','LUK',20,2,null,$b$“Lah ma hên ma moh nau dơi toyh, may ƀư nau nây, mâu lah mbu nơm ăn ma may nau dơi toyh nây?”$b$,false),
('bunong-vn','LUK',20,3,null,$b$Păng plơ̆ lah ma phung nây: “Gâp mra ôp khân may tâm ban lĕ.$b$,false),
('bunong-vn','LUK',20,4,null,$b$Lah ma gâp, nau Y-Yôhan ƀư ƀaptem luh tă bơh trôk lĕ mâu lah tă bơh bunuyh?”$b$,false),
('bunong-vn','LUK',20,5,null,$b$Khân păng tâm nchră ndrăng khân păng nơm: “Tơ lah he plơ̆ lah: ‘Tă bơh trôk,’ Păng mra lah: ‘Mâm ƀư khân may mâu chroh ma Păng?’$b$,false),
('bunong-vn','LUK',20,6,null,$b$Tơ lah, he lah: ‘Tă bơh bunuyh,’ lĕ rngôch bunuyh ƀon lan mra klŭp lŭ ma he, yor lah khân păng chroh ma Y-Yôhan jêng du huê kôranh nơm mbơh lor.”$b$,false),
('bunong-vn','LUK',20,7,null,$b$Khân păng plơ̆ lah, khân păng mâu gĭt ôh mbah tă păng luh.$b$,false),
('bunong-vn','LUK',20,8,null,$b$Pô ri Brah Yêsu lah ma khân păng: “Jêh ri gâp tâm ban lĕ mâu mra lah ma khân may ôh ma moh nau dơi toyh gâp ƀư nau aơ.”$b$,false),
('bunong-vn','LUK',20,9,null,$b$Brah Yêsu ngơi nau hôr aơ ma phung ƀon lan: “Du huê bunuyh ƀư mir tăm play kriăk ƀâu. Păng nkhôm bu chiă jêh ri păng gŭ jŏ tâm n'gor êng.$b$,true),
('bunong-vn','LUK',20,10,null,$b$Yan rek tât jêh, păng njuăl du huê oh mon ma phung chiă mir play kriăk ƀâu nây, gay ma khân păng tâm pă play kriăk ƀâu, ma nơm nây. Phung chiă mir nây dong păng, nsot plơ̆ sĭt dơm dam.$b$,false),
('bunong-vn','LUK',20,11,null,$b$Păng njuăl tay du huê oh mon êng, ƀiă lah ăt phung chiă mir dong đŏng, suai rak, jêh ri nsot plơ̆ sĭt dơm dam.$b$,true),
('bunong-vn','LUK',20,12,null,$b$Păng njuăl đŏng du huê tal pe, ƀiă lah khân păng ƀư tât sôt rmanh jêh ri mprơh lơi.$b$,false),
('bunong-vn','LUK',20,13,null,$b$Kôranh mir kriăk ƀâu lah: ‘Mâm gâp mra ƀư? Gâp mra njuăl kon gâp nơm rŏng ngăn ngên, klăp lah phung nây mra yơk ma păng!’$b$,false),
('bunong-vn','LUK',20,14,null,$b$Ƀiă lah tơ lah phung chiă uănh mir saơ păng, khân păng tâm nchră ndrăng khân păng nơm jêh ri lah: ‘Aơ nơm dơn drăp he nkhĭt lơi păng, pô ri mơ drăp ndơn ma he.’$b$,false),
('bunong-vn','LUK',20,15,null,$b$Khân păng klŭp nơm nây ta pĭt mir kriăk ƀâu, jêh ri nkhĭt lơi păng. Aƀaơ mâm kôranh mir kriăk ƀâu mra ƀư?$b$,false),
('bunong-vn','LUK',20,16,null,$b$Păng mra nkhĭt lơi lĕ rngôch phung chiă mir jêh ri păng mra ăn mir play kriăk ƀâu ma phung êng.” Tơ lah khân păng tăng nau nây, khân păng lah: “Brah Ndu buay pô nây!”$b$,false),
('bunong-vn','LUK',20,17,null,$b$Ƀiă lah Brah Yêsu uănh ma khân păng jêh ri lah: “Pô nây nâm bu ntĭt nau bu nchih aơ: Lŭ phung nkra ngih mƀăr lơi jêh, jêng lŭ njônh?$b$,false),
('bunong-vn','LUK',20,18,null,$b$Mbu nơm mra tŭp ta klơ lŭ aơ, păng mra chah, ƀiă lah ta mbu nơm lŭ aơ mra tŭp ta klơ păng, păng mra lêk.”$b$,true),
('bunong-vn','LUK',20,19,null,$b$Phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt joi ŭch ƀư mhĭk ma Brah Yêsu mông nây ro, ƀiă lah khân păng klach ma phung âk yor lah khân păng gĭt rbăng jêh ma khân păng yơh Brah Yêsu ngơi nau hôr nây.$b$,false),
('bunong-vn','LUK',20,20,null,$b$Khân păng ntơm uănh nđôi Brah Yêsu jêh ri njuăl phung ƀư tâm ban ma phung răp jăp, gay ma dơi nhŭp Brah Yêsu, yor nau Păng ngơi, pô ri dơi jao Păng ma phung kôranh phat dôih jêh ri ma kôranh toyh.$b$,true),
('bunong-vn','LUK',20,21,null,$b$Nơm nây ôp ma Păng pô aơ: “Hơi Kôranh nơm nti, hên gĭt may ngơi, jêh ri nti ma nau sŏng. May mâu uănh ôh pah dih, ƀiă lah may nti trong Brah Ndu tĭng nâm nau nanê̆.$b$,true),
('bunong-vn','LUK',20,22,null,$b$Vay lĕ he chê̆ pi ma Sêsar mâu lah, lơi?”$b$,false),
('bunong-vn','LUK',20,23,null,$b$Brah Yêsu gĭt nau khân păng ndơm jêh ri plơ̆ lah ma khân păng pô aơ:$b$,false),
('bunong-vn','LUK',20,24,null,$b$“Mpơl ma gâp du rêl. Mbu rup jêh ri moh nau nchih aơ?” Khân păng plơ̆ lah: “Tă bơh Sêsar yơh.”$b$,false),
('bunong-vn','LUK',20,25,null,$b$Păng lah ma phung nây: “Moh jêng ndơ Sêsar, mplơ̆ lơi ma Sêsar, jêh ri moh ndơ Brah Ndu, mplơ̆ ma Brah Ndu nơm.”$b$,false),
('bunong-vn','LUK',20,26,null,$b$Phung nây mâu dơi nduyh Brah Yêsu ôh, yor nau păng ngơi ta năp băl âk. Khân păng hih rhâl ma nau Brah Yêsu plơ̆ lah, jêh ri khân păng gŭ rklăk.$b$,false),
('bunong-vn','LUK',20,27,null,$b$Geh ƀa ƀă phung Sađusê lah, mâu geh nau dâk rêh ôh. Khân păng hăn dăch jêh ri ôp Brah Yêsu pô aơ:$b$,true),
('bunong-vn','LUK',20,28,null,$b$“Hơi Kôranh nơm nti, aơ Y-Môis ntăm jêh ma hên pô aơ: ‘Tơ lah nâu khĭt lăn geh ur ƀiă lah ê geh kon, oh păng ntrok ur păng jêh ri mra geh kon ma nâu păng.’$b$,false),
('bunong-vn','LUK',20,29,null,$b$Pô ri geh pơh nuyh oh nâu, nâu lor lơn gŭ ur khĭt, ƀiă lah ê geh kon ôh.$b$,false),
('bunong-vn','LUK',20,30,null,$b$Oh groi deh (tal bar),$b$,true),
('bunong-vn','LUK',20,31,null,$b$jêh ri tal pe dơi gŭ ur păng lĕ, nđâp ma oh mpŭt tal pơh ăt dơi gŭ lĕ. Khân păng khĭt lĕ, ƀiă lah mâu geh kon ôh.$b$,false),
('bunong-vn','LUK',20,32,null,$b$Kêng lôch dŭt bu ur nây khĭt tâm ban lĕ.$b$,false),
('bunong-vn','LUK',20,33,null,$b$Ta nar dâk rêh, ma mbu nơm bu ur nây mra jêng ur, yor lah lĕ pơh nuyh jêng sai păng da dê jêh?”$b$,false),
('bunong-vn','LUK',20,34,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Phung kon rnôk aơ tâm gŭ ur sai,$b$,false),
('bunong-vn','LUK',20,35,null,$b$ƀiă lah phung mra khư lăp tâm rnôk kăndơ̆ , jêh ri dâk rêh tă bơh khĭt, mâu mra hôm tâm gŭ ur sai ôh,$b$,false),
('bunong-vn','LUK',20,36,null,$b$Yor lah khân păng mâu hôm dơi khĭt ôh, yor lah khân păng mra jêng nâm bu phung Tông mpăr ueh Brah Ndu, jêh ri khân păng jêng kon Brah Ndu, jêng kon nau dâk rêh.$b$,false),
('bunong-vn','LUK',20,37,null,$b$Bi ma nau phung khĭt dâk rêh, Y-Môis hŏ mpơl jêh tâm nau nchih ma rlô ŭnh sa, tơ lah păng kuăl Brah Ndu Y-Abraham, Brah Ndu Y-Isăk, jêh ri Brah Ndu Y-Yakôp.$b$,false),
('bunong-vn','LUK',20,38,null,$b$Păng mâu jêng Brah Ndu ma phung khĭt ôh, ƀiă lah ma phung rêh, yor lah lĕ rngôch gŭ rêh, yor lah lĕ rngôch gŭ rêh ma Păng.”$b$,false),
('bunong-vn','LUK',20,39,null,$b$Geh ƀa ƀă phung nchih sămƀŭt ngơi ma Păng: “Hơi Kôranh nơm nti may ngơi di.”$b$,false),
('bunong-vn','LUK',20,40,null,$b$Jêh ri khân păng mâu janh ôp du ntil nau ma Brah Yêsu ôh.$b$,false),
('bunong-vn','LUK',20,41,null,$b$Brah Yêsu lah ma khân păng: “Mâm ƀư bu dơi lah ma Brah Krist jêng kon Y-Đavit?$b$,true),
('bunong-vn','LUK',20,42,null,$b$Yor lah Y Đavit nơm lah tâm ndrom sămƀŭt nau mprơ ơm: ‘Kôranh Brah lah ma kôranh Brah gâp: Gŭ hom may mpeh pa ma gâp.$b$,false),
('bunong-vn','LUK',20,43,null,$b$Tât gâp ăn phung rlăng may jêng ntŭk may chrong jâng.’$b$,true),
('bunong-vn','LUK',20,44,null,$b$Tơ lah Y-Đavit kuăl ma Păng Kôranh Brah; mâm ƀư Brah Yêsu dơi jêng kon păng?”$b$,false),
('bunong-vn','LUK',20,45,null,$b$Dôl phung âk gŭ iăt nau Păng, Păng lah ma phung oh mon Păng:$b$,true),
('bunong-vn','LUK',20,46,null,$b$“Njrăng hom khân may ma phung kôranh nchih sămƀŭt, khân păng ŭch nsoh ao jong hăn nsong, jêh ri khân păng ŭch bu mbah ma khân păng tâm ngih tăch drăp. Khân păng joi ntŭk mrô nguay tâm ngih rƀŭn Yuđa. Jêh ri ntŭk mrô nguay tâm nau sông sa toyh.$b$,false),
('bunong-vn','LUK',20,47,null,$b$Khân păng rvăn sa phung bu ur khĭt sai jêh ri khân păng jan lah mbơh sơm jŏ. Khân păng mra dơn nau tâm rmal ktang lơn.”$b$,false),
('bunong-vn','LUK',21,1,null,$b$Brah Yêsu n'gơr măt uănh phung ndrŏng dơm ndơ khân păng nhhơr tâm hip prăp prăk.$b$,true),
('bunong-vn','LUK',21,2,null,$b$Păng saơ lĕ du huê bu ur ndrô rêh ni, nklăch tâm hip nây bar rêl.$b$,false),
('bunong-vn','LUK',21,3,null,$b$Jêh ri Păng lah: “Nanê̆ gâp lah ma khân may, bu ur ndrô rêh ni nây, nklăch âk lơn ma phung êng.$b$,false),
('bunong-vn','LUK',21,4,null,$b$Yor lah lĕ rngôch phung nây nhhơr ndơ khân păng geh rmeh, nklăch tâm hip prăp prăk, bi bu ur aơ nđâp tơ lah păng o ach kđôi lĕ, ƀiă lah păng nhhơr lĕ ndơ păng geh.”$b$,false),
('bunong-vn','LUK',21,5,null,$b$Geh bunuyh ƀa ƀă ngơi ma ngih brah Yuđa geh âk lŭ ueh, jêh ri ndơ bu nhhơr gay ma n'hĭ păng Brah Yêsu lah:$b$,true),
('bunong-vn','LUK',21,6,null,$b$“Nar mra tât, rnôk nây lĕ ndơ khân may saơ rnôk aơ mra rai. Du mlâm lŭ mâu mra gŭ ta klơ lŭ êng ôh.”$b$,false),
('bunong-vn','LUK',21,7,null,$b$Pô ri khân păng ôp Brah Yêsu: “Hơi Kôranh nơm nti, ndah jŏ nau nây mra tât?”$b$,false),
('bunong-vn','LUK',21,8,null,$b$Păng plơ̆ lah: “Njrăng hom khân may, lơi ăn bu ndơm khân may ôh, yor lah âk bunuyh mra văch ma amoh gâp: ‘Gâp yơh! Jêh ri, nar dăch tât jêh!’ Lơi tĭng khân păng ôh.$b$,false),
('bunong-vn','LUK',21,9,null,$b$Jêh ri tơ lah khân may tăng bu nkoch bri ma nau tâm lơh, jêh ri ma nau tâm rdâng, lơi ta khân may klach ôh, yor lah nau nây mra tât lor lơn, ƀiă lah ê tât nar kêng lôch ôh.”$b$,false),
('bunong-vn','LUK',21,10,null,$b$Jêh ri Păng lah lĕ ma phung nây: “Du phung mpôl băl mra tâm rdâng đah du phung mpôl băl êng, jêh ri du ƀon bri hađăch mra tâm lơh đah du ƀon bri hađăch êng.$b$,true),
('bunong-vn','LUK',21,11,null,$b$Mra geh nau sâr neh ntu, jêh ri nau ji, khĭt, nau sa sât ji ngot, tâm âk ntŭk, mra geh nau tâm nhhu klach ngăn, jêh ri âk nau tâm mbên tâm trôk.$b$,false),
('bunong-vn','LUK',21,12,null,$b$Ƀiă lah lor ma lĕ nau nây tât, bu mra ăn ma khân may âk nau mhĭk, mra njŭn khân may ta năp phung hađăch jêh ri phung kôranh toyh, yor amoh gâp.$b$,false),
('bunong-vn','LUK',21,13,null,$b$Nau nây mra tât ma khân may, gay ma geh nau khân may mbơh nau chroh.$b$,false),
('bunong-vn','LUK',21,14,null,$b$Ăn khân may kah gĭt pô aơ: Lơi ta khân may mĭn lor ôh ma nau khân may n'gang khân may nơm.$b$,true),
('bunong-vn','LUK',21,15,null,$b$Yor lah gâp mra ăn ma khân may nau ngơi jêh ri nau blau mĭn, tât lĕ rngôch phung rlăng đah khân may, mâu mra dơi tâm rdâng mâu lah tâm nkăl đah khân may ôh.$b$,false),
('bunong-vn','LUK',21,16,null,$b$Mbơ̆ mê̆, oh nâu, phung băl jêh ri phung mĭt jiăng khân may nơm lĕ, mra jao khân may, jêh ri mra nkhĭt âk tâm phung khân may.$b$,false),
('bunong-vn','LUK',21,17,null,$b$Lĕ rngôch bunuyh mra tâm rmot ma khân may yor amoh gâp.$b$,false),
('bunong-vn','LUK',21,18,null,$b$Ƀiă lah mâu geh du mbrai sŏk ta bôk khân may mra roh.$b$,true),
('bunong-vn','LUK',21,19,null,$b$Ma nau srôih yơh khân may mra tâm rklaih huêng khân may.$b$,false),
('bunong-vn','LUK',21,20,null,$b$“Ƀiă lah tơ lah khân may saơ phung ta han gŭ jŭm ƀon Yêrusalem, ăn khân may gĭt nau ƀư rai păng dăch jêh.$b$,true),
('bunong-vn','LUK',21,21,null,$b$Rnôk nây ăn phung gŭ tâm n'gor Yuđa du ta yôk. Ăn phung gŭ ta nklang ƀon Yêrusalem, mra luh, jêh ri lơi ăn phung gŭ tâm mir lăp tâm ƀon ôh.$b$,false),
('bunong-vn','LUK',21,22,null,$b$Yor lah rnôk nây jêng nar nau tâm plơng nglay săk, gay ma nanê̆ lĕ nau nchih jêh.$b$,false),
('bunong-vn','LUK',21,23,null,$b$Rêh ni yơh ma phung bu ur ntreo, ăn kon pu toh tâm nar nây! Yor lah mra geh nau rêh ni toyh ngăn tâm n'gor nây, jêh ri nau ji nuih ma phung ƀon lan nây.$b$,false),
('bunong-vn','LUK',21,24,null,$b$Bu mra nkhĭt khân păng ma đao bu njŭn khân păng jêng bu nă tâm lĕ rngôch mpôl băl, jêh ri phung bu năch mra jot ƀon Yêrusalem tâm dâng jâng khân păng, tât rnôk phung bu năch mra ƀư lĕ.$b$,false),
('bunong-vn','LUK',21,25,null,$b$Mra geh nau mbên tâm nar, tâm khay, jêh ri tâm phung mănh, tâm neh ntu mra geh nau uh ah tâm phung mpôl băl bunuyh. Khân păng mâu gĭt, mâm ƀư tăng nteh dak mƀŭt jêh ri dak sial njach.$b$,false),
('bunong-vn','LUK',21,26,null,$b$Âk bunuyh mra khĭt yor nau klach dôl gŭ kâp nau mra tât ma neh ntu, yor lah nau brah tâm trôk mra rgu n'gơ.$b$,false),
('bunong-vn','LUK',21,27,null,$b$Jêh ri bu mra saơ Kon Bunuyh văch tâm ndâr tŭk ma nau brah, jêh ri ma nau chrêk rmah toyh ngăn.$b$,true),
('bunong-vn','LUK',21,28,null,$b$Tơ lah nau nây tât, dâk hom jêh ri n'gơr bôk khân may, yor lah nau tâm chuai khân may hŏ dăch jêh.”$b$,false),
('bunong-vn','LUK',21,29,null,$b$Jêh ri Brah Yêsu ngơi ma khân păng nau tâm ntĭt pô aơ: “Uănh hom ma tơm rvi jêh ri lĕ rngôch tơm si.$b$,true),
('bunong-vn','LUK',21,30,null,$b$Tơ lah păng ntơm chăt nkŭr, khân may saơ jêh ri gĭt ma yan kăl vai dăch jêh.$b$,false),
('bunong-vn','LUK',21,31,null,$b$Tâm ban lĕ, tơ lah khân may saơ nau nây tât, ăn khân may gĭt ma ƀon bri hađăch Brah Ndu dăch jêh.$b$,false),
('bunong-vn','LUK',21,32,null,$b$Nanê̆ gâp lah ma khân may, phung bunuyh rnôk aơ mâu mra rlau lôch ôh, kŏ lĕ nau nây tât.$b$,false),
('bunong-vn','LUK',21,33,null,$b$Trôk jêh ri neh ntu mra rlau lôch, ƀiă lah nau gâp ngơi mâu mra rlau lôch ôh.$b$,true),
('bunong-vn','LUK',21,34,null,$b$“Njrăng hom ma khân may nơm, klach lah nuih n'hâm khân may jêng jâk ma nau sông sa, nhêt ma nau rêh nar aơ jêh ri nar nây tât ma khân may, ƀât lât tâm ban ma jal.$b$,true),
('bunong-vn','LUK',21,35,null,$b$Yor lah păng mra tât tâm ban ma jal ma lĕ rngôch bunuyh gŭ ta klơ neh ntu.$b$,false),
('bunong-vn','LUK',21,36,null,$b$Pô ri njrăng hom jêh ri mbơh sơm ƀa ƀơ, pô ri mơ khân may geh nau ktang dơi klaih bơh lĕ nau mra tât nây, dơi gŭ râng ta năp Kon Bunuyh.”$b$,true),
('bunong-vn','LUK',21,37,null,$b$Ăp nar Brah Yêsu gŭ nti tâm ngih brah Yuđa jêh ri măng Păng hăn bêch ta yôk bu rnha yôk Ôlivơ.$b$,true),
('bunong-vn','LUK',21,38,null,$b$Jêh ri ôi ơm lĕ rngôch bunuyh hăn ta Păng ŭch iăt nau Păng tâm ngih brah Yuđa.$b$,false),
('bunong-vn','LUK',22,1,null,$b$Nau nhêt, sông sa kapŭng mâu geh ndrui, bu rnha Nau Găn dăch tât jêh.$b$,true),
('bunong-vn','LUK',22,2,null,$b$Phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt joi nau ŭch nkhĭt Brah Yêsu, yor lah khân păng klach ma phung âk.$b$,false),
('bunong-vn','LUK',22,3,null,$b$Satan lăp tâm Y-Yuđas, tâm amoh Iskariôt. Păng jêng du huê tâm phung jât ma bar nuyh oh mon.$b$,true),
('bunong-vn','LUK',22,4,null,$b$Y-Yuđas hăn tâm chră đah phung n'gâng kôranh ƀư brah jêh ri đah phung kôranh ta han ma nau păng dơi jao Brah Yêsu ma phung nây.$b$,false),
('bunong-vn','LUK',22,5,null,$b$Phung nây răm maak jêh ri ton ăn prăk ma păng.$b$,false),
('bunong-vn','LUK',22,6,null,$b$Pô ri păng dơn nau nây, jêh ri joi nar di dơi jao Brah Yêsu dôl phung âk mâu gĭt ôh.$b$,true),
('bunong-vn','LUK',22,7,null,$b$Nar sa kapŭng mâu geh ndrui tât jêh. Nar nây bu vay ƀư brah gay ma kah gĭt Nau Găn.$b$,true),
('bunong-vn','LUK',22,8,null,$b$Pô ri Brah Yêsu njuăl Y-Pêtrôs jêh ri Y-Yôhan jêh ri lah: “Hăn hom nkra Nau Găn gay ma he sa.”$b$,false),
('bunong-vn','LUK',22,9,null,$b$Phung nây lah ma Brah Yêsu: “Ta ntŭk may ŭch ăn hên mra nkra?”$b$,false),
('bunong-vn','LUK',22,10,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Tơ lah khân may lăp tâm ƀon, khân may mra mâp, du huê djôt du yăng dak. Tĭng groi păng tât păng lăp tâm ngih,$b$,false),
('bunong-vn','LUK',22,11,null,$b$jêh ri khân may mra lah ma kôranh ngih: ‘Kôranh nơm nti lah ma may, Ta ntŭk gâp mra gŭ sông sa Nau Găn ndrel ma phung oh mon gâp?’$b$,false),
('bunong-vn','LUK',22,12,null,$b$Jêh ri păng mra ntĭm an ma khân may du jrô toyh, tâm nây geh jêh sưng rnơl; khân may mra nkra ta nây.”$b$,false),
('bunong-vn','LUK',22,13,null,$b$Khân păng hăn jêh ri saơ ndơ tâm ban ma Brah Yêsu lah jêh ma khân păng, jêh ri khân păng nkra Nau Găn.$b$,false),
('bunong-vn','LUK',22,14,null,$b$Mông tât jêh, khân păng ntơm sông sa jêh ri phung kôranh oh mon ndrel ma Păng.$b$,true),
('bunong-vn','LUK',22,15,null,$b$Păng lah ma phung nây: “Gâp ŭch ngăn sa Nau Găn aơ ndrel ma khân may, lor ma gâp dơn nau rêh ni.$b$,true),
('bunong-vn','LUK',22,16,null,$b$Yor lah gâp lah ma khân may, gâp mâu mra hôm sa Nau Găn ôh tât păng ƀư nanê̆ tâm ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','LUK',22,17,null,$b$Păng sŏk kchok jêh ri mbơh sơm nau kah gĭt tôr. Păng lah: “Sŏk kchok aơ jêh ri tâm pă ndrăng khân may,$b$,false),
('bunong-vn','LUK',22,18,null,$b$yor lah gâp lah ma khân may, gâp mâu mra hôm nhêt ôh dak play kriăk ƀâu, kŏ tât ƀon bri hađăch Brah Ndu.”$b$,false),
('bunong-vn','LUK',22,19,null,$b$Jêh ri Păng sŏk kapŭng, mbơh sơm lah ueh, nkêch kapŭng ăn ma khân păng, jêh ri lah: “Aơ jêng nglay săk gâp, ăn jêh ma khân may. Ƀư pô aơ gay ma kah gĭt ma gâp.”$b$,false),
('bunong-vn','LUK',22,20,null,$b$Jêh sông sa Păng sŏk kchok tâm ban lĕ, ăn ma khân păng, jêh ri lah: “Kchok aơ jêng nau tâm rnglăp mhe tâm mham gâp nkhŭt jêh ma khân may.$b$,false),
('bunong-vn','LUK',22,21,null,$b$Ƀiă lah aơ, ti nơm rlăng đah gâp gŭ sông ndrel ma gâp.$b$,false),
('bunong-vn','LUK',22,22,null,$b$Kon Bunuyh mra hăn tâm ban ma nau săch jêh Păng, ƀiă lah rêh ni yơh nơm rlăng ma Păng.”$b$,false),
('bunong-vn','LUK',22,23,null,$b$Jêh ri khân păng tâm ôp ndrăng khân păng nơm, mbu nơm tâm phung khân păng mra ƀư nau nây.$b$,true),
('bunong-vn','LUK',22,24,null,$b$Geh nau tâm rlăch ndrăng phung oh mon, mbu nơm tâm phung khân păng bu mra kơp toyh lơn.$b$,true),
('bunong-vn','LUK',22,25,null,$b$Ƀiă lah Brah Yêsu lah ma khân păng: “Phung hađăch phung bu năch, jêng kôranh ma khân păng jêh ri phung geh nau dơi đah khân păng, bu rnha khân păng jêng phung ƀư ueh.$b$,false),
('bunong-vn','LUK',22,26,null,$b$Bi ma khân may mâu geh nâm nđĕ ôh, ƀiă lah ăn nơm toyh lơn tâm phung khân may jêng jê̆ lơn, jêh ri ăn nơm jêng kôranh tâm ban ma oh mon.$b$,false),
('bunong-vn','LUK',22,27,null,$b$Yor lah mbu nơm jêng toyh lơn, nơm gŭ ta sưng sông mâu lah oh mon? Di lĕ nơm gŭ ta sưng sông? Ƀiă lah gâp gŭ ta nklang khân may tâm ban ma oh mon.$b$,false),
('bunong-vn','LUK',22,28,null,$b$Phung khân may gŭ srôih jêh ndrel ma gâp, tâm nau rlong uănh tât ma gâp.$b$,true),
('bunong-vn','LUK',22,29,null,$b$Jêh ri gâp mra jao du ƀon bri hađăch ma khân may tâm ban ma Mbơ̆ jao jêh ma gâp.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','LUK',22,30,null,$b$Pô ri khân may mra sông sa ta sưng gâp tâm ƀon bri hađăch gâp, jêh ri khân may mra gŭ ta sưng hađăch phat dôih phung jât ma bar mpôl băl Israel.”$b$,false),
('bunong-vn','LUK',22,31,null,$b$Kôranh Brah lah: “Y-Simôn, Y-Simôn, Satan dăn jêh ŭch mpruh, nsiăng khân may nâm bu ba.$b$,true),
('bunong-vn','LUK',22,32,null,$b$Ƀiă lah gâp mbơh sơm jêh, yor may, gay ma nau chroh may gŭ nâp. Tơ lah may plơ̆ sĭt ăn may ƀư ăn nâp phung oh nâu may.”$b$,false),
('bunong-vn','LUK',22,33,null,$b$Y Pêtrôs lah ma păng. “Ơ Kôranh Brah, gâp kâp hăn ndrel ma may tâm ndrung mâu lah nau khĭt.”$b$,false),
('bunong-vn','LUK',22,34,null,$b$Brah Yêsu lah: “Hơi Pêtrôs, gâp lah ma may, nar aơ ê hŏ iăr ndrau, may mra dun gâp pe tơ̆ .”$b$,false),
('bunong-vn','LUK',22,35,null,$b$Jêh ri Păng lah: “Nôk gâp njuăl khân may hăn mâu geh prăk djôt, mâu geh dŭng jêh ri mâu geh ntâu jot, geh lĕ ndơ khân may pưt?” Khân păng plơ̆ lah: “Mâu.”$b$,true),
('bunong-vn','LUK',22,36,null,$b$Brah Yêsu lah ma khân păng: “Ƀiă lah aƀaơ mbu nơm geh prăk, sŏk prăk nây, jêh ri, mbu nơm geh dŭng, ăn khân păng sŏk dŭng nây jêh ri mbu nơm mâu geh đao gưm tăch bok ao păng, jêh ri rvăt du n'gâr đao gưm.$b$,false),
('bunong-vn','LUK',22,37,null,$b$Yor lah gâp lah ma khân may, nau bu nchih jêh, mra jêng ngăn tâm gâp: ‘Bu kơp păng ndrel ma phung tih.’ Yor lah nau bu nchih ma gâp dăch jêng ngăn jêh.”$b$,false),
('bunong-vn','LUK',22,38,null,$b$Khân păng lah: “Ơ Kôranh Brah, aơ bar mlâm đao gưm.” Păng plơ̆ lah ma phung nây: “Dŭm nĕ, nŭm jêh.”$b$,false),
('bunong-vn','LUK',22,39,null,$b$Jêh Păng luh, Păng hăn ta yôk Ôlivơ tĭng nâm nau vay mơng Păng, jêh ri phung oh mon Păng tĭng Păng.$b$,true),
('bunong-vn','LUK',22,40,null,$b$Tơ lah Păng tât jêh tâm ntŭk nây, Păng lah ma phung oh mon Păng: “Mbơh sơm hom gay ma lơi ăn khân may tŭp tâm nau ndơm.”$b$,false),
('bunong-vn','LUK',22,41,null,$b$Pô ri Păng hăn ngai đah phung nây, klăp lah dơi klŭp lŭ, jêh ri chon kômâk, Păng mbơh sơm pô aơ:$b$,false),
('bunong-vn','LUK',22,42,null,$b$“Ơ Mbơ̆ , tơ lah may ŭch ăn ngai kchok aơ đah gâp, tĭng nâm may ŭch, mâu geh nau gâp ŭch ôh.”$b$,false),
('bunong-vn','LUK',22,43,null,$b$Dôl nây du huê Tông mpăr ueh tă bơh trôk tâm mpơl ma Păng gay ƀư ktang Păng.$b$,false),
('bunong-vn','LUK',22,44,null,$b$Gŭ tâm nau rngot ngăn, Păng mbơh sơm ktang lơn đŏng, jêh ri dak rhal Păng tâm ban ma hoch mham tŭp ta neh âk ngăn.$b$,false),
('bunong-vn','LUK',22,45,null,$b$Jêh mbơh sơm Păng dâk jêh ri hăn ta phung oh mon. Păng saơ phung nây gŭ bêch jêh ma nau rngot.$b$,false),
('bunong-vn','LUK',22,46,null,$b$Jêh ri Păng lah ma phung nây: “Mâm ƀư khân may bêch? Dâk, jêh ri mbơh sơm hom, pô ri mơ khân may mâu mra tŭp tâm nau ndơm.”$b$,false),
('bunong-vn','LUK',22,47,null,$b$Dôl Păng hôm ngơi, aơ geh du phung âk tât, nơm bu rnha Y-Yuđas, du huê tâm phung jât ma bar nuyh oh mon, hăn pa năp phung âk nây. Păng hăn dăch Brah Yêsu gay ma chŭm Păng,$b$,true),
('bunong-vn','LUK',22,48,null,$b$Brah Yêsu lah ma păng: “Hơi Y-Yuđas, ma nau chŭm hĕ may ƀư rlăng ma Kon Bunuyh?”$b$,false),
('bunong-vn','LUK',22,49,null,$b$Phung ndrel ma Brah Yêsu saơ nau dăch tât nây lah: “Ơ Kôranh Brah, dơi lĕ dŏng đao gưm sreh?”$b$,false),
('bunong-vn','LUK',22,50,null,$b$Du huê tâm phung khân păng sreh oh mon kôranh ƀư brah toyh tăch tôr ma.$b$,false),
('bunong-vn','LUK',22,51,null,$b$Ƀiă lah Brah Yêsu lah: “Lơi hom!” Brah Yêsu pah ta tôr nơm nây, jêh ri tôr păng bah ro.$b$,true),
('bunong-vn','LUK',22,52,null,$b$Pô ri Păng lah ma phung n'gâng kôranh ƀư brah, ma phung chiă uănh ngih brah Yuđa, jêh ri ma phung bu bŭnh bu ranh văch nhŭp păng: “Khân may văch ma đao gưm jêh ri ma mâng, tâm ban ma ŭch nhŭp du huê bunuyh ntŭng.$b$,false),
('bunong-vn','LUK',22,53,null,$b$Gâp gŭ ăp nar tâm ngih brah Yuđa ndrel ma khân may, jêh ri khân may mâu ƀư mhĭk ma gâp ôh. Ƀiă lah aƀaơ yơh mông khân may, jêh ri nau brah nau ngo.”$b$,false),
('bunong-vn','LUK',22,54,null,$b$Jêh khân păng nhŭp Brah Yêsu, khân păng njŭn leo lăp tâm ngih kôranh phat dôih toyh, Y-Pêtrôs tĭng groi bơh ngai.$b$,true),
('bunong-vn','LUK',22,55,null,$b$Khân păng sênh ŭnh ta nklang ngih jêh ri gŭ njâr ndrel. Jêh ri Y-Pêtrôs gŭ ndrel ma khân păng.$b$,true),
('bunong-vn','LUK',22,56,null,$b$Tơ lah păng gŭ jêh dăch ŭnh, geh du huê bu ur uănh ma păng mâu mƀrêh măt, jêh ri lah: “Bu klâu aơ gŭ ndrel Păng lĕ.”$b$,false),
('bunong-vn','LUK',22,57,null,$b$Ƀiă lah păng dun jêh ri lah: “Hơi bu ur, gâp mâu gĭt năl Păng ôh.”$b$,false),
('bunong-vn','LUK',22,58,null,$b$Ƀât lât ta nây du huê êng saơ păng jêh ri lah: “May jêng phung nây lĕ!” Y-Pêtrôs lah: “Hơi may, gâp mâu jêng phung nây ôh.”$b$,false),
('bunong-vn','LUK',22,59,null,$b$Tâm du mông pa kơi nây geh du huê êng lah: “Nanê̆, nây gŭ ndrel ma Brah Yêsu lĕ, yor lah păng jêng du huê tă bơh n'gor Galilê.”$b$,false),
('bunong-vn','LUK',22,60,null,$b$Y-Pêtrôs plơ̆ lah: “Hơi may, gâp mâu gĭt ôh moh nau may lah!” Dôl nây lĕ, lah jêh păng ngơi, iăr nkuăng ndrau.$b$,true),
('bunong-vn','LUK',22,61,null,$b$Brah Yêsu n'gĭl pa kơi uănh ta Y Pêtrôs, Y-Pêtrôs kah gĭt ma Nau Kôranh Brah Ngơi jêh ma păng: “Nar aơ lor ma iăr nkuăng ndrau, may mra dun gâp pe tơ̆ .”$b$,false),
('bunong-vn','LUK',22,62,null,$b$Jêh păng luh păng nhĭm ma nau rngot.$b$,false),
('bunong-vn','LUK',22,63,null,$b$Phung bunuyh chiă Brah Yêsu mưch ma Păng jêh ri dong Păng.$b$,true),
('bunong-vn','LUK',22,64,null,$b$Khân păng nkŭm muh măt Brah Yêsu jêh ri ôp: “May nchroh, mbu dong may?”$b$,false),
('bunong-vn','LUK',22,65,null,$b$Jêh ri khân păng hôm ngơi âk nau mhĭk êng ma Brah Yêsu.$b$,false),
('bunong-vn','LUK',22,66,null,$b$Lah trôk ang jêh, phung bu ranh tâm phung ƀon lan, phung n'gâng kôranh ƀư brah, jêh ri phung kôranh nchih sămƀŭt tâm rƀŭn, jêh ri ăn bu njŭn leo Brah Yêsu ta năp phung kôranh phat dôih phung Yuđa.$b$,true),
('bunong-vn','LUK',22,67,null,$b$Khân păng lah ma Brah Yêsu: “Tơ lah may jêng Brah Krist, mbơh hom ma hên.” Brah Yêsu plơ̆ lah ma khân păng: “Tơ lah gâp mbơh nau nây ma khân may, khân may mâu mra chroh ma nau nây ôh.$b$,true),
('bunong-vn','LUK',22,68,null,$b$Jêh ri tơ lah gâp ôp khân may, khân may mâu mra plơ̆ lah ma gâp ôh.$b$,false),
('bunong-vn','LUK',22,69,null,$b$Ƀiă lah rlet aơ pa năp Kon Bunuyh mra gŭ mpeh pa ma Brah Ndu Nơm brah.”$b$,false),
('bunong-vn','LUK',22,70,null,$b$Lĕ rngôch khân păng lah: “May jêng Kon Brah Ndu hĕ?” Păng plơ̆ lah ma phung nây: “Khân may lah jêh mbu gâp jêng.”$b$,false),
('bunong-vn','LUK',22,71,null,$b$Pô ri khân păng lah: “Moh he hôm ŭch ma bu mbơh đŏng? He hŏ tăng jêh he nơm tă bơh bâr mbung Păng.”$b$,false),
('bunong-vn','LUK',23,1,null,$b$Lĕ rngôch dâk jêh ri njŭn leo Brah Yêsu ta năp Pilat.$b$,true),
('bunong-vn','LUK',23,2,null,$b$Khân păng phong Brah Yêsu pô aơ: “Hên saơ bunuyh aơ nchâp mpôl băl hên ma nau tâm rdâng. Păng buay bu chê̆ pi ma Sêsar, jêh ri Păng lah Păng nơm jêng Krist Hađăch.”$b$,false),
('bunong-vn','LUK',23,3,null,$b$Pilat ôp Păng: “May jêng hađăch Yuđa ƀơh?” Brah Yêsu plơ̆ lah ma păng: “May lah jêh nau nây.”$b$,false),
('bunong-vn','LUK',23,4,null,$b$Pilat lah ma phung n'gâng kôranh ƀư brah jêh ri ma phung âk: “Gâp mâu saơ nau tih ôh tâm bunuyh aơ.”$b$,false),
('bunong-vn','LUK',23,5,null,$b$Ƀiă lah khân păng ăt lah: “Păng ƀư rŭng bunuyh ƀon lan, nti lah lam n'gor Yuđa, Nơm bơh Galilê tât ta ntŭk aơ.”$b$,false),
('bunong-vn','LUK',23,6,null,$b$Tơ lah Pilat tăng nau nây, păng ôp gĭt lah bunuyh nây jêng du huê tă bơh Galilê.$b$,false),
('bunong-vn','LUK',23,7,null,$b$Jêh păng gĭt Brah Yêsu gŭ tâm ntŭk hađăch Hêrôt chiă uănh, păng đă bu njŭn Brah Yêsu ma Hêrôt. Nar nây nđâp ma Hêrôt lĕ gŭ ta ƀon Yêrusalem.$b$,false),
('bunong-vn','LUK',23,8,null,$b$Tơ lah Hêrôt saơ Brah Yêsu, păng geh nau răm ngăn. Yor lah bơh jŏ jêh păng ŭch uănh Brah Yêsu. Yor păng tăng jêh nau bu nkoch bri ma Păng, jêh ri păng kâp gân mra saơ Păng ƀư nau khlay.$b$,true),
('bunong-vn','LUK',23,9,null,$b$Păng ôp âk ntil nau bơh Brah Yêsu, ƀiă lah Brah Yêsu mâu hôm plơ̆ lah ma păng ôh.$b$,false),
('bunong-vn','LUK',23,10,null,$b$Phung n'gâng kôranh ƀư brah jêh ri phung kôranh nchih sămƀŭt gŭ ta nây phong păng ktang ngăn.$b$,false),
('bunong-vn','LUK',23,11,null,$b$Hêrôt, ndrel ma phung ta han păng, tâm rmot ma Brah Yêsu. Jêh khân păng mưch ma Brah Yêsu, jêh ri nsoh Brah Yêsu ma ao chăng rhŏnh, jêh ri mplơ̆ ma Pilat,$b$,true),
('bunong-vn','LUK',23,12,null,$b$jêh ri Hêrôt jêng mĭt jiăng sa ơm ri khân păng tâm rlăng.$b$,false),
('bunong-vn','LUK',23,13,null,$b$Pilat, jêh păng rƀŭn phung n'gâng kôranh ƀư brah, phung kôranh phat dôih jêh ri phung ƀon lan,$b$,true),
('bunong-vn','LUK',23,14,null,$b$lah ma khân păng: “Khân may njŭn bunuyh aơ ma gâp, jêh ri phong Păng jêng nơm nchâp phung ƀon lan ma nau tâm rdâng, ƀiă lah gâp ôp jêh Păng ta năp khân may, jêh ri gâp mâu saơ du ntil nau tih tâm ban ma khân may phong ôh.$b$,false),
('bunong-vn','LUK',23,15,null,$b$Hêrôt mâu saơ lĕ, yor lah păng hŏ mplơ̆ jêh Păng ma he. Pô ri bunuyh aơ mâu mâp ƀư du ntil nau tih khư dơi nkhĭt ôh.$b$,false),
('bunong-vn','LUK',23,16,null,$b$Pô ri, jêh dong păng ma mâng, gâp mra mƀơk păng yơh.”$b$,false),
('bunong-vn','LUK',23,17,null,$b$Ăp năm bu ƀư nau nhêt sông, Pilat geh nau vay mƀơk ma khân păng du huê bu nă.$b$,false),
('bunong-vn','LUK',23,18,null,$b$Khân păng nter ndrel n'grŭp: “Nkhĭt lơi nơm aơ jêh ri mƀơk lơi Y-Ƀarnaƀas!”$b$,false),
('bunong-vn','LUK',23,19,null,$b$Bu krŭng jêh păng yor nau păng ƀư uh ah tâm ƀon jêh ri yor păng nkhĭt bunuyh.$b$,false),
('bunong-vn','LUK',23,20,null,$b$Pilat ngơi ma khân păng ma nau ŭch mƀơk Brah Yêsu.$b$,false),
('bunong-vn','LUK',23,21,null,$b$Jêh ri khân păng nter lah: “Pâng Păng ta si tâm rkăng! Pâng Păng ta si tâm rkăng!”$b$,false),
('bunong-vn','LUK',23,22,null,$b$Pilat lah ma khân păng tal pe: “Moh nau mhĭk Păng ƀư jêh? Gâp mâu saơ tâm Păng nau khư nkhĭt ôh. Pô ri jêh gâp ăn bu dong Păng ma mâng gâp mra mƀơk Păng.”$b$,false),
('bunong-vn','LUK',23,23,null,$b$Ƀiă lah phung nây ăt nter ktang dăn ăn bu pâng Brah Yêsu ta si tâm rkăng, jêh ri nau khĭt păng nau nter dơi đah Pilat.$b$,false),
('bunong-vn','LUK',23,24,null,$b$Pô ri Pilat lah ma nau khân păng ŭch mra tât.$b$,false),
('bunong-vn','LUK',23,25,null,$b$Păng mƀơk nơm bu krŭng jêh yor nau tâm rdâng jêh ri nau tâm nkhĭt bunuyh tĭng nâm phung nây dăn, jêh ri păng jao Brah Yêsu ma nau phung nây ŭch.$b$,false),
('bunong-vn','LUK',23,26,null,$b$Dôl khân păng njŭn Brah Yêsu, khân păng nkân Y-Simôn tă bơh ƀon Siren, păng sĭt tă ta mir, jêh ri khân păng nchâp Simôn tuy si tâm rkăng pa kơi Brah Yêsu.$b$,true),
('bunong-vn','LUK',23,27,null,$b$Geh âk bunuyh tĭng groi Brah Yêsu jêh ri geh âk bu ur tap ntang ntơh khân păng nơm, nhĭm nhhiăng ma Brah Yêsu.$b$,false),
('bunong-vn','LUK',23,28,null,$b$Brah Yêsu n'gĭl uănh ma khân păng jêh ri lah: “Hơi phung kon bu ur ƀon Yêrusalem, lơi nhĭm gâp ôh, ăn khân ay nhĭm ma khân ay nơm, jêh ri ma phung kon khân ay.$b$,false),
('bunong-vn','LUK',23,29,null,$b$Yor lah geh nar mra tât, jêh ri dôl nây bu mra lah, ueh maak yơh phung bu ur ndrô: ‘Ueh maak yơh ndŭl proch mâu mâp n'gơch nkeng, jêh ri toh mâu mâp geh pu!’$b$,false),
('bunong-vn','LUK',23,30,null,$b$Rnôk nây khân păng mra lah ma yôk: ‘Tŭp hom ta klơ hên!’ Jêh ri ma yôk jê̆: ‘Nkŭm hom hên!’$b$,false),
('bunong-vn','LUK',23,31,null,$b$Yor lah, tơ lah bu ƀư nau aơ ma si ndrêh, moh nau mra tât ma si kro?”$b$,false),
('bunong-vn','LUK',23,32,null,$b$Bu njŭn leo nđâp ma bar hê bunuyh mhĭk, gay ma nkhĭt khân păng ndrel ma Brah Yêsu.$b$,false),
('bunong-vn','LUK',23,33,null,$b$Tơ lah khân păng tât ta ntŭk bu rnha, ntŭk nting bôk, khân păng nkhĭt Brah Yêsu ta nây, nđâp ma bar hê bunuyh mhĭk, du huê pa chiau, du huê pa ma.$b$,false),
('bunong-vn','LUK',23,34,null,$b$Brah Yêsu lah: “Ơ Mbơ̆ yô̆ an ma khân păng, yor lah khân păng mâu gĭt moh nau khân păng ƀư.” Jêh ri khân păng tâm pă bok ao Brah Yêsu ma nau nchroh.$b$,false),
('bunong-vn','LUK',23,35,null,$b$Phung ƀon lan gŭ uănh ta nây, jêh ri phung kôranh phat dôih mưch ma Brah Yêsu, jêh ri lah: “Păng tâm rklaih bu jêh, ăn Păng tâm rklaih păng nơm tơ lah păng jêng Brah Krist, Nơm Brah Ndu săch jêh.”$b$,false),
('bunong-vn','LUK',23,36,null,$b$Nđâp ma phung ta han mưch ma Păng, khân păng hăn dăch jêh ri yơr dak srat ma Brah Yêsu jêh ri lah:$b$,false),
('bunong-vn','LUK',23,37,null,$b$“Tơ lah may jêng hađăch phung Yuđa rklaih hom may nơm!”$b$,false),
('bunong-vn','LUK',23,38,null,$b$Geh du pŏk sămƀŭt ta klơ bôk păng bu nchih pô aơ: “Nơm Aơ Jêng Hađăch Yuđa.”$b$,false),
('bunong-vn','LUK',23,39,null,$b$Du huê tâm phung ƀai bu pâng ta si tâm rkăng suai rak ma Brah Yêsu jêh ri lah: “Di lĕ may jêng Brah Krist ngăn? Tâm rklaih may nơm jêh ri tâm rklaih an hên ƀă!”$b$,true),
('bunong-vn','LUK',23,40,null,$b$Ƀiă lah du huê êng buay păng jêh ri lah: “May mâu klach yơk mbah ma Brah Ndu hĕ? May dơn nau tâm rmal tâm ban.$b$,false),
('bunong-vn','LUK',23,41,null,$b$Bi he hŏ di jêh, yor lah he sŏk dơn nau khư ma nau tih he, ƀiă lah nơm aơ mâu mâp ƀư nau mhĭk ôh.”$b$,true),
('bunong-vn','LUK',23,42,null,$b$Jêh ri păng lah: “Brah Yêsu ơi, ăn may kah gĭt ma gâp tơ lah may mra văch jêng hađăch chiă uănh.”$b$,false),
('bunong-vn','LUK',23,43,null,$b$Brah Yêsu plơ̆ lah ma păng: “Nanê̆ gâp lah ma may, nar aơ may mra gŭ ndrel ma gâp tâm Parađi.”$b$,true),
('bunong-vn','LUK',23,44,null,$b$Nar nklang bôk jêh, ƀiă lah geh nau ngo lam bri neh kŏ tât pe mông mhaơ.$b$,true),
('bunong-vn','LUK',23,45,null,$b$Nar jêng ngo bok mphiar tâm ngih brah Yuđa nkhêk ta nklang.$b$,false),
('bunong-vn','LUK',23,46,null,$b$Brah Yêsu nter ma nau ktang lah: “Ơ Mbơ̆ , gâp jao huêng gâp tâm ti may!” Jêh ngơi nây păng khĭt.$b$,false),
('bunong-vn','LUK',23,47,null,$b$Kôranh ta han saơ nau tât, păng mât ton tâm rnê ma Brah Ndu jêh ri lah: “Nanê̆ bunuyh aơ sŏng srăng!”$b$,false),
('bunong-vn','LUK',23,48,null,$b$Jêh ri lĕ rngôch phung âk gŭ uănh nau nây, jêh khân păng saơ nau tât, du sĭt tap ntang ntơh khân păng nơm.$b$,false),
('bunong-vn','LUK',23,49,null,$b$Jêh ri phung gĭt năl Brah Yêsu, nđâp ma phung bu ur tĭng ndô̆ Păng tă bơh n'gor Galilê, gŭ uănh nau nây ta ntŭk ngai.$b$,true),
('bunong-vn','LUK',23,50,null,$b$Geh du huê kôranh nchră, amoh păng Y-Yôsep ƀon Arimathê tâm n'gor Yuđa. Păng jêng bunuyh ueh jêh ri sŏng srăng.$b$,true),
('bunong-vn','LUK',23,51,null,$b$Jêh ri mâu mâp di nuih ma nau phung nây tâm nchră, jêh ri ƀư ôh. Păng gŭ kâp ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','LUK',23,52,null,$b$Păng hăn ta Pilat jêh ri dăn săk jăn Brah Yêsu.$b$,false),
('bunong-vn','LUK',23,53,null,$b$Jêh bu njŭr săk jăn păng tă bơh si tâm rkăng, bu put ma bok jêh ri njor tâm môch, bu lôk trôm lŭ. Ê mâp bu dơm bunuyh khĭt ôh ta ntŭk nây.$b$,false),
('bunong-vn','LUK',23,54,null,$b$Nar nây jêng nar nkra Nau Găn jêh ri nar Saƀat dăch jêh.$b$,true),
('bunong-vn','LUK',23,55,null,$b$Phung bu ur văch tă bơh n'gor Galilê ndrel ma Brah Yêsu hăn ndrel Y-Yôsep, uănh môch jêh ri ŭch gĭt mâm bu dơm săk jăn Brah Yêsu.$b$,false),
('bunong-vn','LUK',23,56,null,$b$Jêh ri khân păng sĭt, nkra dak si ƀâu kah. Jêh ri khân păng rlu nar Saƀat tĭng nâm nau vay.$b$,false),
('bunong-vn','LUK',24,1,null,$b$Nar nguay tâm nar ver khân păng hăn ơm ôi ta môch djôt dak si ƀâu kah, khân păng nkra jêh.$b$,true),
('bunong-vn','LUK',24,2,null,$b$Khân păng saơ lŭ bu rlă lơi jêh ta năp môch.$b$,false),
('bunong-vn','LUK',24,3,null,$b$Ƀiă lah jêh khân păng lăp, khân păng mâu hôm saơ ôh săk jăn kôranh Brah Yêsu.$b$,false),
('bunong-vn','LUK',24,4,null,$b$Dôl khân păng hih rhâl ma nau nây, aơ geh bar hê soh ao nglang rmah ngăn tâm mpơl ma khân păng.$b$,false),
('bunong-vn','LUK',24,5,null,$b$Dôl khân păng kŭnh uănh ma nau klach ngăn: “Phung nây lah ma khân păng mâm ƀư khân ay joi nơm rêh tâm phung khĭt?$b$,false),
('bunong-vn','LUK',24,6,null,$b$Păng mâu gŭ ta aơ ôh, păng hŏ dâk rêh jêh. Khân ay kah gĭt lĕ, mâm nau Păng ngơi jêh ma khân ay dôl Păng gŭ tâm n'gor Galilê, jêh ri Păng lah jêh:$b$,false),
('bunong-vn','LUK',24,7,null,$b$‘Bu mra jao Kon Bunuyh tâm ti phung tih, pâng Păng ta si tâm rkăng, jêh ri Păng mra dâk rêh tăch pe nar ma nây!’ ”$b$,false),
('bunong-vn','LUK',24,8,null,$b$Pô ri khân păng kah gĭt ro ma nau Brah Yêsu ngơi jêh.$b$,false),
('bunong-vn','LUK',24,9,null,$b$Tơ lah khân păng sĭt tă bơh môch, khân păng mbơh lĕ nau nây ma phung jât ma nguay nuyh oh mon jêh ri ma lĕ rngôch phung êng.$b$,false),
('bunong-vn','LUK',24,10,null,$b$H'Mari Mađala, H'Yôana, H'Mari mê̆ Yakơ, jêh ri phung bu ur êng, ndrel ma khân păng mbơh nau aơ ma phung kôranh oh mon,$b$,false),
('bunong-vn','LUK',24,11,null,$b$ƀiă lah nau nkoch bri aơ phung oh mon tăng tâm ban ma nau mbơi, jêh ri khân păng mâu chroh ôh.$b$,false),
('bunong-vn','LUK',24,12,null,$b$Ƀiă lah Y-Pêtrôs dâk jêh ri nchuăt hăn ta môch. Păng kŭnh uănh jêh ri saơ knŏng bok hôm ta nây. Jêh ri păng sĭt ta ngih, păng nơm bêng ma nau hih rhâl ma nau tât jêh.$b$,false),
('bunong-vn','LUK',24,13,null,$b$Nar nây lĕ bar hê oh mon hăn ta du ƀon tâm amoh Êmaus, klăp lah ngai đah ƀon Yêrusalem jât ma nguay vang kilômet.$b$,true),
('bunong-vn','LUK',24,14,null,$b$Jêh ri khân păng nkoch lĕ nau tât jêh.$b$,true),
('bunong-vn','LUK',24,15,null,$b$Dôl khân păng ngơi jêh ri tâm rlăch, Brah Yêsu hăn dăch, jêh ri hăn ndrel ma khân păng.$b$,true),
('bunong-vn','LUK',24,16,null,$b$Ƀiă lah măt khân păng mâu gĭt năl Brah Yêsu ôh.$b$,false),
('bunong-vn','LUK',24,17,null,$b$Brah Yêsu lah ma khân păng: “Moh nau khân may tâm nkoch bri dôl hăn trong?” Jêh ri khân păng gŭ ƀât lât ma nau rngot.$b$,false),
('bunong-vn','LUK',24,18,null,$b$Du huê tâm phung khân păng, amoh păng Y-Klêôpas, plơ̆ lah ma Brah Yêsu: “Knŏng êng may hĕ gŭ ta ƀon Yêrusalem, mâu gĭt moh nau tât jêh tâm nar aơ?”$b$,false),
('bunong-vn','LUK',24,19,null,$b$Brah Yêsu lah ma khân păng: “Moh nau tât?” Khân păng plơ̆ lah ma Brah Yêsu: “Nau tât jêh ma Brah Yêsu, ƀon Nasaret. Păng jêng du huê kôranh nơm mbơh lor, brah ngăn tâm kan jêh ri tâm nau ngơi ta năp Brah Ndu, jêh ri ta năp lĕ rngôch bunuyh.$b$,false),
('bunong-vn','LUK',24,20,null,$b$Jêh ri ma nau phung n'gâng kôranh ƀư brah jêh ri phung kôranh phat dôih he jao jêh Păng, ăn bu nkhĭt lơi ta si tâm rkăng.$b$,false),
('bunong-vn','LUK',24,21,null,$b$Hên kâp gân ma Păng yơh, mra ăn ma phung Israel jêng kon me, jêh ri rlau ma nau nây pe nar jêh nau aơ tât.$b$,false),
('bunong-vn','LUK',24,22,null,$b$Nanê̆ ƀa ƀă phung bu ur tâm phung hên, mbơh nau hih rhâl ngăn ma hên. Khân păng hăn ơm jêh ta môch,$b$,false),
('bunong-vn','LUK',24,23,null,$b$jêh ri khân păng mâu hôm saơ săk jăn păng ôh. Khân păng sĭt mbơh ma hên, geh phung Tông mpăr ueh Brah Ndu tâm mpơl ma khân păng jêh ri mbơh ma khân păng, Brah Yêsu hŏ dâk rêh jêh.$b$,false),
('bunong-vn','LUK',24,24,null,$b$Geh ƀa ƀă tâm phung hên hăn jêh ta môch, jêh ri khân păng saơ tâm ban ma phung bu ur mbơh jêh, ƀiă lah khân păng mâu hôm saơ Brah Yêsu ôh.”$b$,false),
('bunong-vn','LUK',24,25,null,$b$Pô ri Brah Yêsu lah ma khân păng: “Hơi phung bunuyh mâu geh nau gĭt rbăng, jêh ri nuih n'hâm rvưt chroh lĕ nau phung kôranh nơm mbơh lor, mbơh jêh.$b$,false),
('bunong-vn','LUK',24,26,null,$b$Mâu di hĕ Brah Krist mra dơn lĕ nau nđêh nji tâm ban pô nây, jêh ri Păng mra lăp tâm nau chrêk rmah Păng?”$b$,false),
('bunong-vn','LUK',24,27,null,$b$Jêh ri Păng rblang ma phung nây lĕ nau nchih di ma Păng tă bơh Y-Môis, tât ma lĕ rngôch phung kôranh nơm mbơh lor.$b$,false),
('bunong-vn','LUK',24,28,null,$b$Tơ lah khân păng dăch tât jêh ta ƀon khân păng hăn, Brah Yêsu mĭn ŭch hăn ngai lơn.$b$,true),
('bunong-vn','LUK',24,29,null,$b$Ƀiă lah khân păng nchâp Brah Yêsu jêh ri lah: “Gŭ ndrel ma hên, yor lah trôk hŏ dăch măng jêh. Nar dăch nhâp jêh.” Jêh ri Păng lăp gŭ ndrel ma phung nây.$b$,false),
('bunong-vn','LUK',24,30,null,$b$Dôl Brah Yêsu sông sa ndrel ma khân păng, Păng sŏk kapŭng jêh ri jêh mbơh sơm, Păng nkêch kapŭng ăn ma phung nây.$b$,true),
('bunong-vn','LUK',24,31,null,$b$Dôl nây măt khân păng pơk jêh ri khân păng gĭt năl Brah Yêsu ro. Ƀât lât Brah Yêsu roh hêt ro tă bơh măt khân păng saơ.$b$,true),
('bunong-vn','LUK',24,32,null,$b$Jêh ri khân păng tâm ngơi ndrăng khân păng nơm: “Mâm ƀư nuih n'hâm he geh nau nsŭk nsôr lĕ? Tơ lah Păng ngơi đah he rŏ trong jêh ri rblang nau nchih jêh.”$b$,false),
('bunong-vn','LUK',24,33,null,$b$Mông nây ro khân păng dâk, hăn sĭt ta ƀon Yêrusalem jêh ri tâm mâp đah phung jât ma nguay nuyh, jêh ri đah phung oh mon ƀa ƀă, tâm rƀŭn ndrel ma khân păng. Phung jât ma nguay nuyh lah:$b$,false),
('bunong-vn','LUK',24,34,null,$b$“Kôranh Brah dâk rêh ngăn jêh, jêh ri Păng tâm mpơl jêh đah Y-Simôn!”$b$,false),
('bunong-vn','LUK',24,35,null,$b$Jêh ri khân Păng nkoch bri tâm ban lĕ moh nau tât jêh ma khân păng rŏ trong, jêh ri mâm ƀư khân păng gĭt năl Brah Yêsu dôl Păng nkêch kapŭng.$b$,false),
('bunong-vn','LUK',24,36,null,$b$Dôl khân păng ngơi pô nây, Brah Yêsu nơm tâm mpơl ma khân păng, jêh ri lah: “Ăn nau đăp mpăn gŭ ndrel ma khân may!”$b$,true),
('bunong-vn','LUK',24,37,null,$b$Ƀiă lah khân păng hih rhâl jêh ri klach. Khân păng ntôn lah chiak.$b$,true),
('bunong-vn','LUK',24,38,null,$b$Brah Yêsu lah ma khân păng: “Mâm ƀư khân may geh nau uh ah, jêh ri mâm ƀư khân may mĭn pô nây tâm nuih n'hâm khân may?$b$,false),
('bunong-vn','LUK',24,39,null,$b$Uănh ti jêh ri jâng gâp. Gâp yơh aơ, pah bi jêh ri uănh hom. Chiak mâu geh nglay săk mâu lah nting ôh, ƀiă lah khân may saơ gâp geh.”$b$,false),
('bunong-vn','LUK',24,40,null,$b$Dôl Păng lah pô nây, Păng nhhơ ti jêh ri jâng Păng ma phung nây.$b$,false),
('bunong-vn','LUK',24,41,null,$b$Dôl khân păng răm maak jêh ri hih rhâl, ăt ê khân păng iăt ôh. Jêh ri Brah Yêsu lah ma khân păng: “Khân may geh lĕ ndơ sa ta aơ?”$b$,false),
('bunong-vn','LUK',24,42,null,$b$Khân păng nhhơ ma Brah Yêsu ka gŭch, jêh ri dak sŭt.$b$,false),
('bunong-vn','LUK',24,43,null,$b$Păng sŏk sa ka nây ta năp khân păng.$b$,false),
('bunong-vn','LUK',24,44,null,$b$Jêh ri Brah Yêsu lah ma khân păng: “Pô aơ nau gâp ngơi jêh ma khân may, dôl gâp hôm gŭ ndrel ma khân may, ăn lĕ nau bu nchih ma gâp tâm nau vay Y-Môis tâm nau phung kôranh nơm mbơh lor, jêh ri tâm Nau Mprơ Ơm mra nanê̆ da dê.”$b$,false),
('bunong-vn','LUK',24,45,null,$b$Pô ri Brah Yêsu pơk nau mĭn khân păng, gay ma khân păng gĭt rbăng nau nchih jêh.$b$,false),
('bunong-vn','LUK',24,46,null,$b$Jêh ri Păng lah ma phung nây: “Pô aơ nau bu nchih jêh ma Brah Krist mra dơn nau rêh ni jêh ri Păng mra dâk rêh lôch pe nar.$b$,false),
('bunong-vn','LUK',24,47,null,$b$Jêh ri bu mra nti tâm amoh Păng, nau tâm rmal ma nau tih, jêh ri nau yô̆ ma nau tih ma lĕ rngôch mpôl băl bunuyh, ntơm bơh ƀon Yêrusalem.$b$,false),
('bunong-vn','LUK',24,48,null,$b$Khân may jêng nơm leo trong ma lĕ nau aơ.$b$,true),
('bunong-vn','LUK',24,49,null,$b$Jêh ri gâp mra njuăl ma khân may ndơ Mbơ̆ gâp ton jêh, ƀiă lah ăn khân may gŭ tâm ƀon tât khân may soh jêh nau brah tă bơh klơ.”$b$,false),
('bunong-vn','LUK',24,50,null,$b$Brah Yêsu leo khân păng hăn ta ƀon Bêthani jêh ri păng yơr ti mât ton ma khân păng.$b$,true),
('bunong-vn','LUK',24,51,null,$b$Dôl Păng mât ton ma khân păng, Păng du tă bơh khân păng jêh ri Brah Ndu chông Păng hao klơ trôk.$b$,false),
('bunong-vn','LUK',24,52,null,$b$Jêh tâm rnê ma Brah Yêsu, khân păng hăn sĭt ta ƀon Yêrusalem ma nau răm maak.$b$,false),
('bunong-vn','LUK',24,53,null,$b$Khân păng gŭ ƀa ƀơ tâm ngih brah Yuđa, mât ton tâm rnê ma Brah Ndu.$b$,false);
